void __fastcall TfrmMain::funcSetBasicDirectory()
{
	//기본폴더경로//
	ROOTPATH  		= ExtractFilePath(Application->ExeName);

	RESPATH  		= ROOTPATH + "RES\\";
	IMAGEMAINPATH 	= RESPATH + "MAIN\\";
	IMAGEMEMOPATH	= RESPATH + "MEMO\\";
	IMAGEMENUPATH	= RESPATH + "MENU\\";
	IMAGEPOIPATH	= RESPATH + "POI\\";//
	IMAGEUIPATH		= RESPATH + "UI\\";//LMReq, 01Attach, 02Attach, JDM

	TMPPATH			= ROOTPATH + "tmp\\";
	THUMBPATH		= ROOTPATH + "_thumb\\";
	PRINTPATH       = ROOTPATH + "Print\\";
	DOWNLOADPATH    = ROOTPATH;
	DOWNLOADPATH	= StringReplace(DOWNLOADPATH, "BIN\\", "", TReplaceFlags() << rfReplaceAll);
	DOWNLOADPATH    += "DOWNLOAD\\";//251001//'../DOWNLOAD'로 구성하면 SelectDirectory에서 인지를 못한다//
	TEMPPATH		= ROOTPATH + "Temp\\";
	_HIST_PATH		= ROOTPATH + "_HIST_\\";//210223//#_HIST_
	TMPDOCPATH		= ROOTPATH + "tmpDoc\\";//TMEMPDOCPATH//
	TMPTHUMBPATH	= ROOTPATH + "tmpThumb\\";

	//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	//220428//#LOG_EXCEPT//
	LOGPATH			= ROOTPATH + "LOG\\";//
	//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

	DBPATH			= ROOTPATH + "DB\\";//LMFS

 	//기본폴더생성//
	if (DirectoryExists(TMPPATH))//tmp 하위 파일들 삭제하기
		eFunc->funcDeleteDir(true, TMPPATH);
	if (DirectoryExists(PRINTPATH))//print 하위 파일들 삭제하기
		eFunc->funcDeleteDir(true, PRINTPATH);
	if (DirectoryExists(_HIST_PATH))//_HIST_ 하위 파일들 삭제하기//210223//#_HIST_
		eFunc->funcDeleteDir(true, _HIST_PATH);
	//200622//_thumb_ 폴더 삭제안함//
//	if (DirectoryExists(THUMBPATH))//_thumb 하위 파일들 삭제하기
//		eFunc->funcDeleteDir(THUMBPATH);
	if (DirectoryExists(TMPDOCPATH))//TEMPDOC//tmpDoc 하위 파일들 삭제하기//
		eFunc->funcDeleteDir(false, TMPDOCPATH);
	if (DirectoryExists(TMPTHUMBPATH))//TEMPDOC//tmpThumb 하위 파일들 삭제하기//
		eFunc->funcDeleteDir(false, TMPTHUMBPATH);
	if (!DirectoryExists(TMPPATH))
		CreateDir(TMPPATH);
	if (!DirectoryExists(THUMBPATH))
		CreateDir(THUMBPATH);
	if (!DirectoryExists(DOWNLOADPATH))
		CreateDir(DOWNLOADPATH);
	if (!DirectoryExists(PRINTPATH))
		CreateDir(PRINTPATH);
	if (!DirectoryExists(TEMPPATH))
		CreateDir(TEMPPATH);
	if (!DirectoryExists(TMPDOCPATH))//TEMPDOC//tmpDoc 폴더 생성하기//
		CreateDir(TMPDOCPATH);
	if (!DirectoryExists(TMPTHUMBPATH))//TEMPDOC//tmpThumb 폴더 생성하기//
		CreateDir(TMPTHUMBPATH);
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//220428//#LOG_EXCEPT//
	if (!DirectoryExists(LOGPATH))//LOG 폴더 생성하기//
		CreateDir(LOGPATH);
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	if (!DirectoryExists(DBPATH))//LMFS
		CreateDir(DBPATH);
	//=======================================
	//221202//LMREQ//CREATE_DIR
	if(INI_B_LMREQ)
	{
		if (!DirectoryExists(LMREQ_SIGN_PATH))
			CreateDir(LMREQ_SIGN_PATH);
		if (!DirectoryExists(LMREQ_IDSCAN_PATH))
			CreateDir(LMREQ_IDSCAN_PATH);
		if (!DirectoryExists(LMREQ_IMAGES_PATH))
			CreateDir(LMREQ_IMAGES_PATH);
	}
	//=======================================

}
