void __fastcall TfrmMain::funcSetINIFiles()
{
	SIDOINI	= new TIniFile(ROOTPATH + "DATA\\LandArchive.ini");
	if (!FileExists(SIDOINI->FileName))
	{
		String sMessage = L"시스템파일이 존재하지 않습니다.";
		if (Application->MessageBox(sMessage.c_str(), L"오류", MB_OK) == IDOK)
			Close();
	}
	_SIDOCODE	= SIDOINI->ReadString(L"SIDO_CODE", L"CODE", L"");
	_SIDONAME	= SIDOINI->ReadString(L"SIDO_CODE", L"NAME", L"");

	USERSETINI  = new TIniFile(ROOTPATH + "DATA\\UserSet.ini");
	if (!FileExists(USERSETINI->FileName))
	{
		String sMessage = L"설정파일이 존재하지 않습니다.(3)" + SIDOINI->FileName;
		if (Application->MessageBox(sMessage.c_str(), L"오류", MB_OK) == IDOK)
			Close();
	}

	//======================================================
	//211205//구대장 연혁 & 소유자정보//#OWNINFO#
	//======================================================
	CONFIGDOC8INI	= new TIniFile(ROOTPATH + "DATA\\ConfigDoc8.ini");
}
