void __fastcall TfrmMain::funcControlMainProgramRes()
{
	//=============================================================================
	//230913//지적문서통합관리시스템.exe를 RENAME 해야한다.//
	if(FileExists(ROOTPATH + "..\\지적문서통합관리시스템_up.exe"))
	{
		DeleteFile(ROOTPATH + "..\\지적문서통합관리시스템.exe");
		RenameFile(ROOTPATH + "..\\지적문서통합관리시스템_up.exe", ROOTPATH + "..\\지적문서통합관리시스템.exe");
	}
	//=============================================================================

	//=============================================================================
	//231213//Login.exe를 지적문서통합관리시스템.exe로 RENAME 해야한다.//
	if(FileExists(ROOTPATH + "..\\LOGIN.exe"))
	{
		DeleteFile(ROOTPATH + "..\\지적문서통합관리시스템.exe");
		RenameFile(ROOTPATH + "..\\LOGIN.exe", ROOTPATH + "..\\지적문서통합관리시스템.exe");
	}
	//=============================================================================
}
