int __fastcall TfrmMain::func_MessageDlg( const AnsiString Msg, Dialogs::TMsgDlgType DlgType, Dialogs::TMsgDlgButtons Buttons, int HelpCtx)
{
	switch( DlgType ){
		case mtWarning      : ::MessageBeep(  MB_ICONEXCLAMATION ); break;
		case mtError        : ::MessageBeep(  MB_ICONHAND        ); break;
		case mtInformation  : ::MessageBeep(  MB_ICONASTERISK    ); break;
		case mtConfirmation : ::MessageBeep(  MB_ICONQUESTION    ); break;
		case mtCustom       : ::MessageBeep(  MB_OK              ); break;

		default : break;
	}
	return bsSkinMessage1->MessageDlg( Msg, DlgType, Buttons, HelpCtx );
}
