void __fastcall TfrmMain::FormClose(TObject *Sender, TCloseAction &Action)
{
	TRACEF("[FormClose] enter");
	gAppClosing = true;

	//#LogoutTimer
	LogoutTimerCount->Enabled = false;

	//=========================================================
	// LOG HISTORY
	//=========================================================
	wsprintf(frmUserManagement->mCurrentUser.cLogoutDate, "%s", Now().FormatString("yyyy-mm-dd hh:nn:ss").t_str()) ;
	frmUserManagement->funcSetUserLoginState(&frmUserManagement->mCurrentUser, 12);
//230207//funcSetUserHistState()Param변경//
//	AnsiString asKindCode = eFunc->funcGetKindNameToKindCode(503, "로그아웃시각");//210305//#44710//9
//	if( !asKindCode.IsEmpty() )
//		frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, asKindCode.ToInt(), m_nActiveDoc);
	frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, "로그아웃시각", m_nActiveDoc);

	//===================================================
	funcClosePanel();
	funcInitPBControl2();//init pbRect
	funcInitThumb();//FormClose
	funcInitAdjustBar();
	funcInitPrevNextBar(false);//FormClose
//>>>//230328//
//[이슈]한글화 띄운 상태에서 프로그램 종료시 문제 발생//
//원인 : chkDoc8OverlapClick() 에서 이미 해제된 imgDoc08Mover 를 제어해서 발생//
//해결 : 프로그램 종료 시점이라 CheckBox 해제할 필요 없음//
//[제거]	funcInitDoc08Bar(false);//minji@230308//#DOC08_INFO_ICON
//<<<

	funcFreeImage();
	//===================================================

	//===================================================
	funcCloseExternalProgram();
	funcFreeBasicResource();

	funcFreeErrFiles();

	funcFreeExternalFiles();

	funcFreeMapRelation();

	func_clearRealData();
	func_vectorClear();

	funcDeleteButtonImage();

	//DB연결해제//
	func_DBMSDisconnect();

	if(m_bCloseProcess == true) frmProgramClose->Show();

	if(Timer1->Enabled == true)	Timer1->Enabled = false;
	TRACEF("[FormClose] timer disabled");

	funcFreeINIFiles();

	Action = caFree;
	TRACEF("[FormClose] action=caFree");
}
