void __fastcall TfrmMain::funcFreeINIFiles()
{
	AnsiString asIniFile = "";
	asIniFile = frmMain->ROOTPATH + "DATA\\CopyDoc.ini";
	if(FileExists(asIniFile))
		DeleteFile(asIniFile);

	//220930//44770추가//220712//#44250//계룡만 임시로 인쇄 설정 파일 삭제 안함//
	if(_SIDOCODE != "44250" && _SIDOCODE != "44770")
	{
		asIniFile = frmMain->ROOTPATH + "DATA\\PrintSetting.ini";
		if(FileExists(asIniFile))
			DeleteFile(asIniFile);
	}

	asIniFile = frmMain->ROOTPATH + "DATA\\PreviewData.ini";
	if(FileExists(asIniFile))
		DeleteFile(asIniFile);

	//
	delete CONFIGDOC8INI;
	delete _iniPrintSetting;
	delete USERSETINI;
	delete USERINI;
	delete SIDOINI;
	CONFIGDOC8INI = NULL;
	_iniPrintSetting = NULL;
	USERSETINI = NULL;
	USERINI = NULL;
	SIDOINI = NULL;

	//=========================================================
	//구대장 한글표시 초기화//#OWNINFO#//
	delete e08DataAlpha;
	delete e08DataAIOCR;
	delete eAIOCR;
	delete eTree;
	delete eEncrypt;
	e08DataAlpha = NULL;
	e08DataAIOCR = NULL;
	eAIOCR = NULL;
	eTree = NULL;
	eEncrypt = NULL;
	//=========================================================
}
