void __fastcall TfrmMain::funcFreeErrFiles()
{
	//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	//220428//#LOG_EXCEPT//
	if(qryErr != NULL)
	{
		if(qryErr->Count > 0)
		{
			AnsiString  asLogFile 	= LOGPATH + "err_" + Now().FormatString("yyyymmddhhmmsszzz") + ".txt";
			qryErr->SaveToFile(asLogFile.c_str());
		}
		delete qryErr;
		qryErr	= NULL;
	}
	if(qryLog != NULL)
	{
		qryLog->Add("프로그램을 종료합니다.");
		AnsiString  asLogFile 	= LOGPATH + "log_" + Now().FormatString("yyyymmddhhmmsszzz") + ".txt";
		qryLog->SaveToFile(asLogFile.c_str());
		delete qryLog;
		qryLog	= NULL;
	}
	//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
}
