BOOL __fastcall TfrmMain::func_DBMSConnect()
{
	if(frmSql->m_hStmt) SQLCloseCursor(frmSql->m_hStmt);
	if(frmSql->m_hStmt) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmt);
	if(frmSql->m_hDbc)  SQLDisconnect(frmSql->m_hDbc);
	if(frmSql->m_hDbc)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbc);
	if(frmSql->m_hEnv)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnv);
	frmSql->m_hStmt = NULL;
	frmSql->m_hDbc  = NULL;
	frmSql->m_hEnv  = NULL;

	//========================================================================
	// LONGBLOB 데이터를 가져오기 위함//
	//========================================================================
	if(frmSql->m_hStmtDataSize) SQLCloseCursor(frmSql->m_hStmtDataSize);
	if(frmSql->m_hStmtDataSize) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmtDataSize);
	if(frmSql->m_hDbcDataSize)  SQLDisconnect(frmSql->m_hDbcDataSize);
	if(frmSql->m_hDbcDataSize)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbcDataSize);
	if(frmSql->m_hEnvDataSize)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnvDataSize);
	frmSql->m_hStmtDataSize = NULL;
	frmSql->m_hDbcDataSize  = NULL;
	frmSql->m_hEnvDataSize  = NULL;
	//========================================================================

	//========================================================================
	// LONGBLOB 이미지를 가져오기 위함//201027//
	//========================================================================
	if(frmSql->m_hStmtImg) SQLCloseCursor(frmSql->m_hStmtImg);
	if(frmSql->m_hStmtImg) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmtImg);
	if(frmSql->m_hDbcImg)  SQLDisconnect(frmSql->m_hDbcImg);
	if(frmSql->m_hDbcImg)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbcImg);
	if(frmSql->m_hEnvImg)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnvImg);
	frmSql->m_hStmtImg = NULL;
	frmSql->m_hDbcImg  = NULL;
	frmSql->m_hEnvImg  = NULL;
	//========================================================================

	SQLRETURN Ret;
	//환경 핸들을 할당하고 버전 속성을 설정한다.
	if(SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &frmSql->m_hEnv) != SQL_SUCCESS)
		return FALSE;
	if(SQLSetEnvAttr(frmSql->m_hEnv, SQL_ATTR_ODBC_VERSION, (SQLPOINTER)SQL_OV_ODBC3, SQL_IS_INTEGER) != SQL_SUCCESS)
		return FALSE;

	//연결 핸들을 할당하고 연결한다
	if(SQLAllocHandle(SQL_HANDLE_DBC, frmSql->m_hEnv, &frmSql->m_hDbc) != SQL_SUCCESS)
		return FALSE;

	//DB에 연결하기
//	_DBID_ = "itlandoffice";
//	_DBPW_ = "itkorealand++!";


//=============================================================================
	AnsiString  asTitle = "DB_INFO";
	if(_SIDOCODE == "44131" || _SIDOCODE == "44133")
		asTitle = asTitle + "_" + _SIDOCODE;
	_DBIP_ 		= func_Decoder(AnsiString(SIDOINI->ReadString(asTitle,"IP","")));
	_DATABASE_  = func_Decoder(AnsiString(SIDOINI->ReadString(asTitle,"SID","")));//"LANDARCHIVE";
	_DBPORT_ 	= func_Decoder(AnsiString(SIDOINI->ReadString(asTitle,"PORT","")));
	_DBID_ 		= func_Decoder(AnsiString(SIDOINI->ReadString(asTitle,"ID","")));
	_DBPW_ 		= func_Decoder(AnsiString(SIDOINI->ReadString(asTitle,"PW","")));
//=============================================================================

	AnsiString connectString;
	connectString = "Driver=MySQL ODBC 5.1 Driver; server=" + _DBIP_ + ";database=" + _DATABASE_ + ";Port=" + _DBPORT_ + ";uid=" + _DBID_ + ";pwd=" + _DBPW_ + ";OPTION=3; charset=euckr";//외부

	if(_DATABASE_ == "") return FALSE;

	wsprintf((char *)frmSql->m_InCon, connectString.c_str());

	Ret = SQLDriverConnect(frmSql->m_hDbc, NULL, frmSql->m_InCon, sizeof(frmSql->m_InCon), frmSql->m_OutCon, sizeof(frmSql->m_OutCon), &frmSql->m_cbOutCon, SQL_DRIVER_NOPROMPT);
	if((Ret != SQL_SUCCESS) && (Ret != SQL_SUCCESS_WITH_INFO))
		return FALSE;

	//명령 핸들을 할당한다.
	if(SQLAllocHandle(SQL_HANDLE_STMT, frmSql->m_hDbc, &frmSql->m_hStmt) != SQL_SUCCESS)
		return FALSE;

	//========================================================================
	// LONGBLOB 데이터를 가져오기 위함//
	//========================================================================
	//환경 핸들을 할당하고 버전 속성을 설정한다.
	if(SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &frmSql->m_hEnvDataSize) != SQL_SUCCESS)
		return FALSE;

	if(SQLSetEnvAttr(frmSql->m_hEnvDataSize,SQL_ATTR_ODBC_VERSION,(SQLPOINTER)SQL_OV_ODBC3,SQL_IS_INTEGER) != SQL_SUCCESS)
		return FALSE;

	//연결 핸들을 할당하고 연결한다
	if(SQLAllocHandle(SQL_HANDLE_DBC, frmSql->m_hEnvDataSize, &frmSql->m_hDbcDataSize) != SQL_SUCCESS)
		return FALSE;

	wsprintf((char *)frmSql->m_InConDataSize,connectString.c_str());

	Ret = SQLDriverConnect(frmSql->m_hDbcDataSize,NULL,frmSql->m_InConDataSize,sizeof(frmSql->m_InConDataSize),frmSql->m_OutConDataSize, sizeof(frmSql->m_OutConDataSize), &frmSql->m_cbOutConDataSize, SQL_DRIVER_NOPROMPT);
	if((Ret != SQL_SUCCESS) && (Ret != SQL_SUCCESS_WITH_INFO))
		return FALSE;

	//명령 핸들을 할당한다.
	if(SQLAllocHandle(SQL_HANDLE_STMT, frmSql->m_hDbcDataSize, &frmSql->m_hStmtDataSize) != SQL_SUCCESS)
		return FALSE;
	//========================================================================

	//201027//
	//========================================================================
	// LONGBLOB 이미지를 가져오기 위함//
	//========================================================================
	//환경 핸들을 할당하고 버전 속성을 설정한다.
	if(SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &frmSql->m_hEnvImg) != SQL_SUCCESS)
		return FALSE;

	if(SQLSetEnvAttr(frmSql->m_hEnvImg,SQL_ATTR_ODBC_VERSION,(SQLPOINTER)SQL_OV_ODBC3,SQL_IS_INTEGER) != SQL_SUCCESS)
		return FALSE;

	//연결 핸들을 할당하고 연결한다
	if(SQLAllocHandle(SQL_HANDLE_DBC, frmSql->m_hEnvImg, &frmSql->m_hDbcImg) != SQL_SUCCESS)
		return FALSE;

	wsprintf((char *)frmSql->m_InConImg,connectString.c_str());

	Ret = SQLDriverConnect(frmSql->m_hDbcImg,NULL,frmSql->m_InConImg,sizeof(frmSql->m_InConImg),frmSql->m_OutConImg, sizeof(frmSql->m_OutConImg), &frmSql->m_cbOutConImg, SQL_DRIVER_NOPROMPT);
	if((Ret != SQL_SUCCESS) && (Ret != SQL_SUCCESS_WITH_INFO))
		return FALSE;

	//명령 핸들을 할당한다.
	if(SQLAllocHandle(SQL_HANDLE_STMT, frmSql->m_hDbcImg, &frmSql->m_hStmtImg) != SQL_SUCCESS)
		return FALSE;
	//========================================================================

	return TRUE;
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::func_DBMSDisconnect()
{
	if(frmSql->m_hStmt) SQLCloseCursor(frmSql->m_hStmt);
	if(frmSql->m_hStmt) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmt);
	if(frmSql->m_hDbc)  SQLDisconnect(frmSql->m_hDbc);
	if(frmSql->m_hDbc)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbc);
	if(frmSql->m_hEnv)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnv);
	frmSql->m_hStmt = NULL;
	frmSql->m_hDbc  = NULL;
	frmSql->m_hEnv  = NULL;


	//============================================================
	//LONGBLOB DOWNLOAD//
	//============================================================
	if(frmSql->m_hStmtDataSize) SQLCloseCursor(frmSql->m_hStmtDataSize);
	if(frmSql->m_hStmtDataSize) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmtDataSize);
	if(frmSql->m_hDbcDataSize)  SQLDisconnect(frmSql->m_hDbcDataSize);
	if(frmSql->m_hDbcDataSize)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbcDataSize);
	if(frmSql->m_hEnvDataSize)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnvDataSize);
	frmSql->m_hStmtDataSize = NULL;
	frmSql->m_hDbcDataSize  = NULL;
	frmSql->m_hEnvDataSize  = NULL;
	//========================================================================
	// LONGBLOB 이미지를 가져오기 위함//201027//
	//========================================================================
	if(frmSql->m_hStmtImg) SQLCloseCursor(frmSql->m_hStmt);
	if(frmSql->m_hStmtImg) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmt);
	if(frmSql->m_hDbcImg)  SQLDisconnect(frmSql->m_hDbc);
	if(frmSql->m_hDbcImg)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbc);
	if(frmSql->m_hEnvImg)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnv);
	frmSql->m_hStmtImg = NULL;
	frmSql->m_hDbcImg  = NULL;
	frmSql->m_hEnvImg  = NULL;
}
