void __fastcall TfrmMain::funcSetXDBPath()
{
	AnsiString asIniPath = frmMain->ROOTPATH;
	AnsiString asIniFile = asIniPath + "sdbapi.conf";
	AnsiString asBasicPath = "";
	TIniFile 	*_confXDB;

	_confXDB = new TIniFile(asIniFile);

	// To Do SIDO CODE SETTING
	if (FileExists(asIniFile))	{
		asBasicPath = _confXDB->ReadString(L"About Key Configure", L"ObjectFilePath", L"");
		asBasicPath = StringReplace(asBasicPath, ExtractFilePath(asBasicPath), asIniPath, TReplaceFlags()<<rfReplaceAll);

		_confXDB->WriteString(L"About Key Configure", L"ObjectFilePath", asBasicPath);
	}

	//minji@230306//#new-delete pair
	delete _confXDB;
	_confXDB = NULL;
}
