void __fastcall TfrmMain::FormResize(TObject *Sender)
{
	if( !m_bPreventResize )//210204//
	{
		//191119//panWindowsMove 시에 화면이 줄어드는 현상 방지위함//
		IMGSCREEN1->Left   = 0;
		IMGSCREEN1->Top    = 0;
		IMGSCREEN1->Width  = palClient->Width;
		IMGSCREEN1->Height = palClient->Height;//191126//palClient->Height - bsSkinStatusBar1->Height;
		pnlImgDocView->Width 	= palClient->Width;
		pnlImgDocView->Height  	= palClient->Height;
		//####################
		//200825//
		//201223//리사이징 시 기존 배율 유지////201223//#FORMMAX//
		IMGSCREEN2->Width		= pnlImgDocView->Width;
		IMGSCREEN2->Height		= pnlImgDocView->Height;
		//####################

		if(pnlImgDocView->Visible && IMGLOGO->Visible && IMGSCREEN2->Picture->Bitmap->Width == 0)
		{
			IMGLOGO->Left = (pnlImgDocView->Width/2) - (IMGLOGO->Width/2);
			IMGLOGO->Top  = (pnlImgDocView->Height/2) - (IMGLOGO->Height/2);
			Application->ProcessMessages();
		}
		if(palWait->Visible)//200401//
		{
			palWait->Left = (palClient->Width/2) - (palWait->Width/2);
			palWait->Top  = (palClient->Height/2) - (palWait->Height/2);
			Application->ProcessMessages();
		}

		IMGSCREEN1->Picture->Bitmap->Height = IMGSCREEN1->Height;
		IMGSCREEN1->Picture->Bitmap->Width  = IMGSCREEN1->Width;

		pnlSPREAD->Left = 1;
		pnlSPREAD->Top  = palClient->Height/2 - pnlSPREAD->Height/2;
		Application->ProcessMessages();

		if(_CURRENT_WORKMODE == "DOCUMENT")
			funcSetModeLayer(false);
		else if(_CURRENT_WORKMODE == "SPATIAL")
			funcSetModeLayer(true);

		//220105//
		funcFreeEachButtonImage(btnMax);
		if(WindowState == wsMaximized)//최대화
			btnMax->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Max]);
		else
			btnMax->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Mid]);
		//
		funcSetMaxScreen();
		//
//		if(WindowState != wsMaximized)
//		{
//			btnMax->Picture->Bitmap	= NULL;
//			btnMax->Picture			= NULL;
//			btnMax->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Mid]);
//		}
//		else if(WindowState != wsMinimized)//200622//if(WindowState == wsMaximized)
//		{
//			btnMax->Picture->Bitmap	= NULL;
//			btnMax->Picture			= NULL;
//			btnMax->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Max]);
//		}

		if(_CURRENT_WORKMODE == "DOCUMENT")
		{
			if(IMGSCREEN2->Picture->Bitmap->Width != 0 && m_dDocFactor > 0)
			{
				//201223//
				//===================================================
				//화면 중앙
				m_nSrcWidth   	= (int)((double)IMGSCREEN2->Width/m_dDocFactor);
				m_nSrcHeight  	= (int)((double)IMGSCREEN2->Height/m_dDocFactor);
				realLeft     	= (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
				realTop      	= (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);
				//===================================================

				func_DrawImage();//201209//이미지 확대 후 FormResize 시 배율 유지//공주//funcFullView();
			}
		}

		funcMovingForm();
	}
}
