AnsiString __fastcall TfrmMain::func_ConvertLandcdToAddress(AnsiString _landcd)
{
	AnsiString selectemdnm = "";
	AnsiString selectrinm  = "";
	AnsiString selectricd  = _landcd.SubString(9,2);//191123
	AnsiString jibun       = "";
	AnsiString san, bobn, bubn;
	AnsiString address     = "";

	selectemdnm = frmSql->func_ConvertUmdCDtoNM(_landcd.SubString(1,8));//210204//#LOADING_TEST//func_ConvertEmdCDtoNM(_landcd.SubString(1,8));
	if(selectricd != "00") selectrinm  = frmSql->func_ConvertRiCDtoNM(_landcd.SubString(1,10));//210204//#LOADING_TEST//func_ConvertRiCDtoNM(_landcd.SubString(1,10));
	jibun = _landcd.SubString(11,9);
	san   = jibun.SubString(1,1);
	bobn  = jibun.SubString(2,4);
	bubn  = jibun.SubString(6,4);
	if(san == "2") san = "산";
	else san = "";

	while(bobn.SubString(1,1) == "0") bobn.Delete(1,1);
	while(bubn.SubString(1,1) == "0") bubn.Delete(1,1);

	jibun = san;
	if(bubn != "") jibun = jibun + bobn + "-" + bubn;
	else jibun = jibun + bobn ;
	if(selectrinm != "")
	{
		if(jibun != "")
			address = selectemdnm + " " + selectrinm + " " + jibun;
		else
			address = selectemdnm + " " + selectrinm;
	}
	else
	{
		if(jibun != "")
			address = selectemdnm + " " + jibun;
		else
			address = selectemdnm;
	}

	return address;
}
//---------------------------------------------------------------------------

AnsiString __fastcall TfrmMain::func_ConvertEmdCDtoNM(AnsiString selectemdcd)
{
	AnsiString emdnm = "";
	AnsiString emdcd;
	int emdcount = m_v_READEMD.size();
	for(int i=0; i<emdcount; i++){
		emdcd = (char*)m_v_READEMD[i].EMD_CD;
		if(emdcd == selectemdcd){
			emdnm = (char*)m_v_READEMD[i].EMD_NM;
			break;
		}
	}
	return emdnm;
}
//---------------------------------------------------------------------------

AnsiString __fastcall TfrmMain::func_ConvertRiCDtoNM(AnsiString selectricd)
{
	AnsiString rinm = "";
	AnsiString ricd;
	int ricount = m_v_READRI.size();
	for(int i=0; i<ricount; i++){
		ricd = (char*)m_v_READRI[i].RI_CD;
		if(ricd == selectricd){
			rinm = (char*)m_v_READRI[i].RI_NM;
			break;
		}
	}
	return rinm;
}
