void __fastcall TfrmMain::func_readSpatialDataFile()//공간파일 읽기..
{
	//기존에 데이터가 있으면...삭제한다.
	func_clearRealData();

//230920//SHP 표시 화면에 시군구SHP을 맞춤으로 표시할 예정으로 Factor 값을 여기에서 설정하지 않는다//
//	//210308//#LOAING_TEST//기존:func_MapRelation_Initial -> func_readSpatialDataFile -> funcReadyFormShow
//	//210308//#LOAING_TEST//변경:func_MapRelation_Initial -> funcReadyFormShow -> func_readSpatialDataFile
//	if(INIINFO.SIDOCODE == "31110")
//		m_nZoomFactor          = 4;//191125//view fit//1
//	else// if(INIINFO.SIDOCODE == "44200" || INIINFO.SIDOCODE == "44270" || INIINFO.SIDOCODE == "44760")
//		m_nZoomFactor          = 2;//191125//view fit//1
//	//210308//m_nZoomFactor          = 4;//191125//1;
//	//funcSetZoomBarPos(false);
//	btnZoomTrackBar->Value = m_nZoomFactor;
	AnsiString mapRoot = frmMain->ROOTPATH + "MAP\\" + _SIDOCODE + "\\";

//240321//INItoDB//
//	readinterval        = SIDOINI->ReadInteger("READ INTERVAL","INTERVAL",0);
//	readinterval        = readinterval + 20;
	readinterval		= 20 + 5;

	AnsiString filename = mapRoot + "기본.HMF";
	if(FileExists(filename)){
		FILE *rfBasic = fopen(filename.c_str(), "rb");
		fseek(rfBasic, readinterval, SEEK_CUR);

		fread(&m_MBR, sizeof(MBR), 1, rfBasic);
		fclose(rfBasic);

		m_geoCenterPoint.x = (m_MBR.xmin + m_MBR.xmax)/2;
		m_geoCenterPoint.y = (m_MBR.ymin + m_MBR.ymax)/2;

//=============================================================================
//230920//지적도 처음 로딩 시, MBR을 기준으로 화면에 맞는 Zoom Level을 찾아라!
		double _lfRatioX;
		double _lfRatioY;
		double templfRatio;
		_lfRatioX   = fabs((IMGSCREEN1->Width) / (m_MBR.xmax - m_MBR.xmin));
		_lfRatioY   = fabs((IMGSCREEN1->Height) / (m_MBR.ymax - m_MBR.ymin));
		//비율 계산...
		if(_lfRatioX < _lfRatioY) templfRatio = _lfRatioX;
		else templfRatio = _lfRatioY;
		funcGetFitZoomFactor(templfRatio);
		btnZoomTrackBar->Value = m_nZoomFactor;
//=============================================================================

	}
	else{
		//220203//본 함수 종료후에 팝업처리//Application->Terminate();
		return ;
	}

	m_v_READEMD.clear();
	//지번파일 읽기
	filename = mapRoot + "읍면동경계.HMF";
	int recordcount, shpType;
	bool doublecheck;

	if(FileExists(filename)){
		FILE *rfEmd = fopen(filename.c_str(), "rb");

		fseek(rfEmd, readinterval, SEEK_CUR);
		fread(&recordcount, 4, 1, rfEmd);
		fread(&shpType, 4, 1, rfEmd);
		for(int i=0; i<recordcount; i++){
			memset(&tempReadEmd, 0x00, sizeof(READEMD));
			fread(&tempReadEmd, sizeof(tempReadEmd), 1, rfEmd);
			doublecheck = false;
			if(m_v_READEMD.size() == 0){
				m_v_READEMD.push_back(tempReadEmd);
			}
			else{
				for(int j=0; j<(int)m_v_READEMD.size(); j++){
					if(m_v_READEMD[j].EMD_CD == tempReadEmd.EMD_CD){
						doublecheck = true;
						break;
					}
				}
				if(doublecheck == false){
					m_v_READEMD.push_back(tempReadEmd);
				}
			}
		}
		fclose(rfEmd);
	}
	else{
		//220203//본 함수 종료후에 팝업처리//Application->Terminate();
		return ;
	}
	//=======================================================

	int count;
	m_v_READJIBUN.clear();
	filename = mapRoot + "지번.HMF";
	if(FileExists(filename)){
		FILE *rfJibun = fopen(filename.c_str(), "rb");
		fseek(rfJibun, readinterval, SEEK_CUR);

		AnsiString emdcd, emdnm, ricd, rinm, bunji, landcd, jibunindex;
		for(int i=0; i<(int)m_v_READEMD.size(); i++){
			fread(&count, 4, 1, rfJibun);
			for(int j=0; j<count; j++){
				memset(&tempReadJibun, 0x00, sizeof(READJIBUN));
				fread(&tempReadJibun, sizeof(READJIBUN), 1, rfJibun);
				m_v_READJIBUN.push_back(tempReadJibun);
			}
		}
		fclose(rfJibun);
	}

	mShowLPCount  = 0;
	///지적도 열기
	count = frmSql->m_v_STRUCTCODECONVERTLP.size();
	if(count > 0){
		mShowLPCount = count;
		for(int i=0; i<mShowLPCount; i++){
			if(FileExists(mapRoot + frmSql->m_v_STRUCTCODECONVERTLP[i].korname + ".HMF")){
				if(frmSql->m_v_STRUCTCODECONVERTLP[i].thema == "LP")
					func_readRealData("LP",frmSql->m_v_STRUCTCODECONVERTLP[i].korname, mapRoot + frmSql->m_v_STRUCTCODECONVERTLP[i].korname + ".HMF");
				//=============================================================
				//231018//GAGAMLAYER in LandArchive//
				//=============================================================
				else if(frmSql->m_v_STRUCTCODECONVERTLP[i].thema == "ETC")
					func_readRealData("ETC",frmSql->m_v_STRUCTCODECONVERTLP[i].korname, mapRoot + frmSql->m_v_STRUCTCODECONVERTLP[i].korname + ".HMF");
				//=============================================================
			}
		}
	}
	else{
		//220203//본 함수 종료후에 팝업처리//Application->Terminate();
		return ;
	}


//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
//===========================================================
	if((int)m_vSHPPOLYEMD.size() == 0 /*|| (int)m_vSHPPOLYRI.size() == 0 //'동'만 있는 지역도 있어서 주석처리*/ || (int)m_vSHPPOLYCBND.size() == 0)
	{
		funcSetWaitWindows(false);
		//-----------------------------
		frmMsg->funcMessageDlg("파일 오류 알림:", "MAP 파일 정보(건수누락 또는 타 시군구)가 불명확합니다.", 3);
		return;
	}
//===========================================================


	//=======================================================================
	//minji@230306//공간정보 나중 loading으로 변경되었기에 아래 내용을 여기로 옮김//
	if(m_vSHPPOLYIDX0500.size() == 0 && m_vSHPPOLYIDX0600.size() == 0
	&& m_vSHPPOLYIDX1000.size() == 0 && m_vSHPPOLYIDX1200.size() == 0
	&& m_vSHPPOLYIDX3000.size() == 0 && m_vSHPPOLYIDX6000.size() == 0)
	{
		chkIndexAll->Enabled 	= false;
		chkIndex500->Enabled 	= false;
		chkIndex600->Enabled 	= false;
		chkIndex1000->Enabled 	= false;
		chkIndex1200->Enabled 	= false;
		chkIndex3000->Enabled 	= false;
		chkIndex6000->Enabled 	= false;
		lbl500->Enabled 		= false;
		lbl600->Enabled 		= false;
		lbl1000->Enabled 		= false;
		lbl1200->Enabled 		= false;
		lbl3000->Enabled 		= false;
		lbl6000->Enabled 		= false;
	}
	else
	{
		chkIndexAll->Enabled 	= true;
		if(m_vSHPPOLYIDX0500.size() > 0)
		{
			chkIndex500->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스0500", "");
			if(configindex < 0) return;
			chkIndex500->Checked	= m_vCONFIGLP[configindex].showuse;
		}
		if(m_vSHPPOLYIDX0600.size() > 0)
		{
			chkIndex600->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스0600", "");
			if(configindex < 0) return;
			chkIndex600->Checked	= m_vCONFIGLP[configindex].showuse;
		}
		if(m_vSHPPOLYIDX1000.size() > 0)
		{
			chkIndex1000->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스1000", "");
			if(configindex < 0) return;
			chkIndex1000->Checked	= m_vCONFIGLP[configindex].showuse;
		}
		if(m_vSHPPOLYIDX1200.size() > 0)
		{
			chkIndex1200->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스1200", "");
			if(configindex < 0) return;
			chkIndex1200->Checked	= m_vCONFIGLP[configindex].showuse;
		}
		if(m_vSHPPOLYIDX3000.size() > 0)
		{
			chkIndex3000->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스3000", "");
			if(configindex < 0) return;
			chkIndex3000->Checked	= m_vCONFIGLP[configindex].showuse;
		}
		if(m_vSHPPOLYIDX6000.size() > 0)
		{
			chkIndex6000->Enabled 	= true;
			int configindex = func_ConfigIndexAlloc(1,"인덱스6000", "");
			if(configindex < 0) return;
			chkIndex6000->Checked	= m_vCONFIGLP[configindex].showuse;
		}
	}
	//=======================================================================


	if(PROGRAM_START)
	{
		if(m_bJijukLoading)//210204//#LOADING_TEST//
		{
			if(_SELECTREALLANDCD.Length() == 0)
			{
				int nJibunIndex = func_readJibunIndex(m_asSearchPnu) - 1;
				if(nJibunIndex > -1)
				{
					if(m_vSHPPOLYCBND[nJibunIndex].x > 0 && m_vSHPPOLYCBND[nJibunIndex].y > 0)
					{
						m_geoCenterPoint.x = m_vSHPPOLYCBND[nJibunIndex].x;
						m_geoCenterPoint.y = m_vSHPPOLYCBND[nJibunIndex].y;

						m_nZoomFactor	= 8;//220105//
					}
				}
			}

			//
			func_DrawImagePaint();
		}
	}
}
