void __fastcall TfrmMain::func_readRealData(AnsiString theme, AnsiString layer, AnsiString fname)
{
	FILE *readfile = fopen(fname.c_str(), "rb");
	fseek(readfile, readinterval, SEEK_CUR);

	int m_nShapeType, m_nRecords;
	fread(&m_nRecords, 4, 1, readfile);
	fread(&m_nShapeType, 4, 1, readfile);
	double area,centerx,centery;
	bool success = false;
	if(theme == "LP"){
		//=======================================================
		//210315//아래와 같은 이유로 여기를 주석처리하면 읍면동경계 Draw 정보를 못 가져온다//
		//동지역경계를 못 가져옴//210204//#LOADING_TEST
		//m_v_READEMD은 func_readSpatialDataFile에서 읍면동경계.HMF 파일로 가져온다//
		m_v_READEMD.clear();//210315//
		if(layer == "읍면동경계"){
			m_STANDARDEMD.m_nRecords   = m_nRecords;
			m_STANDARDEMD.m_nShapeType = m_nShapeType;
			m_v_READEMD.reserve(m_nRecords);

			AnsiString _emdcd;
			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadEmd, 0x00, sizeof(READEMD));
				fread(&tempReadEmd, sizeof(tempReadEmd), 1, readfile);
//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
				_emdcd	= (char*)tempReadEmd.EMD_CD;
				if(_emdcd.AnsiPos(_SIDOCODE) == 0)
					continue;
//===========================================================
				m_v_READEMD.push_back(tempReadEmd);
			}
			memset(&tempReadEmd, 0x00, sizeof(READEMD));

//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
			if((int)m_v_READEMD.size() == 0)
				success	= false;
			else
//===========================================================
				success = true;
		}
		else if(layer == "리경계"){
			m_STANDARDRI.m_nRecords   = m_nRecords;
			m_STANDARDRI.m_nShapeType = m_nShapeType;
			m_v_READRI.reserve(m_nRecords);
			AnsiString _ricd;
			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadRi, 0x00, sizeof(READRI));
				fread(&tempReadRi, sizeof(tempReadRi), 1, readfile);
//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
				_ricd	= (char*)tempReadRi.RI_CD;
				if(_ricd.AnsiPos(_SIDOCODE) == 0)
					continue;
//===========================================================
				m_v_READRI.push_back(tempReadRi);
			}
			memset(&tempReadRi, 0x00, sizeof(READRI));
//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
			if((int)m_v_READRI.size() == 0)
				success	= false;
			else
//===========================================================
				success = true;
		}
		else if(layer == "지적도"){
			m_STANDARDCBND.m_nRecords   = m_nRecords;
			m_STANDARDCBND.m_nShapeType = m_nShapeType;
			m_v_READCBND.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadCbnd, 0x00, sizeof(READCBND));
				fread(&tempReadCbnd, sizeof(tempReadCbnd), 1, readfile);

				//241205//#CenterPoint#//
				//bCenterPoint = false//tempReadCbnd.centerx	= fabs(tempReadCbnd.centerx);
				//bCenterPoint = false//tempReadCbnd.centery	= fabs(tempReadCbnd.centery);

				m_v_READCBND.push_back(tempReadCbnd);
			}
			memset(&tempReadCbnd, 0x00, sizeof(READCBND));
//===========================================================
//[v1.0.0.7]//241126//다른 시군 MAP을 참조하는 경우//
			if((int)m_v_READCBND.size() == 0)
				success	= false;
			else
//===========================================================
				success = true;
		}
		//191114_LAYER_DOGWAK
		else if(layer == "인덱스0500"){
			m_STANDARDIDX0500.m_nRecords   = m_nRecords;
			m_STANDARDIDX0500.m_nShapeType = m_nShapeType;
			m_v_READIDX0500.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx0500, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx0500, sizeof(tempReadIdx0500), 1, readfile);
				m_v_READIDX0500.push_back(tempReadIdx0500);
			}
			memset(&tempReadIdx0500, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
		else if(layer == "인덱스0600"){
			m_STANDARDIDX0600.m_nRecords   = m_nRecords;
			m_STANDARDIDX0600.m_nShapeType = m_nShapeType;
			m_v_READIDX0600.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx0600, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx0600, sizeof(tempReadIdx0600), 1, readfile);
				m_v_READIDX0600.push_back(tempReadIdx0600);
			}
			memset(&tempReadIdx0600, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
		else if(layer == "인덱스1000"){
			m_STANDARDIDX1000.m_nRecords   = m_nRecords;
			m_STANDARDIDX1000.m_nShapeType = m_nShapeType;
			m_v_READIDX1000.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx1000, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx1000, sizeof(tempReadIdx1000), 1, readfile);
				m_v_READIDX1000.push_back(tempReadIdx1000);
			}
			memset(&tempReadIdx1000, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
		else if(layer == "인덱스1200"){
			m_STANDARDIDX1200.m_nRecords   = m_nRecords;
			m_STANDARDIDX1200.m_nShapeType = m_nShapeType;
			m_v_READIDX1200.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx1200, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx1200, sizeof(tempReadIdx1200), 1, readfile);
				m_v_READIDX1200.push_back(tempReadIdx1200);
			}
			memset(&tempReadIdx1200, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
		else if(layer == "인덱스3000"){
			m_STANDARDIDX3000.m_nRecords   = m_nRecords;
			m_STANDARDIDX3000.m_nShapeType = m_nShapeType;
			m_v_READIDX3000.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx3000, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx3000, sizeof(tempReadIdx3000), 1, readfile);
				m_v_READIDX3000.push_back(tempReadIdx3000);
			}
			memset(&tempReadIdx3000, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
		else if(layer == "인덱스6000"){
			m_STANDARDIDX6000.m_nRecords   = m_nRecords;
			m_STANDARDIDX6000.m_nShapeType = m_nShapeType;
			m_v_READIDX6000.reserve(m_nRecords);

			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadIdx6000, 0x00, sizeof(READINDEXMAP));
				fread(&tempReadIdx6000, sizeof(tempReadIdx6000), 1, readfile);
				m_v_READIDX6000.push_back(tempReadIdx6000);
			}
			memset(&tempReadIdx6000, 0x00, sizeof(READINDEXMAP));
			success = true;
		}
	}
//=============================================================================
//231018//GAGAMLAYER in LandArchive//
//=============================================================================
	else if(theme == "ETC"){
		if(layer == "가감대장"){
			m_STANDARDGAGAM.m_nRecords   = m_nRecords;
			m_STANDARDGAGAM.m_nShapeType = m_nShapeType;
			m_v_READGAGAM.reserve(m_nRecords);

			AnsiString _landcd;
			for(int i=0; i<m_nRecords; i++){
				memset(&tempReadGagam, 0x00, sizeof(READGAGAM));
				fread(&tempReadGagam, sizeof(tempReadGagam), 1, readfile);
				m_v_READGAGAM.push_back(tempReadGagam);
			}
			memset(&tempReadGagam, 0x00, sizeof(READGAGAM));
			success = true;
		}
	}
//=============================================================================

	if(success == true){
		//공간정보 읽기..
		if(m_nShapeType == 3 || m_nShapeType == 5) func_readPolyData(layer,m_nRecords,readfile,m_nShapeType);
		else func_readPointData(layer,m_nRecords,readfile);
	}

	fclose(readfile);
}
