void __fastcall TfrmMain::func_readPointData(AnsiString layer, int nRecords, FILE *readfile)
{
	GPoint temppoint;
	int pointCount;
	READPOINTS _readpoint;
	AnsiString label, nmdc, dpnse, mnnm, slno, rncd;

	if(layer == "읍면동경계"){
		m_vSHPPOLYEMD.reserve(nRecords);
	}
	else if(layer == "리경계"){
		m_vSHPPOLYRI.reserve(nRecords);
	}
	else if(layer == "지적도"){
		m_vSHPPOLYCBND.reserve(nRecords);
	}

	AnsiString reallabel;
	for(int i = 0; i < nRecords; ++i){
		SHPPoly.m_nID        = -1;
		memset(&SHPPoly.m_MBR, 0x00, sizeof(MBR));
		SHPPoly.m_nNumParts  = -1;
		SHPPoly.m_nNumPoints = -1;
		SHPPoly.m_vParts.clear();
		SHPPoly.m_vPoints.clear();
		SHPPoly.m_nShow      = false;
		SHPPoly.x            = 0.0;
		SHPPoly.y            = 0.0;
		SHPPoly.label        = "";
		SHPPoly.area         = 0.0;

		fread(&_readpoint, sizeof(READPOINTS), 1, readfile);
		SHPPoly.x            = _readpoint.x;
		SHPPoly.y            = _readpoint.y;

		SHPPoly.m_nID   = i;

		if(layer == "읍면동경계"){
			label         = (char*)m_v_READEMD[i].EMD_NM;
			SHPPoly.label = label;
			m_vSHPPOLYEMD.push_back(SHPPoly);
		}
		else if(layer == "리경계"){
			label         = (char*)m_v_READRI[i].RI_NM;
			SHPPoly.label = label;
			m_vSHPPOLYRI.push_back(SHPPoly);
		}
		else if(layer == "지적도"){
			label         = (char*)m_v_READCBND[i].JIBUN;
			SHPPoly.label = label;
			m_vSHPPOLYCBND.push_back(SHPPoly);
		}

		SHPPoly.m_nID        = -1;
		memset(&SHPPoly.m_MBR, 0x00, sizeof(MBR));
		SHPPoly.m_nNumParts  = -1;
		SHPPoly.m_nNumPoints = -1;
		SHPPoly.m_vParts.clear();
		SHPPoly.m_vPoints.clear();
		SHPPoly.m_nShow      = false;
		SHPPoly.x            = 0.0;
		SHPPoly.y            = 0.0;
		SHPPoly.label        = "";
		SHPPoly.area         = 0.0;
	}
}
