//---------------------------------------------------------------------------
double __fastcall TfrmMain::func_Area2(GPoint a, GPoint b, GPoint c)
{
	return	(b.x - a.x) * (c.y - a.y) -	(c.x - a.x) * (b.y - a.y);
}
//---------------------------------------------------------------------------
GPoint __fastcall TfrmMain::func_FindCG(vector<GPoint>& vPoint, double *area)
{
	GPoint	gPoint;
	GPoint	point;
	double  A2, Areasum2 = 0;        /* Partial area sum */

	for(int i = 1; i < ((int)vPoint.size() - 1); ++i)
	{
		point = func_Centroid3(vPoint[0], vPoint[i], vPoint[i+1]);
		A2 = func_Area2(vPoint[0], vPoint[i], vPoint[i+1]);

		gPoint.x += A2 * point.x;
		gPoint.y += A2 * point.y;

		Areasum2 += A2;
	}

	if(gPoint.x != 0){
		gPoint.x /= 3 * Areasum2;
		gPoint.y /= 3 * Areasum2;
		*area = Areasum2;
	}
	else *area = 0;
	return gPoint;
}
//---------------------------------------------------------------------------
GPoint __fastcall TfrmMain::func_Centroid3(GPoint a, GPoint b, GPoint c)
{
	GPoint result;
	result.x = a.x + b.x + c.x;
	result.y = a.y + b.y + c.y;

	return result;
}
//---------------------------------------------------------------------------
AnsiString __fastcall TfrmMain::func_CodeTableIndexAlloc(AnsiString layer)
{
	int size;
	size = m_vCODETABLE.size();

	AnsiString result = "";

	if(size > 0){
		AnsiString temp;
		int head, mid, tail, prev;
		head = 0;
		tail = size;
		mid  = (tail + head)/2;

		if(layer.Length() == 6){
			temp = m_vCODETABLE[mid].code_no ;

			while(1){
				if(layer < temp) tail = mid;
				else if(layer > temp) head = mid;
				else{
					result = m_vCODETABLE[mid].code_nm ;
					break;
				}
				prev = mid;
				mid = (head + tail)/2;

				temp = m_vCODETABLE[mid].code_no ;

				if(prev == mid){
					break;
				}
			}
		}
		else if(layer.Length() == 5){
			temp = m_vCODETABLE[mid].code_main;

			while(1){
				if(layer < temp) tail = mid;
				else if(layer > temp) head = mid;
				else{
					result = m_vCODETABLE[mid].code_nm ;
					break;
				}
				prev = mid;
				mid = (head + tail)/2;

				temp = m_vCODETABLE[mid].code_main ;

				if(prev == mid){
					break;
				}
			}
		}
	}
	return result;
}
