void __fastcall TfrmMain::_2DEngineObject_pnsFunc_DrawSelectCbnd(int gbn, HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	int remarkcolor = m_MAININI.SELECT_REMARK_COLOR;
	int remarkalpha = m_MAININI.SELECT_REMARK_ALPHA;
	int remarkwidth = m_MAININI.SELECT_REMARK_WIDTH;

	TRect  mbrRect, rectBuffer;

	// 화면 밖이면 그리지 않는다..
	mbrRect = func_WorldToDevice(m_MBR);
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)) return;

	int r = GetRValue(remarkcolor);
	int g = GetGValue(remarkcolor);
	int b = GetBValue(remarkcolor);

	gdp::Pen pen(gdp::Color(r, g, b), remarkwidth);
	int i,j,k;

	int size = m_vSelectedID.size();
	AnsiString tempString;

	TPoint tmpPoint;
	GPoint gPoint;

	for( i = 0; i < size; ++i){
		int _pyonum1 = -1;
		int _pyonum2 = -1;
		int	_selectIndex = -1;
		int _buildsue = -1;
		_selectIndex  = -1;
		AnsiString _landcd = (char*)m_v_READCBND[m_vSelectedID[i]].PNU;
		int memoIndex = -1;

		if(gbn == 2){
			TPoint pScrPoints;
			gdp::Point *points = new gdp::Point[m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumPoints];
			for( j = 0; j < m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumPoints; ++j){
				pScrPoints  = func_WorldToDevice(m_vSHPPOLYCBND[m_vSelectedID[i]].m_vPoints[j]);
				points[j].X = pScrPoints.x;
				points[j].Y = pScrPoints.y;
			}

			int* pParts = new int[m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumParts];
			for(j = 0; j < m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumParts; ++j){
				if(j == m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumParts - 1)
					pParts[j] = m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumPoints - m_vSHPPOLYCBND[m_vSelectedID[i]].m_vParts[j];
				else
					pParts[j] = m_vSHPPOLYCBND[m_vSelectedID[i]].m_vParts[j + 1] - m_vSHPPOLYCBND[m_vSelectedID[i]].m_vParts[j];
			}

			int r1 = GetRValue(remarkcolor);
			int g1 = GetGValue(remarkcolor);
			int b1 = GetBValue(remarkcolor);

			gdp::SolidBrush solidbrushNew(gdp::Color(remarkalpha, r1, g1, b1));
			gdp::GraphicsPath Path;
			int indexcount = 0;
			for(j = 0; j < m_vSHPPOLYCBND[m_vSelectedID[i]].m_nNumParts; ++j){
				Path.AddPolygon(&points[indexcount], pParts[j]);
				indexcount = indexcount + pParts[j];
			}

			if(cbSelectJibunSolid->Checked == true) graphics.FillPath(&solidbrushNew, &Path);
			graphics.DrawPath(&pen,&Path);

			delete []pParts;
			delete []points;

			if(currentModeShow1 == false && currentModeShow8 == true)//191212
			{
				//라벨 출력하자..추가 2017.01.06
				int configindex = func_ConfigIndexAlloc(1,"지적도", "");
				if(configindex > -1){
					AnsiString select_labelfont = m_vCONFIGLP[configindex].labelfont;
					String select_temp;

					HFONT select_m_font;
					HFONT select_hOldFont, select_hOldFontEtc;
					int select_nHeight, select_nWidth, select_fsize, select_r, select_g, select_b;
					select_fsize   = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];

					select_nHeight = select_fsize;

					if(currentModeShow8 == true){
						if(cbViewRoad->Checked == false) remarkcolor = m_MAININI.SELECT_USEJIBUN_COLOR;
						else remarkcolor = m_MAININI.SELECT_UNUSEJIBUN_COLOR;
					}
					else remarkcolor = m_MAININI.SELECT_UNUSEJIBUN_COLOR;

					//remarkcolor = 16777215 - (int)remarkcolor;

					select_nWidth  = 0;
					if(m_MAININI.WIDTHRATE != 1) select_nWidth = func_widthRateCalc(select_nHeight);

					select_m_font = ::CreateFont(select_nHeight, 0, 0, 0, 600, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, select_labelfont.c_str());

					select_hOldFont = (HFONT)::SelectObject(_pDC,select_m_font);

					select_r = GetRValue(remarkcolor);
					select_g = GetGValue(remarkcolor);
					select_b = GetBValue(remarkcolor);

					gdp::Font select_font(_pDC, select_m_font);
					graphics.SetSmoothingMode(gdp::SmoothingModeAntiAlias);
					graphics.SetInterpolationMode(gdp::InterpolationModeHighQualityBicubic);

					gdp::StringFormat select_format;
					if(m_MAININI.LABEL_ALIGNMENT == 0){
						select_format.SetAlignment(gdp::StringAlignmentNear);
						select_format.SetLineAlignment(gdp::StringAlignmentNear);
					}
					else{
						select_format.SetAlignment(gdp::StringAlignmentCenter);
						select_format.SetLineAlignment(gdp::StringAlignmentCenter);
					}

					gdp::SolidBrush select_solidbrush(gdp::Color(select_r, select_g, select_b));

					TPoint select_vPoint, select_tmpPoint;
					select_vPoint.x = m_vSHPPOLYCBND[m_vSelectedID[i]].x;
					select_vPoint.y = m_vSHPPOLYCBND[m_vSelectedID[i]].y;
					GPoint select_gPoint = select_vPoint;
					select_tmpPoint = func_WorldToDevice(select_gPoint);

					tempString = m_vSHPPOLYCBND[m_vSelectedID[i]].label;

					if(memoIndex > -1){
						tempString = tempString + "(★)";
					}

					select_temp = tempString;

					gdp::PointF select_ptText(select_tmpPoint.x, select_tmpPoint.y);//241129//

					graphics.DrawString(select_temp.w_str(), -1, &select_font, select_ptText, &select_format, &select_solidbrush);

					::SelectObject(_pDC, select_hOldFont);
					::DeleteObject(select_m_font);
				}
			}
		}
		//=====================================================================
		//241219//
		//=====================================================================
		else//gbn==1
		{
			gPoint.x = m_vSHPPOLYCBND[m_vSelectedID[0]].x;
			gPoint.y = m_vSHPPOLYCBND[m_vSelectedID[0]].y;
			m_tPOINT.sPoint = func_WorldToDevice(gPoint);
		}
		//=====================================================================
	}
}
