void __fastcall TfrmMain::func_DrawPaintImageCbndPolygon(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	int configindex = func_ConfigIndexAlloc(1,"지적도", "");
	if(configindex < 0) return;
	int gagamconfigindex = func_ConfigIndexAlloc(1,"가감대장", "");
	if(INI_B_GAGAM && gagamconfigindex < 0) return;

	int showuse           = m_vCONFIGLP[configindex].showuse;
	int showlevel         = m_vCONFIGLP[configindex].showlevel;
	int linewidth         = m_vCONFIGLP[configindex].linewidth;

	if(showuse != 1) return;
	if(showlevel > m_nZoomFactor) return;

	TRect  mbrRect, rectBuffer;

	// 화면 밖이면 그리지 않는다..
	mbrRect = func_WorldToDevice(m_MBR);
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)) return;

	//=========================================================
	int alpha;
	if(currentModeShow8 == true){
		if(cbViewRoad->Checked == false || (cbViewRoad->Checked == true && m_nZoomFactor < 10)) alpha = m_MAININI.IMAGE_PLUS_ALPHABLEND_VALUE;
		else alpha = m_MAININI.IMAGE_MINUS_ALPHABLEND_VALUE;
	}
	else alpha = m_MAININI.IMAGE_MINUS_ALPHABLEND_VALUE;

	//=========================================================
	int	linecolor;
	int labelcolor;
	if(currentModeShow8 == true){
		if(cbViewRoad->Checked == true){
			linecolor  = m_MAININI.UN_USE_IMAGE_JIJUKLINECOLOR;
			labelcolor = m_MAININI.UN_USE_IMAGE_JIBUNCOLOR;
		}
		else{
			linecolor  = m_MAININI.USE_IMAGE_JIJUKLINECOLOR;
			labelcolor = m_MAININI.USE_IMAGE_JIBUNCOLOR;
		}
	}
	else{
		linecolor 	= m_MAININI.UN_USE_IMAGE_JIJUKLINECOLOR;
		labelcolor 	= m_MAININI.UN_USE_IMAGE_JIBUNCOLOR;
	}
	int r 	= GetRValue(linecolor);
	int g 	= GetGValue(linecolor);
	int b 	= GetBValue(linecolor);
	int r1 	= GetRValue(labelcolor);
	int g1 	= GetGValue(labelcolor);
	int b1 	= GetBValue(labelcolor);
	gdp::Pen pen(gdp::Color(r, g, b), linewidth);
	gdp::Pen penSelected(gdp::Color(0, 0, 255), linewidth);//241116//
	gdp::SolidBrush solidbrush(gdp::Color(255, 255, 255, m_MAININI.IMAGE_PLUS_ALPHABLEND_VALUE));//231113//가감대장.필지는 그냥 투명하게 처리하자/

	//=========================================================
	int gagambrushcolor	= m_vCONFIGLP[gagamconfigindex].brushcolor;
	int gagambrushR 	= GetRValue(gagambrushcolor);
	int gagambrushG 	= GetGValue(gagambrushcolor);
	int gagambrushB 	= GetBValue(gagambrushcolor);
	int gagambrushSelectR 	= 255;
	int gagambrushSelectG 	= 190;
	int gagambrushSelectB 	= 125;
	gdp::SolidBrush solidbrushGagam(gdp::Color(alpha, gagambrushR, gagambrushG, gagambrushB));
	gdp::SolidBrush solidbrushGagamSelect(gdp::Color(alpha, gagambrushSelectR, gagambrushSelectG, gagambrushSelectB));

	//=========================================================
	AnsiString labelfont = m_vCONFIGLP[configindex].labelfont;
	HFONT m_font;
	HFONT hOldFont, hOldFontEtc;
	int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
	int nWidth  = 0;
	int nHeight = fsize;
	int showfactor  = m_MAININI.SHOW_FACTOR_SCALE;
	double showarea = m_MAININI.SHOW_FACTOR_LIMITAREA;

	if(m_MAININI.WIDTHRATE != 1) nWidth = func_widthRateCalc(nHeight);

	m_font   = ::CreateFont(nHeight, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, labelfont.c_str());
	hOldFont = (HFONT)::SelectObject(_pDC,m_font);

	gdp::Font font(_pDC, m_font);
	graphics.SetSmoothingMode(gdp::SmoothingModeAntiAlias);
	graphics.SetInterpolationMode(gdp::InterpolationModeHighQualityBicubic);
	gdp::StringFormat format;

	if(m_MAININI.LABEL_ALIGNMENT == 0){
		format.SetAlignment(gdp::StringAlignmentNear);
		format.SetLineAlignment(gdp::StringAlignmentNear);
	}
	else{
		format.SetAlignment(gdp::StringAlignmentCenter);
		format.SetLineAlignment(gdp::StringAlignmentCenter);
	}


	//=========================================================
	int m_nRecords = m_STANDARDCBND.m_nRecords;
	int i,j,k;
	String temp;
	AnsiString _landcd;
	AnsiString tempString;

	//===========================================================
	for( i = 0; i < m_nRecords; ++i){
		mbrRect = func_WorldToDevice(m_vSHPPOLYCBND[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			m_vSHPPOLYCBND[i].m_nShow = false;
			continue;
		}

		_landcd   = (char*)m_v_READCBND[i].PNU;
		TPoint pScrPoints;
		gdp::Point *points = new gdp::Point[m_vSHPPOLYCBND[i].m_nNumPoints];
		for( j = 0; j < m_vSHPPOLYCBND[i].m_nNumPoints; j++){
			pScrPoints  = func_WorldToDevice(m_vSHPPOLYCBND[i].m_vPoints[j]);
			points[j].X = pScrPoints.x;
			points[j].Y = pScrPoints.y;
		}

		int* pParts = new int[m_vSHPPOLYCBND[i].m_nNumParts];
		for(j = 0; j < m_vSHPPOLYCBND[i].m_nNumParts; j++){
			if(j == m_vSHPPOLYCBND[i].m_nNumParts - 1){
				pParts[j] = m_vSHPPOLYCBND[i].m_nNumPoints - m_vSHPPOLYCBND[i].m_vParts[j];
			}
			else{
				pParts[j] = m_vSHPPOLYCBND[i].m_vParts[j + 1] - m_vSHPPOLYCBND[i].m_vParts[j];
			}
		}

		gdp::GraphicsPath Path;
		int indexcount = 0;
		for(j = 0; j < (int)m_vSHPPOLYCBND[i].m_nNumParts; j++){
			Path.AddPolygon(&points[indexcount], pParts[j]);
			indexcount = indexcount + pParts[j];
		}

		//===========================================================================
		// 가감대장 필지 채색(선택 or 전체)//
		//===========================================================================
		//선택한 사업에 포함되는 지번일때 컬러 다르게 표시//
		if(INI_B_GAGAM && (int)m_vGAGAMLANDLISTALL.size() > 0)
		{
			int nGagamLandListIndex = -1;
			nGagamLandListIndex	= funcGetIndexGagamLandList(_landcd);
			if(nGagamLandListIndex > -1)//현재 선택된 가감대장에 포함된 필지인지 확인//
			{
				graphics.FillPath(&solidbrushGagamSelect, &Path);//255, 190, 125
			}
			else
			{
				nGagamLandListIndex	= funcGetIndexGagamLandListAll(_landcd);
				if(nGagamLandListIndex > -1)//가감대장 전체 필지에 포함된 필지인지 확인//
				{
					graphics.FillPath(&solidbrushGagam, &Path);//DB.BrushColor
				}
			}
		}

		//===========================================================================
		//241116//선택지번이 있는 경우 LineColor 다르게//
		//===========================================================================
		if((int)m_vSelectedID.size() > 0)
		{
			if( i == m_vSelectedID[0])
				graphics.DrawPath(&penSelected,&Path);
			else
				graphics.DrawPath(&pen,&Path);
		}
		else
		{
			graphics.DrawPath(&pen,&Path);
        }
		//===========================================================================

		m_vSHPPOLYCBND[i].m_nShow = true;

		delete []pParts;
		delete []points;
	}
}
