void __fastcall TfrmMain::func_DrawPaintImageCbndLabel(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	int configindex = func_ConfigIndexAlloc(1,"지적도", "");
	if(configindex < 0) return;
	if(m_vCONFIGLP[configindex].showuse != 1) return;
	if(m_vCONFIGLP[configindex].showlevel > m_nZoomFactor) return;
	if(m_vCONFIGLP[configindex].labeluse != 1) return;
	if(m_vCONFIGLP[configindex].labelscale > m_nZoomFactor) return;

	int  labelcolor;
	if(currentModeShow8 == true){
		if(cbViewRoad->Checked == true) labelcolor = m_MAININI.UN_USE_IMAGE_JIBUNCOLOR;
		else labelcolor = m_MAININI.USE_IMAGE_JIBUNCOLOR;
	}
	else labelcolor = m_MAININI.UN_USE_IMAGE_JIBUNCOLOR;

	AnsiString labelfont = m_vCONFIGLP[configindex].labelfont;

	TRect  mbrRect, rectBuffer;

	// 화면 밖이면 그리지 않는다..
	mbrRect = func_WorldToDevice(m_MBR);
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rect))
		return;

	HFONT m_font;
	HFONT hOldFont, hOldFontEtc;
	int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
	int nWidth	= 0;
	int nHeight	= fsize;
	if(m_MAININI.WIDTHRATE != 1) nWidth = func_widthRateCalc(nHeight);

	int r = GetRValue(labelcolor);
	int g = GetGValue(labelcolor);
	int b = GetBValue(labelcolor);

	int i,j,k;

	AnsiString tempString;
	int m_nRecords  = m_STANDARDCBND.m_nRecords;
	int showfactor  = m_MAININI.SHOW_FACTOR_SCALE;
	double showarea = m_MAININI.SHOW_FACTOR_LIMITAREA;

	AnsiString _landcd, view;

	m_font   = ::CreateFont(nHeight, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, labelfont.c_str());
	hOldFont = (HFONT)::SelectObject(_pDC,m_font);

	gdp::Font font(_pDC, m_font);
	graphics.SetSmoothingMode(gdp::SmoothingModeAntiAlias);
	graphics.SetInterpolationMode(gdp::InterpolationModeHighQualityBicubic);
	gdp::StringFormat format;

	int m_nKindofDocCount      = -1;
	int m_nMemoLandkeySelectIndex = -1;

	if(m_MAININI.LABEL_ALIGNMENT == 0){
		format.SetAlignment(gdp::StringAlignmentNear);
		format.SetLineAlignment(gdp::StringAlignmentNear);
	}
	else{
		format.SetAlignment(gdp::StringAlignmentCenter);
		format.SetLineAlignment(gdp::StringAlignmentCenter);
	}

	String temp;
	int _landIndex;

	gdp::SolidBrush solidbrush(gdp::Color(255, 255, 255, 0));

	//*******************************************************************************
	//문서&메모 아이콘//
	int _index = 0;
	int _index1 = 0;
	for( i = 0; i < m_nRecords; ++i){
		mbrRect = func_WorldToDevice(m_vSHPPOLYCBND[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			m_vSHPPOLYCBND[i].m_nShow = false;
			continue;
		}

		TPoint vPoint, tmpPoint;
		GPoint gPoint;
		bool m_bExistsData = false;

		vPoint.x = m_vSHPPOLYCBND[i].x;
		vPoint.y = m_vSHPPOLYCBND[i].y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);

		_landcd  = (char*)m_v_READCBND[i].PNU;
		//M//191025//m_asSelectLandCd = _landcd;//M

		if(m_vSelectedID.size() == 0){
			r = GetRValue(labelcolor);
			g = GetGValue(labelcolor);
			b = GetBValue(labelcolor);
		}
		else{
			if( i == m_vSelectedID[0]){
				r = 255;
				g = 0;
				b = 0;
			}
			else{
				r = GetRValue(labelcolor);
				g = GetGValue(labelcolor);
				b = GetBValue(labelcolor);
			}
		}

		tempString = m_vSHPPOLYCBND[i].label;

		temp = tempString;
		if(currentModeShow8 == true){
			if(cbViewRoad->Checked == false){
				if(m_bJibunDblLine == true){
					gdp::SolidBrush solidbrush1(gdp::Color(255, 255, 255));
					gdp::PointF ptText1(tmpPoint.x-1, (tmpPoint.y - nHeight/2));

					gdp::SolidBrush solidbrush2(gdp::Color(255, 255, 255));
					gdp::PointF ptText2(tmpPoint.x  , (tmpPoint.y - nHeight/2)-1);

					gdp::SolidBrush solidbrush3(gdp::Color(255, 255, 255));
					gdp::PointF ptText3(tmpPoint.x+1, (tmpPoint.y - nHeight/2));

					gdp::SolidBrush solidbrush4(gdp::Color(255, 255, 255));
					gdp::PointF ptText4(tmpPoint.x  , (tmpPoint.y - nHeight/2)+1);

					graphics.DrawString(temp.w_str(), -1, &font, ptText1, &format, &solidbrush1);
					graphics.DrawString(temp.w_str(), -1, &font, ptText2, &format, &solidbrush2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText3, &format, &solidbrush3);
					graphics.DrawString(temp.w_str(), -1, &font, ptText4, &format, &solidbrush4);

					gdp::SolidBrush solidbrush(gdp::Color(0, 0, 0));
					gdp::PointF ptText(tmpPoint.x, tmpPoint.y - nHeight/2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
				}
				else{
					gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
					gdp::PointF ptText(tmpPoint.x, tmpPoint.y - nHeight/2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
				}
			}
			else{
				gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
				gdp::PointF ptText(tmpPoint.x, tmpPoint.y - nHeight/2);
				graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
			}
		}
		else{
			gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
			gdp::PointF ptText(tmpPoint.x, tmpPoint.y - nHeight/2);
			graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
		}
		//=================================================================

		m_vSHPPOLYCBND[i].m_nShow = true;
	}

	::SelectObject(_pDC, hOldFont);
	::DeleteObject(m_font);
}
