void __fastcall TfrmMain::func_DrawPaintImageCbndSymbol(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	//=========================================================
	//241211//가감대장 심볼 표시//
	//=========================================================
	int configgagamindex = func_ConfigIndexAlloc(1,"가감대장", "");
	if(configgagamindex < 0) return;
	AnsiString labelfont = m_vCONFIGLP[configgagamindex].labelfont;
	int gagamlabelcolor = m_vCONFIGLP[configgagamindex].labelcolor;
	if(currentModeShow8 == true) 	gagamlabelcolor = 65535;
	int r = GetRValue(gagamlabelcolor);
	int g = GetGValue(gagamlabelcolor);
	int b = GetBValue(gagamlabelcolor);
	//=========================================================

	TRect  mbrRect, rectBuffer;
	// 화면 밖이면 그리지 않는다..
	mbrRect = func_WorldToDevice(m_MBR);
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rect))
		return;

	HFONT m_font;
	HFONT hOldFont, hOldFontEtc;
	int fsize			= m_vCONFIGLP[configgagamindex].fontsize[m_nZoomFactor-1];
	int nWidth	= 0;
	int nHeight	= fsize;
	if(m_MAININI.WIDTHRATE != 1) nWidth = func_widthRateCalc(nHeight);

	m_font   = ::CreateFont(nHeight, 0, 0, 0, FW_BOLD/*241213*/, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, labelfont.c_str());
	hOldFont = (HFONT)::SelectObject(_pDC,m_font);

	gdp::Font font(_pDC, m_font);
	graphics.SetSmoothingMode(gdp::SmoothingModeAntiAlias);
	graphics.SetInterpolationMode(gdp::InterpolationModeHighQualityBicubic);
	gdp::StringFormat format;

	if(m_MAININI.LABEL_ALIGNMENT == 0){
		format.SetAlignment(gdp::StringAlignmentNear);
		format.SetLineAlignment(gdp::StringAlignmentNear);
	}
	else{
		format.SetAlignment(gdp::StringAlignmentCenter);
		format.SetLineAlignment(gdp::StringAlignmentCenter);
	}

	int m_nRecords  = m_STANDARDCBND.m_nRecords;
	int showfactor  = m_MAININI.SHOW_FACTOR_SCALE;
	double showarea = m_MAININI.SHOW_FACTOR_LIMITAREA;
	AnsiString _landcd, view;
	int m_nKindofDocCount      = -1;
	AnsiString tempString;
	String temp;
	gdp::SolidBrush solidbrushGagam(gdp::Color(r, g, b));

	//=====================================================================
	//241120//#DOCPOI#//울주군팀장님[REQ]//문서POI-사용자별 설정으로 표시//처음에는 설정정보 없으므로 Default는 QRYCHECK Value//
	//=====================================================================
	AnsiString      asPoiDocNo	= "";
	if(frmChangeMenu->m_nChkPoiCnt == 1 &&  frmChangeMenu->m_nChkPoiDocNo > 0)
		asPoiDocNo.sprintf("%02d", frmChangeMenu->m_nChkPoiDocNo);
	//=====================================================================


	//*******************************************************************************
	//문서 아이콘//
	for(int i = 0; i < m_nRecords; ++i){
		mbrRect = func_WorldToDevice(m_vSHPPOLYCBND[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			m_vSHPPOLYCBND[i].m_nShow = false;
			continue;
		}

		TPoint vPoint, tmpPoint;
		GPoint gPoint;
		bool m_bExistsData = false;

		vPoint.x = m_vSHPPOLYCBND[i].x;
		vPoint.y = m_vSHPPOLYCBND[i].y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);

		_landcd  = (char*)m_v_READCBND[i].PNU;

		//=================================================================
		// KINDOFSYMBOL
		//=================================================================
		int nIndex  = func_readKindOfSymbolIndex(_landcd);
		int x	= tmpPoint.x;
		int y	= tmpPoint.y;
		int gapx, gapy;

		if(nIndex > -1){
			UnicodeString	usPoiFileName;

			//=============================================================
			//191122//인덱스별 문서 개수 표시//
			int COUNT = func_readKindofSymbolCount(nIndex);
			if(COUNT > 0)
			{
				//=========================================================
				//241211//가감대장 (대표)필지 심볼 표시//
				//=========================================================
				int nGagamIndex	= -1;

				//241212//문서심볼.가감대장 체크 시에만 가감대장 사업지구명(TB_DOCUMENT20.DOC_NAME) 표시//
				if(frmMain->INIINFO.B_DOCPOI[20])
					nGagamIndex	= funcGetIndexGagamList(_landcd);

				if( (int)m_vSelectedID.size() > 0 && i == m_vSelectedID[0]){
					if( !asPoiDocNo.IsEmpty() )
					{
						//=========================================================
						//241211//가감대장 심볼 표시//개별필지는 최대 확대 단계에서만 표시//
						//=========================================================
						if(asPoiDocNo != "20")
						{
							usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconPoiDoc" + asPoiDocNo + ".png";
						}
						else
						{
							if( (m_nZoomFactor == 10) || (m_nZoomFactor < 10 && nGagamIndex > -1) )
								usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconPoiDoc" + asPoiDocNo + ".png";
						}
					}
					else
					{
						usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconDocCnt" + IntToStr(COUNT) + "_0.png";
					}

					if(FileExists(usPoiFileName)){
						gdp::Image image(usPoiFileName.w_str());
						gapx 	= image.GetWidth();
						gapy 	= image.GetHeight();
						x    = tmpPoint.x - gapx/2;
						y    = tmpPoint.y - nHeight - gapy;
						graphics.DrawImage(&image, x, y, gapx, gapy);//이미지그대로출력
					}
				}
				else{
					if( !asPoiDocNo.IsEmpty() )
					{
						//=========================================================
						//241211//가감대장 심볼 표시//개별필지는 최대 확대 단계에서만 표시//
						//=========================================================
						if(asPoiDocNo != "20")
						{
							usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconPoiDoc" + asPoiDocNo + "s.png";
						}
						else
						{
							if( (m_nZoomFactor == 10) || (m_nZoomFactor < 10 && nGagamIndex > -1) )
								usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconPoiDoc" + asPoiDocNo + "s.png";
						}
					}
					else
					{
						usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconDocCnt" + IntToStr(COUNT) + ".png";
					}

					if(FileExists(usPoiFileName)){
						gdp::Image image(usPoiFileName.w_str());
						gapx 	= image.GetWidth();
						gapy 	= image.GetHeight();
						x    = tmpPoint.x - gapx/2;
						y    = tmpPoint.y - nHeight - gapy;
						graphics.DrawImage(&image, x, y, gapx, gapy);//이미지그대로출력
					}
				}

				//=========================================================
				//241211//가감대장 (대표필지)심볼 표시//
				//=========================================================
				if(nGagamIndex > -1)
				{
					String 		sGagam	= "";
					AnsiString  asGagamLabel	= "";
					AnsiString  asDocName		= (char*)m_vGAGAMLIST[nGagamIndex].DOC_NAME;
					AnsiString  asKwonNo		= (char*)m_vGAGAMLIST[nGagamIndex].KWON_NO;
					AnsiString  asSurvEtc		= (char*)m_vGAGAMLIST[nGagamIndex].SURV_ETC;
					if( asSurvEtc.IsEmpty() )
						asGagamLabel.sprintf("[%s]%s", asKwonNo, asDocName);
					else
						asGagamLabel.sprintf("[%s][%s]%s", asKwonNo, asSurvEtc, asDocName);
					sGagam	= asGagamLabel;

					gdp::PointF ptText(x, tmpPoint.y - nHeight - gapy - 8);
					graphics.DrawString(sGagam.w_str(), -1, &font, ptText , &format, &solidbrushGagam);
				}
				//=========================================================


				TPoint _tpoint;
				GPoint _gpoint;

				frmSql->m_vKINDOFSYMBOLDATA[nIndex].m_nID = nIndex;
				_tpoint.x = x;
				_tpoint.y = y;
				_gpoint   = func_DeviceToWorld(_tpoint);
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].m_MBR.xmin = _gpoint.x;
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].m_MBR.ymax = _gpoint.y;

				_tpoint.x = x + gapx;
				_tpoint.y = y + gapy;
				_gpoint   = func_DeviceToWorld(_tpoint);
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].m_MBR.xmax = _gpoint.x;
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].m_MBR.ymin = _gpoint.y;

				_tpoint.x = x + gapx/2;
				_tpoint.y = y + gapy/2;
				_gpoint   = func_DeviceToWorld(_tpoint);
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].x          = _gpoint.x;
				frmSql->m_vKINDOFSYMBOLDATA[nIndex].y          = _gpoint.y;
			}
		}
		//=================================================================
	}

	::SelectObject(_pDC, hOldFont);
	::DeleteObject(m_font);
}
