void __fastcall TfrmMain::func_DrawPaintImageRi(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	int configindex = func_ConfigIndexAlloc(1,"리경계", "");
	if(configindex < 0) return;

	int showuse           = m_vCONFIGLP[configindex].showuse;
	int showlevel         = m_vCONFIGLP[configindex].showlevel;
	int labeluse          = m_vCONFIGLP[configindex].labeluse;
	int labelscale        = m_vCONFIGLP[configindex].labelscale;
	int labelcolor        = m_vCONFIGLP[configindex].labelcolor;
	AnsiString labelfont  = m_vCONFIGLP[configindex].labelfont;
	int brushuse          = m_vCONFIGLP[configindex].brushuse;
	int brushcolor        = m_vCONFIGLP[configindex].brushcolor;
	int lineuse           = m_vCONFIGLP[configindex].lineuse;
	int linecolor         = m_vCONFIGLP[configindex].linecolor;
	int linewidth         = m_vCONFIGLP[configindex].linewidth;

	if(showuse != 1) return;
	if(showlevel > m_nZoomFactor) return;
	if(brushuse != 1 && lineuse != 1) return;

	TRect  mbrRect, rectBuffer;

	// 화면 밖이면 그리지 않는다..
	mbrRect = func_WorldToDevice(m_MBR);
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)) return;

	int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];

	if(lineuse == 1){
	}
	else{
		linecolor  = 0;
		linewidth  = 1;
	}

	int r = GetRValue(linecolor);
	int g = GetGValue(linecolor);
	int b = GetBValue(linecolor);

	gdp::Pen pen(gdp::Color(r, g, b), linewidth);
	pen.SetDashStyle(gdp::DashStyleDot);
	//pen.SetLineJoin(gdp::LineJoinRound);     //꺽이는부분처리
	//pen.SetEndCap(gdp::LineCapArrowAnchor);
	int i,j,k;

	int m_nRecords = m_STANDARDRI.m_nRecords;

	r = GetRValue(labelcolor);
	g = GetGValue(labelcolor);
	b = GetBValue(labelcolor);
	//gdp::SolidBrush solidbrush(gdp::Color(r, g, b));

	String temp;

	HFONT m_font = ::CreateFont(fsize, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, labelfont.c_str());
	HFONT hOldFont = (HFONT)::SelectObject(_pDC,m_font);
	HFONT hOldFontEtc;

	gdp::Font font(_pDC, m_font);

	gdp::StringFormat format;
	format.SetAlignment(gdp::StringAlignmentCenter);
	//format.SetLineAlignment(gdp::StringAlignmentCenter);

	TPoint tmpPoint;
	GPoint gPoint;
	for( i = 0; i < m_nRecords; ++i){
		mbrRect = func_WorldToDevice(m_vSHPPOLYRI[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			m_vSHPPOLYRI[i].m_nShow = false;
			continue;
		}

		TPoint pScrPoints;
		gdp::Point *points = new gdp::Point[m_vSHPPOLYRI[i].m_nNumPoints];
		for( j = 0; j < m_vSHPPOLYRI[i].m_nNumPoints; ++j){
			pScrPoints  = func_WorldToDevice(m_vSHPPOLYRI[i].m_vPoints[j]);
			points[j].X = pScrPoints.x;
			points[j].Y = pScrPoints.y;
		}

		int* pParts = new int[m_vSHPPOLYRI[i].m_nNumParts];
		for(j = 0; j < m_vSHPPOLYRI[i].m_nNumParts; ++j){
			if(j == m_vSHPPOLYRI[i].m_nNumParts - 1)
				pParts[j] = m_vSHPPOLYRI[i].m_nNumPoints - m_vSHPPOLYRI[i].m_vParts[j];
			else
				pParts[j] = m_vSHPPOLYRI[i].m_vParts[j + 1] - m_vSHPPOLYRI[i].m_vParts[j];
		}

		int indexcount = 0;
		for(j = 0; j < m_vSHPPOLYRI[i].m_nNumParts; ++j){
			if(brushuse == true) graphics.DrawPolygon(&pen, &points[indexcount], pParts[j]);
			else graphics.DrawLines(&pen, &points[indexcount], pParts[j]);

			indexcount = indexcount + pParts[j];
		}

		if(labeluse == 1 && labelscale <= m_nZoomFactor){
			gPoint.x = m_vSHPPOLYRI[i].x;
			gPoint.y = m_vSHPPOLYRI[i].y;

			tmpPoint = func_WorldToDevice(gPoint);
			AnsiString tempString = m_vSHPPOLYRI[i].label;
			//gdp::PointF ptText(tmpPoint.x, tmpPoint.y - fsize/2);
			temp = tempString;

			if(currentModeShow8 == true){
				if(cbViewRoad->Checked == false){
					gdp::SolidBrush solidbrush1(gdp::Color(255, 255, 255));
					gdp::PointF ptText1(tmpPoint.x-1, (tmpPoint.y - fsize/2));

					gdp::SolidBrush solidbrush2(gdp::Color(255, 255, 255));
					gdp::PointF ptText2(tmpPoint.x  , (tmpPoint.y - fsize/2)-1);

					gdp::SolidBrush solidbrush3(gdp::Color(255, 255, 255));
					gdp::PointF ptText3(tmpPoint.x+1, (tmpPoint.y - fsize/2));

					gdp::SolidBrush solidbrush4(gdp::Color(255, 255, 255));
					gdp::PointF ptText4(tmpPoint.x  , (tmpPoint.y - fsize/2)+1);

					graphics.DrawString(temp.w_str(), -1, &font, ptText1, &format, &solidbrush1);
					graphics.DrawString(temp.w_str(), -1, &font, ptText2, &format, &solidbrush2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText3, &format, &solidbrush3);
					graphics.DrawString(temp.w_str(), -1, &font, ptText4, &format, &solidbrush4);

					gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
					gdp::PointF ptText(tmpPoint.x, tmpPoint.y - fsize/2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
				}
				else{
					gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
					gdp::PointF ptText(tmpPoint.x, tmpPoint.y - fsize/2);
					graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
				}
			}
			else{
				gdp::SolidBrush solidbrush(gdp::Color(r, g, b));
				gdp::PointF ptText(tmpPoint.x, tmpPoint.y - fsize/2);
				graphics.DrawString(temp.w_str(), -1, &font, ptText , &format, &solidbrush);
			}
		}
		m_vSHPPOLYRI[i].m_nShow = true;
		delete []pParts;
		delete []points;
	}
	::SelectObject(_pDC, hOldFont);
	::DeleteObject(m_font);
}
