//===========================================================================
// 폐쇄지적도 아이콘 표시//
//===========================================================================
void __fastcall TfrmMain::func_DrawPaintImageDoc07IndexLabel(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	//--------
	TRect  mbrRect, rectBuffer;

	//191123//폐쇄지적도 인덱스 아이콘//
	m_vDOC07INDEXICON.clear();
	memset(&tempDOC07INDEXICON, 0x00, sizeof(POISPATIAL_STRUCT));

	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = m_ResultDocument07Index.size();

	for(int i = 0; i < m_nRecords; ++i){
		MBR tmbr;
		tmbr.xmin = m_ResultDocument07Index[i].X - 10;
		tmbr.ymin = m_ResultDocument07Index[i].Y - 10;
		tmbr.xmax = m_ResultDocument07Index[i].X + 10;
		tmbr.ymax = m_ResultDocument07Index[i].Y + 10;
		mbrRect = func_WorldToDevice(tmbr);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			continue;
		}

		TPoint vPoint, tmpPoint;
		GPoint gPoint;

		vPoint.x = m_ResultDocument07Index[i].X;
		vPoint.y = m_ResultDocument07Index[i].Y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);

		int x, y;
		int gapx, gapy;
		AnsiString tempString = "";
		tempString = (char*)m_ResultDocument07Index[i].SUR;
		tempString = tempString + (char*)m_ResultDocument07Index[i].SCALE;
		tempString = tempString + (char*)m_ResultDocument07Index[i].DOHO_BON;
		//=============================================================
		//191122//인덱스별 문서 개수 표시//
		int nIndex = funcGetDoc07Index(tempString);
		if(nIndex > -1)
		{
			UnicodeString 	usPoiFileName = frmMain->ROOTPATH + L"RES\\POI\\iconDoc7Cnt" + IntToStr(nIndex) + ".png";

			if(nIndex > 0)
			{
				if(FileExists(usPoiFileName)){
					gdp::Image image(usPoiFileName.w_str());
					x    = tmpPoint.x + image.GetWidth()/2;
					y    = tmpPoint.y - image.GetHeight();
					graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
					gapx 	= image.GetWidth();
					gapy 	= image.GetHeight();
				}
			}
		}

		//191122//인덱스별 문서 아이콘 클릭//
		if(nIndex > -1)
		{
			AnsiString asStr = "";
			asStr = m_ResultDocument07Index[nIndex].SUR;
			//한글라벨링하기전에는 시군구코드가 필요함//asStr = asStr.SubString(6, asStr.Length() - 5);
			asStr = asStr + "-" + m_ResultDocument07Index[nIndex].SCALE;
			asStr = asStr + "-" + m_ResultDocument07Index[nIndex].DOHO_BON;
			memcpy(tempDOC07INDEXICON.LAND_KEY, asStr.c_str(), sizeof(tempDOC07INDEXICON.LAND_KEY));
			tempDOC07INDEXICON.m_nID = _index;
			TPoint _tpoint;
			GPoint _gpoint;

			_tpoint.x = x;
			_tpoint.y = y;
			_gpoint   = func_DeviceToWorld(_tpoint);
			tempDOC07INDEXICON.m_MBR.xmin = _gpoint.x;
			tempDOC07INDEXICON.m_MBR.ymax = _gpoint.y;

			_tpoint.x = x + gapx;
			_tpoint.y = y + gapy;
			_gpoint   = func_DeviceToWorld(_tpoint);
			tempDOC07INDEXICON.m_MBR.xmax = _gpoint.x;
			tempDOC07INDEXICON.m_MBR.ymin = _gpoint.y;

			_tpoint.x = x + gapx/2;
			_tpoint.y = y + gapy/2;
			_gpoint   = func_DeviceToWorld(_tpoint);
			tempDOC07INDEXICON.x          = _gpoint.x;
			tempDOC07INDEXICON.y          = _gpoint.y;

			m_vDOC07INDEXICON.push_back(tempDOC07INDEXICON);
			memset(&tempDOC07INDEXICON, 0x00, sizeof(POISPATIAL_STRUCT));
			_index++;
		}
	}
}
