void __fastcall TfrmMain::func_DrawPaintImageMemo(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	//--------
	UnicodeString 	usPoiFileName1 = frmMain->ROOTPATH + L"RES\\POI\\iconMemo1.png";
	UnicodeString 	usPoiFileName2 = frmMain->ROOTPATH + L"RES\\POI\\iconMemo2.png";

	int configindex = func_ConfigIndexAlloc(1,"메모", "");
	if(configindex < 0) return;

	int showuse           = m_vCONFIGLP[configindex].showuse;
	int showlevel         = m_vCONFIGLP[configindex].showlevel;
	int labeluse          = m_vCONFIGLP[configindex].labeluse;
	int labelscale        = m_vCONFIGLP[configindex].labelscale;
	int labelcolor        = m_vCONFIGLP[configindex].labelcolor;
	AnsiString labelfont  = m_vCONFIGLP[configindex].labelfont;
	int brushuse          = m_vCONFIGLP[configindex].brushuse;
	int brushcolor        = m_vCONFIGLP[configindex].brushcolor;
	int lineuse           = m_vCONFIGLP[configindex].lineuse;
	int linecolor         = m_vCONFIGLP[configindex].linecolor;
	int linewidth         = m_vCONFIGLP[configindex].linewidth;

	if(showuse != 1) return;
	if(showlevel > m_nZoomFactor) return;
	if(brushuse != 1 && lineuse != 1) return;

	int labelR = GetRValue(labelcolor);
	int labelG = GetGValue(labelcolor);
	int labelB = GetBValue(labelcolor);
	int lineR = GetRValue(linecolor);
	int lineG = GetGValue(linecolor);
	int lineB = GetBValue(linecolor);
	int pathR = GetRValue(brushcolor);
	int pathG = GetGValue(brushcolor);
	int pathB = GetBValue(brushcolor);

	//--------
	TRect  mbrRect, rectBuffer;
	//---
	TRect rect;
	rect.Left   = 0;
	rect.Top    = 0;
	rect.Right  = IMGSCREEN1->Width;
	rect.Bottom = IMGSCREEN1->Height;

	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = frmSql->m_vALLMEMOINFO.size();

	for(int i = 0; i < m_nRecords; ++i){
		if(frmSql->m_vALLMEMOINFO[i].DATA_CNT >= 3)//EXCEPT MEMOPOLY
			continue;

		MBR tmbr;
//#NOPHOTO#//사장님Req//191224
//		tmbr.xmin = frmSql->m_vALLMEMOINFO[i].X - (double)18 / m_lfZoomFactor / m_lfRatio;
//		tmbr.ymin = frmSql->m_vALLMEMOINFO[i].Y - (double)18 / m_lfZoomFactor / m_lfRatio;
//		tmbr.xmax = frmSql->m_vALLMEMOINFO[i].X;
//		tmbr.ymax = frmSql->m_vALLMEMOINFO[i].Y;
		tmbr.xmin = frmSql->m_vALLMEMOINFO[i].X - (double)9 / m_lfZoomFactor / m_lfRatio;
		tmbr.ymin = frmSql->m_vALLMEMOINFO[i].Y - (double)9 / m_lfZoomFactor / m_lfRatio;
		tmbr.xmax = frmSql->m_vALLMEMOINFO[i].X + (double)9 / m_lfZoomFactor / m_lfRatio;
		tmbr.ymax = frmSql->m_vALLMEMOINFO[i].Y + (double)9 / m_lfZoomFactor / m_lfRatio;
		mbrRect = func_WorldToDevice(tmbr);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			continue;
		}

		TPoint vPoint, tmpPoint;
		GPoint gPoint;

		vPoint.x = frmSql->m_vALLMEMOINFO[i].X;
		vPoint.y = frmSql->m_vALLMEMOINFO[i].Y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);

		int x, y;
		int gapx, gapy;

		//=============================================================
		AnsiString tempString = (char*)frmSql->m_vALLMEMOINFO[i].POI_KEY;
		//메모아이콘 표시//
		int nIndex = funcGetMemoIndex(tempString);
		if(nIndex > -1)
		{
			//---
			if(m_nSelectMemoIndex > -1 && i == m_nSelectMemoIndex)
			{
				if(FileExists(usPoiFileName2)){
					gdp::Image image(usPoiFileName2.w_str());
					gapx 	= image.GetWidth();
					gapy 	= image.GetHeight();
					x    = tmpPoint.x;
					y    = tmpPoint.y - gapy/2;
					graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
				}
				//200207//메모에서 영역은 안 그린다//메모에 영역이 있다면 영역인거다//
//				if(frmSql->m_vALLMEMOINFO[m_nSelectMemoIndex].DATA_CNT >= 3)//200120
//				{
//					TPoint	tPoint;
//					int nSize = (int)frmMemo->m_vMEMOVECTOR[i].VECTOR.size();
//					if(nSize > 0)
//					{
//						gdp::Point *points = new gdp::Point[nSize];
//						for(int j = 0; j < nSize; j++){
//							tPoint  = func_WorldToDevice(frmMemo->m_vMEMOVECTOR[i].VECTOR[j]);
//							points[j].X = tPoint.x;
//							points[j].Y = tPoint.y;
//						}
//						graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);
//						gdp::Pen pen(gdp::Color(lineR, lineG, lineB), m_MAININI.SELECT_REMARK_WIDTH);
//						pen.SetDashStyle(gdp::DashStyleCustom);
//						gdp::SolidBrush solidbrushNew(gdp::Color(m_MAININI.SELECT_REMARK_ALPHA, pathR, pathG, pathB));
//						gdp::GraphicsPath Path;
//						Path.AddPolygon(points, nSize);
////200207//선택한 메모일때는 brushuse 사용한다//					if(brushuse)
//							graphics.FillPath(&solidbrushNew, &Path);
//						delete []points;
//					}
//				}
			}
			//---
			else
			{
			    if(FileExists(usPoiFileName1)){
				    gdp::Image image(usPoiFileName1.w_str());
					gapx 	= image.GetWidth();
					gapy 	= image.GetHeight();
				    x    = tmpPoint.x;// - gapx/2;
				    y    = tmpPoint.y - gapy/2;
				    graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
				}
			}

			//---
			AnsiString label = (char*)frmSql->m_vALLMEMOINFO[i].TITLE;
			String sLabel	= label;
			HDC memDC1 = ::CreateCompatibleDC(IMGSCREEN1->Canvas->Handle);

			int x1, y1;
			int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
			HFONT m_font = ::CreateFont(fsize, 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, label.c_str());
			HFONT hOldFont = (HFONT)::SelectObject(memDC1,m_font);
			gdp::Font font(memDC1, m_font);
			gdp::SolidBrush solidbrush(gdp::Color(255, labelR, labelG, labelB));
			gdp::StringFormat format;
			format.SetAlignment(gdp::StringAlignmentNear);//StringAlignmentNear, StringAlignmentCenter, StringAlignmentFar
			format.SetLineAlignment(gdp::StringAlignmentNear);
			x1 = x + gapx/2 + 4;
			y1 = y - (gapy - fsize)/2;
			gdp::PointF ptText(x1, y1);
			graphics.DrawString(sLabel.w_str(), -1, &font, ptText , &format, &solidbrush);
			::SelectObject(memDC1, hOldFont);
			::DeleteObject(m_font);
		}
	}
}
