//===========================================================================
// 포토 아이콘 표시//
//===========================================================================
void __fastcall TfrmMain::func_DrawPaintImagePhoto(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

	//--------
	UnicodeString 	usPoiFileName1 = frmMain->ROOTPATH + L"RES\\POI\\iconPhoto1.png";
	UnicodeString 	usPoiFileName2 = frmMain->ROOTPATH + L"RES\\POI\\iconPhoto2.png";

	//--------
	TRect  mbrRect, rectBuffer;
	//---
	TRect rect;
	rect.Left   = 0;
	rect.Top    = 0;
	rect.Right  = IMGSCREEN1->Width;
	rect.Bottom = IMGSCREEN1->Height;

	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = frmSql->m_vALLPHOTOINFO.size();

	for(int i = 0; i < m_nRecords; ++i){
		MBR tmbr;
		tmbr.xmin = frmSql->m_vALLPHOTOINFO[i].X;
		tmbr.ymin = frmSql->m_vALLPHOTOINFO[i].Y - (double)18 / m_lfZoomFactor / m_lfRatio;
		tmbr.xmax = frmSql->m_vALLPHOTOINFO[i].X + (double)18 / m_lfZoomFactor / m_lfRatio;
		tmbr.ymax = frmSql->m_vALLPHOTOINFO[i].Y;
		mbrRect = func_WorldToDevice(tmbr);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			continue;
		}

		TPoint vPoint, tmpPoint;
		GPoint gPoint;

		vPoint.x = frmSql->m_vALLPHOTOINFO[i].X;
		vPoint.y = frmSql->m_vALLPHOTOINFO[i].Y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);

		int x, y;
		int gapx, gapy;

		if(m_nSelectPhotoIndex > -1 && i == m_nSelectPhotoIndex){
			AnsiString asPoiKey = frmSql->m_vALLPHOTOINFO[m_nSelectPhotoIndex].POI_KEY;
			//200109
//			frmMemo->funcReadMemoVector(asPoiKey);
//
//			GPoint	gPoint;
//			TPoint	tPoint;
//			int nSize = (int)frmMemo->m_vMEMOVECTOR.size();
//			gdp::Point *points = new gdp::Point[nSize];
//			for(int j = 0; j < nSize; j++){
//				gPoint.x = frmMemo->m_vMEMOVECTOR[j].X;
//				gPoint.y = frmMemo->m_vMEMOVECTOR[j].Y;
//				tPoint  = func_WorldToDevice(gPoint);
//				points[j].X = tPoint.x;
//				points[j].Y = tPoint.y;
//			}
//			graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);
//			gdp::Pen pen(gdp::Color(0, 0, 255), m_MAININI.SELECT_REMARK_WIDTH);
//			gdp::SolidBrush solidbrushNew(gdp::Color(m_MAININI.SELECT_REMARK_ALPHA, 0, 0, 255));
//			gdp::GraphicsPath Path;
//			Path.AddPolygon(points, nSize);
//			graphics.FillPath(&solidbrushNew, &Path);
//			graphics.DrawPath(&pen,&Path);
//			delete []points;
		}

		//=============================================================
		AnsiString tempString = (char*)frmSql->m_vALLPHOTOINFO[i].POI_KEY;
		//포토아이콘 표시//
		int nIndex = funcGetPhotoIndex(tempString);
		if(nIndex > -1)
		{
			if(FileExists(usPoiFileName1)){
				gdp::Image image(usPoiFileName1.w_str());
				gapx 	= image.GetWidth();
				gapy 	= image.GetHeight();
				x    = tmpPoint.x - gapx/2;
				y    = tmpPoint.y + gapy/2;
				graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
			}


			//
			AnsiString tempString = (char*)frmSql->m_vALLPHOTOINFO[i].POI_KEY;
			//사진아이콘 표시//
			int nIndex = funcGetMemoIndex(tempString);
			if(nIndex == -1)//메모도 있는 경우, 라벨이 중복된다.//메모없는 경우만 라벨표시//
			{
				AnsiString label = (char*)frmSql->m_vALLPHOTOINFO[i].TITLE;
				String sLabel	= label;
	//			bsSkinStatusPanel2->Caption = label;

				HDC memDC1 = ::CreateCompatibleDC(IMGSCREEN1->Canvas->Handle);

				int x1, y1;
				int configindex = func_ConfigIndexAlloc(1,"메모", "");
				int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
				HFONT m_font = ::CreateFont(fsize, 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, label.c_str());
				HFONT hOldFont = (HFONT)::SelectObject(memDC1,m_font);
				gdp::Font font(memDC1, m_font);
//				if(currentModeShow8)
//					gdp::SolidBrush solidbrush(gdp::Color(255, 255, 255, 255));
//				else
					gdp::SolidBrush solidbrush(gdp::Color(255, 0, 0, 255));
				gdp::StringFormat format;
				format.SetAlignment(gdp::StringAlignmentNear);//StringAlignmentNear, StringAlignmentCenter, StringAlignmentFar
				format.SetLineAlignment(gdp::StringAlignmentNear);
				x1 = x + gapx/2;
				y1 = y;
				gdp::PointF ptText(x1, y1);
				graphics.DrawString(sLabel.w_str(), -1, &font, ptText , &format, &solidbrush);
				::SelectObject(memDC1, hOldFont);
				::DeleteObject(m_font);
			}
		}
	}
}
