//===========================================================================
// 영역 표시//
//===========================================================================
void __fastcall TfrmMain::func_DrawPaintImagePoly(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

 	//--------
	UnicodeString 	usPoiFileName1 = frmMain->ROOTPATH + L"RES\\POI\\iconPoly1.png";
	UnicodeString 	usPoiFileName2 = frmMain->ROOTPATH + L"RES\\POI\\iconPoly2.png";

	int configindex = func_ConfigIndexAlloc(1,"메모", "");
	if(configindex < 0) return;

	int showuse           = m_vCONFIGLP[configindex].showuse;
	int showlevel         = m_vCONFIGLP[configindex].showlevel;
	int labeluse          = m_vCONFIGLP[configindex].labeluse;
	int labelscale        = m_vCONFIGLP[configindex].labelscale;
	int labelcolor        = m_vCONFIGLP[configindex].labelcolor;
	AnsiString labelfont  = m_vCONFIGLP[configindex].labelfont;
	int brushuse          = m_vCONFIGLP[configindex].brushuse;
	int brushcolor        = m_vCONFIGLP[configindex].brushcolor;
	int lineuse           = m_vCONFIGLP[configindex].lineuse;
	int linecolor         = m_vCONFIGLP[configindex].linecolor;
	int linewidth         = m_vCONFIGLP[configindex].linewidth;

	if(showuse != 1) return;
	if(showlevel > m_nZoomFactor) return;
	if(brushuse != 1 && lineuse != 1) return;

	int labelR 	= GetRValue(labelcolor);
	int labelG 	= GetGValue(labelcolor);
	int labelB 	= GetBValue(labelcolor);
	int pathR 	= GetRValue(brushcolor);
	int pathG 	= GetGValue(brushcolor);
	int pathB 	= GetBValue(brushcolor);
	int lineR 	= GetRValue(linecolor);
	int lineG 	= GetGValue(linecolor);
	int lineB 	= GetBValue(linecolor);
	int lineR1, lineG1, lineB1;//Selected
	int pathR1, pathG1, pathB1;//Selected

	if(currentModeShow8)
	{
		lineR1 	= 255;
		lineG1 	= 128;
		lineB1 	= 0;
		pathR1 	= 255;
		pathG1 	= 128;
		pathB1 	= 0;
	}
	else
	{
		lineR1 	= 0;
		lineG1 	= 0;
		lineB1 	= 255;
		pathR1 	= 0;
		pathG1 	= 0;
		pathB1 	= 255;
	}

	//--------
	TRect  mbrRect, rectBuffer;
	//---
	TRect rect;
	rect.Left   = 0;
	rect.Top    = 0;
	rect.Right  = IMGSCREEN1->Width;
	rect.Bottom = IMGSCREEN1->Height;

	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = frmSql->m_vMEMOPOLY.size();

	for(int i = 0; i < m_nRecords; ++i){
		MBR tmbr = frmSql->m_vMEMOPOLY[i].m_MBR;
		mbrRect = func_WorldToDevice(tmbr);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
			continue;
		}

		int x, y;
		int gapx, gapy;
		AnsiString label = frmSql->m_vMEMOPOLY[i].label;//POI_KEY
		//메모아이콘 표시//
		int nIndex = funcGetMemoIndex(label);

		//=============================================================
		AnsiString asSelectPoiKey = "";
		AnsiString asPoiKey       = "";

		if(m_nSelectMemoIndex > -1)
		{
			asSelectPoiKey = frmSql->m_vALLMEMOINFO[m_nSelectMemoIndex].POI_KEY;
		}
		if(nIndex > -1)
		{
			asPoiKey	= frmSql->m_vALLMEMOINFO[nIndex].POI_KEY;
		}
		//=============================================================


		//201109//TEST
		int linecolorDB	= frmSql->m_vALLMEMOINFO[nIndex].LINECOLOR;
		if(linecolorDB > 0)
		{
			lineR 	= GetRValue(linecolorDB);
			lineG 	= GetGValue(linecolorDB);
			lineB 	= GetBValue(linecolorDB);
		}
		else
		{
			lineR 	= GetRValue(linecolor);
			lineG 	= GetGValue(linecolor);
			lineB 	= GetBValue(linecolor);
		}
//		edtRed->Text	= lineR;
//		edtGreen->Text	= lineG;
//		edtBlue->Text	= lineB;
		//---


		//POLYGON
		GPoint	gPoint;
		TPoint	tPoint;
		int nSize = (int)frmSql->m_vMEMOPOLY[i].m_nNumPoints;
		if(nSize > 0)
		{
			gdp::Point *points = new gdp::Point[nSize];
			for(int j = 0; j < nSize; j++){
				gPoint.x = frmSql->m_vMEMOPOLY[i].m_vPoints[j].x;
				gPoint.y = frmSql->m_vMEMOPOLY[i].m_vPoints[j].y;
				tPoint  = func_WorldToDevice(gPoint);
				points[j].X = tPoint.x;
				points[j].Y = tPoint.y;
			}
			graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

			if(m_nSelectMemoIndex > -1 &&
				( (nIndex == m_nSelectMemoIndex) || (!strcmp(frmSql->m_vALLMEMOINFO[nIndex].BATCH_YN, "Y") && asSelectPoiKey.SubString(1, 17) == asPoiKey.SubString(1, 17)) ) )
			{
				gdp::Pen pen(gdp::Color(lineR1, lineG1, lineB1), linewidth);
				pen.SetDashStyle(gdp::DashStyleDash);
				gdp::SolidBrush solidbrushNew(gdp::Color(m_MAININI.SELECT_REMARK_ALPHA, pathR1, pathG1, pathB1));
				gdp::GraphicsPath Path;
				Path.AddPolygon(points, nSize);
				graphics.FillPath(&solidbrushNew, &Path);
				if(lineuse)
					graphics.DrawPath(&pen,&Path);
			}
			else
			{
				gdp::Pen pen(gdp::Color(lineR, lineG, lineB), linewidth);
				pen.SetDashStyle(gdp::DashStyleCustom);
				gdp::SolidBrush solidbrushNew(gdp::Color(m_MAININI.SELECT_REMARK_ALPHA, pathR, pathG, pathB));
				gdp::GraphicsPath Path;
				Path.AddPolygon(points, nSize);
				if(lineuse)
					graphics.DrawPath(&pen,&Path);
			}
			delete []points;
		}

		//=============================================================
		//200110//메모레이어와 아이콘까지도 분리//if( !INIINFO.B_MEMO )//메모레이어해제//
		if(nIndex > -1)
		{
			AnsiString asPoiKey	= frmSql->m_vALLMEMOINFO[nIndex].POI_KEY;

			TPoint tLblPoint;
			GPoint gLblPoint;
			tLblPoint.x = frmSql->m_vALLMEMOINFO[nIndex].X;
			tLblPoint.y = frmSql->m_vALLMEMOINFO[nIndex].Y;
			gLblPoint   = tLblPoint;
			tLblPoint = func_WorldToDevice(gLblPoint);

			if(m_nSelectMemoIndex > -1 &&
				( (nIndex == m_nSelectMemoIndex) || (!strcmp(frmSql->m_vALLMEMOINFO[nIndex].BATCH_YN, "Y") && asSelectPoiKey.SubString(1, 17) == asPoiKey.SubString(1, 17)) ) )
			{
				if(FileExists(usPoiFileName2)){
					gdp::Image image(usPoiFileName2.w_str());
					gapx 	= image.GetWidth();
					gapy 	= image.GetHeight();
					x    = tLblPoint.x;
					y    = tLblPoint.y - gapy/2;
					graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
				}
			}
			else
			{
				if(FileExists(usPoiFileName1)){
					gdp::Image image(usPoiFileName1.w_str());
					gapx 	= image.GetWidth();
					gapy 	= image.GetHeight();
					x    = tLblPoint.x;
					y    = tLblPoint.y - gapy/2;
					graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
				}
			}

			//
			label = frmSql->m_vALLMEMOINFO[nIndex].TITLE;
			//200210//TEST
			if( !strcmp(frmSql->m_vALLMEMOINFO[nIndex].BATCH_YN, "N") || (!strcmp(frmSql->m_vALLMEMOINFO[nIndex].BATCH_YN, "Y") && asPoiKey.SubString(18, 4) == "0000") )
			{
				String sLabel	= label;
				HDC memDC1 = ::CreateCompatibleDC(IMGSCREEN1->Canvas->Handle);
				int x1, y1;
				int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
				HFONT m_font = ::CreateFont(fsize, 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, label.c_str());
				HFONT hOldFont = (HFONT)::SelectObject(memDC1,m_font);
				gdp::Font font(memDC1, m_font);
				gdp::SolidBrush solidbrush(gdp::Color(255, labelR, labelG, labelB));
				gdp::StringFormat format;
				format.SetAlignment(gdp::StringAlignmentNear);
				format.SetLineAlignment(gdp::StringAlignmentNear);
				x1 = x + gapx/2 + 4;// - (label.Length() * fsize) / 2;
				y1 = y - (gapy - fsize)/2;
				gdp::PointF ptText(x1, y1);
				graphics.DrawString(sLabel.w_str(), -1, &font, ptText , &format, &solidbrush);
				::SelectObject(memDC1, hOldFont);
				::DeleteObject(m_font);
			}
        }
	}
}
//---------------------------------------------------------------------------

TRect TfrmMain::func_WorldToDevice(const MBR& _mbr)
{
	TRect  tmpRect;
	TPoint tmpPT1, tmpPT2;
	GPoint pt1, pt2;

	pt1.x = _mbr.xmin;	pt1.y = _mbr.ymin;
	pt2.x = _mbr.xmax;  pt2.y = _mbr.ymax;

	tmpPT1 = func_WorldToDevice(pt1);
	tmpPT2 = func_WorldToDevice(pt2);

	tmpRect.bottom = tmpPT1.y;
	tmpRect.left   = tmpPT1.x;
	tmpRect.top    = tmpPT2.y;
	tmpRect.right  = tmpPT2.x;
	return tmpRect;
}
//---------------------------------------------------------------------------
TPoint TfrmMain::func_WorldToDevice(const GPoint& _GPoint)
{
	TPoint tmpPoint;

	tmpPoint.x = long(m_lfRatio * (_GPoint.x - m_geoCenterPoint.x) * m_lfZoomFactor + (double)m_ptCenterPoint.x);
	tmpPoint.y = long(m_lfRatio * (m_geoCenterPoint.y - _GPoint.y) * m_lfZoomFactor + (double)m_ptCenterPoint.y);
	return tmpPoint;
}
//---------------------------------------------------------------------------
int __fastcall TfrmMain::func_ConfigIndexAlloc(int index, AnsiString layer, AnsiString layerparent)
{
	int size;
	if(index == 1)      size = m_vCONFIGLP.size();
	else return -1;

	int result = -1;

	AnsiString _layer, _layerparent, findlayer;
	int head, mid, tail, prev;
	head = 0;
	tail = size;
	mid  = (tail + head)/2;

	if(index == 1){
		_layer       = m_vCONFIGLP[mid].layername;
		_layerparent = m_vCONFIGLP[mid].layerparent;
		findlayer    = layer;
	}

	while(1){
		if(findlayer < _layer) tail = mid;
		else if(findlayer > _layer) head = mid;
		else{
			result = mid;
			break;
		}

		prev = mid;
		mid = (head + tail)/2;

		if(index == 1){
			_layer       = m_vCONFIGLP[mid].layername;
			_layerparent = m_vCONFIGLP[mid].layerparent;
		}

		if(prev == mid){
			break;
		}
	}

	return result;
}
