int __fastcall TfrmMain::func_readJibunIndex(AnsiString _landcd)
{
	AnsiString landcd;
	int size = m_v_READJIBUN.size();
	int result = -1;

	if(size > 0)
	{
	    AnsiString temp;
	    int head, mid, tail, prev;
	    head = 0;
	    tail = size;
	    mid  = (tail + head)/2;
    
	    temp   = (char*)m_v_READJIBUN[mid].LAND_CD;
		if(_landcd != ""){
		    while(1){
			    if(_landcd < temp) tail = mid;
			    else if(_landcd > temp) head = mid;
			    else{
				    result = m_v_READJIBUN[mid].JIBUNINDEX;
				    break;
			    }
			    prev = mid;
			    mid = (head + tail)/2;
			    temp = (char*)m_v_READJIBUN[mid].LAND_CD;
			    if(prev == mid){
				    break;
			    }
		    }
	    }
	}
	return result;
}
