void __fastcall TfrmMain::IMGSCREEN1MouseDown(TObject *Sender, TMouseButton Button,
		  TShiftState Shift, int X, int Y)
{
	//=======================================================
	//폼 리사이즈
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);
	int SysCommWparam = -1;

	if(SenderControl != NULL)//201228//
	{
		if(X > SenderControl->Width-8 && Y < 8)
			SysCommWparam = SC_DRAG_RESIZEUR;
		else if(X > SenderControl->Width-8)
			SysCommWparam = SC_DRAG_RESIZER;
		else if(Y < 8)
			SysCommWparam = SC_DRAG_RESIZEU;
		else
			SysCommWparam = SC_DRAG_MOVE;
	}

	if(SysCommWparam != -1 && SysCommWparam != SC_DRAG_MOVE)//FormResizing//
	{
		ReleaseCapture();
		SendMessage(Handle, WM_SYSCOMMAND, SysCommWparam, 0);

		currentWidth  = this->ClientWidth;
		currentHeight = this->ClientHeight;
	}
	//=======================================================
	else//지적도를 움직임//
	{
		if(palWait->Visible == false){
			if(Button == mbRight)//M//191025
			{
	//			startPoint.x = IMGSCREEN1->Left + IMGSCREEN1->Width;//[TODO]
	//			startPoint.y = IMGSCREEN1->Top;
	//			clickPoint.x = X;
	//			clickPoint.y = Y;

				if(IsCTRLpressed())//[TODO]항공뷰 패닝 느린 것 확인 위함//
				{
					currentModeShow8 = !currentModeShow8;
					currentModeShow1 = !currentModeShow8;

					if(palLayerSet->Visible)
					{
						//일단 항공뷰레이어 이미지를 변경하기 전이지만 반대로 생각하자!!!
						//IMGLAYERAIR==항공뷰, IMGMODECHANGEJIJUK==지적도
						//=============================================
						//241205//[레이어] 이미지 표시 설정//
						//=============================================
						funcSetImageLayer(IMGLAYERAIR, currentModeShow8, false);
						//=============================================
					}

					//=============================================
					//241205//우측 상단 [문서]-[지적도] 이미지 표시 설정//
					//=============================================
					funcSetImageModeChange(currentModeShow8);
					//=============================================

					func_DrawImagePaint();
				}
			}
			if(Button == mbLeft)//M//191029//if(Shift.Contains(ssLeft))
			{
				startPoint.x = IMGSCREEN1->Left;
				startPoint.y = IMGSCREEN1->Top;
				clickPoint.x = X;
				clickPoint.y = Y;
				if(m_eManipulationMode == Panning){//이동
					m_bFlags = true;
					GetCursorPos(&_movepoint);  //현재 마우스 좌표를 저장
					m_ptZoomWindowBR = _movepoint;

					//==========================================
					//200829//
	/*
					TRect _rctRect;
					_rctRect.Left   = 0;
					_rctRect.Top    = 0;
					_rctRect.Right  = IMGSCREEN1->Width;
					_rctRect.Bottom = IMGSCREEN1->Height;
					m_ptCenterPoint.x = (_rctRect.right - _rctRect.left)/2;
					m_ptCenterPoint.y = (_rctRect.bottom - _rctRect.top)/2;
					m_geoCenterPoint	= func_DeviceToWorld(clickPoint);
	*/
					//==========================================
				}
				else if(m_eManipulationMode == StreetGauge){//거리재기
					if(pbControl1DblClick == false)
					 {
						m_bControlFlags = true;
					 }
					else
					{
						pbControl1DblClick = false;
						m_eManipulationMode = Panning;
					}
				}
				else if(m_eManipulationMode == AreaGauge){//면적재기
					GPoint _xy;
					if(pbControl1DblClick == false){
						if(m_bControlFlags == false){
							m_bControlFlags = true;
							m_ptAreaGaugeSP = m_ptCenter = clickPoint;
							m_ptAreaGaugeLP.x = -1000; m_ptAreaGaugeLP.y = -1000;

							m_vAREA.clear();

							_xy = func_DeviceToWorld(m_ptAreaGaugeSP);
							tempAREA.x = _xy.x; tempAREA.y = _xy.y;
							m_vAREA.push_back(tempAREA);
						}
						else{
							m_ptAreaGaugeLP = clickPoint;
							_xy = func_DeviceToWorld(m_ptAreaGaugeLP);
							tempAREA.x = _xy.x; tempAREA.y = _xy.y;
							m_vAREA.push_back(tempAREA);
						}
					}
					else pbControl1DblClick = false;
				}
				else if(m_eManipulationMode == ZoomWindow){
					if(PBCONTROL1->Visible == false) PBCONTROL1->Visible = true;
					m_bFlags = true;
					m_ptZoomWindowLT = m_ptZoomWindowBR = _movepoint = clickPoint;
				}
				else if(m_eManipulationMode == SpaceRect){//191116
					if(PBSPACE->Visible == false) PBSPACE->Visible = true;
					//PBSPACEMouseDown(PBSPACE, Button, Shift, X, Y);
				}
				else if(m_eManipulationMode == MemoRect){//메모영역설정//191129
					GPoint _xy;
					if(pbControl1DblClick == false){
						memset(&tempMEMORECT, 0x00, sizeof(REALAREA_STRUCT));
						if(m_bControlFlags == false){
							m_vMEMORECT.clear();

							m_bControlFlags = true;
							m_ptMemoRectSP = m_ptMemoRectCenter = clickPoint;
							m_ptMemoRectLP.x = -1000; m_ptMemoRectLP.y = -1000;

							_xy = func_DeviceToWorld(m_ptMemoRectSP);
							if(_xy.x <= 0 || _xy.y <= 0)//200122//영역클릭하다가 값이 0으로 저장되는 경우가 있는것 같다//
							{
								m_bControlFlags = false;
								return;
							}
							if(m_vMEMORECT.size() == 0)
								tempMEMORECT.gbn	= 1;
							else
								tempMEMORECT.gbn	= 2;
							tempMEMORECT.x = _xy.x; tempMEMORECT.y = _xy.y;
							m_vMEMORECT.push_back(tempMEMORECT);
						}
						else{
							m_ptMemoRectLP = clickPoint;
							_xy = func_DeviceToWorld(m_ptMemoRectLP);
							if(_xy.x <= 0 || _xy.y <= 0)//200122//영역클릭하다가 값이 0으로 저장되는 경우가 있는것 같다//
							{
								return;
							}
							tempMEMORECT.x = _xy.x; tempMEMORECT.y = _xy.y;
							m_vMEMORECT.push_back(tempMEMORECT);
						}
					}
					//191227//TEST//더블클릭후 여기에 들어와서 해제가 되어 panning이 된다//else pbControl1DblClick = false;
				}
			}
		}
	}
}
