void __fastcall TfrmMain::IMGSCREEN1MouseMove(TObject *Sender, TShiftState Shift, int X,
		  int Y)
{
	//마우스 모양 변경
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);

	if(SenderControl != NULL)//201228//
	{
		if(X > SenderControl->Width-8 && Y < 8)
			SenderControl->Cursor = crSizeNESW;
		else if(X > SenderControl->Width-8)
			SenderControl->Cursor = crSizeWE;
		else if(Y < 8)
			SenderControl->Cursor = crSizeNS;
		else
			SenderControl->Cursor = crDefault;
	}

	if(palMiniSearchBar->Visible)//200318//
	{
		if(Y < 4)
		{
			pnlSystem->Visible	= true;
			pnlSystem->Left		= EDGEGAP;
			pnlSystem->Top		= 0;//palMiniSearchBar과 중복되지만//palMiniSearchBar->Top + palMiniSearchBar->Height;
		}
		else
		{
			pnlSystem->Visible	= false;
		}
	}

	if(ICONMEMOPOINT->Visible)
	{
		if( !frmMemo->Showing )
		{
			ICONMEMOPOINT->Left	= X - ICONMEMOPOINT->Width/2;
			ICONMEMOPOINT->Top	= Y - ICONMEMOPOINT->Height;
			MEMOPOINTHELP->Left	= ICONMEMOPOINT->Left + ICONMEMOPOINT->Width/2 + 4;
			MEMOPOINTHELP->Top	= ICONMEMOPOINT->Top + ICONMEMOPOINT->Height;
		}
	}
	else if(ICONMEMOPOLY->Visible)
	{
		if( !frmMemo->Showing )
		{
			ICONMEMOPOLY->Left	= X - ICONMEMOPOLY->Width/2;
			ICONMEMOPOLY->Top	= Y - ICONMEMOPOLY->Height;//- palClient->Top - palMainView->Top
			MEMOPOLYHELP->Left	= ICONMEMOPOLY->Left + ICONMEMOPOLY->Width/2 + 4;
			MEMOPOLYHELP->Top	= ICONMEMOPOLY->Top + ICONMEMOPOLY->Height;
		}
	}

	if(palWait->Visible == false){
		TPoint _ptPoint;
		_ptPoint.x = X;
		_ptPoint.y = Y;
		pWheelMousePos = _ptPoint;//200827

		//M//191029
		GPoint _gpoint   = func_DeviceToWorld(_ptPoint);
		AnsiString asStr = IntToStr((int)_gpoint.x) + "," + IntToStr((int)_gpoint.y);
		funcSetStatusBarMsg(0, asStr);

		asStr = IntToStr(X) + "," + IntToStr(Y);

		if(m_eManipulationMode == Panning && m_bFlags){
			TGraphicControl *GCtrl=(TGraphicControl *)IMGSCREEN1;
			GetCursorPos(&_ptPoint); //마우스 움직인 후의 현재 마우스 가져옴
			//이전 좌표와 비교해서 Image의 위치를 이동시켜줌
			GCtrl->Left = GCtrl->Left + (_ptPoint.x-_movepoint.x);
			GCtrl->Top  = GCtrl->Top  + (_ptPoint.y-_movepoint.y);

			_movepoint  = _ptPoint; // 현재 좌표를 이전좌표로 기억해둠

			double dX = (m_ptZoomWindowBR.x - _ptPoint.x) ;
			double dY = (m_ptZoomWindowBR.y - _ptPoint.y) ;
			m_geoCenterPoint.x += dX / (m_lfRatio * m_lfZoomFactor );
			m_geoCenterPoint.y -= dY / (m_lfRatio * m_lfZoomFactor );
			m_ptZoomWindowBR = _ptPoint;

			if(PBCONTROL1->Visible == true) PBCONTROL1->Invalidate();
		}
		else if(m_eManipulationMode ==StreetGauge){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptCenter = _movepoint;
			if(PBCONTROL1->Visible == true) PBCONTROL1->Invalidate();
		}
		else if(m_eManipulationMode == AreaGauge && m_bControlFlags){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptCenter = _movepoint;
			if(PBCONTROL1->Visible == true) PBCONTROL1->Invalidate();
		}
		else if(m_eManipulationMode == ZoomWindow && m_bFlags){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptZoomWindowLT = _movepoint;
			if(PBCONTROL1->Visible == true) PBCONTROL1->Invalidate();
		}
		else if(m_eManipulationMode == SpaceRect){//191202
//			_movepoint.x = X; _movepoint.y = Y;
//			m_ptCenter = _movepoint;
			if(PBSPACE->Visible == true) PBSPACE->Invalidate();
			//PBSPACEMouseMove(PBSPACE, Shift, X, Y);
		}
		else if(m_eManipulationMode == MemoRect && m_bControlFlags){//191129
			_movepoint.x = X; _movepoint.y = Y;
			m_ptMemoRectCenter = _movepoint;
			if(PBCONTROL1->Visible == true) PBCONTROL1->Invalidate();
		}
	}
}
