int __fastcall TfrmMain::_2DEngineObject_pnsFunc_Track(GPoint point,TRect rect)
{
	//200303//Poi존재>메모등록>지번클릭>Poi index가 바뀌어버린다
	//이 함수는 메모등록시에만 사용하므로 m_vSelectedID 를 사용하지 않는다//
	//m_vSelectedID.clear();
	int m_nSelectIDNum = -1;

	// 점을 찍었는지 선을 찍었는지 hit test 한다.
	int ID;      // 오브젝트 아이디...
	int PointID; // 몇번재 포인트인가..

	hit_status hit_test = _2DEngineObject_pnsFunc_HitTest(point, rect, ID, PointID);

	if ((hit_test != hitPoint) && (hit_test != hitCurve) && (hit_test != hitPolygon)){
		if (m_eStatus == stateSelect){
			m_eStatus = stateNone;
		}
		m_nSelectIDNum = -1;
		return -1;
	}

	//200303//Poi존재>메모등록>지번클릭>Poi index가 바뀌어버린다
	//이 함수는 메모등록시에만 사용하므로 m_vSelectedID 를 사용하지 않는다//
	//m_vSelectedID.push_back(ID);
	m_nSelectIDNum = ID;

	// 원래 선택이 되어있지 않았다면, 선택된 것을 표시하기 위해 한번 그려준다.
	if (m_eStatus == stateNone){
		m_eStatus = stateSelect;
		hit_test = hitCurve;

		if(ID != -1){
			return ID;//191210//연속지적도 표시안하면 <메모등록> 안됐던 이유//
//			if(m_vSHPPOLYCBND[ID].m_nShow == true) return ID;
//			else{
//				m_vSelectedID.clear();
//				m_nSelectIDNum = -1;
//				return -1;
//			}
		}
	}

	// 상태를 선택한 것으로 변화시킨다.
	m_eStatus = stateSelect;

	if(ID != -1){
		return ID;//191210//연속지적도 표시안하면 <메모등록> 안됐던 이유//
//		if(m_vSHPPOLYCBND[ID].m_nShow == true) return ID;
//		else{
//			m_vSelectedID.clear();
//			m_nSelectIDNum = -1;
//			return -1;
//		}
	}
	return m_nSelectIDNum;
}
