//---------------------------------------------------------------------------
TfrmMain::hit_status TfrmMain::_2DEngineObject_pnsFunc_HitTest(GPoint _gPoint, TRect _rctScreen, int& _ID, int& _PointID)
{
	POINT_LIST::iterator iter;
	RECT mbrRect, rectBuffer;
	mbrRect = func_WorldToDevice(m_MBR);

	//디버그 모드일 경우만 된다...이상하다....된장
    if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen)){
        return hitNone;
    }
    // 면 위를 본다.
	int i,j,k;

	int m_nRecords;

	m_nRecords = m_STANDARDCBND.m_nRecords;

	int icount = 0;
	bool selectOption = false;
	MBR sizeMBR;
	for(i =0; i < m_nRecords; ++i){
		// 화면 밖이면 처리하지 않는다.
		mbrRect = func_WorldToDevice(m_vSHPPOLYCBND[i].m_MBR);

		if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen))
			continue;

		//191210//if( m_vSHPPOLYCBND[i].m_nShow == true)//연속지적도 표시안하면 <메모등록> 안됐던 이유//
		{
			for(j = 0; j < m_vSHPPOLYCBND[i].m_nNumParts; ++j){
				if (_2DEngineObject_pnsFunc_PtInPolygon(m_vSHPPOLYCBND[i].m_vPoints, _gPoint)){
					if(selectOption == false){
						selectOption = true;
						sizeMBR = m_vSHPPOLYCBND[i].m_MBR;
						_ID = m_vSHPPOLYCBND[i].m_nID;
					}
					else{
						if(sizeMBR.xmax >= m_vSHPPOLYCBND[i].m_MBR.xmax && sizeMBR.ymax >= m_vSHPPOLYCBND[i].m_MBR.ymax){
							sizeMBR = m_vSHPPOLYCBND[i].m_MBR;
							_ID = m_vSHPPOLYCBND[i].m_nID;
						}
					}
				}
			}
		}
	}

	if(selectOption == true) return hitPolygon;
	if(icount > 0) return hitPolygon;
	return hitNone;
}
