void __fastcall TfrmMain::PBCONTROL1DblClick(TObject *Sender)
{
	if(m_eManipulationMode == AreaGauge && m_bControlFlags){
		int size = m_vAREA.size();
		if(size >= 3){
			for(int i=0; i<size; i++){
				memset(&tempREALAREA, 0x00, sizeof(REALAREA_STRUCT));

				if(i==0) tempREALAREA.gbn = 1;
				else if(i == size-1){
					tempREALAREA.gbn = 3;
					tempREALAREA.labelx = m_vAREA[i].x;
					tempREALAREA.labely = m_vAREA[i].y;
					tempREALAREA.area = func_DrawAreaValue();
				}
				else tempREALAREA.gbn = 2;
				tempREALAREA.x    = m_vAREA[i].x;
				tempREALAREA.y    = m_vAREA[i].y;
				m_vREALAREA.push_back(tempREALAREA);
			}
		}
		m_vAREA.clear();

		PBCONTROL1->Cursor	= crDefault;//200227
		m_bControlFlags   	= false;
		pbControl1DblClick 	= true;
		PBCONTROL1->Invalidate();

		//191212//m_eManipulationMode = Panning;//M//191031
	}
	else if(m_eManipulationMode == StreetGauge ){
		int size = m_vDIST.size();
		if(size >= 2){
			for(int i=0; i<size; i++){
				memset(&tempREALDIST, 0x00, sizeof(REALDIST_STRUCT));

				if(i==0)             tempREALDIST.gbn = 1; //시작점
				else if(i == size-1) tempREALDIST.gbn = 3; //끝점
				else                 tempREALDIST.gbn = 2; //중간점

				tempREALDIST.x      = m_vDIST[i].x;
				tempREALDIST.y      = m_vDIST[i].y;
				tempREALDIST.labelx = m_vDIST[i].x;
				tempREALDIST.labely = m_vDIST[i].y;
				tempREALDIST.dist   = m_vDIST[i].dist;
				m_vREALDIST.push_back(tempREALDIST);
			}
		}
		m_vDIST.clear();

		PBCONTROL1->Cursor	= crDefault;//200227
		m_bControlFlags    	= false;
		pbControl1DblClick 	= true;
		PBCONTROL1->Invalidate();

		//191212//m_eManipulationMode = Panning;
	}
	else if(m_eManipulationMode == MemoRect && m_bControlFlags){//191129
		int size = m_vMEMORECT.size();
		if(size >= 3){
			memset(&tempMEMORECT, 0x00, sizeof(REALAREA_STRUCT));
			tempMEMORECT.gbn = 3;
			tempMEMORECT.area = func_DrawMemoRectAreaValue();
			tempMEMORECT.labelx = m_pgMemoRectCenter.x;
			tempMEMORECT.labely = m_pgMemoRectCenter.y;
			tempMEMORECT.x    = m_vMEMORECT[size-1].x;
			tempMEMORECT.y    = m_vMEMORECT[size-1].y;
			m_vMEMORECT.push_back(tempMEMORECT);
		}
		m_bControlFlags   = false;
		pbControl1DblClick = true;
		PBCONTROL1->Invalidate();

		frmMemo->m_asSelectPoiKey 		= "";
		if( !frmMemo->Showing )//Regist//Poly
		{
			frmMemo->m_bMemoRegist = true;
			frmMemo->Show();//Regist//Rect
		}
		else
		{
			//등록중일 때, 더블클릭으로 두번 실행되는 것 방지//
			if(!frmMemo->m_bMemoRegist)//Regist
			{
				frmMemo->m_bMemoChange = true;//Regist->Regist
				frmMemo->m_bMemoRegist = true;
				frmMemo->IMGEXITClick(frmMemo->IMGEXIT);
			}
//			else
//			{
//				frmMsg->funcMessageDlg("메모등록 확인:", "메모등록중입니다.", 3);
//				return;
//			}
		}

		//191212//m_eManipulationMode = Panning;
	}
}
