//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcPbControl1Draw()
{
	PBCONTROL1->Canvas->Lock();

	HPEN pen;
	HFONT m_font;
	HFONT hOldFont;
	int size = m_vDIST.size();
	TPoint start, end;
	GPoint inputPoint;

	if(m_eManipulationMode == StreetGauge){//거리재기
		if((int)m_vDIST.size() > 0){
			inputPoint.x = m_vDIST[(int)m_vDIST.size()-1].x;
			inputPoint.y = m_vDIST[(int)m_vDIST.size()-1].y;
			start = func_WorldToDevice(inputPoint);

			pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
			::SelectObject(PBCONTROL1->Canvas->Handle, pen);
			int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);
			::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
			::LineTo(PBCONTROL1->Canvas->Handle,m_ptCenter.x, m_ptCenter.y);
			::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
			::DeleteObject( pen );
		}
	}

	if(size > 0){//거리재기
		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);
		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		for(int i=0; i<size; i++){
			if(i == 0){
				inputPoint.x = m_vDIST[i].x;
				inputPoint.y = m_vDIST[i].y;

				start = func_WorldToDevice(inputPoint);
				::Rectangle(PBCONTROL1->Canvas->Handle,start.x-3, start.y-3,start.x+3, start.y+3);
			}
			else{
				inputPoint.x = m_vDIST[i].x;
				inputPoint.y = m_vDIST[i].y;

				end = func_WorldToDevice(inputPoint);

				::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
				::LineTo(PBCONTROL1->Canvas->Handle,end.x, end.y);

				::Rectangle(PBCONTROL1->Canvas->Handle,end.x-3, end.y-3,end.x+3, end.y+3);
				::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
				::DeleteObject( pen );

				//double temp = m_vDIST[i].dist;
				double temp = 0.0;

				for(int k=0; k<=i; k++) temp = temp + m_vDIST[k].dist;
				temp = RoundTo(temp,-2);

				AnsiString rangeValue;
				rangeValue = FormatFloat("거리:###,##0.00 m",  temp);//191212

				int fontwidth = INIUSERSETINFO.AREAFONTSIZE;//201119//측정(면적거리) Label Size, Color//14;
				m_font   = ::CreateFont(fontwidth, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
				hOldFont = (HFONT)::SelectObject(PBCONTROL1->Canvas->Handle,m_font);
//201119//측정(면적거리) Label Size, Color//
				::SetBkMode(PBCONTROL1->Canvas->Handle,TRANSPARENT);
//				::SetTextAlign(PBCONTROL1->Canvas->Handle,0|0);
//				::AlphaBlend(PBCONTROL1->Canvas->Handle, end.x, end.y, BITMAP_BTN_TGA[TgaStreet]->Width, BITMAP_BTN_TGA[TgaStreet]->Height,BITMAP_BTN_TGA[TgaStreet]->Canvas->Handle,0,0,BITMAP_BTN_TGA[TgaStreet]->Width,BITMAP_BTN_TGA[TgaStreet]->Height,bf);
				::SetTextColor(PBCONTROL1->Canvas->Handle, INIUSERSETINFO.AREAFONTCOLOR);//201119//측정(면적거리) Label Size, Color//RGB(250,250,250));
				//PBCONTROL1->Canvas->TextOutA(end.x+40, end.y+2, rangeValue);
				PBCONTROL1->Canvas->TextOut(end.x+40, end.y+2, rangeValue);
				::SelectObject(PBCONTROL1->Canvas->Handle, hOldFont);
				::DeleteObject(m_font);

				start = end;
			}
		}
		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}

	if(m_eManipulationMode == AreaGauge){//면적재기
		if((int)m_vAREA.size() > 0){
			inputPoint.x = m_vAREA[(int)m_vAREA.size()-1].x;
			inputPoint.y = m_vAREA[(int)m_vAREA.size()-1].y;
			start = func_WorldToDevice(inputPoint);

			pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
			::SelectObject(PBCONTROL1->Canvas->Handle, pen);
			int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);
			::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
			::LineTo(PBCONTROL1->Canvas->Handle,m_ptCenter.x, m_ptCenter.y);

			inputPoint.x = m_vAREA[0].x;
			inputPoint.y = m_vAREA[0].y;
			start = func_WorldToDevice(inputPoint);
			::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
			::LineTo(PBCONTROL1->Canvas->Handle,m_ptCenter.x, m_ptCenter.y);

			::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
			::DeleteObject( pen );
		}
	}

	size = m_vAREA.size();
	if(size > 0){
		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);

		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		if(size == 1){
			inputPoint.x = m_vAREA[0].x;
			inputPoint.y = m_vAREA[0].y;
			start = func_WorldToDevice(inputPoint);

			::Rectangle(PBCONTROL1->Canvas->Handle,start.x-3, start.y-3, start.x+3, start.y+3);
		}
		else{
			for(int i=0; i<size-1; i++){
				inputPoint.x = m_vAREA[i].x;
				inputPoint.y = m_vAREA[i].y;
				start = func_WorldToDevice(inputPoint);

				inputPoint.x = m_vAREA[i+1].x;
				inputPoint.y = m_vAREA[i+1].y;
				end = func_WorldToDevice(inputPoint);

				::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
				::LineTo(PBCONTROL1->Canvas->Handle,end.x, end.y);
				::Rectangle(PBCONTROL1->Canvas->Handle, start.x-3, start.y-3, start.x+3, start.y+3);
			}

			inputPoint.x = m_vAREA[0].x;
			inputPoint.y = m_vAREA[0].y;
			start = func_WorldToDevice(inputPoint);
			inputPoint.x = m_vAREA[size-1].x;
			inputPoint.y = m_vAREA[size-1].y;
			end = func_WorldToDevice(inputPoint);

			//::MoveToEx(PBCONTROL1->Canvas->Handle, end.x, end.y, NULL);
			//::LineTo(PBCONTROL1->Canvas->Handle, start.x, start.y);
			::Rectangle(PBCONTROL1->Canvas->Handle, end.x-3, end.y-3, end.x+3, end.y+3);

			if(size >= 3) func_DrawAreaValue();
		}

		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}

	//============================================================================================
	//191129
	if(m_eManipulationMode == MemoRect){//영역등록//
		if((int)m_vMEMORECT.size() > 0){
			inputPoint.x = m_vMEMORECT[(int)m_vMEMORECT.size()-1].x;
			inputPoint.y = m_vMEMORECT[(int)m_vMEMORECT.size()-1].y;
			start = func_WorldToDevice(inputPoint);

			pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
			::SelectObject(PBCONTROL1->Canvas->Handle, pen);
			int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);
			::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
			::LineTo(PBCONTROL1->Canvas->Handle,m_ptMemoRectCenter.x, m_ptMemoRectCenter.y);

			inputPoint.x = m_vMEMORECT[0].x;
			inputPoint.y = m_vMEMORECT[0].y;
			start = func_WorldToDevice(inputPoint);
			::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
			::LineTo(PBCONTROL1->Canvas->Handle,m_ptMemoRectCenter.x, m_ptMemoRectCenter.y);

			::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
			::DeleteObject( pen );
		}
	}

	size = m_vMEMORECT.size();
	if(size > 0){
		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);

		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		if(size == 1){
			inputPoint.x = m_vMEMORECT[0].x;
			inputPoint.y = m_vMEMORECT[0].y;
			start = func_WorldToDevice(inputPoint);

			::Rectangle(PBCONTROL1->Canvas->Handle,start.x-3, start.y-3, start.x+3, start.y+3);
		}
		else{
			for(int i=0; i<size-1; i++){
				inputPoint.x = m_vMEMORECT[i].x;
				inputPoint.y = m_vMEMORECT[i].y;
				start = func_WorldToDevice(inputPoint);

				inputPoint.x = m_vMEMORECT[i+1].x;
				inputPoint.y = m_vMEMORECT[i+1].y;
				end = func_WorldToDevice(inputPoint);

				::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
				::LineTo(PBCONTROL1->Canvas->Handle,end.x, end.y);
				::Rectangle(PBCONTROL1->Canvas->Handle, start.x-3, start.y-3, start.x+3, start.y+3);
			}

			inputPoint.x = m_vMEMORECT[0].x;
			inputPoint.y = m_vMEMORECT[0].y;
			start = func_WorldToDevice(inputPoint);
			inputPoint.x = m_vMEMORECT[size-1].x;
			inputPoint.y = m_vMEMORECT[size-1].y;
			end = func_WorldToDevice(inputPoint);

			//::MoveToEx(PBCONTROL1->Canvas->Handle, end.x, end.y, NULL);
			//::LineTo(PBCONTROL1->Canvas->Handle, start.x, start.y);
			::Rectangle(PBCONTROL1->Canvas->Handle, end.x-3, end.y-3, end.x+3, end.y+3);

			if(size >= 3) func_DrawMemoRectAreaValue();
		}

		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}
	//============================================================================================

	//거리재기
	size = m_vREALDIST.size();
	int calcStartIndex = 0;
	int calcEndIndex   = 0;
	if(size > 0){
		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);
		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		for(int i=0; i<size; i++){
			if(m_vREALDIST[i].gbn == 1){
				inputPoint.x = m_vREALDIST[i].x;
				inputPoint.y = m_vREALDIST[i].y;

				start = func_WorldToDevice(inputPoint);
				::Rectangle(PBCONTROL1->Canvas->Handle,start.x-3, start.y-3,start.x+3, start.y+3);
				calcStartIndex = i;
			}
			else{
				inputPoint.x = m_vREALDIST[i].x;
				inputPoint.y = m_vREALDIST[i].y;

				end = func_WorldToDevice(inputPoint);

				::MoveToEx(PBCONTROL1->Canvas->Handle,start.x, start.y, NULL);
				::LineTo(PBCONTROL1->Canvas->Handle,end.x, end.y);

				::Rectangle(PBCONTROL1->Canvas->Handle,end.x-3, end.y-3,end.x+3, end.y+3);
				::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
				::DeleteObject( pen );

				//double temp = m_vREALDIST[i].dist;
				double temp = 0.0;

				for(int k=calcStartIndex; k<=i; k++) temp = temp + m_vREALDIST[k].dist;
				temp = RoundTo(temp,-2);

				AnsiString rangeValue;
				rangeValue = FormatFloat("###,##0.00 m",  temp);

				int fontwidth = 14;
				m_font   = ::CreateFont(fontwidth, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
				hOldFont = (HFONT)::SelectObject(PBCONTROL1->Canvas->Handle,m_font);
//201119//측정(면적거리) Label Size, Color//
				::SetBkMode(PBCONTROL1->Canvas->Handle,TRANSPARENT);
//				::SetTextAlign(PBCONTROL1->Canvas->Handle,0|0);
//				::AlphaBlend(PBCONTROL1->Canvas->Handle, end.x, end.y, BITMAP_BTN_TGA[TgaStreet]->Width, BITMAP_BTN_TGA[TgaStreet]->Height,BITMAP_BTN_TGA[TgaStreet]->Canvas->Handle,0,0,BITMAP_BTN_TGA[TgaStreet]->Width,BITMAP_BTN_TGA[TgaStreet]->Height,bf);
				::SetTextColor(PBCONTROL1->Canvas->Handle, INIUSERSETINFO.AREAFONTCOLOR);//201119//측정(면적거리) Label Size, Color//RGB(250,250,250));
				//PBCONTROL1->Canvas->TextOutA(end.x+40, end.y+2, rangeValue);
				PBCONTROL1->Canvas->TextOut(end.x+40, end.y+2, rangeValue);
				::SelectObject(PBCONTROL1->Canvas->Handle, hOldFont);
				::DeleteObject(m_font);

				start = end;
			}
		}
		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}

	size = m_vREALAREA.size();
	if(size > 0){
		int iCount    = 0;
		int readIndex = 0;
		TPoint *points;
		int index;

		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);
		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		for(int i=0; i<size; i++){
			inputPoint.x = m_vREALAREA[i].x;
			inputPoint.y = m_vREALAREA[i].y;
			start = func_WorldToDevice(inputPoint);

			::Rectangle(PBCONTROL1->Canvas->Handle,start.x-3, start.y-3, start.x+3, start.y+3);

			iCount++;
			if(m_vREALAREA[i].gbn == 3){
				points = new TPoint[iCount+1];
				for(int j=readIndex; j<readIndex+iCount; j++){
					inputPoint.x        = m_vREALAREA[j].x;
					inputPoint.y        = m_vREALAREA[j].y;
					points[j-readIndex] = func_WorldToDevice(inputPoint);
				}
				inputPoint.x        = m_vREALAREA[readIndex].x;
				inputPoint.y        = m_vREALAREA[readIndex].y;
				points[iCount]      = func_WorldToDevice(inputPoint);

				::Polyline(PBCONTROL1->Canvas->Handle, points, iCount+1);

				//글자출력 위치
				inputPoint.x = m_vREALAREA[i].x;
				inputPoint.y = m_vREALAREA[i].y;
				start = func_WorldToDevice(inputPoint);
				int fontwidth  = 14;
				m_font   = ::CreateFont(fontwidth, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
				hOldFont = (HFONT)::SelectObject(PBCONTROL1->Canvas->Handle,m_font);
//201119//측정(면적거리) Label Size, Color//
				::SetBkMode(PBCONTROL1->Canvas->Handle,TRANSPARENT);
//				::SetTextAlign(PBCONTROL1->Canvas->Handle,0|0);
//				::AlphaBlend(PBCONTROL1->Canvas->Handle, start.x, start.y, BITMAP_BTN_TGA[TgaArea]->Width, BITMAP_BTN_TGA[TgaArea]->Height,BITMAP_BTN_TGA[TgaArea]->Canvas->Handle,0,0,BITMAP_BTN_TGA[TgaArea]->Width,BITMAP_BTN_TGA[TgaArea]->Height,bf);
				::SetTextColor(PBCONTROL1->Canvas->Handle, INIUSERSETINFO.AREAFONTCOLOR);//201119//측정(면적거리) Label Size, Color//RGB(250,250,250);
				//PBCONTROL1->Canvas->TextOutA(start.x+40, start.y+2, m_vREALAREA[i].area);
				PBCONTROL1->Canvas->TextOut(start.x+40, start.y+2, m_vREALAREA[i].area);
				::SelectObject(PBCONTROL1->Canvas->Handle, hOldFont);
				::DeleteObject(m_font);

				delete[] points;
				points = NULL;

				iCount    = 0;
			}
			else if(m_vREALAREA[i].gbn == 1){
				readIndex = i;
			}
		}

		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}

	//영역확대
	if(m_eManipulationMode == ZoomWindow && m_bFlags == true){
		pen   = ::CreatePen(PS_SOLID, 3, 0x00ff0000);
		::SelectObject(PBCONTROL1->Canvas->Handle, pen);

		int oldro2 = ::SetROP2( PBCONTROL1->Canvas->Handle, R2_COPYPEN);

		PBCONTROL1->Canvas->Brush->Style = bsClear;

		PBCONTROL1->Canvas->Rectangle(m_ptZoomWindowLT.x, m_ptZoomWindowLT.y, m_ptZoomWindowBR.x, m_ptZoomWindowBR.y);
		PBCONTROL1->Canvas->Rectangle(m_ptZoomWindowLT.x, m_ptZoomWindowLT.y, _movepoint.x, _movepoint.y);

		::SetROP2( PBCONTROL1->Canvas->Handle, oldro2);
		::DeleteObject( pen );
	}

	PBCONTROL1->Canvas->Unlock();
}
