HBITMAP __fastcall TfrmMain::func_Load32bppTga(const char * pFileName, bool bPreMultiply)
{
    HANDLE handle = CreateFile(pFileName, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
	if(handle == INVALID_HANDLE_VALUE) return NULL;

	dwRead = 0;
	HSIZE = sizeof(header);
	ReadFile(handle, &header, HSIZE, &dwRead, NULL);

    if((header.IDLength!=0) || (header.ColorMapType!=0) || (header.ImageType!=2) || (header.PixelDepth!=32) || (header.ImageDescriptor!=8)){
        CloseHandle(handle);
        return NULL;
    }

    BITMAPINFO bmp = {{sizeof(BITMAPINFOHEADER), header.Width, header.Height, 1, 32}};

    pBits = NULL;
    HBITMAP hBmp;
    hBmp = CreateDIBSection(NULL, & bmp, DIB_RGB_COLORS, & pBits, NULL, NULL);
    if(hBmp == NULL){
        CloseHandle(handle);
        return NULL;
    }

    ReadFile(handle, pBits, header.Width * header.Height * 4, & dwRead, NULL);
    CloseHandle(handle);

    if (bPreMultiply){
        for (int y=0; y<header.Height; y++){
            pPixel = (BYTE *) pBits + header.Width * 4 * y;
            for (int x=0; x<header.Width; x++){
                pPixel[0] = pPixel[0] * pPixel[3] / 255;
                pPixel[1] = pPixel[1] * pPixel[3] / 255;
                pPixel[2] = pPixel[2] * pPixel[3] / 255;

                pPixel += 4;
                Application->ProcessMessages() ;
            }
            Application->ProcessMessages() ;
        }
    }

    return hBmp;
}
