AnsiString __fastcall TfrmMain::func_DrawAreaValue()
{
	AnsiString result;
	double area,centerx,centery,x1,x2,y1,y2;
	GPoint pt1,pt2,ptCenter;
	TPoint textCenter;

	int k;
	area = centerx = centery = x1 = x2 = y1 = y2 = 0;
	int icount = m_vAREA.size();
	TPoint point1, point2;
	for( int j = 0; j < icount; ++j){
		k=(j+1) % icount;

		pt1.x = m_vAREA[j].x;
		pt1.y = m_vAREA[j].y;

		pt2.x = m_vAREA[k].x;
		pt2.y = m_vAREA[k].y;

		x1  = pt1.x;
		x2  = pt2.x;
		y1  = pt1.y;
		y2  = pt2.y;

		area += x1*y2;
		area -= y1*x2;

		centerx += ((x1 + x2) * ((x1 * y2) - (x2 * y1)));
		centery += ((y1 + y2) * ((x1 * y2) - (x2 * y1)));
	}
	area /= 2;
	area = fabs(area);

	AnsiString rangeValue;

	area = RoundTo(area, -2);
	//rangeValue = area;
	rangeValue = FormatFloat("면적:###,##0.00 ㎡", area);//191212
	result = rangeValue;
	//중심점
	if((6.0*area) != 0){
		centerx    = centerx/(6.0*area);
		centery    = centery/(6.0*area);
		ptCenter.x = fabs(centerx);
		ptCenter.y = fabs(centery);
	}
	textCenter = func_WorldToDevice(ptCenter);

	GPoint inputPoint;

	inputPoint.x = m_vAREA[icount-1].x;
	inputPoint.y = m_vAREA[icount-1].y;
	TPoint start = func_WorldToDevice(inputPoint);

	int fontwidth  = INIUSERSETINFO.AREAFONTSIZE;//201119//측정(면적거리) Label Size, Color//14;

	HFONT m_font   = ::CreateFont(fontwidth, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
	HFONT hOldFont = (HFONT)::SelectObject(PBCONTROL1->Canvas->Handle,m_font);
//201119//측정(면적거리) Label Size, Color//
	::SetBkMode(PBCONTROL1->Canvas->Handle,TRANSPARENT);
//	::SetTextAlign(PBCONTROL1->Canvas->Handle,0|0);
//	::AlphaBlend(PBCONTROL1->Canvas->Handle, start.x, start.y, BITMAP_BTN_TGA[TgaArea]->Width, BITMAP_BTN_TGA[TgaArea]->Height,BITMAP_BTN_TGA[TgaArea]->Canvas->Handle,0,0,BITMAP_BTN_TGA[TgaArea]->Width,BITMAP_BTN_TGA[TgaArea]->Height,bf);
	::SetTextColor(PBCONTROL2->Canvas->Handle, INIUSERSETINFO.AREAFONTCOLOR);//201119//측정(면적거리) Label Size, Color//RGB(250,250,250);

	//PBCONTROL1->Canvas->TextOutA(start.x+40, start.y+2, rangeValue);
	PBCONTROL1->Canvas->TextOut(start.x+40, start.y+2, rangeValue);
	::SelectObject(PBCONTROL1->Canvas->Handle, hOldFont);
	::DeleteObject(m_font);

	return result;
}
