void __fastcall TfrmMain::func_CalcCoorNS()
{
	//변환작업시작
	double lon_temp;
    double lat_temp;
	double h;
	int i;

	h = 42.0;

	//Major axis of Bessel1841 and WGS84
	major_0 = 6377397.155;
	major_1 = 6378137.0;

	//Minor axis of Bessel1841 and WGS84
	minor_0 = 6356078.96325;
	minor_1 = 6356752.3142;

	//Scale reduction factor
	SF_1 = 1.0;
	SF_2 = 1.0;
	SF_3 = 1.0;
	SF_4 = 0.9999;
	SF_5 = 0.9996;
	SF_6 = 0.9996;

	//Longitude center
	LonCen_1 = 2.18171200985643;
	//=====================================================
	//241128//TEST//
//ORG//	LonCen_2 = 2.21661859489632;
//	if(_SIDOCODE.SubString(1, 2) != "44")
//		LonCen_2 = 2.216568150032796;
//	else
		LonCen_2 = 2.21661859489632;
	//=====================================================
	LonCen_3 = 2.2515251799362;
	LonCen_4 = 2.23402144255274;
	LonCen_5 = 2.25147473507269;
	LonCen_6 = 2.14675497995303;

	//Latitude origin
	LatCen_1 = 0.663225115757845;
	LatCen_2 = 0.663225115757845;
	LatCen_3 = 0.663225115757845;
	LatCen_4 = 0.663225115757845;
	LatCen_5 = 0.0;
	LatCen_6 = 0.0;

	//False northing
	FN_1 = 500000;
	FN_2 = 500000;
	FN_3 = 500000;
	FN_4 = 600000;
	FN_5 = 0.0;
	FN_6 = 0.0;

	//False easting
	FE_1 = 200000;
	FE_2 = 200000;
	FE_3 = 200000;
	FE_4 = 400000;
	FE_5 = 500000;
	FE_6 = 500000;

	int cboSystem_0 = m_MAININI.SYSTEM_CONVERT_SYSTEM_0;
	int cboEllips_0 = m_MAININI.SYSTEM_CONVERT_ELLIPS_0;
	int cboSystem_1 = m_MAININI.SYSTEM_CONVERT_SYSTEM_1;
	int cboEllips_1 = m_MAININI.SYSTEM_CONVERT_ELLIPS_1;

	double r_maj;
	double r_min;
	double scale_fact;
	double center_lon;
	double center_lat;
	double false_east;
	double false_north;

	if(cboEllips_0 == 0){
		r_maj = major_0;
		r_min = minor_0;
	}
	else{
		r_maj = major_1;
		r_min = minor_1;
	}

	if(cboSystem_0 == 1){
		scale_fact  = SF_1;
		center_lon  = LonCen_1;
		center_lat  = LatCen_1;
		false_east  = FE_1;
		false_north = FN_1;
	}
	else if(cboSystem_0 == 2){
		scale_fact  = SF_2;
		center_lon  = LonCen_2;
		center_lat  = LatCen_2;
		false_east  = FE_2;
		false_north = FN_2;
	}
	else if(cboSystem_0 == 3){
		scale_fact  = SF_3;
		center_lon  = LonCen_3;
		center_lat  = LatCen_3;
		false_east  = FE_3;
		false_north = FN_3;
	}
	else if(cboSystem_0 == 4){
		scale_fact  = SF_4;
		center_lon  = LonCen_4;
		center_lat  = LatCen_4;
		false_east  = FE_4;
		false_north = FN_4;
	}
	else if(cboSystem_0 == 5){
		scale_fact  = SF_5;
		center_lon  = LonCen_5;
		center_lat  = LatCen_5;
		false_east  = FE_5;
		false_north = FN_5;
	}
	else if(cboSystem_0 == 6){
		scale_fact  = SF_6;
		center_lon  = LonCen_6;
		center_lat  = LatCen_6;
		false_east  = FE_6;
		false_north = FN_6;
	}
	else {
		scale_fact  = SF_1;
		center_lon  = LonCen_1;
		center_lat  = LatCen_1;
		false_east  = FE_1;
		false_north = FN_1;
	}

	tmint(r_maj, r_min, scale_fact, center_lon, center_lat, false_east, false_north);

	tminv(latitudeNS.ToDouble(), longitudeNS.ToDouble(), &lon_temp, &lat_temp);

	conv(lon_temp, lat_temp, h, 1);
}
//---------------------------------------------------------------------------
double __fastcall TfrmMain::Cube(double x)
{
    return (x * x * x);
}
//---------------------------------------------------------------------------
double __fastcall TfrmMain::Quad(double x)
{
    return (x * x * x * x);
}
//---------------------------------------------------------------------------
double __fastcall TfrmMain::e0fn(double x)
{
    return (1.0 - 0.25 * x * (1.0 + x / 16.0 * (3.0 + 1.25 * x)));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::e1fn(double x)
{
    return (0.375 * x * (1.0 + 0.25 * x * (1.0 + 0.46875 * x)));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::e2fn(double x)
{
    return (0.05859375 * x * x * (1.0 + 0.75 * x));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::e3fn(double x)
{
	return (x * x * x * (35.0 / 3072.0));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::e4fn(double x)
{
    double con, com;

    con = 1.0 + x;
    com = 1.0 - x;
    return (sqrt(pow(con, con) * pow(com,com)));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::mlfn(double e0, double e1, double e2, double e3, double phi)
{
    return (e0 * phi - e1 * sin(2.0 * phi) + e2 * sin(4.0 * phi) - e3 * sin(6.0 * phi));
}
//---------------------------------------------------------------------------
double __fastcall TfrmMain::acos1(double x)
{
    return (atan(-x / sqrt(-x * x + 1)) + 2 * atan(1));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::asin1(double x)
{
	return (atan(x / sqrt(-x * x + 1)));
}
//---------------------------------------------------------------------------

double __fastcall TfrmMain::asinz1(double con)
{
    if( fabs(con) > 1.0){
        if( con > 1.0 ) con = 1.0;
		else con = -1.0;
    }

	return (asin1(con));
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::d2dms(double *Lon, double *Lat, int *LonMin, double *LonSec, int *LatMin, double *LatSec)
{
    double deltaLon, deltaLat;

    deltaLon = *Lon - (int)(*Lon);
    deltaLat = *Lat - (int)(*Lat);

    *LonMin = (int)(deltaLon * 60);
    *LatMin = (int)(deltaLat * 60);

    *LonSec = (deltaLon * 60 - *LonMin) * 60;
    *LatSec = (deltaLat * 60 - *LatMin) * 60;

    if(*LonSec >= 60){
        *LonSec = *LonSec - 60;
        *LonMin = *LonMin + 1;

        if(*LonMin >= 60){
            *LonMin = *LonMin - 60;
            *Lon = (int)*Lon + 1;
        }
        else{
            *Lon = (int)(*Lon);
        }
    }
    else{
        *Lon = (int)(*Lon);
    }

    if(*LatSec >= 60){
        *LatSec = *LatSec - 60;
        *LatMin = *LatMin + 1;

        if(*LatMin >= 60){
            *LatMin = *LatMin - 60;
			*Lat = (int)(*Lat) + 1;
        }
        else{
            *Lat = (int)(*Lat);
        }
    }
    else{
        *Lat = (int)(*Lat);
    }
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::DatumTrans(double input_a, double input_b, double input_Phi, double input_Lamda, double input_H, double output_a, double output_b, double *output_Phi, double *output_Lamda, double *output_H, float delta_X, float delta_Y, float delta_Z)
{
    double delta_a, delta_f, delta_Phi, delta_Lamda, delta_H; //differeces between input ellipsoid and output ellipsoid like major axis and flattening. As is ouput - input
    double Rm, Rn;//radius of curvature in the meridian and radius of curvature in the prime vertical
    double temp, es_temp, f;

    temp          = input_b / input_a;
    f             = 1 - temp; //flattening
    es_temp       = 1.0 - temp * temp; //e2

    delta_a       = output_a - input_a; //output major axis - input major axis
    delta_f       = input_b / input_a - output_b / output_a; //Output Flattening - input flattening

    Rm            = (input_a * (1 - es_temp)) / pow((1 - es_temp * sin(input_Phi) * sin(input_Phi)),(3 / 2));
    Rn            = input_a / pow((1 - es_temp * sin(input_Phi) * sin(input_Phi)) , (1 / 2));

    delta_Phi     = ((((-delta_X * sin(input_Phi) * cos(input_Lamda) - delta_Y * sin(input_Phi) * sin(input_Lamda)) + delta_Z * cos(input_Phi)) + delta_a * Rn * es_temp * sin(input_Phi) * cos(input_Phi) / input_a) + delta_f * (Rm / temp + Rn * temp) * sin(input_Phi) * cos(input_Phi)) / (Rm + input_H);
    delta_Lamda   = (-delta_X * sin(input_Lamda) + delta_Y * cos(input_Lamda)) / ((Rn + input_H) * cos(input_Phi));
    delta_H       = delta_X * cos(input_Phi) * cos(input_Lamda) + delta_Y * cos(input_Phi) * sin(input_Lamda) + delta_Z * sin(input_Phi) - delta_a * input_a / Rn + delta_f * temp * Rn * sin(input_Phi) * sin(input_Phi);

    *output_Phi   = input_Phi + delta_Phi;
    *output_Lamda = input_Lamda + delta_Lamda;
    *output_H     = input_H + delta_H;
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::conv(double lon_temp, double lat_temp, double h, int _gbn)
{
	int df;
	double out_lat;
	double out_lon;
    double out_h;
    int LonMin;
    int LatMin;
    double LonSec;
    double LatSec;
    double TMX;
    double TMY;

    //direction factor for datum transformation
    //eg) Bessel to Bessel would be 0
    //    WGS84 to Bessel would be 1
    //    BEssel to WGS84 would be -1
	int cboSystem_0;
	int cboEllips_0;
	int cboSystem_1;
	int cboEllips_1;

	if(_gbn == 1){
		cboSystem_0 = m_MAININI.SYSTEM_CONVERT_SYSTEM_0;
		cboEllips_0 = m_MAININI.SYSTEM_CONVERT_ELLIPS_0;
		cboSystem_1 = m_MAININI.SYSTEM_CONVERT_SYSTEM_1;
		cboEllips_1 = m_MAININI.SYSTEM_CONVERT_ELLIPS_1;
	}
	else{
		cboSystem_0 = 0;
		cboEllips_0 = 1;
		cboSystem_1 = 2;
		cboEllips_1 = 0;
	}

	df = cboEllips_0 - cboEllips_1;

    if( df == 0){
        out_lon = lon_temp;
        out_lat = lat_temp;
        out_h   = h;
    }
    else{
        //Datum transformation using molodensky function
        double input_a;
		double input_b;
		double output_a;
        double output_b;

		if(cboEllips_0 == 0){
			input_a = major_0;
            input_b = minor_0;
        }
        else{
            input_a = major_1;
            input_b = minor_1;
        }

		if(cboEllips_1 == 0){
            output_a = major_0;
            output_b = minor_0;
        }
        else{
            output_a = major_1;
            output_b = minor_1;
        }

        DatumTrans(input_a, input_b, lat_temp, lon_temp, h, output_a, output_b, &out_lat, &out_lon, &out_h, df * dX_W2B, df * dY_W2B, df * dZ_W2B);
    }

    //now we should make a output. but it depends on user options
    if(cboSystem_1 == 0){ //if output option is latitude & longitude
        out_lon = out_lon * 180 / PI;
        out_lat = out_lat * 180 / PI;

		_coorData._coord.y = out_lon;
		_coorData._coord.x = out_lat;

        //to make decimal degree into DMS
        d2dms(&out_lon, &out_lat, &LonMin, &LonSec, &LatMin, &LatSec);

        AnsiString txtdms_6  = (int)(out_lon);
        AnsiString txtdms_7  = LonMin;
        AnsiString txtdms_8  = FormatFloat( "0.00", LonSec);
        AnsiString txtdms_9  = (int)(out_lat);
        AnsiString txtdms_10 = LatMin;
        AnsiString txtdms_11 = FormatFloat("0.00", LatSec );

		_coorData._long = txtdms_6 + "˚" + txtdms_7 + "′" + txtdms_8 + "″";
        _coorData._lat  = txtdms_9 + "˚" + txtdms_10 + "′" + txtdms_11 + "″";
    }
    else{ //if output option is cartesian systems

        //initializing factor for TM or UTM projection
        double r_maj;
        double r_min;
        double scale_fact;
        double center_lon;
        double center_lat;
        double false_east;
        double false_north;

		if(cboEllips_1 == 0){
			r_maj = major_0;
			r_min = minor_0;
		}
		else{
			r_maj = major_1;
			r_min = minor_1;
		}

		if(cboSystem_1 == 1){
			scale_fact  = SF_1;
			center_lon  = LonCen_1;
			center_lat  = LatCen_1;
			false_east  = FE_1;
			false_north = FN_1;
		}
		else if(cboSystem_1 == 2){
			scale_fact  = SF_2;
			center_lon  = LonCen_2;
			center_lat  = LatCen_2;
			false_east  = FE_2;
			false_north = FN_2;
		}
		else if(cboSystem_1 == 3){
			scale_fact  = SF_3;
			center_lon  = LonCen_3;
			center_lat  = LatCen_3;
			false_east  = FE_3;
			false_north = FN_3;
		}
		else if(cboSystem_1 == 4){
			scale_fact  = SF_4;
            center_lon  = LonCen_4;
            center_lat  = LatCen_4;
            false_east  = FE_4;
            false_north = FN_4;
        }
		else if(cboSystem_1 == 5){
			scale_fact  = SF_5;
			center_lon  = LonCen_5;
			center_lat  = LatCen_5;
			false_east  = FE_5;
			false_north = FN_5;
		}
        else if(cboSystem_1 == 6){
            scale_fact  = SF_6;
            center_lon  = LonCen_6;
            center_lat  = LatCen_6;
            false_east  = FE_6;
            false_north = FN_6;
        }
        else {
            scale_fact  = SF_1;
            center_lon  = LonCen_1;
            center_lat  = LatCen_1;
            false_east  = FE_1;
            false_north = FN_1;
        }

        tmint(r_maj, r_min, scale_fact, center_lon, center_lat, false_east, false_north);
        Application->ProcessMessages();
        //TM of UTM calculating
        tmfor(out_lon, out_lat, &TMX, &TMY);
		_coorData._point.x = TMX;
		_coorData._point.y = TMY;

		out_lon = out_lon * 180 / PI;
		out_lat = out_lat * 180 / PI;

		_coorData._coord.y = out_lon;
		_coorData._coord.x = out_lat;

		//to make decimal degree into DMS
		d2dms(&out_lon, &out_lat, &LonMin, &LonSec, &LatMin, &LatSec);

		AnsiString txtdms_6  = (int)(out_lon);
		AnsiString txtdms_7  = LonMin;
		AnsiString txtdms_8  = FormatFloat("0.00", LonSec);
		AnsiString txtdms_9  = (int)(out_lat);
		AnsiString txtdms_10 = LatMin;
		AnsiString txtdms_11 = FormatFloat("0.00", LatSec);

		_coorData._long = txtdms_6 + "˚" + txtdms_7 + "′" + txtdms_8 + "″";
		_coorData._lat  = txtdms_9 + "˚" + txtdms_10 + "′" + txtdms_11 + "″";
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::tmfor(double Lon, double Lat, double *x, double *y)
{
    double delta_lon; //Delta longitude (Given longitude - center longitude)
    double theta; //angle
	double delta_theta; //adjusted longitude
    double sin_phi, cos_phi; //sin and cos value
    double al, als; //temporary values
    double b, c, t, tq; //temporary values
    double con, n, ml; //cone constant, small m

    //LL to TM Forward equations from here

    delta_lon = Lon - lon_center;
    sin_phi = sin(Lat);
    cos_phi = cos(Lat);

    if( ind != 0){
      b = cos_phi * sin(delta_lon);
      /*
	  If ((Abs(Abs(b) - 1.0)) < 0.0000000001) Then
         MsgBox "지정하신 점이 무한대로 갑니다", vbCritical
      End If
      */
    }
	else{
		*x   = 0.5 * r_major * scale_factor * log((1.0 + b) / (1.0 - b));
		con = acos1(cos_phi * cos(delta_lon) / sqrt(1.0 - b * b));
        if (Lat < 0){
            con = -con;
            *y = r_major * scale_factor * (con - lat_origin);
        }
    }

    al  = cos_phi * delta_lon;
    als = al * al;
    c   = esp * cos_phi * cos_phi;
    tq  = tan(Lat);
    t   = tq * tq;
    con = 1.0 - es * sin_phi * sin_phi;
    n   = r_major / sqrt(con);
    ml  = r_major * mlfn(e0, e1, e2, e3, Lat);

    *x  = scale_factor * n * al * (1.0 + als / 6.0 * (1.0 - t + c + als / 20.0 * (5.0 - 18.0 * t + t * t + 72.0 * c - 58.0 * esp))) + false_easting;
    *y  = scale_factor * (ml - ml0 + n * tq * (als * (0.5 + als / 24.0 * (5.0 - t + 9.0 * c + 4.0 * c * c + als / 30.0 * (61.0 - 58.0 * t + t * t + 600.0 * c - 330.0 * esp))))) + false_northing;
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::tmint(double r_maj, double r_min, double scale_fact, double center_lon, double center_lat, double false_east, double false_north)
{
    double temp;

    r_major        = r_maj;
    r_minor        = r_min;
    scale_factor   = scale_fact;
    lon_center     = center_lon;
    lat_origin     = center_lat;
    false_northing = false_north;
    false_easting  = false_east;

    temp           = r_minor / r_major;
    es             = 1.0 - temp * temp;
    e              = sqrt(es);
    e0             = e0fn(es);
    e1             = e1fn(es);
    e2             = e2fn(es);
    e3             = e3fn(es);
    ml0            = r_major * mlfn(e0, e1, e2, e3, lat_origin);
    esp            = es / (1.0 - es);

    if(es < 0.00001) ind = 1;
    else ind = 0;
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::tminv(double x, double y, double *Lon, double *Lat)
{
    double con;//temporary angles
    double phi;//temporary angles
    double delta_Phi;//difference between longitudes
    long i;//counter variable
    double sin_phi, cos_phi, tan_phi;//sin cos and tangent values
    double c, cs, t, ts, n, r, d, ds;//temporary variables
    double f, h, g, temp;//temporary variables

    int max_iter = 6; //maximun number of iterations

    if( ind != 0){
        f    = exp(x / (r_major * scale_factor));
        g    = 0.5 * (f - 1 / f);
        temp = lat_origin + y / (r_major * scale_factor);
        h    = cos(temp);
        con  = sqrt((1.0 - h * h) / (1.0 + g * g));
		*Lat = asinz1(con);

        if(temp < 0) *Lat = -*Lat;

        if ((g == 0) && (h == 0)) *Lon = lon_center;
        else *Lon = atan(g / h) + lon_center;
    }

    //TM to LL inverse equations from here

    x = x - false_easting;
    y = y - false_northing;

    con = (ml0 + y / scale_factor) / r_major;
    phi = con;

    i = 0;
    while(TRUE){
        delta_Phi = ((con + e1 * sin(2.0 * phi) - e2 * sin(4.0 * phi) + e3 * sin(6.0 * phi)) / e0) - phi;
		phi = phi + delta_Phi;
        if (fabs(delta_Phi) <= EPSLN) break;

        if (i >= max_iter){}
                //throw (CString)"Latitude failed to converge";

        i++;
    }

    if( fabs(phi) < (PI / 2)){
        sin_phi = sin(phi);
		cos_phi = cos(phi);
        tan_phi = tan(phi);
        c       = esp * cos_phi * cos_phi;
        cs      = c * c;
        t       = tan_phi * tan_phi;
        ts      = t * t;
        con     = 1.0 - es * sin_phi * sin_phi;
        n       = r_major / sqrt(con);
        r       = n * (1.0 - es) / con;
        d       = x / (n * scale_factor);
        ds      = d * d;
        *Lat     = phi - (n * tan_phi * ds / r) * (0.5 - ds / 24.0 * (5.0 + 3.0 * t + 10.0 * c - 4.0 * cs - 9.0 * esp - ds / 30.0 * (61.0 + 90.0 * t + 298.0 * c + 45.0 * ts - 252.0 * esp - 3.0 * cs)));
        *Lon     = lon_center + (d * (1.0 - ds / 6.0 * (1.0 + 2.0 * t + c - ds / 20.0 * (5.0 - 2.0 * c + 28.0 * t - 3.0 * cs + 8.0 * esp + 24.0 * ts))) / cos_phi);
    }
    else{
        *Lat = PI * 0.5 * sin(y);
        *Lon = lon_center;
    }
}
