int __fastcall TfrmMain::func_widthRateCalc(int fsize)
{
	double widthscale;
	double realvalue;
	int fontwidth, fontheight;
	int scalesizeX, scalesizeY;
	int nWidth  = 0;

	scalesizeY  = fsize / 0.8125;
	scalesizeX  = scalesizeY * 4;

	widthscale  = 0.15;

	fontwidth   = scalesizeX - (scalesizeX * widthscale * 2);
	fontwidth   = fontwidth / 8;
	realvalue   = fontwidth * m_MAININI.WIDTHRATE;
	nWidth      = realvalue;

	return nWidth;
}
