int __fastcall TfrmMain::func_calcCharLength(AnsiString strline)
{
	int length = 0;
	String temp = strline;
	String cTemp;
	int size = strline.Length() ;
	while(temp != ""){
		cTemp = temp.SubString(1,1);
		if(cTemp >= "가" && cTemp <= "힝") length = length + 13;
		else length = length + 9;
		temp.Delete(1,1);
	}
    return length;
}
