void __fastcall TfrmMain::func_CalcCoorNS(double _lat, double _lon,	int _gbn)
{
	// 변환작업시작
	double lon_temp;
	double lat_temp;
	double h;
	int i;

	h = 42.0;

	// Major axis of Bessel1841 and WGS84
	major_0 = 6377397.155;
	major_1 = 6378137.0;

	// Minor axis of Bessel1841 and WGS84
	minor_0 = 6356078.96325;
	minor_1 = 6356752.3142;

	// Scale reduction factor
	SF_1 = 1.0;
	SF_2 = 1.0;
	SF_3 = 1.0;
	SF_4 = 0.9999;
	SF_5 = 0.9996;
	SF_6 = 0.9996;

	// Longitude center
	LonCen_1 = 2.18171200985643;
	//=====================================================
	//241128//TEST//
//ORG//	LonCen_2 = 2.21661859489632;
//	if(_SIDOCODE.SubString(1, 2) != "44")
//		LonCen_2 = 2.216568150032796;
//	else
		LonCen_2 = 2.21661859489632;
	//=====================================================
	LonCen_3 = 2.2515251799362;
	LonCen_4 = 2.23402144255274;
	LonCen_5 = 2.25147473507269;
	LonCen_6 = 2.14675497995303;

	// Latitude origin
	LatCen_1 = 0.663225115757845;
	LatCen_2 = 0.663225115757845;
	LatCen_3 = 0.663225115757845;
	LatCen_4 = 0.663225115757845;
	LatCen_5 = 0.0;
	LatCen_6 = 0.0;

	// False northing
	FN_1 = 500000;
	FN_2 = 500000;
	FN_3 = 500000;
	FN_4 = 600000;
	FN_5 = 0.0;
	FN_6 = 0.0;

	// False easting
	FE_1 = 200000;
	FE_2 = 200000;
	FE_3 = 200000;
	FE_4 = 400000;
	FE_5 = 500000;
	FE_6 = 500000;

	//로드뷰
	int cboSystem_0 = 0;//m_MAININI.SYSTEM_CONVERT_SYSTEM_0;//0
	int cboEllips_0 = 1;//m_MAININI.SYSTEM_CONVERT_ELLIPS_0;//1
	int cboSystem_1 = 2;//m_MAININI.SYSTEM_CONVERT_SYSTEM_1;//2
	int cboEllips_1 = 0;//m_MAININI.SYSTEM_CONVERT_ELLIPS_1;//0

	lon_temp = _lon;
	lat_temp = _lat;

	if(_gbn == 1)
	{
		int doo;
		double temp, bun;
		temp = lat_temp / 100;
		doo = (int)temp;
		temp = temp -int(temp);
		temp = temp * 100; // 12.345
		bun = temp / 60; // 12.345 / 60
		lat_temp = doo + bun;

		temp = lon_temp / 100;
		doo = (int)temp;
		temp = temp -int(temp);
		temp = temp * 100; // 12.345
		bun = temp / 60; // 12.345 / 60
		lon_temp = doo + bun;
	}

	lon_temp = lon_temp * PI / 180;
	lat_temp = lat_temp * PI / 180;

	conv(lon_temp, lat_temp, h, 2);
}

