AnsiString __fastcall TfrmMain::func_ConvertLandcdToFullAddress(AnsiString _landcd)
{
	AnsiString selectsidonm = "";
	AnsiString selectemdnm  = "";
	AnsiString selectrinm   = "";
	AnsiString selectricd   = "";
	AnsiString jibun        = "";
	AnsiString san, bobn, bubn;
	AnsiString address      = "";

	selectsidonm = frmSql->func_ConvertSidoCDtoNM(_landcd.SubString(1,5));

	selectemdnm  = func_ConvertEmdCDtoNM(_landcd.SubString(1,8));
	if(selectricd != "00") selectrinm  = func_ConvertRiCDtoNM(_landcd.SubString(1,10));
	jibun = _landcd.SubString(11,9);
	san   = jibun.SubString(1,1);
	bobn  = jibun.SubString(2,4);
	bubn  = jibun.SubString(6,4);
	if(san == "2") san = "산";
	else san = "";

	while(bobn.SubString(1,1) == "0") bobn.Delete(1,1);
	while(bubn.SubString(1,1) == "0") bubn.Delete(1,1);

	jibun = san;
	if(bubn != "") jibun = jibun + bobn + "-" + bubn;
	else jibun = jibun + bobn ;
	if(selectrinm != "") address = selectemdnm + " " + selectrinm + " " + jibun;
	else address = selectemdnm + " " + jibun;

	return selectsidonm + " " + address;
}
