int __fastcall TfrmMain::func_base64_encode(char *text, int numBytes, char **encodedText)
{
	unsigned char input[3]  = {0,0,0};
	unsigned char output[4] = {0,0,0,0};
	int   index, i, j, size;
	char *p, *plen;
	plen           = text + numBytes - 1;
	size           = (4 * (numBytes / 3)) + (numBytes % 3? 4 : 0) + 1;
	(*encodedText) = (char*)malloc(size);
	j              = 0;

	for(i = 0, p = text;p <= plen; i++, p++) {
		index = i % 3;
		input[index] = *p;
		if (index == 2 || p == plen) {
			output[0] = ((input[0] & 0xFC) >> 2);
			output[1] = ((input[0] & 0x3) << 4) | ((input[1] & 0xF0) >> 4);
			output[2] = ((input[1] & 0xF) << 2) | ((input[2] & 0xC0) >> 6);
			output[3] = (input[2] & 0x3F);
			(*encodedText)[j++] = MimeBase64[output[0]];
			(*encodedText)[j++] = MimeBase64[output[1]];
			(*encodedText)[j++] = index == 0? '=' : MimeBase64[output[2]];
			(*encodedText)[j++] = index <  2? '=' : MimeBase64[output[3]];
			input[0] = input[1] = input[2] = 0;
		}
	}
	(*encodedText)[j] = '\0';
	return size;
}
//---------------------------------------------------------------------------
AnsiString __fastcall TfrmMain::func_Encoder(AnsiString _data)
{
	AnsiString result;
	result = _data;
	//210210//데이터에 콤마가 있으면 원본으로 변환 못함//result = StringReplace(result, ", ","", TReplaceFlags() << rfReplaceAll);

	if(result == "") return "";

	int len = result.Length();

	char* b64encoded_text = NULL;
	int len_b64_encoded = func_base64_encode(result.c_str(), len+1, &b64encoded_text);
	result = b64encoded_text;
	return result;
}
//---------------------------------------------------------------------------
int __fastcall TfrmMain::func_base64_decode(char *text, unsigned char *dst, int numBytes )
{
	const char* cp;
	int space_idx = 0, phase;
	int d, prev_d = 0;
	unsigned char c;
	space_idx = 0;
	phase = 0;

	for ( cp = text; *cp != '\0'; ++cp ) {
		d = DecodeMimeBase64[(int) *cp];
		if ( d != -1 ) {
			switch ( phase ) {
				case 0:
					++phase;
					break;
				case 1:
					c = ( ( prev_d << 2 ) | ( ( d & 0x30 ) >> 4 ) );
					if ( space_idx < numBytes )
						dst[space_idx++] = c;
					++phase;
					break;
				case 2:
					c = ( ( ( prev_d & 0xf ) << 4 ) | ( ( d & 0x3c ) >> 2 ) );
					if ( space_idx < numBytes )
						dst[space_idx++] = c;
					++phase;
					break;
				case 3:
					c = ( ( ( prev_d & 0x03 ) << 6 ) | d );
					if ( space_idx < numBytes )
						dst[space_idx++] = c;
					phase = 0;
					break;
			}
			prev_d = d;
		}
	}
	return space_idx;
}
//---------------------------------------------------------------------------
AnsiString __fastcall TfrmMain::func_Decoder(AnsiString _data )
{
	AnsiString result;
	result = _data;
	//210210//데이터에 콤마가 있으면 원본으로 변환 못함//result = StringReplace(result, ", ","", TReplaceFlags() << rfReplaceAll);

	if(result == "") return "";

	char *dst = (char*)malloc(200);
	int len_b64 = func_base64_decode(result.c_str(), dst, 200);
	result = dst;
	result = result.SubString(1,len_b64);
	free(dst);
	dst = NULL;

	return result;
}
