void __fastcall TfrmMain::IMGDOCMouseEnter(TObject *Sender)
{
	if(_CURRENT_WORKMODE  == "DOCUMENT"){
		//===============================================
		if(_CURRENT_DOCWORKMODE != "편의기능"){
			palConvBar->Visible	= false;
		}

		//===============================================
		if(_CURRENT_DOCWORKMODE != "파일저장"){
			funcFreeEachButtonImage(IMGDOCSAVEFILE);
		}

		if(_CURRENT_DOCWORKMODE != "인쇄"){
			funcFreeEachButtonImage(IMGDOCPRINT);
		}

		if(_CURRENT_DOCWORKMODE != "회전"){
			funcFreeEachButtonImage(IMGDOCROTATE);
		}

		if(_CURRENT_DOCWORKMODE != "영역선택" && _CURRENT_DOCWORKMODE != "영역지우기"){
			funcFreeEachButtonImage(IMGDOCRECTCLEAR);
		}

		if(_CURRENT_DOCWORKMODE != "음영조정"){
			funcFreeEachButtonImage(IMGDOCADJUST);
		}

		if(_CURRENT_DOCWORKMODE != "편의기능"){
			funcFreeEachButtonImage(IMGDOCCONV);
		}

		if(Sender == IMGDOCSAVEFILE)//파일저장
			IMGDOCSAVEFILE->Picture->Bitmap->Assign(BITMAP_BTN_DOC[SaveFile]);
		else if(Sender == IMGDOCPRINT)//인쇄
			IMGDOCPRINT->Picture->Bitmap->Assign(BITMAP_BTN_DOC[Print]);
		else if(Sender == IMGDOCROTATE)//회전
			IMGDOCROTATE->Picture->Bitmap->Assign(BITMAP_BTN_DOC[Rotate]);
		else if(Sender == IMGDOCRECTCLEAR)//영역지우기-영역삭제는 Click에서 선택한대로 변경하지 않는다//
			if(_CURRENT_DOCWORKMODE != "영역선택" && _CURRENT_DOCWORKMODE != "영역지우기")
				IMGDOCRECTCLEAR->Picture->Bitmap->Assign(BITMAP_BTN_DOC[RectClear]);
		else if(Sender == IMGDOCADJUST)//음영조정
			IMGDOCADJUST->Picture->Bitmap->Assign(BITMAP_BTN_DOC[Adjust]);
		else if(Sender == IMGDOCCONV)//편의기능
			IMGDOCCONV->Picture->Bitmap->Assign(BITMAP_BTN_DOC[Conv]);

		//
		AnsiString filename = "";
		Graphics::TBitmap *bmpTip;
		int left, top;

		left = palDocControlBar->Left;
		top = palDocControlBar->Top + palDocControlBar->Height;

		if(Sender == IMGDOCSAVEFILE){//파일저장
			bmpTip = BITMAP_BTN_HELP[TipSaveFile];
			left   = left + IMGDOCSAVEFILE->Left;
		}
		else if(Sender == IMGDOCPRINT){//파일인쇄
			bmpTip = BITMAP_BTN_HELP[TipPrint];
			left   = left + IMGDOCPRINT->Left + IMGDOCPRINT->Width/2;
		}
		else if(Sender == IMGDOCROTATE){//회전
			bmpTip = BITMAP_BTN_HELP[TipRotate];
			left   = left + IMGDOCROTATE->Left + IMGDOCROTATE->Width/2;
		}
		else if(Sender == IMGDOCRECTCLEAR){
			if(_CURRENT_DOCWORKMODE == "영역선택")//영역지우기//
				bmpTip = BITMAP_BTN_HELP[TipRectClear];
			else//영역선택//
				bmpTip = BITMAP_BTN_HELP[TipRectSelect];
			left   = left + IMGDOCRECTCLEAR->Left + IMGDOCRECTCLEAR->Width/2;
		}
		else if(Sender == IMGDOCADJUST){//음영조정
			bmpTip = BITMAP_BTN_HELP[TipAdjust];
			left   = left + IMGDOCADJUST->Left + IMGDOCADJUST->Width/2;
		}
		else if(Sender == IMGDOCCONV){//편의기능
			bmpTip = BITMAP_BTN_HELP[TipConv];
			left   = left + IMGDOCCONV->Left + IMGDOCCONV->Width/2;
		}

		//---
		IMGDOCTIP32->Bitmap = NULL;
		IMGDOCTIP32->Bitmap->Assign(bmpTip);

		if(palMainSearchBar->Visible && Sender == IMGDOCSAVEFILE)//
			IMGDOCTIP32->Left 	= left;
		else
			IMGDOCTIP32->Left 	= left - IMGDOCTIP32->Bitmap->Width / 2;
		IMGDOCTIP32->Top  	= top + 4;
		IMGDOCTIP32->Width 	= IMGDOCTIP32->Bitmap->Width;
		IMGDOCTIP32->Height = IMGDOCTIP32->Bitmap->Height;
		IMGDOCTIP32->Visible = true;
		IMGDOCTIP32->BringToFront();

		m_bIngIMGDOCCONTROL	  = true;
	}
}
