void __fastcall TfrmMain::IMGCONVMouseEnter(TObject *Sender)
{
	if(_CURRENT_WORKMODE  == "DOCUMENT"){
		if(_CURRENT_DOCWORKMODE != "한자찾기")
			funcFreeEachButtonImage(IMGCONVHANJA);
		if(_CURRENT_DOCWORKMODE != "연대환산")
			funcFreeEachButtonImage(IMGCONVCALCDATE);
		if(_CURRENT_DOCWORKMODE != "단위변환")
			funcFreeEachButtonImage(IMGCONVCALCAREA);
		if(_CURRENT_DOCWORKMODE != "계산기")
			funcFreeEachButtonImage(IMGCONVCALCULATOR);

		if(Sender == IMGDOCADJUST)//한자찾기
			IMGCONVHANJA->Picture->Bitmap->Assign(BITMAP_BTN_CONV[Hanja]);
		else if(Sender == IMGDOCCONV)//연대환산
			IMGCONVCALCDATE->Picture->Bitmap->Assign(BITMAP_BTN_CONV[CalcDate]);
		else if(Sender == IMGDOCCONV)//단위변환
			IMGCONVCALCAREA->Picture->Bitmap->Assign(BITMAP_BTN_CONV[CalcArea]);
		else if(Sender == IMGDOCCONV)//계산기
			IMGCONVCALCULATOR->Picture->Bitmap->Assign(BITMAP_BTN_CONV[Calcuator]);

		//
		AnsiString filename = "";
		Graphics::TBitmap *bmpTip;
		int left, top;

		left 	= palConvBar->Left + palConvBar->Width;
		top 	= palConvBar->Top;

		if(Sender == IMGCONVHANJA){//한자찾기
			bmpTip = BITMAP_BTN_HELP[TipHanja];
			top    = top + IMGCONVHANJA->Top + IMGCONVHANJA->Height/2;
		}
		else if(Sender == IMGCONVCALCDATE){//연대환산
			bmpTip = BITMAP_BTN_HELP[TipCalcDate];
			top    = top + IMGCONVCALCDATE->Top + IMGCONVCALCDATE->Height/2;
		}
		else if(Sender == IMGCONVCALCAREA){//단위변환
			bmpTip = BITMAP_BTN_HELP[TipOrg];
			top    = top + IMGCONVCALCAREA->Top + IMGCONVCALCAREA->Height/2;
		}
		else if(Sender == IMGCONVCALCULATOR){//공학계산기
			bmpTip = BITMAP_BTN_HELP[TipCalculator];
			top    = top + IMGCONVCALCULATOR->Top + IMGCONVCALCULATOR->Height/2;
		}

		//---
		IMGDOCTIP32->Bitmap = NULL;
		IMGDOCTIP32->Bitmap->Assign(bmpTip);
		IMGDOCTIP32->Left 	= left;
		IMGDOCTIP32->Top  	= top - IMGDOCTIP32->Bitmap->Height / 2;
		IMGDOCTIP32->Width 	= IMGDOCTIP32->Bitmap->Width;
		IMGDOCTIP32->Height = IMGDOCTIP32->Bitmap->Height;
		IMGDOCTIP32->Visible = true;
		IMGDOCTIP32->BringToFront();
	}
}
