void __fastcall TfrmMain::IMGZOOMMouseEnter(TObject *Sender)
{
	int left, top, width, height, center;
	IMGCOMTIP32->Bitmap         = NULL;

	left = palZoomControlBar->Left;
	top  = palZoomControlBar->Top;
	IMGCOMTIP32->BringToFront();

	if(Sender == IMGZOOMIN){//확대
		IMGCOMTIP32->Bitmap->Assign(BITMAP_BTN_HELP[TipZoomIn]);
		width  = IMGCOMTIP32->Bitmap->Width;
		height = IMGCOMTIP32->Bitmap->Height;

		left   = left - width;
		top    = top  + IMGZOOMIN->Top + (IMGZOOMIN->Height - height) / 2;
		IMGCOMTIP32->Left = left - 4;
		IMGCOMTIP32->Top  = top;
	}
	else if(Sender == IMGZOOMOUT){//축소
		IMGCOMTIP32->Bitmap->Assign(BITMAP_BTN_HELP[TipZoomOut]);
		width  = IMGCOMTIP32->Bitmap->Width;
		height = IMGCOMTIP32->Bitmap->Height;

		left   = left - width;
		top    = top  + IMGZOOMOUT->Top + (IMGZOOMOUT->Height - height) / 2;
		IMGCOMTIP32->Left = left - 4;
		IMGCOMTIP32->Top  = top;
	}

	IMGCOMTIP32->Width  	= width;
	IMGCOMTIP32->Height 	= height;
	IMGCOMTIP32->Visible 	= true;
}
