void __fastcall TfrmMain::IMGZOOMClick(TObject *Sender)
{
	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 확대/축소를 해주세요.", 3);
		return;
	}

	funcClosePanel();//200110

	if(Sender == IMGZOOMIN){//확대
		if(_CURRENT_WORKMODE == "SPATIAL"){
			IMGZOOMIN->Picture->Bitmap->Assign(BITMAP_BTN_SPATIAL[SpatialZoomIn]);

			//한단계 확대 호출
			m_nZoomFactor++;
			if(m_nZoomFactor > 10) m_nZoomFactor = 10;
			//funcSetZoomBarPos(false);
			btnZoomTrackBar->Value = m_nZoomFactor;

			func_DrawImagePaint();
			Application->ProcessMessages();

			funcFreeEachButtonImage(IMGZOOMIN);
		}
		//M
		else if(_CURRENT_WORKMODE == "DOCUMENT"){
			//한단계 확대 호출
			if(mGetImageInfo.m_DIB != NULL){//확대
				//201217//44230Req//m_dDocFactor = m_dDocFactor + dScaleGap;
				m_dDocFactor = funcGetImageScale(true);//201217//44230Req//

				m_nSrcWidth  = (int)((double)IMGSCREEN2->Width / m_dDocFactor);
				m_nSrcHeight = (int)((double)IMGSCREEN2->Height / m_dDocFactor);
				realLeft     = (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
				realTop      = (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);

				func_DrawImage();
			}
			//#####################################################
			Application->ProcessMessages();

			funcFreeEachButtonImage(IMGZOOMIN);
		}
	}
	else if(Sender == IMGZOOMOUT){//축소
		if(_CURRENT_WORKMODE == "SPATIAL"){
			IMGZOOMOUT->Picture->Bitmap->Assign(BITMAP_BTN_SPATIAL[SpatialZoomOut]);

			//한단계 축소 호출
			m_nZoomFactor--;
			if(m_nZoomFactor < 1) m_nZoomFactor = 1;
			//funcSetZoomBarPos(false);
			btnZoomTrackBar->Value = m_nZoomFactor;

			func_DrawImagePaint();
			Application->ProcessMessages();

			funcFreeEachButtonImage(IMGZOOMOUT);
		}
		//M
		else if(_CURRENT_WORKMODE == "DOCUMENT"){
			//#####################################################
			if(mGetImageInfo.m_DIB != NULL){//축소
				if( m_dDocFactor == m_dDocFitFactor)	return;

				//201217//44230Req//m_dDocFitFactor
				m_dDocFactor	= funcGetImageScale(false);
				if(m_dDocFactor <= m_dDocFitFactor)
					m_dDocFactor	= m_dDocFitFactor;
				//201217//44230Req//m_dDocFitFactor
//				if(m_dDocFactor - dScaleGap <= m_dDocFitFactor){ m_dDocFactor = m_dDocFitFactor; }
//				else m_dDocFactor = m_dDocFactor - dScaleGap;

				m_nSrcWidth  = (int)((double)IMGSCREEN2->Width / m_dDocFactor);
				m_nSrcHeight = (int)((double)IMGSCREEN2->Height / m_dDocFactor);

				realLeft     = (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
				realTop      = (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);

				func_DrawImage();
			}
			//#####################################################
			Application->ProcessMessages();

			funcFreeEachButtonImage(IMGZOOMOUT);
		}
	}
}
