int __fastcall TfrmMain::func_readKindOfSymbolIndex(AnsiString _landcd)
{
	int size = frmSql->m_vKINDOFSYMBOLDATA.size();
	int result = -1;

	if(size > 0){
		AnsiString temp;
		int head, mid, tail, prev;
		head = 0;
		tail = size;
		mid  = (tail + head)/2;

		temp   = (char*)frmSql->m_vKINDOFSYMBOLDATA[mid].LAND_KEY;
		if(_landcd != ""){
			while(1){
				if(_landcd < temp) tail = mid;
				else if(_landcd > temp) head = mid;
				else{
					result = mid;
					break;
				}
				prev = mid;
				mid = (head + tail)/2;
				temp = (char*)frmSql->m_vKINDOFSYMBOLDATA[mid].LAND_KEY;
				if(prev == mid){
					break;
				}
			}
		}
	}
	return result;
}
