bool __fastcall TfrmMain::func_readKindofDocYN(AnsiString _landcd, int _nDocNo)
{
	int size;
	size = frmSql->m_vKINDOFSYMBOLDATA.size();

	bool bResult = false;

	if(size > 0){
		AnsiString readlandcd;
		int head, mid, tail, prev;
		head = 0;
		tail = size;
		mid  = (tail + head)/2;

		readlandcd = (char*)frmSql->m_vKINDOFSYMBOLDATA[mid].LAND_KEY;

		while(1){
			if(_landcd < readlandcd) tail = mid;
			else if(_landcd > readlandcd) head = mid;
			else{
				if(_nDocNo == 1)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC01_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 2)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC02_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 3)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC03_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 4)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC04_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 20)//241211//[DOC20_YN]//else if(_nDocNo == 5)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC05_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 6)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC06_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 7)//201008//
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC07_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 8)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC08_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 9)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC09_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 11)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC11_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 12)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC12_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 14)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC14_YN, "1"))
						bResult = true;
				}
				else if(_nDocNo == 17)
				{
					if( !strcmp(frmSql->m_vKINDOFSYMBOLDATA[mid].DOC17_YN, "1"))
						bResult = true;
				}
				break;
			}
			prev = mid;
			mid = (head + tail)/2;

			readlandcd = (char*)frmSql->m_vKINDOFSYMBOLDATA[mid].LAND_KEY;

			if(prev == mid){
				break;
			}
		}
	}

	return bResult;
}
