int __fastcall TfrmMain::func_POISelectTrack(GPoint point,TRect rect)
{
	int m_nSelectIDNum = -1;

	// 점을 찍었는지 선을 찍었는지 hit test 한다.
	int ID;      // 오브젝트 아이디...
	int PointID; // 몇번재 포인트인가..

	hit_status hit_test = func_POIHitTest(point, rect, ID, PointID);

	if ((hit_test != hitPoint) && (hit_test != hitCurve) && (hit_test != hitPolygon)){
		if (m_eStatus == stateSelect){
			m_eStatus = stateNone;
		}
		m_nSelectIDNum = -1;
		return -1;
	}

	m_nSelectIDNum = ID;

	// 원래 선택이 되어있지 않았다면, 선택된 것을 표시하기 위해 한번 그려준다.
	if (m_eStatus == stateNone){
		m_eStatus = stateSelect;
		hit_test = hitCurve;

		if(ID != -1){
			return m_nSelectIDNum;
		}
	}

	// 상태를 선택한 것으로 변화시킨다.
	m_eStatus = stateSelect;

	if(ID != -1){
        return m_nSelectIDNum;
	}
	return m_nSelectIDNum;
}
//---------------------------------------------------------------------------
TfrmMain::hit_status TfrmMain::func_POIHitTest(GPoint _gPoint, TRect _rctScreen, int& _ID, int& _PointID)
{
	POINT_LIST::iterator iter;
	RECT mbrRect, rectBuffer;
	mbrRect = func_WorldToDevice(m_MBR);

	//디버그 모드일 경우만 된다...이상하다....된장
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen)){
        return hitNone;
    }
    // 면 위를 본다.
	int i,j,k;

	int m_nRecords;

	m_nRecords = (int)frmSql->m_vKINDOFSYMBOLDATA.size();

	int icount = 0;
	bool selectOption = false;
	MBR sizeMBR;
	HRGN fRGN;
	bool success = false;

	for(i =0; i < m_nRecords; ++i){
		// 화면 밖이면 처리하지 않는다.
		mbrRect = func_WorldToDevice(frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen)){
			continue;
		}

		GPoint iPoint;
		iPoint.x = frmSql->m_vKINDOFSYMBOLDATA[i].x;
		iPoint.y = frmSql->m_vKINDOFSYMBOLDATA[i].y;

		if (func_PtInRect(iPoint, _gPoint)){
			if(selectOption == false){
				selectOption = true;
				sizeMBR = frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR;
				_ID = frmSql->m_vKINDOFSYMBOLDATA[i].m_nID;
				break;
			}
			else{
				if(sizeMBR.xmax >= frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR.xmax && sizeMBR.ymax >= frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR.ymax){
					sizeMBR = frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR;
					_ID = frmSql->m_vKINDOFSYMBOLDATA[i].m_nID;
					break;
				}
			}
		}
	}

	if(selectOption == true) return hitPolygon;
	if(icount > 0) return hitPolygon;
	return hitNone;
}
//---------------------------------------------------------------------------
bool __fastcall TfrmMain::func_PtInRect(const GPoint& _geoInputPoint, const GPoint& _geoRectCenter) //API 함수 재정의
{
	int nOffset = (m_nZoomFactor*2)/2;

	if(_geoInputPoint.x < (_geoRectCenter.x - (double)nOffset / m_lfZoomFactor / m_lfRatio))
		return false;
	else if(_geoInputPoint.x > (_geoRectCenter.x + (double)nOffset / m_lfZoomFactor / m_lfRatio))
		return false;
	else if(_geoInputPoint.y < ( _geoRectCenter.y - (double)nOffset / m_lfZoomFactor/ m_lfRatio))
		return false;
	else if(_geoInputPoint.y > ( _geoRectCenter.y + (double)nOffset / m_lfZoomFactor / m_lfRatio))
		return false;
	else
		return true;
}
