int __fastcall TfrmMain::func_ICONSymbolSelectTrack(GPoint point, TRect rect)
{
	int nSelectIDNum = -1;

	if(INIINFO.DOC_COUNT == 0 || m_nZoomFactor < INIINFO.DOC_LEVEL)//DOC_LEVEL 이전단계라면 NOACTION
		return nSelectIDNum;


	// 점을 찍었는지 선을 찍었는지 hit test 한다.
	int ID;      // 오브젝트 아이디...
	int PointID; // 몇번재 포인트인가..

	hit_status hit_test = func_ICONSymbolHitTest(point, rect, ID, PointID);

	if ((hit_test != hitPoint) && (hit_test != hitCurve) && (hit_test != hitPolygon)){
		if (m_eStatus == stateSelect){
			m_eStatus = stateNone;
		}
		nSelectIDNum = -1;
		return -1;
	}

	nSelectIDNum = ID;

	// 원래 선택이 되어있지 않았다면, 선택된 것을 표시하기 위해 한번 그려준다.
	if (m_eStatus == stateNone){
		m_eStatus = stateSelect;
		hit_test = hitCurve;

		if(ID != -1){
			return nSelectIDNum;
		}
	}

	// 상태를 선택한 것으로 변화시킨다.
	m_eStatus = stateSelect;

	if(ID != -1){
		return nSelectIDNum;
	}
	return nSelectIDNum;
}
