TfrmMain::hit_status TfrmMain::func_ICONSymbolHitTest(GPoint _gPoint, TRect _rctScreen, int& _ID, int& _PointID)
{
	POINT_LIST::iterator iter;
	RECT mbrRect, rectBuffer;
	mbrRect = func_WorldToDevice(m_MBR);

	//디버그 모드일 경우만 된다...이상하다....된장
	if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen)){
        return hitNone;
    }
    // 면 위를 본다.
	int i,j,k;

	int nRecords;

	nRecords = (int)frmSql->m_vKINDOFSYMBOLDATA.size();

	int icount = 0;
	bool selectOption = false;
	MBR sizeMBR;
	HRGN fRGN;
	bool success = false;

	for(i =0; i < nRecords; ++i){
		// 화면 밖이면 처리하지 않는다.
		mbrRect = func_WorldToDevice(frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR);
		if(!IntersectRect(&rectBuffer,&mbrRect, &_rctScreen)){
			continue;
		}

		GPoint iPoint;
		iPoint.x = frmSql->m_vKINDOFSYMBOLDATA[i].x;
		iPoint.y = frmSql->m_vKINDOFSYMBOLDATA[i].y;

		if (func_PtInRect(iPoint, _gPoint)){
			if(selectOption == false){
				selectOption = true;
				sizeMBR = frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR;
				_ID = frmSql->m_vKINDOFSYMBOLDATA[i].m_nID;
				break;
			}
			else{
				if(sizeMBR.xmax >= frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR.xmax && sizeMBR.ymax >= frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR.ymax){
					sizeMBR = frmSql->m_vKINDOFSYMBOLDATA[i].m_MBR;
					_ID = frmSql->m_vKINDOFSYMBOLDATA[i].m_nID;
					break;
				}
			}
		}
	}

	if(selectOption == true) return hitPolygon;
	if(icount > 0) return hitPolygon;
	return hitNone;
}
