//#INDEXICON#폐쇄지적도 아이콘 클릭 시 pnlPoi 상단에 표시할 라벨링//
AnsiString __fastcall TfrmMain::func_ConvertIndexCDtoNM(AnsiString selectcd)
{
	AnsiString 	emdcd 	= selectcd.SubString(1,8);
	AnsiString 	emdnm 	= "";
	AnsiString 	ricd  	= selectcd.SubString(9,2);
	AnsiString 	rinm  	= "";
	AnsiString 	scale  	= selectcd.SubString(12,2);
	AnsiString 	doho  	= selectcd.SubString(15,3);
	AnsiString 	result 	= "";
	int 		nScale  = 0;
	int			nDoho	= 0;

	if( !scale.IsEmpty() )
		nScale = scale.ToInt();

	if( !doho.IsEmpty() )
		nDoho = doho.ToInt();

	emdnm = func_ConvertEmdCDtoNM(emdcd);
	if(ricd != "00")
		rinm  = func_ConvertRiCDtoNM(selectcd.SubString(1,10));

	result = emdnm;
	if( !rinm.IsEmpty() )
		result = result + " " + rinm;

	if( nDoho > 0 )
		result = result + " " + IntToStr(nDoho) + "호";

	if( nScale > 0 )
		result = result + " " + IntToStr(nScale) + "00 축척";

	return result;
}
