void __fastcall TfrmMain::IMGMODECHANGEClick(TObject *Sender)
{
	if(frmUserLogList->Tag == 2 && frmUserLogList->Showing)//200429//
		frmUserLogList->Close();

	if(pnlPoiInfo->Visible)
		pnlPoiInfo->Visible = false;

	if( (Sender == IMGMODECHANGEJIJUK && _CURRENT_WORKMODE == "SPATIAL" && currentModeShow8)
	 || (Sender == IMGMODECHANGEDOC && _CURRENT_WORKMODE == "DOCUMENT") )
		return;

	if(Sender == IMGMODECHANGEDOC)//항공뷰 -> 문서보기
	{
		_CURRENT_WORKMODE          	= "DOCUMENT";
	}
	else//문서보기 -> 항공뷰
	{
		//210204//LOADING_TEST
		//===================================================
		if( !m_bJijukLoading )
		{
			//-----------------------------
			lblWait1->Caption  = "지적도를 로딩중입니다.";
			lblWait2->Caption  = "처음 로딩 시 다소 시간이 소요됩니다.";
			funcSetWaitWindows(true);//210326//#PERSON_INFO
			//-----------------------------

			frmSql->func_readConfigData();
			//프로그래스 폼 출력

//==========================================================
//v1.0.0.0//Use DB Value
//		//210427//#ROADVIEW
//		roadviewUrl	= "112.220.25.34/loadview_kakao4";
//==========================================================

//241216//위치이동//[지적도]띄우기 해야지만 KRAS 정보 가지고 오기에 위치 이동함//			frmSql->func_readMainIni();
			func_daumKeySet();

			frmSql->func_readCodeConvert();

			//===================================================
			frmSql->func_readKindofSymbol();//200626//연속지적도상에 표현할 수 있는 지번만 심볼정보를 갖고 있는다//
			frmSql->func_readMemoLandkeyData();


			//===========================================================================
			// GetTickCount 체크
			//===========================================================================
			DWORD startTickCount;
			DWORD currentTickCount;
			startTickCount = Gr32_system::GetTickCount();
			//===========================================================================


			//===================================================
			//공간파일 읽기
			//===================================================
			func_readSpatialDataFile();
			//===================================================


			//===========================================================================
			// GetTickCount 체크
			//===========================================================================
			currentTickCount	= Gr32_system::GetTickCount();
			AnsiString asMsg	= "D:" + IntToStr((int)(currentTickCount - startTickCount));
			if(m_bDEBUG)
				funcSetStatusBarMsg(2, asMsg);
			//===========================================================================


			//===========================================================================
			//210428//#MAP
			if(m_MBR.xmax == 0 || m_MBR.ymax == 0)
			{
				//-----------------------------
				funcSetWaitWindows(false);//210326//#PERSON_INFO
				//-----------------------------
				frmMsg->funcMessageDlg("파일부재 알림:", "MAP 파일을 확인해주세요.", 3);
				return;
			}
 			//===========================================================================

			func_readBaseOption();

			Screen->Cursor  = crDefault;



			//=======================================================
			//241127//가감대장 문서 열람 중 '지적도' On > 가감대장(기준점) 레이어 Off이면 On 묻기//
			//=======================================================
			if(m_nViewDocNo == 20 && INI_B_GAGAM)
			{
				if(!INIUSERSETINFO.B_GAGAMLAYER)
				{
					frmMsg->funcMessageDlg("알림:", "가감(기준점) 레이어를 표시하시겠습니까?", 1);
					if(frmMsg->m_bClick == 1)//Yes
					{
						INIUSERSETINFO.B_GAGAMLAYER	= true;
						USERSETINI->WriteInteger(L"LAYER", L"GAGAM", INIUSERSETINFO.B_GAGAMLAYER);
					}
				}

				//열람 중 문서가 '가감대장 관련문서'이면 '지적도' On 했을 때, 해당 가감레이어 표시하기//
				DOCUMENT20_STRUCT	*mDoc20Struct;
				mDoc20Struct = (DOCUMENT20_STRUCT*)mSearchNode.tSelectNode->Data;
				if ( mDoc20Struct )
				{
					AnsiString asMNUM = "";
					asMNUM.sprintf("%s%s%s", (char*)mDoc20Struct->UMDRI_CD, (char*)mDoc20Struct->KWON_NO, (char*)mDoc20Struct->GAGAM_NO);
					//가감대장 선택 아이콘 표시//
					funcGetGagamIndex(asMNUM);
				}
			}
			//=======================================================

			//cbShow08->Checked = true;

//241125//테이블 생성은 로딩 시 1회만 진행//
//			if(INIINFO.B_ENCRYPT)
//				frmSql->funcSQLCreateTableDecryptFile();

//241122//NotUsed//
////minji@230310//위치이동(TO)//항공뷰이미ON -> 문서 -> 지적도 들어가면 항공뷰on이 초기화되어 위치이동//
//			//191214//사장님Req//
//			if(INIUSERSETINFO.B_VIEWAIR)//200601//44250//스크립트오류때문에 일단 '항공뷰' 기본 해제//INI에서만 한다//currentModeShow8            = true;//200311//사장님Req//
//				currentModeShow8            = true;
//			else
//				currentModeShow8            = false;


			//200401//TEST//PROGRAM_START   = TRUE;
			m_bJijukLoading	= true;

			//-----------------------------
			funcSetWaitWindows(false);//210326//#PERSON_INFO
			//-----------------------------
		}
		//===================================================

		_CURRENT_WORKMODE          	= "SPATIAL";
		currentModeShow1            = true;//191214//사장님Req//
//minji@230310//위치이동(FROM)//
//		//191214//사장님Req//
//		if(INIUSERSETINFO.B_VIEWAIR)//200601//44250//스크립트오류때문에 일단 '항공뷰' 기본 해제//INI에서만 한다//currentModeShow8            = true;//200311//사장님Req//
//			currentModeShow8            = true;
//		else
//			currentModeShow8            = false;

		//=======================================================
		//210308//#LOAING_TEST
		if(m_bJijukLoading && m_asSearchPnu.Length() == 19)
		{
			frmSearch->funcSaveLog(9, 0, "JIBUN");
			func_JibunUnifiedSearch(m_asSearchText, INIINFO.SIDOCODE);
		}
		//=======================================================
	}

	funcSetMainViewBar();//260611//IMGMODECHANGEClick
	//200109//IMGSPREAD->BringToFront();
}
