void __fastcall TfrmMain::IMGLAYERClick(TObject *Sender)
{
	if(pnlPoiInfo->Visible)
		pnlPoiInfo->Visible = false;

	if(palRegistSet->Visible)
	{
		funcFreeEachButtonImage(IMGREGIST);
		IMGREGIST->Picture->Bitmap->Assign(BITMAP_BTN_REGIST[0][RegistIcon]);
		palRegistSet->Visible = false;
	}

	if(Sender == IMGLAYER)//레이어
	{
		if(_CURRENT_WORKMODE == "DOCUMENT")
			return;

		if( !palLayerSet->Visible )
		{
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERAIR, currentModeShow8, false);
			//=============================================

			//법정경계//
			int configindex1 = func_ConfigIndexAlloc(1,"리경계", "");
			if(configindex1 < 0) return;
			int configindex2 = func_ConfigIndexAlloc(1,"읍면동경계", "");
			if(configindex2 < 0) return;

			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERLEGAL, m_vCONFIGLP[configindex1].showuse && m_vCONFIGLP[configindex2].showuse, false);
			//=============================================

			if(frmMain->INIINFO.B_MEMO)//Memo//191124
			{
				IMGLAYERMEMO->Visible = true;
				//=============================================
				//241205//[레이어] 이미지 표시 설정//
				//=============================================
				funcSetImageLayer(IMGLAYERMEMO, INIINFO.B_MEMO, false);
				//=============================================
			}

//191223//사장님Req//
//			if(frmMain->INIINFO.B_PHOTO)//Photo
//			{
//				IMGLAYERPHOTO->Visible = true;
//				if(INIINFO.B_PHOTO)
//				{
//					IMGLAYERPHOTO->Picture->Bitmap->Assign(BITMAP_BTN_LAYERPHOTO[1]);
//				}
//				else
//				{
//					IMGLAYERPHOTO->Picture->Bitmap->Assign(BITMAP_BTN_LAYERPHOTO[0]);
//				}
//			}

			if(frmMain->INIINFO.B_POLY)//Poly
			{
				IMGLAYERPOLY->Visible = true;
				//=============================================
				//241205//[레이어] 이미지 표시 설정//
				//=============================================
				funcSetImageLayer(IMGLAYERPOLY, INIINFO.B_POLY, false);
				//=============================================
			}

			//220105//문서심볼 사용자 선택하기전까지 띄우지 마라//
			IMGLAYERDOC->Visible = true;
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERDOC, INIINFO.DOC_SHOW, false);
			//=============================================

			if(frmMain->INIINFO.B_DOCKIND[18])//Doc18//191127
			{
				IMGLAYERDOGN->Visible = true;
				//=============================================
				//241205//[레이어] 이미지 표시 설정//
				//=============================================
				funcSetImageLayer(IMGLAYERDOGN, INIINFO.B_QRYCHECK[18], false);
				//=============================================
			}

			//실건물보기//200311
			IMGLAYERHYBRID->Visible = true;
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERHYBRID, cbViewHybrid->Checked, false);
			//=============================================

			//=============================================================================
			//231021//GAGAMLAYER in LandArchive
			//=============================================================================
			if(INI_B_GAGAM)//시군별 전체설정 VALUE//
			{
				IMGLAYERGAGAM->Visible = true;

				//=============================================
				//241205//[레이어] 이미지 표시 설정//
				//=============================================
				funcSetImageLayer(IMGLAYERGAGAM, INIUSERSETINFO.B_GAGAMLAYER, false);
				//=============================================
			}
		}

		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYER, !palLayerSet->Visible, true);
		//=============================================
	}
}
