void __fastcall TfrmMain::IMGLAYERSETClick(TObject *Sender)
{
	if(_CURRENT_WORKMODE == "DOCUMENT")
		return;

	//=============================================
	//241205//[레이어] 이미지 표시 설정//
	//=============================================
	funcSetImageLayer(IMGLAYER, true, false);
	//=============================================

	if(Sender == IMGLAYERAIR){//레이어_지적도//
		currentModeShow8	= !currentModeShow8;//191214//사장님Req//

		if(currentModeShow8)//항공뷰//
		{
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERAIR, true, false);
			//=============================================
		}
		else
		{
			if(cbViewHybrid->Checked)//<하이브리드>는 <항공뷰>상태에서만//
			{
				//=============================================
				//241205//[레이어] 이미지 표시 설정//
				//=============================================
				funcSetImageLayer(IMGLAYERHYBRID, false, true);
				//=============================================
			}
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYER, false, false);
			//=============================================
		}

		if(currentModeShow8 == true){
			if(StatusBar1->Panels->Items[5]->Text == "") funcSetStatusBarMsg(5, "본지도는 열람조회용으로 제공하는 것으로 실제 이용현황과 다를 수 있습니다. 참고바랍니다.");
		}
		else{
			if(StatusBar1->Panels->Items[5]->Text != "") funcSetStatusBarMsg(5, "");
		}
	}
	else if(Sender == IMGLAYERLEGAL){//레이어_법정경계 //
		int configindex1 = func_ConfigIndexAlloc(1,"리경계", "");
		if(configindex1 < 0) return;
		int configindex2 = func_ConfigIndexAlloc(1,"읍면동경계", "");
		if(configindex2 < 0) return;
		//
		m_vCONFIGLP[configindex1].showuse	= !m_vCONFIGLP[configindex1].showuse;
		m_vCONFIGLP[configindex2].showuse	= !m_vCONFIGLP[configindex2].showuse;

		if(currentModeShow1)
		{
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGLAYERLEGAL, m_vCONFIGLP[configindex1].showuse && m_vCONFIGLP[configindex2].showuse, false);
			//=============================================
		}
	}
	else if(Sender == IMGLAYERDOC){//레이어_문서 //
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERDOC, !INIINFO.DOC_SHOW, true);
		//=============================================


		//=====================================================================
		//241203//[문서] 레이어 ON && 설정된 문서 개수가 0이라면 팝업 처리//
		//=====================================================================
		if( INIINFO.DOC_SHOW && frmChangeMenu->m_nChkPoiCnt == 0 )
		{
			frmMsg->funcMessageDlg("알림:", "설정된 문서가 없습니다. [검색문서설정].문서심볼을 체크해주세요", 3);
			if( !frmChangeMenu->Showing )
				IMGCHANGEMENUClick(IMGTABSET);
		}
		//=====================================================================

	}
	else if(Sender == IMGLAYERDOGN){//레이어_좌표계산부//
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERDOGN, !INIINFO.B_QRYCHECK[18], true);
		//=============================================
	}
	else if(Sender == IMGLAYERMEMO){//레이어_메모//
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERMEMO, !INIINFO.B_MEMO, true);
		//=============================================
	}
	else if(Sender == IMGLAYERPOLY){//레이어_영역//
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERPOLY, !INIINFO.B_POLY, true);
		//=============================================
	}
	//200311
	else if(Sender == IMGLAYERHYBRID){//레이어_실건물보기(HYBRID) //
		if( !cbViewHybrid->Checked && !currentModeShow8)
		{
			frmMsg->funcMessageDlg("알림:", "<하이브리드>는 <항공뷰>상태에서 가능합니다.", 3);
			return;
		}

		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERHYBRID, !cbViewHybrid->Checked, true);
		//=============================================
	}
//=============================================================================
//231113//GAGAMLAYER in LandArchive//
//=============================================================================
	else if(Sender == IMGLAYERGAGAM){//레이어_가감대장//
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGLAYERGAGAM, !INIUSERSETINFO.B_GAGAMLAYER, true);
		//=============================================

		USERSETINI->WriteInteger(L"LAYER", L"GAGAM", INIUSERSETINFO.B_GAGAMLAYER);
	}

	//공통//
	if(IMGSCREEN1->Visible == false) IMGSCREEN1->Visible = true;
	func_DrawImagePaint();

//=============================================================================
//	else if(Sender == IMGLAYERINDEX){//레이어_인덱스//
//		int nCnt = 0;
//		for(int i = 2; i < 8; i ++)
//		{
//			if(m_vCONFIGLP[i].showuse)
//				nCnt++;
//		}
//		if(IMGSCREEN1->Visible == false) IMGSCREEN1->Visible = true;
//		func_DrawImagePaint();
//	}
}
