//미리보기 有 : 검색창숨기기 1회 - 미리보기 숨기기, 2회 - 검색창 최소화
//미리보기 無 : 검색창숨기기 1회 - 검색창 최소화
void __fastcall TfrmMain::IMGSPREADClick(TObject *Sender)
{
	//210427//#ROADVIEW
	if(currentModeShow3 && panelback1->Visible)
	{
		IMGROADVIEWClick(IMGROADVIEW);
		return;
	}

	funcFreeEachButtonImage(IMGSPREAD);
	Application->ProcessMessages();

	//M//191108//미니검색창이 보여도 메인검색창을 visible == false하지 않고, 위치만 변경해서 안보이게 처리한다//
	//검색결과 그대로 처리해야 해서//
	if(IMGSPREAD->Tag == 1)//show->hide
	{
		if(pnlPreview->Visible)//Exist Thumb
		{
			if(pnlPreview->Width == 0)//200806
			{
				IMGSPREAD->Tag				= 2;
				pnlPnuList->Visible			= false;//220504//#GSCERT//
				palMiniSearchBar->Visible 	= true;
				//palMainSearchBar->Left    = 0 - palMainSearchBar->Width;
				Application->ProcessMessages();
				edtMiniSearchText->Text 	= edtMainSearchText->Text;
				palMainSearchBar->Width     = 0;
				pnlSystem->Visible			= false;//200318//
			}
			else
			{
				if( !palMiniSearchBar->Visible )//Main Show + Thumb Hide
				{
					m_nPreviewWidth         = pnlPreview->Width;
					pnlPreview->Width 		= 0;
					pnlSPREAD->Left			= pnlPreview->Width + 1;//200827
					palMiniSearchBar->Left	= EDGEGAP;
				}
				else//Mini Hide -> Main Show
				{
					IMGSPREAD->Tag				= 2;
					pnlPnuList->Visible			= false;//220504//#GSCERT//
					palMiniSearchBar->Visible 	= false;
					//palMainSearchBar->Left    = 0;
					edtMainSearchText->Text 	= edtMiniSearchText->Text;
					palMainSearchBar->Left		= 0;
					palMainSearchBar->Width		= 340;
					pnlSystem->Visible			= true;//200318//
					pnlSystem->Left				= palMainSearchBar->Left + pnlSearchBar->Left + IMGHEAD2->Left + IMGHEAD2->Width;//200318//
					pnlSystem->Top				= 0;
				}
			}
		}
		else//No Thumb
		{
			IMGSPREAD->Tag	= 2;
			pnlPnuList->Visible			= false;//220504//#GSCERT//
			palMiniSearchBar->Visible 	= true;
			//palMainSearchBar->Left    = 0 - palMainSearchBar->Width;
			Application->ProcessMessages();
			edtMiniSearchText->Text 	= edtMainSearchText->Text;
			palMainSearchBar->Width     = 0;
			pnlSystem->Visible			= false;//200318//
		}
	}
	else//hide->show
	{
		if(pnlPreview->Visible)//Exist Thumb
		{
			if(pnlPreview->Width == 0)//200806
			{
				if( palMiniSearchBar->Visible )//Main Show
				{
					palMiniSearchBar->Visible 	= false;
					//palMainSearchBar->Left    = 0;
					edtMainSearchText->Text 	= edtMiniSearchText->Text;
					palMainSearchBar->Left		= 0;
					palMainSearchBar->Width		= 340;
					pnlSystem->Visible			= true;//200318//
					pnlSystem->Left				= palMainSearchBar->Left + pnlSearchBar->Left + IMGHEAD2->Left + IMGHEAD2->Width;//200318//
					pnlSystem->Top				= 0;
				}
				else
				{
					IMGSPREAD->Tag	   	= 1;
					pnlPreview->Width  	= m_nPreviewWidth;
					pnlSPREAD->Left	   	= pnlPreview->Width + 1;//200827
				}
			}
			else
			{
				if( !palMiniSearchBar->Visible )//Main Show + Thumb Show
				{
					if(pnlPreview->Width == 0)
					{
						pnlPreview->Width 		= m_nPreviewWidth;
					}
				}
				else//Mini Hide -> Main Show
				{
					palMiniSearchBar->Visible 	= false;
					//palMainSearchBar->Left    = 0;
					edtMainSearchText->Text 	= edtMiniSearchText->Text;
					palMainSearchBar->Left		= 0;
					palMainSearchBar->Width		= 340;
					pnlSystem->Visible			= true;//200318//
					pnlSystem->Left				= palMainSearchBar->Left + pnlSearchBar->Left + IMGHEAD2->Left + IMGHEAD2->Width;//200318//
					pnlSystem->Top				= 0;
				}
			}
		}
		else//No Thumb
		{
			if( palMiniSearchBar->Visible )//Main Show
			{
				IMGSPREAD->Tag				= 1;
				palMiniSearchBar->Visible 	= false;
				//palMainSearchBar->Left    = 0;
				edtMainSearchText->Text 	= edtMiniSearchText->Text;
				palMainSearchBar->Left		= 0;
				palMainSearchBar->Width		= 340;
				pnlSystem->Visible			= true;//200318//
				pnlSystem->Left				= palMainSearchBar->Left + pnlSearchBar->Left + IMGHEAD2->Left + IMGHEAD2->Width;//200318//
				pnlSystem->Top				= 0;
			}
		}
	}

	funcSetDocControlBar();//200108//IMGSPREADClick

	if(_CURRENT_WORKMODE == "DOCUMENT")//M//191108
		funcSetModeLayer(false);
	else
		funcSetModeLayer(true);

	//260618//[TODO]//중복 아닐까요?//
	funcFreeEachButtonImage(IMGSPREAD);
	Application->ProcessMessages();

	if(IMGSPREAD->Tag == 2)
		IMGSPREAD->Picture->Bitmap->Assign(BITMAP_BTN_SPREAD[RightArrow1]);
	else
		IMGSPREAD->Picture->Bitmap->Assign(BITMAP_BTN_SPREAD[LeftArrow1]);

	if(_CURRENT_WORKMODE == "DOCUMENT")//M//191108
	{
		//funcFullView();//201119//미리보기창, 미니검색창 등 이미지 뷰 크기 변경되면 다시 계산하기//func_DrawImage();//0719//funcRefreshView();
		//===================================================
		IMGSCREEN2->Width		= pnlImgDocView->Width;
		IMGSCREEN2->Height		= pnlImgDocView->Height;
		//화면 중앙
		m_nSrcCenterX   = (-readImageWidth/2);
		m_nSrcCenterY   = (readImageHeight/2);
		m_nSrcWidth   	= (int)((double)IMGSCREEN2->Width/m_dDocFactor);
		m_nSrcHeight  	= (int)((double)IMGSCREEN2->Height/m_dDocFactor);
		realLeft     	= (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
		realTop      	= (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);
		//===================================================

		func_DrawImage();
	}
}
