int __fastcall TfrmMain::func_readMemoLandkeyDataIndex(AnsiString _landcd)
{
	int size;
	size = frmSql->m_vMEMOLANDKEYDATA.size();

	int result = -1;

	if(size > 0){
		AnsiString readlandcd;
		int head, mid, tail, prev;
		head = 0;
		tail = size;
		mid  = (tail + head)/2;

		readlandcd = (char*)frmSql->m_vMEMOLANDKEYDATA[mid].LAND_KEY;

		while(1){
			if(_landcd < readlandcd) tail = mid;
			else if(_landcd > readlandcd) head = mid;
			else{
				result = mid;
				break;
			}
			prev = mid;
			mid = (head + tail)/2;

			readlandcd = (char*)frmSql->m_vMEMOLANDKEYDATA[mid].LAND_KEY ;

			if(prev == mid){
				break;
			}
		}
	}

	return result;
}
