		frmAreaCalculatorTypeA->btnCloseTypeB->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Close22]);
		frmCalculator->btnCloseTypeB->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Close22]);
		frmUserAdd->btnCloseTypeB->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Close22]);
		frmUserManagement->btnCloseTypeB->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Close22]);
		frmUserLogList->btnCloseTypeB->Picture->Bitmap->Assign(BITMAP_BTN_SYSTEM[Close22]);
