void __fastcall TfrmMain::IMGTABMouseEnter(TObject *Sender)
{
	wchar_t wBufImg[64];
	TImage *tcmpImg;
	int nTag 				= dynamic_cast<TImage*>(Sender)->Tag;

	memset(wBufImg, 0, sizeof(wBufImg));
	swprintf(wBufImg, L"IMGTAB%02d", nTag);
	tcmpImg = (TImage*)this->FindComponent(wBufImg);
	if(tcmpImg != NULL)
	{
		funcFreeEachButtonImage(tcmpImg);
		tcmpImg->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[nTag][1]);
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::IMGTABMouseLeave(TObject *Sender)
{
	wchar_t wBufImg[64];
	TImage *tcmpImg;
	int nTag 				= dynamic_cast<TImage*>(Sender)->Tag;

	if(m_nActiveDoc != nTag)
	{
		memset(wBufImg, 0, sizeof(wBufImg));
		swprintf(wBufImg, L"IMGTAB%02d", nTag);
		tcmpImg = (TImage*)this->FindComponent(wBufImg);
		if(tcmpImg != NULL)
		{
			funcFreeEachButtonImage(tcmpImg);
			tcmpImg->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[nTag][0]);
		}
	}
}
