void __fastcall TfrmMain::IMGTABClick(TObject *Sender)
{
	wchar_t wBufImgOld[64];
	TImage *tcmpImgOld;
	wchar_t wBufImgNew[64];
	TImage *tcmpImgNew;
	wchar_t wBufTab[64];
	TTabSheet *tcmpTab;
	wchar_t wBufPnl[64];
	TPanel *tcmpPnl;
	int nTag 				= dynamic_cast<TImage*>(Sender)->Tag;

	funcClosePanel();//200110
 	edtDate_OnClick(NULL);//200526#4

	if(m_nActiveDoc != nTag)
	{
//231009//Add//상세검색 탭+1//통합검색 <->상세검색 Toggle//
		if(m_nActiveDoc != 0)
		{
			if(frmChangeMenu->m_bDetailSearching)
			{
				AnsiString asStr = "";

				if(nTag == 0)
					asStr = "상세검색 진행중입니다. 통합검색화면으로 이동할까요?";
				else
					asStr = "상세검색 진행중입니다. <" + frmMain->INIINFO.DOCKINDNAME[nTag] + "> 검색으로 이동할까요?";

				frmMsg->funcMessageDlg("검색중 알림:", asStr, 1);
				if( frmMsg->m_bClick )//예//
				{
					if(nTag == 0 || INIINFO.B_DOCFAVOR[nTag])//즐겨찾기 메뉴일때만 changemenu close한다//
					{
						frmChangeMenu->m_bDetailSearching = false;
						frmChangeMenu->Close();
					}
				}
				else//아니오//
				{
					return;
				}
			}
		}

		//=====================================================================
		//231114//상세검색 탭 기능추가//통합검색 <-> 상세검색
		funcSetTotalDetailQueryButtons(nTag);
		//=====================================================================

		//new
		memset(wBufImgNew, 0, sizeof(wBufImgNew));
		swprintf(wBufImgNew, L"IMGTAB%02d", nTag);
		tcmpImgNew = (TImage*)this->FindComponent(wBufImgNew);
		if(tcmpImgNew != NULL)
		{
			funcFreeEachButtonImage(tcmpImgNew);
			tcmpImgNew->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[nTag][1]);//활성화//
		}
		//old
		memset(wBufImgOld, 0, sizeof(wBufImgOld));
		swprintf(wBufImgOld, L"IMGTAB%02d", m_nActiveDoc);
		tcmpImgOld = (TImage*)this->FindComponent(wBufImgOld);
		if(tcmpImgOld != NULL)
		{
			funcFreeEachButtonImage(tcmpImgOld);
			tcmpImgOld->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[m_nActiveDoc][0]);//비활성화//
		}
		m_nActiveDoc	= nTag;

		pgDetail->Visible			= false;//210205//moved

		//탭이동하면 결과 초기화//200529//#10//
        //송과장
		//funcInitSearchList();
		frmSearch->funcInitSearchSuccess();

		//210215//funcInitDetailCommon(false);//pnlDetailCommon->Visible   	= false;//210215//TEST

		//change tabsheet
		if(nTag == 0)
		{
			//210205//moved//pgDetail->Visible			= false;
			funcInitDetailCommon(false);//pnlDetailCommon->Visible   	= false;

			//200603//#13//통합검색으로 이동 시 포커스//
			if(palMiniSearchBar->Visible)
			{
				edtMiniSearchText->SetFocus();
			}
			else if(palMainSearchBar->Visible)
			{
				edtMainSearchText->SetFocus();
			}
		}
		else
		{
			memset(wBufTab, 0, sizeof(wBufTab));
			swprintf(wBufTab, L"TabSheet%d", nTag);
			tcmpTab = (TTabSheet*)this->FindComponent(wBufTab);
			if(tcmpTab != NULL)
			{
				if(INIINFO.B_DOCKIND[nTag])
				{
					memset(wBufPnl, 0, sizeof(wBufPnl));
					swprintf(wBufPnl, L"pnlDetailDoc%02d", nTag);
					tcmpPnl = (TPanel*)this->FindComponent(wBufPnl);
					if(tcmpPnl != NULL)
					{
						if(nTag == 8)//200206//구대장//소유자명//
						{
							if(frmMain->INI_B_OWNNAMES)
								tcmpPnl->Height = 64;
							else
								tcmpPnl->Height = 38;
                        }
						pgDetail->Height			= 8 + tcmpPnl->Height;
						pgDetail->ActivePage		= tcmpTab;
						//송과장
						//pnlDocInfo->Visible			= false;
						//Memo1->Visible 				= false;//200526

						pgDetail->Visible			= true;//210205//TEST

						//191231//doc07은 pnu는 없지만 LAND_INFO 테이블을 통해서 지번 검색이 가능하다//
						if(/*nTag == 7 || */nTag == 10 || nTag == 13 || nTag == 15 || nTag == 16 || nTag == 18)//No Pnu
						{
							funcInitDetailCommon(false);//pnlDetailCommon->Visible   	= false;
						}
						else//Exist Pnu
						{
							funcInitDetailCommon(true);//pnlDetailCommon->Visible   	= true;//pgDetail, pnlDetailCommon 모두 alTop이라서 먼저 Visible 되는 것이 나중에 놓이게 된다.
						}

						switch(nTag)//문서별 초기화//
						{
							case  1:		funcInitIMGTAB01();		break;
							case  2:		funcInitIMGTAB02();		break;
							case  3:		funcInitIMGTAB03();		break;
							case  4:		funcInitIMGTAB04();		break;
							case  5:		funcInitIMGTAB05();		break;
							case  6:		funcInitIMGTAB06();		break;
							case  7:		funcInitIMGTAB07();		break;
							case  8:		funcInitIMGTAB08();		break;
							case  9:		funcInitIMGTAB09();		break;
							case 11:		funcInitIMGTAB11();		break;
							case 12:		funcInitIMGTAB12();		break;
							case 13:		funcInitIMGTAB13();		break;
							case 14:		funcInitIMGTAB14();		break;
							case 15:		funcInitIMGTAB15();		break;
							case 17:		funcInitIMGTAB17();		break;
							case 18:		funcInitIMGTAB18();		break;
							case 20:		funcInitIMGTAB20();		break;//231020//GAGAMLAYER in LandArchive
						}
					}
				}
			}
		}
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcInitDetailCommon(bool _bVisible)
{
	//종이지적도 기준좌표 설정 미구축 시군의 경우, 지번검색이 어렵다//
	if(m_nActiveDoc == 7 && !INI_B_MAPPOINT)
		pnlDetailCommonBlank->Visible	= true;
	else
		pnlDetailCommonBlank->Visible	= false;

	if(m_nActiveDoc == 9)//220104//논산 공시지가(DOC09)에 블럭지번 포함//
		funcSetComboGbn(1, 2);//상세검색 & 블록지번//
	else
		funcSetComboGbn(1, 1);//상세검색 & 일반지번//

	pnlDetailCommon->Visible = _bVisible;
	if(_bVisible)//210205//TEST
	{
		pnlDetailCommon->Top	= pgDetail->Top + pgDetail->Height;
    }


	if(_bVisible && m_asSearchPnuDoc0.Length() >= 11)//210104//통검->상세검색(07)>상세검색(08)로 이동하면서//201219//44270Req//
	{
		if(_SIDOCODE == "36110" && m_asSejongOldPnu.Length() >= 11 && m_asSejongOldPnu.SubString(1, 5) != _SIDOCODE)//210115//#SEJONG_PNU
		{
			edtUmdRiCd->Text 	= m_asSejongOldPnu.SubString(1, 10);
			edtUmdRiNm->Text 	= eFunc->funcPnuToUMDRIName(m_asSejongOldPnu.c_str(), true);
		}
//=============================================================================
//v1.0.0.6//11305//강북구//
		else if(_SIDOCODE == "11305" && m_asSearchPnuDoc0.Length() >= 11 && m_asSearchPnuDoc0.SubString(1, 5) != _SIDOCODE)
		{
			edtUmdRiCd->Text 	= m_asSearchPnuDoc0.SubString(1, 10);
			edtUmdRiNm->Text 	= eFunc->funcPnuToUMDRIName(m_asSearchPnuDoc0.c_str(), true);
		}
//=============================================================================
		else
		{
			edtUmdRiCd->Text 	= m_asSearchPnuDoc0.SubString(6, 5);
			edtUmdRiNm->Text 	= eFunc->funcPnuToUMDRIName(m_asSearchPnuDoc0.c_str(), false);
		}

		//210104//moved here
		if( !pnlDetailCommonBlank->Visible )
		{
			cboGbn->Enabled 	= true;
			edtBobn->Enabled 	= true;
			edtBobn->SetFocus();
		}

		cboGbn->ItemIndex 	= m_asSearchPnuDoc0.SubString(11, 1).ToInt() - 1;
		if(_SIDOCODE == "36110" && cboGbn->ItemIndex < 0)//220727//세종_옛날지번으로 검색시 TB_SEJONG_PNU.FD_PNU_NEW 정보를 가져와서 LAND_GBN 정보가 없는 경우가 많다.
		{
			cboGbn->ItemIndex 	= m_asSejongOldPnu.SubString(11, 1).ToInt() - 1;
		}
		edtBobn->Text 		= "";//m_asSearchPnuDoc0.SubString(12, 4).ToInt();
		edtBubn->Text 		= "";//m_asSearchPnuDoc0.SubString(16, 4)ToInt();
	}
	else
	{
		edtUmdRiCd->Text 	= "";
		edtUmdRiNm->Text 	= "";
		cboGbn->ItemIndex 	= 0;
		edtBobn->Text 		= "";
		edtBubn->Text 		= "";

		//210104//moved here
		cboGbn->Enabled 	= false;
		edtBobn->Enabled 	= false;
	}
	//200926//edtBubn->Enabled 	= false;
}
