//			::StretchDIBits(bmpLoad->Canvas->Handle, 0, 0, bmpLoad->Width, bmpLoad->Height, 0, 0, readImageWidth, readImageHeight, FreeImage_GetBits(mGetImageInfo.m_DIB), FreeImage_GetInfo(mGetImageInfo.m_DIB), DIB_RGB_COLORS, SRCCOPY);
//			//################################################################
