void __fastcall TfrmMain::funcFullView()
{
	funcInitLogo(false);//241205//

	//################################################################
	m_dDocFactor	= funcSetImageBaseScale();
	if (m_dDocFactor == 0) {
		AnsiString strMsg = "m_dDocFactor is 0";
		frmMsg->funcMessageDlg("이미지 DIB 확인:", strMsg, 2);
		return;
	}

	//201217//44230Req//dScaleGap	    = 0.3;

	//===================================================
	//화면 중앙
	m_nSrcCenterX   = (-readImageWidth/2);
	m_nSrcCenterY   = (readImageHeight/2);
	m_nSrcWidth   	= (int)((double)IMGSCREEN2->Width/m_dDocFactor);
	m_nSrcHeight  	= (int)((double)IMGSCREEN2->Height/m_dDocFactor);
	realLeft     	= (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
	realTop      	= (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);
	//===================================================


	//=============================================================================
	//240321//[Add]카드대장.개인정보.MASKING.최소사용자 권한//
	//=============================================================================
	if(m_asParamStr2 == "SYSTEM_OK_USER_B" || func_Decoder(m_asCurrentId).SubString(1, 2).LowerCase()  == "lx")
		funcCheckCardMasking(m_asCurrentFilePath);
	//=============================================================================


	func_DrawImage();

	mToolButtonState	= DF_PANNING;
	IMGSCREEN1->Visible = false;
	//################################################################
}
//---------------------------------------------------------------------------
//201217//이미지 확대 범위가 조금 작았으면 좋겠다//
//44230Req//지적원도 1단계에서 2단계 갈때 너무 훅 커진다//
//그래서 알씨 줌 크기를 반영//10%,20%,30%,50%,70%,100%,150%,200%,300%,500%,700%,1000%,2000%,3000%,5000%
//우리는 제한이 없으니까 1000% 이후로는 500%씩 커지게 하자//
double __fastcall TfrmMain::funcGetImageScale(bool _bZoomIn)
{
	//=========================================================
	//221222//#DOC8_OVERLAP//확대 후 이동하면 리소스 오류 발생하여 처리함//
	if(_bZoomIn && (pbRect2->Visible || pbRect4->Visible) && m_dDocFactor >= 1.0)//확대일 때 <원본크기> 이상 커지지 않게 하기 위함//
	{
		m_dDocFactor	= 1.0;
		return m_dDocFactor;
	}
	//=========================================================

	if(_bZoomIn)//ZoomIn
	{
		if(m_dDocFactor < 0.1)//10%
			m_dDocFactor	= 0.1;
		else if(m_dDocFactor < 0.2)//20%
			m_dDocFactor	= 0.2;
		else if(m_dDocFactor < 0.3)//30%
			m_dDocFactor	= 0.3;
		else if(m_dDocFactor < 0.5)//50%
			m_dDocFactor	= 0.5;
		else if(m_dDocFactor < 0.7)//70%
			m_dDocFactor	= 0.7;
		else if(m_dDocFactor < 1.0)//100%
			m_dDocFactor	= 1.0;
		else if(m_dDocFactor < 1.5)//150%
			m_dDocFactor	= 1.5;
		else if(m_dDocFactor < 2.0)//200%
			m_dDocFactor	= 2.0;
		else if(m_dDocFactor < 3.0)//300%
			m_dDocFactor	= 3.0;
		else if(m_dDocFactor < 5.0)//500%
			m_dDocFactor	= 5.0;
		else if(m_dDocFactor < 7.0)//700%
			m_dDocFactor	= 7.0;
		else if(m_dDocFactor < 10.0)//1000%
			m_dDocFactor	= 10.0;
		else if(m_dDocFactor >= 10.0)//1000% 이상//
			m_dDocFactor	+= 5;
	}
	else//ZoomOut
	{
		if(m_dDocFactor - 5 >= 10.0)//1000% 이상//
			m_dDocFactor	-= 5;
		else if(m_dDocFactor > 10.0)//1000%
			m_dDocFactor	= 10.0;
		else if(m_dDocFactor > 7.0)//700%
			m_dDocFactor	= 7.0;
		else if(m_dDocFactor > 5.0)//500%
			m_dDocFactor	= 5.0;
		else if(m_dDocFactor > 3.0)//300%
			m_dDocFactor	= 3.0;
		else if(m_dDocFactor > 2.0)//200%
			m_dDocFactor	= 2.0;
		else if(m_dDocFactor > 1.5)//150%
			m_dDocFactor	= 1.5;
		else if(m_dDocFactor > 1.0)//100%
			m_dDocFactor	= 1.0;
		else if(m_dDocFactor > 0.7)//70%
			m_dDocFactor	= 0.7;
		else if(m_dDocFactor > 0.5)//50%
			m_dDocFactor	= 0.5;
		else if(m_dDocFactor > 0.3)//30%
			m_dDocFactor	= 0.3;
		else if(m_dDocFactor > 0.2)//20%
			m_dDocFactor	= 0.2;
		else if(m_dDocFactor > 0.1)//10%
			m_dDocFactor	= 0.1;

		if(m_dDocFactor < m_dDocFitFactor)
			m_dDocFactor	= m_dDocFitFactor;
	}

	//=====================================
	//221215//열람화면//한글표시 폰트크기//
	funcGetDoc8FontSize();
	//=====================================

	return m_dDocFactor;
}
