void __fastcall TfrmMain::func_DrawImage()
{
	this->funcSetWaitWindows(true);

	IMGSCREEN2->Canvas->Lock();

	//=======================================
	//221218//#DOC8_OVERLAP//
	if(pbRect2->Visible /*//이 변수를 체크하면 안됨//&& bOwnNamesMove*/)
	{
		//=============================================================================
		//231120//#SHAREOWN#
		if( m_bSUBBOOK )//부책//
			e08DataAlpha->funcSetDoc8ViewBoundary();
		else//공유지연명부//
			e08DataAlpha->funcSetDoc8ViewBoundaryShare();
		//=============================================================================
	}
	//=======================================

	//=======================================
	//260525//AIOCR//
	if(pbRect4->Visible /*//이 변수를 체크하면 안됨//&& bOwnNamesMove*/)
	{
		//=============================================================================
		//231120//#SHAREOWN#
		if( m_bSUBBOOK )//부책//
			e08DataAIOCR->funcSetDoc8ViewBoundary();
		else//공유지연명부//
			e08DataAIOCR->funcSetDoc8ViewBoundaryShare();
		//=============================================================================
	}
	//=======================================

	if(mGetImageInfo.m_DIB != NULL)
	{
		IMGSCREEN2->Left    = 0;
		IMGSCREEN2->Top     = 0;
		PBCONTROL2->Left    = 0;
		PBCONTROL2->Top     = 0;

		IMGSCREEN2->Picture->Bitmap->Width  = IMGSCREEN2->Width;
		IMGSCREEN2->Picture->Bitmap->Height	= IMGSCREEN2->Height;

		TRect rect;
		rect.Left   = IMGSCREEN2->Left;
		rect.Top    = IMGSCREEN2->Top;
		rect.Right  = IMGSCREEN2->Width;
		rect.Bottom = IMGSCREEN2->Height;

		pDCDoc   = IMGSCREEN2->Canvas->Handle; //복사본
		memDCDoc = ::CreateCompatibleDC(IMGSCREEN2->Canvas->Handle);

		if(memDCDoc){
			hMembitmapDoc = ::CreateCompatibleBitmap(IMGSCREEN2->Canvas->Handle, IMGSCREEN2->Width, IMGSCREEN2->Height);
			if(hMembitmapDoc){
				pDCDoc = memDCDoc;
				pObjDoc = ::SelectObject(memDCDoc,hMembitmapDoc);
			}

			//---
			hbrDoc   = ::CreateSolidBrush( 0x00ffffff ); //브러쉬
			::FillRect( pDCDoc, &rect, hbrDoc  );
			DeleteObject( hbrDoc );

			::SetStretchBltMode(pDCDoc,HALFTONE);

			realPosX	=  -(double)realLeft;
			realPosY	= readImageHeight - m_nSrcHeight - (double)realTop;

			::StretchDIBits(pDCDoc, 0, 0, IMGSCREEN2->Width, IMGSCREEN2->Height, realPosX, realPosY, m_nSrcWidth, m_nSrcHeight, FreeImage_GetBits(mGetImageInfo.m_DIB), FreeImage_GetInfo(mGetImageInfo.m_DIB), DIB_RGB_COLORS, SRCCOPY);

			if (pDCDoc != IMGSCREEN2->Canvas->Handle){
				::BitBlt(IMGSCREEN2->Canvas->Handle, 0,0,rect.Width() ,rect.Height(), memDCDoc ,0 ,0 , SRCCOPY);
			}

			::DeleteDC(memDCDoc);
			::DeleteObject(hMembitmapDoc);
			::DeleteObject(pObjDoc);


			//==================================================================
			//이미지 밖 검정색 부분 처리//
			//==================================================================
			//------
			HBRUSH brush = ::CreateSolidBrush(RGB(255,255,255));
			HDC pDraw1    = IMGSCREEN2->Canvas->Handle;
			IMGSCREEN2->Canvas->Brush->Color = clWhite;
			pDCDoc   = IMGSCREEN2->Canvas->Handle; //복사본
			TRect _rctRect;
			//Left
			if(realPosX < 0)
			{
				_rctRect.Left   = 0;
				_rctRect.Top    = 0;
				_rctRect.Right  =  -(int)((double)realPosX * m_dDocFactor);
				_rctRect.Bottom = IMGSCREEN2->Height;
				hbrDoc   = ::CreateSolidBrush( 0x00ffffff ); //브러쉬
				::FillRect( pDCDoc, &_rctRect, hbrDoc  );
				::SelectObject(pDCDoc, hbrDoc);
			}
			//Top
			if((double)(readImageHeight - realPosY) * m_dDocFactor < IMGSCREEN2->Height)
			{
				_rctRect.Left   = 0;
				_rctRect.Top    = 0;
				_rctRect.Right  = IMGSCREEN2->Width;
				_rctRect.Bottom = IMGSCREEN2->Height - (int)((double)(readImageHeight - realPosY) * m_dDocFactor);
				hbrDoc   = ::CreateSolidBrush( 0x00ffffff ); //브러쉬
				::FillRect( pDCDoc, &_rctRect, hbrDoc  );
				::SelectObject(pDCDoc, hbrDoc);
			}
			//Right
			if((double)(readImageWidth - realPosX) * m_dDocFactor < IMGSCREEN2->Width)
			{
				_rctRect.Left   = (int)((double)(readImageWidth - realPosX) * m_dDocFactor);
				_rctRect.Top    = 0;
				_rctRect.Right  = IMGSCREEN2->Width;
				_rctRect.Bottom = IMGSCREEN2->Height;
				hbrDoc   = ::CreateSolidBrush( 0x00ffffff ); //브러쉬
				::FillRect( pDCDoc, &_rctRect, hbrDoc  );
				::SelectObject(pDCDoc, hbrDoc);
			}
			//Bottom
			if((double)(realPosY + m_nSrcHeight) * m_dDocFactor < IMGSCREEN2->Height)
			{
				_rctRect.Left   = 0;
				_rctRect.Top    = (int)((double)(realPosY + m_nSrcHeight) * m_dDocFactor);
				_rctRect.Right  = IMGSCREEN2->Width;
				_rctRect.Bottom = IMGSCREEN2->Height;
				hbrDoc   = ::CreateSolidBrush( 0x00ffffff ); //브러쉬
				::FillRect( pDCDoc, &_rctRect, hbrDoc  );
				::SelectObject(pDCDoc, hbrDoc);
			}
			DeleteObject( hbrDoc );
			//------
			//==================================================================


			//=================================================
			//221209//#DOC8_OVERLAP//
			if(pbRect2->Visible == true)
				pbRect2->Invalidate();
			//=================================================

			//=================================================
			//260521//AIOCR//
			if(pbRect4->Visible == true)
				pbRect4->Invalidate();
			//=================================================

			IMGSCREEN2->Invalidate();

			//210220//ZoomIn/Out 시 rectangle만 In/Out 되고 아이콘은 변동없어서 추가//
			//210219//if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
			if(PBCONTROL2->Visible == true && mToolButtonState == DF_RECTANGLE)
			{
				PBCONTROL2->Invalidate();

				//===============================================================
				//영역선택
				//===============================================================
				int size = 0;
				TPoint start, end;
				GPoint gIconPoint;
				TPoint tpIconPoint;//210208//ZoomIn/Out 시 rectangle만 In/Out 되고 아이콘은 변동없어서 추가//

				int nLeft = 0;
				int nTop = 0;
				int nRight = 0;
				int nBottom = 0;

				size = m_vRECT.size();
				for(int i=0; i<size; i++)
				{
					gIconPoint.x	= m_vRECT[i].rImage.Left;
					gIconPoint.y	= m_vRECT[i].rImage.Top;
					start	= eFunc->funcSurveyMapToDevice(gIconPoint);
					gIconPoint.x	= m_vRECT[i].rImage.Right;
					gIconPoint.y	= m_vRECT[i].rImage.Bottom;
					end	= eFunc->funcSurveyMapToDevice(gIconPoint);

					//===========================================
					int nX = start.x;
					int nY = start.y;
					int nWidth	= end.x - start.x;

					if(start.x > end.x)
					{
						nX = end.x;
						nWidth = start.x - end.x;
					}
					if(start.y > end.y)
						nY = end.y;

					tpIconPoint.x	= nX;
					tpIconPoint.y	= nY;

					funcSetStatusBarMsg(5, IntToStr((int)tpIconPoint.x) + "," + IntToStr((int)tpIconPoint.y) + "," + IntToStr(nWidth));
					funcMoveRectIcon(i, tpIconPoint, nWidth);
					//===========================================
				}
            }

//241113//
			//=============================================================================
			//240321//[Add]카드대장.개인정보.MASKING.최소사용자 권한//
			//=============================================================================
			if(B_MASKING)
			{
				brush = ::CreateSolidBrush(clSilver);//RGB(0,0,255));
				IMGSCREEN2->Canvas->Brush->Style	= bsSolid;//bsDiagCross;

				//=============================================================================
				//240321//[Add]카드대장.개인정보.MASKING.최소사용자 권한//
				//=============================================================================
				if((int)m_vMASKINGRECT.size() == 1)
				{
					TPoint start, end;
					GPoint gMapPoint;
					//---
					gMapPoint.x	= m_vMASKINGRECT[0].rImage.Left;
					gMapPoint.y	= m_vMASKINGRECT[0].rImage.Top;
					start	= eFunc->funcSurveyMapToDevice(gMapPoint);
					_rctRect.left	= start.x;
					_rctRect.top	= start.y;

					gMapPoint.x	= m_vMASKINGRECT[0].rImage.Right;
					gMapPoint.y	= m_vMASKINGRECT[0].rImage.Bottom;
					end	= eFunc->funcSurveyMapToDevice(gMapPoint);
					_rctRect.right	= end.x;
					_rctRect.bottom	= end.y;

					//=======================================
					int nStampW = end.x - start.x;
					int nStampH = end.y - start.y;
					::AlphaBlend(IMGSCREEN2->Canvas->Handle, start.x, start.y, nStampW, nStampH, IMGMASKING->Canvas->Handle, 0, 0, IMGMASKING->Width, IMGMASKING->Height, maskingbf);
					//=======================================
				}
				DeleteObject( brush );

				AnsiString  asStr	= "개인정보보호영역";
				int nLen		= asStr.Length();
				int fontwidth 	= 0;
				int nTxtLeft	= 0;
				int nTxtTop		= 0;

				nLen	= asStr.Length();
				fontwidth = 40 * m_dDocFactor;

				nTxtLeft	= _rctRect.left + (_rctRect.right - _rctRect.left) / 2;
				nTxtTop		= _rctRect.top + (_rctRect.bottom - _rctRect.top) / 2;

				HFONT m_font    = ::CreateFont(fontwidth, 0, 0, 0, FW_HEAVY, FALSE, FALSE, 0, HANGUL_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
				HFONT hOldFont  = (HFONT)::SelectObject(IMGSCREEN2->Canvas->Handle, m_font);
				::SetBkMode(IMGSCREEN2->Canvas->Handle, TRANSPARENT);
				::SetTextAlign( IMGSCREEN2->Canvas->Handle, TA_CENTER );
				::SetTextColor(IMGSCREEN2->Canvas->Handle, 0x00ff0000);
				IMGSCREEN2->Canvas->TextOutA(nTxtLeft, nTxtTop, asStr);
				::SelectObject(IMGSCREEN2->Canvas->Handle, hOldFont);
				::DeleteObject(m_font);
			}//#MASKING
			//=============================================================================

		}
//		else
//		{
//			ShowMessage("memDCDoc is NULL");
//		}
		//===========================================
	}
	IMGSCREEN2->Canvas->Unlock();

	funcRedrawMapPoint();//201016//

	if(m_bWheelZoom)
		m_bWheelZoom	= false;

	this->funcSetWaitWindows(false);
}
