void __fastcall TfrmMain::funcRotateView()
{
	if(mGetImageInfo.m_DIB == NULL)// || bmpLoad->Width == 0 || bmpLoad->Height == 0)
		return;

	double dAngle = -90;

	this->funcSetWaitWindows(true);

	//mGetImageInfo.m_DIB	= FreeImage_Rotate(mGetImageInfo.m_DIB, dAngle);
	FIBITMAP* m_DIB1;
	m_DIB1	= FreeImage_Rotate(mGetImageInfo.m_DIB, dAngle);
	FreeImage_Unload(mGetImageInfo.m_DIB);
	mGetImageInfo.m_DIB = NULL;
	mGetImageInfo.m_DIB = m_DIB1;

	readImageWidth  = FreeImage_GetWidth(mGetImageInfo.m_DIB);
	readImageHeight = FreeImage_GetHeight(mGetImageInfo.m_DIB);

	Application->ProcessMessages();

	if(m_nAngleCount == 3)
		m_nAngleCount = 0;
	else
		m_nAngleCount++;

	funcRotateMapPoint();

	this->funcSetWaitWindows(false);

	//201229//
	//===================================================
	//화면 중앙
	//m_nSrcCenterX   = (-readImageWidth/2);
	//m_nSrcCenterY   = (readImageHeight/2);
	m_nSrcWidth   	= (int)((double)IMGSCREEN2->Width/m_dDocFactor);
	m_nSrcHeight  	= (int)((double)IMGSCREEN2->Height/m_dDocFactor);
	realLeft     	= (int)(m_nSrcCenterX + (double)m_nSrcWidth/2);
	realTop      	= (int)(m_nSrcCenterY - (double)m_nSrcHeight/2);
	//===================================================

	func_DrawImage();//201222//TEST//배율유지때문//funcFullView();//func_DrawImage();
}
