void __fastcall TfrmMain::funcInitRectView()
{
	int rectsize 		= (int)m_vRECT.size();
	int distsize      	= (int)m_vDIST2.size();
	int realdistsize 	= (int)m_vREALDIST2.size();
	int areasize     	= (int)m_vAREA2.size();
	int realareasize 	= (int)m_vREALAREA2.size();

	if( rectsize > 0 || distsize > 0 || areasize > 0 || realareasize > 0)
	{
		if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
	}

	//[TODO]
	int ownsize     = (int)e08DataAlpha->m_vOWNINFONAME.size();//#OWNINFO#
	if( ownsize > 0){
		this->tcmpPaintBox[1]->Invalidate();//200606
	}
	int dogwaksize     = (int)m_vDOGAKLINE.size();//#DOGWAK#
	if( dogwaksize > 0){
		this->tcmpPaintBox[3]->Invalidate();
	}
	int spacesize      = (int)m_vSPACE.size();
	if( spacesize > 0){
		PBSPACE->Invalidate();
	}

	nMoveStatus = 1;
}
