double __fastcall TfrmMain::funcSetImageBaseScale()
{
	if (this->mGetImageInfo.nImageWidth == 0 || this->mGetImageInfo.nImageHeight == 0) {
		AnsiString strMsg = "이미지의 길이가 0입니다. 명령어 수행이 중지 됩니다.";
		frmMsg->funcMessageDlg("이미지 크기 확인:", strMsg, 2);
		return 0;
	}

	//200825//
	IMGSCREEN2->Width		= pnlImgDocView->Width;
	IMGSCREEN2->Height		= pnlImgDocView->Height;

	if (readImageWidth > pnlImgDocView->Width || readImageHeight > pnlImgDocView->Height)
	{
		double dRateW = (double)pnlImgDocView->Width / (double)readImageWidth;
		double dRateH = (double)pnlImgDocView->Height / (double)readImageHeight;

		m_dDocFitFactor = ( dRateW > dRateH ) ? (dRateH) : (dRateW);
	}
	else//201204//pnlImgDocView 크기보다 이미지가 작은 경우, 비율 1
	{
		m_dDocFitFactor	= 1.0;
	}

	return m_dDocFitFactor;
}
