void __fastcall TfrmMain::funcSaveFile()
{
	if(m_asSaveFileDir.IsEmpty())
		SaveDialog1->InitialDir = DOWNLOADPATH;//frmMain->ROOTPATH;
	else
		SaveDialog1->InitialDir = m_asSaveFileDir;

	AnsiString  asSrcExt	= ExtractFileExt(this->mGetImageInfo.asPathName);
	SaveDialog1->FileName   = SaveDialog1->InitialDir + "\\" + ExtractFileName(this->mGetImageInfo.asPathName);
	SaveDialog1->DefaultExt = ExtractFileExt(SaveDialog1->FileName);

	FREE_IMAGE_FORMAT 	fiformat;//201015//
	int nTgtExtType = 0;

	if(asSrcExt.UpperCase() == ".JPG"){
		SaveDialog1->Filter = "Jpeg|*.jpg";
		SaveDialog1->FilterIndex = 1;
		fiformat	= FIF_JPEG;//201015//
	}
	else if(asSrcExt.UpperCase() == ".TIF"){
		SaveDialog1->Filter = "Tiff|*.Tif|Jpeg|*.jpg";
		SaveDialog1->FilterIndex = 1;
		fiformat	= FIF_TIFF;//201015//
	}

	if (SaveDialog1->Execute(Handle)){
		funcSetWaitWindows(true);//200925//

		m_asSaveFileDir = ExtractFilePath(SaveDialog1->FileName);
		//to change target file extention type
		AnsiString asDstFile 	= SaveDialog1->FileName;
		AnsiString asTmpFile;
		AnsiString asTgtExt;

		if(FileExists(asDstFile))
		{
			funcSetWaitWindows(false);//200925//

			AnsiString strMsg = "파일이 존재합니다. 덮어쓰시겠습니까?";
			frmMsg->funcMessageDlg("파일명 존재 알림:", strMsg, 1);

			if(frmMsg->m_bClick == 1)//Yes
			{
				funcSetWaitWindows(true);//200925//

				if(INIUSERSETINFO.B_WATERMARK)//201006
				{
					if( !funcDrawWaterMark(fiformat, asDstFile) )//250114//#대용량이미지#다운로드#FreeImage_Clone return null(NOT SUPPORT)//
					{
						funcSetWaitWindows(false);
						frmMsg->funcMessageDlg("알림:", "대용량 파일 저장 지원이 불가한 관계로 DB구축 업체로 문의해주세요.", 3);
						return;
					}
				}
				else
				{
					asTgtExt 	= ExtractFileExt(asDstFile);
					FreeImage_Save(fiformat, mGetImageInfo.m_DIB, asDstFile.c_str());
				}
				funcSetWaitWindows(false);//200925//
			}
			else
			{
				funcSaveFile();
			}
		}
		else//파일이 없으면....
		{
			funcSetWaitWindows(true);//200925//

			if(INIUSERSETINFO.B_WATERMARK)//201006
			{
				funcDrawWaterMark(fiformat, asDstFile);
			}
			else
			{
				asTgtExt 	= ExtractFileExt(asDstFile);
				FreeImage_Save(fiformat, mGetImageInfo.m_DIB, asDstFile.c_str());
			}
			funcSetWaitWindows(false);//200925//
		}

		//200929//
		if(FileExists(asTmpFile)) DeleteFile(asTmpFile);

//230207//funcSetUserHistState()Param변경//
//		AnsiString asKindCode = eFunc->funcGetKindNameToKindCode(503, "파일저장");//210305//#44710//7
//		if( !asKindCode.IsEmpty() )
//			frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, asKindCode.ToInt(), m_nActiveDoc);//7:SaveFile
		frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, "파일저장", m_nActiveDoc);//7:SaveFile

		//210303//#TB_COPY_DNLD//다운로드 사유 입력 > 파일 저장 > 다운로드 사유 DB 저장//
		frmSql->funcSQLWriteTbCopyDnld(DF_NEW_RECORD);
		funcSetPnlDownloadReason(false);

		Application->ProcessMessages();
	}

	funcFreeEachButtonImage(IMGDOCSAVEFILE);
}
