//201015//TEST
bool __fastcall TfrmMain::funcDrawWaterMark(FREE_IMAGE_FORMAT _fiformat, AnsiString _asDstFile)
{
	AnsiString asLabel		= "";
	AnsiString asDepart		= USERINI->ReadString("USER_CONFIG", "DEPART", "");
	AnsiString asDate		= Now().FormatString("yyyy.mm.dd hh:mm:ss");
	AnsiString asSaveWM		= "";//asSaveWM	= ROOTPATH + "tmp\\SaveWM.jpg";
	AnsiString asFileExt	= ExtractFileExt(_asDstFile);

	asSaveWM	= ROOTPATH + "tmp\\SaveWM" + asFileExt;

	if( FileExists(asSaveWM) )//201223
		DeleteFile(asSaveWM);

	if(asDepart.IsEmpty())
		asLabel.sprintf("저장:%s(%s)", m_asCurrentNm, asDate);
	else
		asLabel.sprintf("저장:%s/%s(%s)", m_asCurrentNm, asDepart, asDate);

	int fontwidth = 30;//20;//201015//24->32-> (bmpWM->Height - 8)
	Graphics::TBitmap  	*bmpWM;
	bmpWM = new Graphics::TBitmap();
	bmpWM->PixelFormat = pf24bit;
	bmpWM->Width  = (int)(((double)fontwidth / 2) * (double)asLabel.Length() * (double)1 + 20);
	bmpWM->Height = 64;//TEST//bmpWM->Width * asLabel.Length();//(int)((double)readImageHeight * 0.02);

	HDC pDraw    		= bmpWM->Canvas->Handle;
	TCanvas  *pCanvas   = bmpWM->Canvas;
	HPEN pen;
	HFONT m_font;
	HFONT hOldFont, hOldFontA;
	TPoint tpText;
	//int fontwidth = (int)((double)bmpWM->Height * 0.7);//201015//24->32-> (bmpWM->Height - 8)

	m_font    = ::CreateFont(fontwidth, 0, 0, 0, 0/*FW_HEAVY*/, FALSE, FALSE, 0, HANGUL_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
	hOldFont  = (HFONT)::SelectObject(pDraw, m_font);

	::SetBkMode(pDraw, TRANSPARENT);
	::SetTextColor(pDraw, clBlue);

	pCanvas->TextOutA((bmpWM->Height - fontwidth) / 2, (bmpWM->Height - fontwidth) / 2, asLabel);

	::SelectObject(pDraw, hOldFont);
	::DeleteObject(m_font);

	//Save JPG
	TJPEGImage *jpgWM = new TJPEGImage();
	jpgWM->CompressionQuality = 70;
	jpgWM->Compress();
	//jpgWM->PixelFormat = pf24bit;
	jpgWM->Assign(bmpWM);
	jpgWM->SaveToFile(asSaveWM);

	delete jpgWM;
	jpgWM = NULL;

	delete bmpWM;
	bmpWM = NULL;

	//---
	FIBITMAP* dibOrg;
	FIBITMAP* dibWM;
	FREE_IMAGE_FORMAT 	fiformatOrg;
	FREE_IMAGE_FORMAT 	fiformatWM;

	dibOrg	= FreeImage_Clone(mGetImageInfo.m_DIB);

	fiformatOrg	= FreeImage_GetFileType(asSaveWM.c_str(), 16);
	dibWM	= FreeImage_Load(fiformatOrg, asSaveWM.c_str());

	//https://github.com/imazen/freeimage/blob/master/Source/FreeImage/ConversionType.cpp#L307
	//250114//#대용량이미지#다운로드#FreeImage_ConvertTo24Bits return null(NOT SUPPORT)//
	//원본tif라고 tif포맷으로 저장하면 LandOffice07.exe에서 tif가 적용안되는 상태(적용하려면 이미지 로딩방식을 freeimage로 변경해야함)
	//원본tif여도 jpg파일의 jpg형식으로 변경하면 0kb로 저장이 제대로 안됨.
	//tif인 경우에는 위와 같이, bit수를 24로 변경해서 jpg로 저장한다//
//동일한 효과//
//	FREE_IMAGE_TYPE src_type = FreeImage_GetImageType(dibOrg);
//  if(src_type != 1/*FIT_BITMAP*/)
	int readBpp = FreeImage_GetBPP(mGetImageInfo.m_DIB);
	if(readBpp < 16)
	{
		dibOrg = FreeImage_ConvertTo24Bits(dibOrg);
		//-------------------------------------------------------------------------
		if(dibOrg == NULL)
		{
			return false;
		}
	}
	FreeImage_Paste(dibOrg, dibWM, fontwidth, fontwidth, 110/*alpha*/);
	//FreeImage_Save(FIF_JPEG/*_fiformat*//*mGetImageInfo.fiformat*/, dibOrg/*mGetImageInfo.m_DIB*/, _asDstFile.c_str());
	FreeImage_Save(_fiformat/*mGetImageInfo.fiformat*/, dibOrg, _asDstFile.c_str());
	//-------------------------------------------------------------------------

	FreeImage_Unload(dibOrg);
	dibOrg = NULL;
//
	FreeImage_Unload(dibWM);
	dibWM = NULL;

//	FreeImage_Unload(m_DIBClone);
//	m_DIBClone = NULL;
//	m_DIBClone = FreeImage_Clone(mGetImageInfo.m_DIB);

	if( FileExists(asSaveWM) )
		DeleteFile(asSaveWM);

	return true;
}
