void __fastcall TfrmMain::funcSaveFileTif(AnsiString _asTmpFile, AnsiString _asDstFile)
{
	FIBITMAP* i_DIB;

	try {
		i_DIB = FreeImage_Load(FreeImage_GetFileType(_asTmpFile.c_str(), 16), _asTmpFile.c_str());
	} catch (Exception &exception) {
		AnsiString strMsg = "Exception is broken up to load mGetImageInfo.m_DIB";
		frmMsg->funcMessageDlg("이미지 DIB 확인:", strMsg, 2);
		return;
	}

	if (!i_DIB) {
		//241220//이미지 열람 오류 알림//
//		AnsiString strMsg = "mGetImageInfo.m_DIB is NULL";
		AnsiString strMsg = "Tiff 이미지를 저장할 수 없습니다. 개발사로 문의해주세요.";
		frmMsg->funcMessageDlg("이미지 DIB 확인:", strMsg, 2);
		return;
	}

	try {
		FreeImage_Save(FIF_TIFF, i_DIB, _asDstFile.c_str());
	} catch (Exception &exception) {
		AnsiString strMsg = "Exception is broken up to load mGetImageInfo.m_DIB";
		frmMsg->funcMessageDlg("이미지 DIB 확인:", strMsg, 2);
		return;
	}

	if (i_DIB != NULL)
	{
		FreeImage_Unload(i_DIB);
		i_DIB = NULL;
	}
}
