int __fastcall TfrmMain::funcActDeactPaintBox(int _nIndex, bool _bState)
{
	if (_nIndex == 0)
	{
		frmMain->tcmpPaintBox[1]->Visible = _bState;
		frmMain->tcmpPaintBox[2]->Visible = _bState;
		frmMain->tcmpPaintBox[3]->Visible = _bState;
		frmMain->tcmpPaintBox[4]->Visible = _bState;//260520//AIOCR//
	}
	else {
		frmMain->tcmpPaintBox[_nIndex]->Visible = _bState;
	}

	if (frmMain->tcmpPaintBox[1]->Visible == false)  {//#OWNNAMES#
		frmMain->tcmpPaintBox[1]->Invalidate();
	} else {
		frmMain->tcmpPaintBox[1]->BringToFront();
	}

	if (frmMain->tcmpPaintBox[2]->Visible == false) {//#OWNNAMES#
		frmMain->tcmpPaintBox[2]->Invalidate();
	} else {
		frmMain->tcmpPaintBox[2]->BringToFront();
	}

	if (frmMain->tcmpPaintBox[3]->Visible == false) {//#DOGWAK#
		frmMain->tcmpPaintBox[3]->Invalidate();
	} else {
		frmMain->tcmpPaintBox[3]->BringToFront();
	}

	//260520//AIOCR//
	if (frmMain->tcmpPaintBox[4]->Visible == false) {//#OWNNAMES#
		frmMain->tcmpPaintBox[4]->Invalidate();
	} else {
		frmMain->tcmpPaintBox[4]->BringToFront();
	}

	return 1;
}
