void __fastcall TfrmMain::PBSPACEMouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	if (Button != mbLeft)
		return;

	// 마우스 휠 이벤트 중복때문에 아래 SetFocus 을 이용하여
	// 폼 휠이벤트 내에서 처리 하여야 합니다.
	palMainView->SetFocus();
	PBSPACE->BringToFront();

	if (m_eManipulationMode == SpaceRect && !mRactState.bRactCalcFlag)
	{
		m_vSPACE.clear();

		mRactState.bRactCalcFlag = true;

//		if (mToolButtonState == DF_RECTPRINT)
//			bPrintDrag = true;

		TPoint tpClickPoint;

		tpClickPoint.x = X;
		tpClickPoint.y = Y;

		mMouseStateLayer4.tpStartPoint = tpClickPoint;
		mRactState.tpRactStartPoint = tpClickPoint;
		mRactState.tpRactEndPoint = tpClickPoint;

		PBSPACE->Invalidate();
	}
	else if(m_eManipulationMode == Panning)//(mToolButtonState == DF_PANNING)
	{
		this->IMGSCREEN1MouseDown(Sender, Button, Shift, X, Y);
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::PBSPACEMouseMove(TObject *Sender, TShiftState Shift, int X,
		  int Y)
{
	if (m_eManipulationMode == SpaceRect && mRactState.bRactCalcFlag)
	{
		mMouseStateLayer4.tpMovePoint.x = X;
		mMouseStateLayer4.tpMovePoint.y = Y;
		mRactState.tpRactEndPoint = mMouseStateLayer4.tpMovePoint;

		PBSPACE->Invalidate();
	}
	else if(m_eManipulationMode == Panning)//(mToolButtonState == DF_PANNING)
	{
		this->IMGSCREEN1MouseMove(Sender, Shift, X, Y);
	}
}
