void __fastcall TfrmMain::PBSPACEMouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	if (Button != mbLeft)
		return;

	if (m_eManipulationMode == SpaceRect && mRactState.bRactCalcFlag)
	{
		mRactState.tpRactEndPoint.x = X;
		mRactState.tpRactEndPoint.y = Y;

		if(mRactState.tpRactStartPoint.x > mRactState.tpRactEndPoint.x)
		{
			int nTemp = mRactState.tpRactStartPoint.x;
			mRactState.tpRactStartPoint.x = mRactState.tpRactEndPoint.x;
			mRactState.tpRactEndPoint.x = nTemp;
		}
		if(mRactState.tpRactStartPoint.y < mRactState.tpRactEndPoint.y)
		{
			int nTemp = mRactState.tpRactStartPoint.y;
			mRactState.tpRactStartPoint.y = mRactState.tpRactEndPoint.y;
			mRactState.tpRactEndPoint.y = nTemp;
		}

		PBSPACE->Invalidate();

		//화면좌표를 실좌표로 변경//
		//그 영역에 intersect 되는 지번을 찾는다.
		m_pgSpaceRectSP = func_DeviceToWorld(mRactState.tpRactStartPoint);
		m_pgSpaceRectEP = func_DeviceToWorld(mRactState.tpRactEndPoint);

		memset(&tempSPACE, 0x00, sizeof(RECT_STRUCT));
		tempSPACE.rImage.left    = m_pgSpaceRectSP.x;
		tempSPACE.rImage.top     = m_pgSpaceRectSP.y;
		tempSPACE.rImage.right   = m_pgSpaceRectEP.x;
		tempSPACE.rImage.bottom  = m_pgSpaceRectEP.y;
		tempSPACE.option  = false;  //기존 정보인지 추가 정보인지를 구분하는 옵션값..true이면 추가정보, 저장시 적용됨.
		m_vSPACE.push_back(tempSPACE);

		AnsiString asMsg	= "S(" + IntToStr((int)m_pgSpaceRectSP.x) + "," + IntToStr((int)m_pgSpaceRectSP.y) + "),E(" + IntToStr((int)m_pgSpaceRectEP.x) + "," + IntToStr((int)m_pgSpaceRectEP.y) + ")";
		bsSkinStatusPanel->Caption = asMsg;
		StatusBar2->Panels->Items[0]->Text = asMsg;//200402

		edtMainSearchText->Text = "";
		edtMiniSearchText->Text = "";
		m_asSearchText          = "";

		m_bSearching	= true;//200303
		_SELECTREALLANDCD 			= "";//200316//
		m_vSelectedID.clear();//200316//
		//NotUsed//m_vSelectedGagamID.clear();//231114//GAGAMLAYER in LandArchive

		frmSearch->funcSaveLog(0, 0, "");
		frmSearch->funcSpaceSearch();


//Vessel_East 자료로 받았을 때 보정//
//		m_pgSpaceRectSP.x = m_pgSpaceRectSP.x - 181300;
//		m_pgSpaceRectEP.x = m_pgSpaceRectEP.x - 181300;
//		m_pgSpaceRectSP.y = m_pgSpaceRectSP.y - 2400;
//		m_pgSpaceRectEP.y = m_pgSpaceRectEP.y - 2400;

//GRS80_Center 자료로 받았을 때 보정//
//		m_pgSpaceRectSP.x = m_pgSpaceRectSP.x + 292;
//		m_pgSpaceRectEP.x = m_pgSpaceRectEP.x + 292;
//		m_pgSpaceRectSP.y = m_pgSpaceRectSP.y - 10;
//		m_pgSpaceRectEP.y = m_pgSpaceRectEP.y - 10;

//현재 자료 Vessel_Center자료//

		//=======================================================================================
	}
	else if(mToolButtonState == DF_PANNING){
		this->IMGSCREEN1MouseUp(Sender, Button, Shift, X, Y);
	}

	IMGSPACEClick(IMGSPACE);
	mRactState.bRactCalcFlag = false;//191124//up을 하면 무조건 해제시키는게 맞는지??
}
