void __fastcall TfrmMain::funcDrawRectangleLayer4()
{
	PBSPACE->Canvas->Lock();

	//if (m_eManipulationMode == SpaceRect && mRactState.bRactCalcFlag)
	{
		int nLeft   = 0;
		int nTop    = 0;
		int nRight  = 0;
		int nBottom = 0;

		if (m_vSPACE.size() > 0)
		{
			GPoint gpStart, gpEnd;
			TPoint tpStart, tpEnd;
			gpStart.x 	= m_vSPACE[0].rImage.left;
			gpStart.y 	= m_vSPACE[0].rImage.top;
			gpEnd.x 	= m_vSPACE[0].rImage.right;
			gpEnd.y 	= m_vSPACE[0].rImage.bottom;

			tpStart 	= func_WorldToDevice(gpStart);
			tpEnd 		= func_WorldToDevice(gpEnd);

			nLeft   = tpStart.x;
			nTop    = tpStart.y;
			nRight  = tpEnd.x;
			nBottom = tpEnd.y;
			if(nLeft == 0 && nTop == 0 && nRight == 0 && nBottom == 0)
				return;
		}
		else
		{
			if(mRactState.bRactCalcFlag)
			{
				nLeft   = mRactState.tpRactStartPoint.x;
				nTop    = mRactState.tpRactStartPoint.y;
				nRight  = mRactState.tpRactEndPoint.x;
				nBottom = mRactState.tpRactEndPoint.y;
			}
		}

		HPEN pen1   = ::CreatePen(PS_SOLID, 2, 0x000000ff);
		::SelectObject(PBSPACE->Canvas->Handle, pen1);

		PBSPACE->Canvas->Brush->Style = bsClear;
		::SetBkMode(PBSPACE->Canvas->Handle,TRANSPARENT);

		//point로 하나 rectangle로 하나 동일함//사각형 내부를 투명하게 하고 싶다//
		gdp::Graphics graphics(PBSPACE->Canvas->Handle);
		graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);
		int remarkcolor = clRed;//m_MAININI.SELECT_REMARK_COLOR;
		int remarkalpha = m_MAININI.SELECT_REMARK_ALPHA;
		int remarkwidth = m_MAININI.SELECT_REMARK_WIDTH;
//		int r = GetRValue(remarkcolor);
//		int g = GetGValue(remarkcolor);
//		int b = GetBValue(remarkcolor);
//		int r1 = GetRValue(remarkcolor);
//		int g1 = GetGValue(remarkcolor);
//		int b1 = GetBValue(remarkcolor);
//		gdp::Point *points = new gdp::Point[4];
//		gdp::Pen pen(gdp::Color(r, g, b), remarkwidth);
//		gdp::SolidBrush solidbrushNew(gdp::Color(remarkalpha, r1, g1, b1));
//		gdp::GraphicsPath Path;
		gdp::Point *points = new gdp::Point[4];
		gdp::Pen pen(gdp::Color(255, 0, 0), remarkwidth);
		gdp::SolidBrush solidbrushNew(gdp::Color(remarkalpha, 255, 0, 0));
		gdp::GraphicsPath Path;

		points[0].X	= nLeft;
		points[0].Y	= nTop;
		points[1].X	= nLeft;
		points[1].Y	= nBottom;
		points[2].X	= nRight;
		points[2].Y	= nBottom;
		points[3].X	= nRight;
		points[3].Y	= nTop;
		Path.AddPolygon(points, 4);
		graphics.FillPath(&solidbrushNew, &Path);
		graphics.DrawPath(&pen,&Path);
		delete []points;

//		PBSPACE->Canvas->Rectangle(nLeft, nTop, nRight, nBottom);
//		::DeleteObject(pen1);
	}

	PBSPACE->Canvas->Unlock();

	nMoveStatus = 0;
}
