void __fastcall TfrmMain::funcCreateRectIcon(TPoint _tpIconPoint, int WIDTH)
{
	if (mToolButtonState == DF_RECTANGLE)
	{
		if(imgRECTClearList == NULL)//181010//
			imgRECTClearList = new TList();
		if(imgRECTCancelList == NULL)//181010//
			imgRECTCancelList = new TList();

		AnsiString asClearPath  = frmMain->ROOTPATH + "RES\\POI\\btnClear.bmp";
		AnsiString asCancelPath = frmMain->ROOTPATH + "RES\\POI\\btnCancel.bmp";

		if( FileExists( asClearPath ) )
		{
			TImage *imgClear  = new TImage(this);
			imgClear->Parent = pnlImgDocView;
			if(WIDTH < 32)
				imgClear->SetBounds(_tpIconPoint.x + WIDTH/2 - 17, _tpIconPoint.y - 18, 16, 16);
			else
				imgClear->SetBounds(_tpIconPoint.x - 2, _tpIconPoint.y - 18, 16, 16);
			imgClear->Picture->LoadFromFile(asClearPath);
			imgClear->BringToFront();//210219//
			imgClear->OnClick = imgClear_OnClick;
			imgClear->Tag = nRECTIconCount;
			imgRECTClearList->Add(imgClear);
		}

		if( FileExists( asCancelPath ) )
		{
			TImage *imgCancel = new TImage(this);
			imgCancel->Parent = pnlImgDocView;
			if(WIDTH < 32)
				imgCancel->SetBounds(_tpIconPoint.x + WIDTH/2 + 1, _tpIconPoint.y - 18, 16, 16);
			else
				imgCancel->SetBounds(_tpIconPoint.x + WIDTH - 17, _tpIconPoint.y - 18, 16, 16);
			imgCancel->Picture->LoadFromFile(asCancelPath);
			imgCancel->BringToFront();//210219//
			imgCancel->OnClick = imgCancel_OnClick;
			imgCancel->Tag = nRECTIconCount;
			imgRECTCancelList->Add(imgCancel);
		}
		//img32DocView->Repaint();
		//tcmpPaintBox[2]->Repaint();
		nRECTIconCount++;
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcDeleteRectIcon()
{
	//210208//삭제시 하는 거니까 조건없이 처리//if( mToolButtonState == DF_RECTANGLE	|| (mToolButtonStateBck == DF_RECTANGLE && mToolButtonState == DF_PANNING))
	{
		if(imgRECTCancelList != NULL)
		{
			for(int i = 0; i < nRECTIconCount ; i++)
			{
				TImage *imgCancel = (TImage *)imgRECTCancelList->Items[i];
				if(imgCancel != NULL)
				{
					imgRECTCancelList->Items[i] = NULL;
					delete imgCancel;
				}

				TImage *imgClear = (TImage *)imgRECTClearList->Items[i];
				if(imgClear != NULL)
				{
					imgRECTClearList->Items[i] = NULL;
					delete imgClear;
				}
			}
			delete imgRECTCancelList;
			delete imgRECTClearList;
			imgRECTCancelList = NULL;
			imgRECTClearList  = NULL;
			nRECTIconCount 	= 0;
		}
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcMoveRectIcon(int _nIndex, TPoint _tpIconPoint, int WIDTH)
{
	if(_nIndex < nRECTIconCount)
	{
		//Clear
		TImage *imgClear = (TImage *)imgRECTClearList->Items[_nIndex];
		if(imgClear != NULL)
		{
			if(WIDTH < 32)
			{
				imgClear->Left = _tpIconPoint.x + WIDTH/2 - 17;
				imgClear->Top  = _tpIconPoint.y - 18;
			}
			else
			{
				imgClear->Left = _tpIconPoint.x - 2;
				imgClear->Top  = _tpIconPoint.y - 18;
			}
			imgClear->BringToFront();//210219//
		}
		//Cancel
		TImage *imgCancel = (TImage *)imgRECTCancelList->Items[_nIndex];
		if(imgCancel != NULL)
		{

			if(WIDTH < 32)
			{
				imgCancel->Left = _tpIconPoint.x + WIDTH/2 + 1;
				imgCancel->Top  = _tpIconPoint.y - 18;
			}
			else
			{
				imgCancel->Left = _tpIconPoint.x + WIDTH - 17;
				imgCancel->Top  = _tpIconPoint.y - 18;
			}
			imgCancel->BringToFront();//210219//
		}
	}
}
