void __fastcall TfrmMain::imgClear_OnClick(TObject *Sender)
{
	if (mToolButtonState == DF_RECTANGLE || mToolButtonState == DF_PANNING)
	{
		int nTag = dynamic_cast<TImage*>(Sender)->Tag;

		func_SelectRectangleOneClear(nTag);
		func_SelectRectangleOneCancel(nTag);

		TImage *imgClear = (TImage *)imgRECTClearList->Items[nTag];
		if(imgClear != NULL)
		{
			imgRECTClearList->Items[nTag] = NULL;
			delete imgClear;

			for(int i = nTag + 1; i < imgRECTClearList->Count; i++)
			{
				if(imgRECTClearList->Items[i] != NULL)
				{
					TImage *imgClear = (TImage *)imgRECTClearList->Items[i];
					imgClear->Tag = i - 1;
				}
			}
			imgRECTClearList->Delete(nTag);
}

		TImage *imgCancel = (TImage *)imgRECTCancelList->Items[nTag];
		if(imgCancel != NULL)
{
			imgRECTCancelList->Items[nTag] = NULL;
			delete imgCancel;

			for(int i = nTag + 1; i < imgRECTCancelList->Count; i++)
{
				if(imgRECTCancelList->Items[i] != NULL)
	{
					TImage *imgCancel = (TImage *)imgRECTCancelList->Items[i];
					imgCancel->Tag = i - 1;
				}
	}
			imgRECTCancelList->Delete(nTag);
		}

		nRECTIconCount--;
	}
}
