void __fastcall TfrmMain::func_SelectRectangleClear()
{
	HBRUSH brush = ::CreateSolidBrush(RGB(255,255,255));
	HDC pDraw1    = IMGSCREEN2->Canvas->Handle;

	PBCONTROL2->Canvas->Brush->Color = clWhite;

	GPoint gInputPoint;
	TPoint tpInputPoint;
	TRect _rctRect;
	int left, top, right, bottom;
	for (int i=0; i<(int)m_vRECT.size(); i++)
	{
		gInputPoint.x	= m_vRECT[i].rImage.Left;
		gInputPoint.y	= m_vRECT[i].rImage.Top;
		tpInputPoint	= eFunc->funcSurveyMapToDevice(gInputPoint);
		_rctRect.left   = tpInputPoint.x;
		_rctRect.top    = tpInputPoint.y;

		gInputPoint.x	= m_vRECT[i].rImage.Right;
		gInputPoint.y	= m_vRECT[i].rImage.Bottom;
		tpInputPoint	= eFunc->funcSurveyMapToDevice(gInputPoint);
		_rctRect.right  = tpInputPoint.x;
		_rctRect.bottom = tpInputPoint.y;

		::FillRect(pDraw1, &_rctRect, brush );
		::SelectObject(pDraw1, brush);
	}

	::DeleteObject(brush);

	bool success = true;
//	AnsiString asFileName  = frmMain->ROOTPATH + "PRINT\\Rect.";
//	if(FileExists(asFileName))
//		DeleteFile(asFileName);
//
//	if(mGetImageInfo.fiformat == FIF_BMP)       asFileName = asFileName + "bmp";
//	else if(mGetImageInfo.fiformat == FIF_JPEG) asFileName = asFileName + "jpg";
//	else if(mGetImageInfo.fiformat == FIF_TIFF) asFileName = asFileName + "tif";
//	else success = false;

	if(success == true){
		int w = readImageWidth;
		int h = readImageHeight;

		if(mGetImageInfo.nBPP < 16){
			mGetImageInfo.m_DIB = FreeImage_ConvertTo16Bits565(mGetImageInfo.m_DIB);
		}

		RGBQUAD pixel;
		int nTmpX, nTmpY;
		for (int i=0; i<(int)m_vRECT.size(); i++)
		{
			_rctRect.left   = m_vRECT[i].rImage.Left;
			_rctRect.top    = readImageHeight - m_vRECT[i].rImage.Top;
			_rctRect.right  = m_vRECT[i].rImage.Right;
			_rctRect.bottom = readImageHeight - m_vRECT[i].rImage.Bottom;

			if(_rctRect.left > _rctRect.right)
			{
				nTmpX			= _rctRect.left;
				_rctRect.left	= _rctRect.right;
				_rctRect.right	= nTmpX;
			}
			if(_rctRect.top > _rctRect.bottom)
			{
				nTmpY			= _rctRect.top;
				_rctRect.top	= _rctRect.bottom;
				_rctRect.bottom	= nTmpY;
			}

			for(int y = _rctRect.top; y < _rctRect.bottom; y++){
				for(int x = _rctRect.left; x < _rctRect.right; x++){
					pixel.rgbRed   = 255;
					pixel.rgbGreen = 255;
					pixel.rgbBlue  = 255;
					FreeImage_SetPixelColor( mGetImageInfo.m_DIB, x, y, &pixel);
				}
			}
        }

		if(mGetImageInfo.nBPP == 1){
			mGetImageInfo.m_DIB = FreeImage_ConvertToGreyscale(mGetImageInfo.m_DIB);
		}
		else if(mGetImageInfo.nBPP == 4){
			mGetImageInfo.m_DIB = FreeImage_ConvertTo4Bits(mGetImageInfo.m_DIB);
		}
		else if(mGetImageInfo.nBPP == 8){
			mGetImageInfo.m_DIB = FreeImage_ConvertTo8Bits(mGetImageInfo.m_DIB);
		}
		else if(mGetImageInfo.nBPP == 16){
			mGetImageInfo.m_DIB = FreeImage_ConvertTo16Bits565(mGetImageInfo.m_DIB);
		}

//		FreeImage_Save( mGetImageInfo.fiformat, mGetImageInfo.m_DIB, asFileName.c_str());
	}

	func_DrawImage();
}
