void __fastcall TfrmMain::IMGSCREEN2MouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	//=======================================================
	//폼 리사이즈
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);
	int SysCommWparam = -1;

	if(SenderControl != NULL)//201228//
	{
		if(X > SenderControl->Width-8 && Y < 8)
			SysCommWparam = SC_DRAG_RESIZEUR;
		else if(X > SenderControl->Width-8)
			SysCommWparam = SC_DRAG_RESIZER;
		else if(Y < 8)
			SysCommWparam = SC_DRAG_RESIZEU;
		else
			SysCommWparam = SC_DRAG_MOVE;
	}

	if(SysCommWparam != -1 && SysCommWparam != SC_DRAG_MOVE)//FormResizing//)
	{
		ReleaseCapture();
		SendMessage(Handle, WM_SYSCOMMAND, SysCommWparam, 0);

		currentWidth  = this->ClientWidth;
		currentHeight = this->ClientHeight;
	}
	//=======================================================
	else//이미지가 움직임//
	{
		if (this->palWait->Visible)//221214//
			return;

		if(IMGSCREEN2->Picture->Bitmap->Width == 0)
			return;

		palMainView->SetFocus();

		if(Shift.Contains(ssLeft)){
			startPoint.x = IMGSCREEN2->Left;
			startPoint.y = IMGSCREEN2->Top;
			clickPoint.x = X;
			clickPoint.y = Y;

			if(mToolButtonState == DF_PANNING){//이동
				m_bFlags = true;
				GetCursorPos(&_movepoint);  //현재 마우스 좌표를 저장
				//m_ptZoomWindowBR = _movepoint;

				//200820
				GPoint	_gPoint;
				TPoint	_tPoint;
				_tPoint.x	= IMGSCREEN2->Width / 2;
				_tPoint.y	= IMGSCREEN2->Height / 2;
				_gPoint	= eFunc->funcDeviceToSurveyMap(_tPoint);
				m_nSrcCenterX = -_gPoint.x;
				m_nSrcCenterY = _gPoint.y;

				//============================================================
				// DOGWAK - PANNING
				//============================================================
				if( m_vDOGAKLINE.size() > 0 )
				{
					GPoint gInputPoint;
					TPoint start, end;

					int i = 0;
					for(i = 0; i < (int)m_vDOGAKLINE.size(); i++)
					{
						start	= eFunc->funcSurveyMapToDevice(m_vDOGAKLINE[i].tpMapStt);
						end		= eFunc->funcSurveyMapToDevice(m_vDOGAKLINE[i].tpMapEnd);

						if( (X >= start.x - 1 && X <= start.x + 1) || (X >= end.x - 1 && X <= end.x + 1)
						 || (Y >= start.y - 1 && Y <= start.y + 1) || (Y >= end.y - 1 && Y <= end.y + 1) )
						{
							break;
						}
					}

					if (i == (int)m_vDOGAKLINE.size())
					{
						mToolButtonStateBck 	= mToolButtonState;
						mToolButtonState		= Panning;
					}
					else
					{
						mToolButtonState = Dogwak;
					}
				}
			}
			else if(mToolButtonState == DF_STREETGAUGE){//거리재기
				if(pbControl2DblClick == false)
				 {
					m_bControlFlags = true;
				 }
				else
				{
					pbControl2DblClick = false;
					m_eManipulationMode = Panning;
				}
			}
			else if(mToolButtonState == DF_AREAGAUGE){//면적재기
				GPoint gpInputPoint;
				if(pbControl2DblClick == false){
					if(m_bControlFlags == false){
						m_bControlFlags = true;
						m_ptAreaGaugeSP = m_ptCenter2 = clickPoint;
						m_ptAreaGaugeLP.x = -1000; m_ptAreaGaugeLP.y = -1000;

						m_vAREA2.clear();

						gpInputPoint = eFunc->funcDeviceToSurveyMap(m_ptAreaGaugeSP);
						tempAREA.x 	= gpInputPoint.x;
						tempAREA.y 	= gpInputPoint.y;
					}
					else{
						m_ptAreaGaugeLP = clickPoint;
						gpInputPoint = eFunc->funcDeviceToSurveyMap(m_ptAreaGaugeLP);
						tempAREA.x 	= gpInputPoint.x;
						tempAREA.y 	= gpInputPoint.y;
					}
					m_vAREA2.push_back(tempAREA);
					//lblXY->Caption		= "L : " + IntToStr((int)tempAREA.x) + ", T : " + IntToStr((int)tempAREA.y);
				}
				else pbControl2DblClick = false;
			}
			else if(mToolButtonState == DF_RECTANGLE && !m_bControlFlags){//영역선택//
				mRactState.tpRactStartPoint 	= clickPoint;
				mRactState.tpRactEndPoint 		= clickPoint;

				//lblStart->Caption	= "x : " + IntToStr((int)mRactState.tpRactStartPoint.x) + ", y : " + IntToStr((int)mRactState.tpRactStartPoint.y);
				//lblEnd->Caption		= "x : " + IntToStr((int)mRactState.tpRactEndPoint.x) + ", y : " + IntToStr((int)mRactState.tpRactEndPoint.y);
				if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
				m_bControlFlags = true;
			}
			else if(mToolButtonState == ZoomWindow){
				if(PBCONTROL2->Visible == false) PBCONTROL2->Visible = true;
				m_bFlags = true;
				m_ptZoomWindowLT = m_ptZoomWindowBR = _movepoint = clickPoint;
			}
			else if(mToolButtonState == DF_DOGAKLINE){
				if( m_vDOGAKLINE.size() > 0 )
				{
					GPoint gInputPoint;
					TPoint start, end;

					int i = 0;
					for(i = 0; i < (int)m_vDOGAKLINE.size(); i++)
					{
						start	= eFunc->funcSurveyMapToDevice(m_vDOGAKLINE[i].gpMapStt);
						end		= eFunc->funcSurveyMapToDevice(m_vDOGAKLINE[i].gpMapEnd);

						if( (X >= start.x - 1 && X <= start.x + 1) || (X >= end.x - 1 && X <= end.x + 1)
						 || (Y >= start.y - 1 && Y <= start.y + 1) || (Y >= end.y - 1 && Y <= end.y + 1) )
						{
							break;
						}
					}

					if (i == (int)m_vDOGAKLINE.size())
					{
						mToolButtonStateBck 	= mToolButtonState;
						mToolButtonState		= Panning;
					}
					else
					{
						mToolButtonState = Dogwak;
						m_bControlFlags	= true;
					}
				}

				if(mToolButtonState == Panning)
				{
					m_bFlags = true;
					GetCursorPos(&_movepoint);  //현재 마우스 좌표를 저장
				}
			}
			else if(mToolButtonState == DF_OWNNAMES){

			}
		}
		//201119//사용자설정축척//
		else if(Shift.Contains(ssRight))
		{
			TPoint    _poppoint;
			GetCursorPos(&_poppoint);
			PopupMenu2->Popup(_poppoint.x, _poppoint.y);
		}
	}
}
