void __fastcall TfrmMain::IMGSCREEN2MouseMove(TObject *Sender, TShiftState Shift, int X,
		  int Y)
{
	//마우스 모양 변경
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);

	if(SenderControl != NULL)//201228//
	{
		if(X > SenderControl->Width-8 && Y < 8)
			SenderControl->Cursor = crSizeNESW;
		else if(X > SenderControl->Width-8)
			SenderControl->Cursor = crSizeWE;
		else if(Y < 8)
			SenderControl->Cursor = crSizeNS;
		else
			SenderControl->Cursor = crDefault;
	}

	if(palMiniSearchBar->Visible)//200318//
	{
		if(Y < 4)
		{
			pnlSystem->Visible	= true;
			pnlSystem->Left		= EDGEGAP;
			pnlSystem->Top		= 0;//palMiniSearchBar과 중복되지만//palMiniSearchBar->Top + palMiniSearchBar->Height;
		}
		else
		{
			pnlSystem->Visible	= false;
		}
	}

	if (this->palWait->Visible)//221214//
		return;

	if(IMGSCREEN2->Picture->Bitmap->Width == 0)
		return;


//	if(Shift.Contains(ssLeft)){
		TPoint _ptPoint;
		_ptPoint.x = X;
		_ptPoint.y = Y;
		pWheelMousePos = _ptPoint;

		GPoint	_gPoint;
		TPoint  _sPoint;

		_gPoint	= eFunc->funcDeviceToSurveyMap(_ptPoint);
		//201014//StatusBar1->Panels->Items[3]->Text	= "(G)L : " + IntToStr((int)_gPoint.x) + ", T : " + IntToStr((int)_gPoint.y);
		_sPoint	= eFunc->funcSurveyMapToDevice(_gPoint);
		//201014//StatusBar1->Panels->Items[4]->Text	= "(S)L : " + IntToStr((int)_sPoint.x) + ", T : " + IntToStr((int)_sPoint.y);

		//same code #1
		if(mToolButtonState == DF_PANNING && m_bFlags){
			GetCursorPos(&_ptPoint); //마우스 움직인 후의 현재 마우스 가져옴
			int nMovedL = IMGSCREEN2->Left  + (_ptPoint.x - _movepoint.x);
			int nMovedT  = IMGSCREEN2->Top  + (_ptPoint.y - _movepoint.y);

			if(_ptPoint.x < this->Left + palMainSearchBar->Width + pnlPreview->Width
			|| _ptPoint.x > this->Left + this->Width
			|| _ptPoint.y < this->Top
			|| _ptPoint.y > this->Top + this->Height)
			{
				m_bAlphaBlend = true;
			}
			else
			{
				IMGSCREEN2->Left	= nMovedL;
				IMGSCREEN2->Top  	= nMovedT;
				PBCONTROL2->Left 	= IMGSCREEN2->Left;
				PBCONTROL2->Top     = IMGSCREEN2->Top;

				_movepoint  = _ptPoint; // 현재 좌표를 이전좌표로 기억해둠

				funcRedrawMapPoint();

				if(IMGSCREEN2->Left < -(IMGSCREEN2->Width - palMainView->Width + palMainView->Width/2)) IMGSCREEN2->Left = -(IMGSCREEN2->Width - palMainView->Width + palMainView->Width/2);
				else if(IMGSCREEN2->Left > palMainView->Width/2) IMGSCREEN2->Left = palMainView->Width/2;

				if(IMGSCREEN2->Top < -(IMGSCREEN2->Height - palMainView->Height + palMainView->Height/2)) IMGSCREEN2->Top = -(IMGSCREEN2->Height - palMainView->Height + palMainView->Height/2);
				else if(IMGSCREEN2->Top > palMainView->Height/2) IMGSCREEN2->Top = palMainView->Height/2;

				if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();

				//260530//둘다 공존 기능 제거//
/*				if(cbOverlapDB->Checked && cbOverlapAI->Checked)
				{
					if(IsCTRLpressed()){
						//=================================================
						//221209//#DOC8_OVERLAP//
						if(pbRect2->Visible == true)
							pbRect2->BringToFront();
						//=================================================
					}
					else{
						//=================================================
						//260521//AIOCR//
						if(pbRect4->Visible == true)
							pbRect4->BringToFront();
						//=================================================
					}
				}
				else
*/
				{
					if(pbRect2->Visible == true)
						pbRect2->BringToFront();
					else if(pbRect4->Visible == true)
						pbRect4->BringToFront();
				}
			}
		}
		else if(mToolButtonState ==DF_STREETGAUGE){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptCenter2 = _movepoint;
			if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
		}
		else if(mToolButtonState == DF_AREAGAUGE && m_bControlFlags){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptCenter2 = _movepoint;
			if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
		}
		else if(mToolButtonState == DF_RECTANGLE && m_bControlFlags){//영역선택//
			mRactState.tpRactEndPoint.x = X;
			mRactState.tpRactEndPoint.y = Y;

			//lblStart->Caption	= "x : " + IntToStr((int)mRactState.tpRactStartPoint.x) + ", y : " + IntToStr((int)mRactState.tpRactStartPoint.y);
			//lblEnd->Caption		= "x : " + IntToStr((int)mRactState.tpRactEndPoint.x) + ", y : " + IntToStr((int)mRactState.tpRactEndPoint.y);
			if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
		}
		else if(mToolButtonState == ZoomWindow && m_bFlags){
			_movepoint.x = X; _movepoint.y = Y;
			m_ptZoomWindowLT = _movepoint;
			if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
		}
		else if(mToolButtonState == DF_DOGAKLINE && m_bControlFlags)
		{
			int m_nMovedW = 0;
			int m_nMovedH = 0;

			_movepoint.x = X; _movepoint.y = Y;
			m_nMovedW = (_movepoint.x - clickPoint.x) / m_dDocFactor;
			m_nMovedH = (_movepoint.y - clickPoint.y) / m_dDocFactor;

			for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
			{
				m_vDOGAKLINE[i].tpMapStt.x += m_nMovedW;
				m_vDOGAKLINE[i].tpMapStt.y -= m_nMovedH;
				m_vDOGAKLINE[i].tpMapEnd.x += m_nMovedW;
				m_vDOGAKLINE[i].tpMapEnd.y -= m_nMovedH;
			}

			if(PBCONTROL2->Visible == true) PBCONTROL2->Invalidate();
		}
//	}
}
