void __fastcall TfrmMain::imgSearchBarBgMouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	//폼 리사이즈
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);
	int SysCommWparam = -1;

	if(SenderControl != NULL)//201228//
	{
		if(X < 8 && Y < 8)
			SysCommWparam = SC_DRAG_RESIZEUL;
		else if(X < 8)
			SysCommWparam = SC_DRAG_RESIZEL;
		else if(Y < 8)
			SysCommWparam = SC_DRAG_RESIZEU;
		else
			SysCommWparam = SC_DRAG_MOVE;
	}

	if(SysCommWparam != -1){
		ReleaseCapture();
		SendMessage(Handle, WM_SYSCOMMAND, SysCommWparam, 0);

		currentWidth  = this->ClientWidth;
		currentHeight = this->ClientHeight;
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::imgSearchBarBgMouseMove(TObject *Sender, TShiftState Shift, int X, int Y)
{
	//마우스 모양 변경
	TControl *SenderControl = dynamic_cast<TImage *>(Sender);

	if(SenderControl != NULL)//201228//
	{
		if(X < 8 && Y < 8)
			SenderControl->Cursor = crSizeNWSE;
		else if(X < 8)
			SenderControl->Cursor = crSizeWE;
		else if(Y < 8)
			SenderControl->Cursor = crSizeNS;
		else
			SenderControl->Cursor = crDefault;
	}
}
