void __fastcall TfrmMain::funcDeleteComponentsThumb()
{
	//btnCreate4
	if(pnlThumbList != NULL)
	{
		for(int i = 0; i < pnlThumbList->Count; i++)
		{
			TPanel *pnlDC = (TPanel *)pnlThumbList->Items[i];
			if(pnlDC != NULL)
			{
				TImage *imgDocDC	= (TImage *)imgThumbList->Items[i];
				if(imgDocDC != NULL)
				{
					imgThumbList->Items[i] = NULL;
					delete imgDocDC;
					imgDocDC	= NULL;
				}

				TLabel *lblDocDC	= (TLabel *)lblThumbList->Items[i];
				if(lblDocDC != NULL)
				{
					lblThumbList->Items[i] = NULL;
					delete lblDocDC;
					lblDocDC	= NULL;
				}

				//201126//
				TCheckBox *chkDocDC	= (TCheckBox *)chkThumbList->Items[i];
				if(chkDocDC != NULL)
				{
					chkDocDC->Checked		= false;//210104//
					chkThumbList->Items[i] 	= NULL;
					delete chkDocDC;
					chkDocDC	= NULL;
				}

				pnlThumbList->Items[i] = NULL;
				delete pnlDC;
				pnlDC	= NULL;
			}
		}

		//201126//
		chkThumbList->Clear();
		delete chkThumbList;
		chkThumbList = NULL;

		imgThumbList->Clear();
		delete imgThumbList;
		imgThumbList = NULL;

		lblThumbList->Clear();
		delete lblThumbList;
		lblThumbList = NULL;

		pnlThumbList->Clear();
		delete pnlThumbList;
		pnlThumbList = NULL;
	}

	m_nThumbHeight	= 0;
	m_nThumbDownloadedCnt	= 0;//201222//


	for(int i = 0; i < (int)m_vThumbPathList.size(); i++)//210104
		m_vThumbPathList[i].CHECKED	= false;
}
