void __fastcall TfrmMain::funcMakeDynamicThumbnail(int _nIndex)
{
	AnsiString asPageNo		= "";
	AnsiString asStr		= "";
	AnsiString asPathName 	= "";
	AnsiString asThumbFile 	= "";
	//download 받은 thumbnail경로//
	//200603//#11
	AnsiString asFileExt 	= "";
	if(INI_AS_THUMBEXT	== "JPG")
		asFileExt 	= ".jpg";
	else
		asFileExt 	= ".bmp";

	asThumbFile = (char *)m_vThumbPathList[_nIndex].PATH_NAME;
	asPathName	= asThumbFile;//FTP원본이미지경로//

	asThumbFile = ExtractFileName(asThumbFile);
	asThumbFile	= asThumbFile.SubString(1, asThumbFile.Pos(".")-1) + asFileExt;
	asThumbFile = THUMBPATH + asThumbFile;

	//201202//썸네일 미 존재 시, NoImage표시//
//	if(!FileExists(asThumbFile))
//		return;

	//---
	TPanel *pnlDC 			= new TPanel(ScrollBox1);
	TImage *imgDocDC 		= new TImage(pnlDC);
	imgDocDC->Width			= THUMBNAILSIZE;
	imgDocDC->Height		= THUMBNAILSIZE;

	//201202//썸네일 미 존재 시, NoImage표시//
	if(!FileExists(asThumbFile) || asThumbFile.IsEmpty())
		imgDocDC->Picture->Bitmap->Assign(BITMAP_BTN_ETC[NoImage]);
	else
		imgDocDC->Picture->LoadFromFile(asThumbFile);

	//---
	pnlDC->Align			= alTop;
	pnlDC->Tag 				= _nIndex;
	//200623//pnlDC->Hint				= IntToStr(m_nViewDocNo);//문서번호(이동결의서:1)
	pnlDC->Caption			= "pnlDC" + IntToStr(_nIndex + 1);
	pnlDC->BevelKind    	= Controls::bvNone;
//	pnlDC->BevelKind		= bkFlat;
//	pnlDC->BevelEdges   	>> beLeft;
//	pnlDC->BevelEdges   	>> beTop;
//	pnlDC->BevelEdges   	>> beRight;
//	pnlDC->BevelEdges   	<< beBottom;
	pnlDC->BevelOuter 		= Controls::bvNone;
	pnlDC->SetBounds(0, m_nThumbHeight + 20 * _nIndex, pnlPreview->Width, 20 + imgDocDC->Picture->Height);
	pnlDC->ParentFont		= true;
	pnlDC->ParentBackground = false;
	pnlDC->Parent 			= ScrollBox1;
	pnlDC->Hint				= m_nThumbHeight + 20 * _nIndex;

	//201126//
	//---
	TCheckBox *chkDocDC 	= new TCheckBox(pnlDC);
	chkDocDC->Parent 		= pnlDC;
	chkDocDC->Tag 			= _nIndex;
	//======================================
	//201130//각 페이지당 전체체크여부//
	if(m_vThumbPathList[_nIndex].CHECKED)
		chkDocDC->Checked		= true;
	else
		chkDocDC->Checked		= false;
	//======================================
	chkDocDC->SetBounds(2, 4, 16, 16);
	chkDocDC->Visible		= m_bThumbChecked;
	chkDocDC->OnMouseUp 	= chkThumbDC_onMouseUp;

	//---
	TLabel *lblDocDC 		= new TLabel(pnlDC);//200623//(ScrollBox1);
	lblDocDC->Parent 		= pnlDC;
	lblDocDC->Tag 			= _nIndex;
	//201015//asPageNo	= (char*)m_vThumbPathList[_nIndex].PAGE_NO;
	//201015//asStr	= eFunc->funcGetKindCodeToKindName(m_nViewDocNo, m_vThumbPathList[_nIndex].KIND_CODE);
	//201015//asStr	= asStr + "(" + asPageNo + ")";
	//201015//측량결과도, 종이지적도는 페이지 아닌 도호번호로 표시
	if(m_nViewDocNo == 2 || m_nViewDocNo == 7)
	{
		asPageNo	= (char*)m_vThumbPathList[_nIndex].DOHO;
		//220315//DOC02.DOHO에 2개의 도호정보가 있는 경우에 오류발생//44710.31021.2.651.3, 4, 5//
		if(asPageNo.IsEmpty())	asPageNo	= "-";//220315//
		//220315//if(!asPageNo.IsEmpty())	asPageNo	= IntToStr(asPageNo.ToInt());
		asStr	= eFunc->funcGetKindCodeToKindName(m_nViewDocNo, m_vThumbPathList[_nIndex].KIND_CODE);
		asStr	= asStr + "(도호:" + asPageNo + ")";
	}
	else
	{
		asPageNo	= (char*)m_vThumbPathList[_nIndex].PAGE_NO;
		if(!asPageNo.IsEmpty())
		{
			//201015//asPageNo	= IntToStr(asPageNo.ToInt());//201015//
			asPageNo	= eFunc->funcGetPageNoName(m_nViewDocNo, asPageNo.c_str());//201015//
		}

		//201218//좌표계산부 첫페이지 표시 때문에 문서구분  '좌표계산부'를 00010으로 표시했으므로 관련하여 처리//
		if(m_nViewDocNo == 18 && asPageNo == "00010")
		{
			asStr	= eFunc->funcGetKindCodeToKindName(m_nViewDocNo, "01");
			asStr	= asStr + "(P:" + asPageNo + ")";
		}
		else
		{
			asStr	= eFunc->funcGetKindCodeToKindName(m_nViewDocNo, m_vThumbPathList[_nIndex].KIND_CODE);
			asStr	= asStr + "(P:" + asPageNo + ")";
		}
	}

	lblDocDC->Caption 		= asStr;
	lblDocDC->Alignment		= taCenter;
	if(m_bThumbChecked)
		lblDocDC->SetBounds(20, 5, pnlPreview->Width-24, 16);//201126//
	else
		lblDocDC->SetBounds(4, 5, pnlPreview->Width-8, 16);

	lblDocDC->ParentFont	= true;
	lblDocDC->Transparent   = true;
	if(_nIndex == m_nThumbCurrIndex && m_nThumbCurrIndex != m_nThumbPathIndex)//191124
	{
		lblDocDC->Font->Style   = TFontStyles() << fsBold;
		lblDocDC->Font->Color	= clWhite;
		pnlDC->Color	  		= (TColor)RGB(51, 150, 255);
	}
	else if(_nIndex == m_nThumbPathIndex)//191124
	{
		lblDocDC->Font->Style   = TFontStyles() << fsBold;
		lblDocDC->Font->Color	= clWhite;
		pnlDC->Color	  		= (TColor)RGB(243, 115, 33);
	}
	else
	{
		lblDocDC->Font->Color	= clBlack;
		pnlDC->Color			= clCream;//200429
	}

	//---
	m_nThumbHeight			+= pnlDC->Height;

	//---
	imgDocDC->Parent 		= pnlDC;
	imgDocDC->Tag 			= _nIndex;
	imgDocDC->Hint          = IntToStr(m_nViewDocNo);//문서번호(이동결의서:1);//200623//asPathName;//FTP원본이미지경로//
	//imgDocDC->SetBounds((THUMBNAILSIZE - imgDocDC->Picture->Width) / 2, 20, imgDocDC->Picture->Width, imgDocDC->Picture->Height);
	imgDocDC->SetBounds((THUMBNAILSIZE - imgDocDC->Picture->Width) / 2 + 3, 20, imgDocDC->Picture->Width-2, imgDocDC->Picture->Height-3);
	imgDocDC->OnClick 		= imgThumbDC_onClick;

	//201222//
	pnlDC->OnMouseEnter		= ScrollBox1MouseEnter;
	lblDocDC->OnMouseEnter	= ScrollBox1MouseEnter;
	imgDocDC->OnMouseEnter	= ScrollBox1MouseEnter;


	chkThumbList->Add(chkDocDC);//201126//
	imgThumbList->Add(imgDocDC);
	lblThumbList->Add(lblDocDC);
	pnlThumbList->Add(pnlDC);
}
