void __fastcall TfrmMain::funcShowCurrentThumbLabel()
{
	if(pnlThumbList != NULL)
	{
		if(m_nThumbCurrIndex < 0)
		{
			return;
		}

		//======================================================================
		//241015//#전주#중앙정보테크//
		//======================================================================
		int nSkinColor	= SIDOINI->ReadInteger(L"FUNCTIONS", L"VALUE", (TColor)RGB(243, 115, 33));//16750131
		int nSkinColor2	= SIDOINI->ReadInteger(L"FUNCTIONS", L"VALUE2", (TColor)RGB(51, 150, 255));//16760962
		int nShpTop	= 0;
		for(int i = 0; i < pnlThumbList->Count; i++)
		{
			TPanel *pnlDC = (TPanel *)pnlThumbList->Items[i];
			if(pnlDC != NULL)
			{
				TLabel *lblDocDC 		= (TLabel *)lblThumbList->Items[i];
				if(lblDocDC != NULL)
				{
					if(pnlDC->Tag == m_nThumbCurrIndex && m_nThumbCurrIndex != m_nThumbPathIndex)
					{
						lblDocDC->Font->Style   = TFontStyles() << fsBold;
						lblDocDC->Font->Color	= clWhite;//clBlue;
						pnlDC->Color	  		= nSkinColor2;
						//pnlDC->BevelOuter 	= Controls::bvLowered;//200429
						nShpTop	= pnlDC->Top;
					}
					//201020//
					else if(pnlDC->Tag == m_nThumbPathIndex)
					{
						lblDocDC->Font->Style   = TFontStyles() << fsBold;
						lblDocDC->Font->Color	= clWhite;
//						pnlDC->BevelKind		= bkFlat;
//						pnlDC->BevelEdges   	>> beLeft;
//						pnlDC->BevelEdges   	>> beTop;
//						pnlDC->BevelEdges   	>> beRight;
//						pnlDC->BevelEdges   	>> beBottom;
						pnlDC->Color	  		= nSkinColor;
					}
					else
					{
						lblDocDC->Font->Style   = TFontStyles() >> fsBold;
						lblDocDC->Font->Color	= clBlack;
						pnlDC->Color	  		= clCream;//200429
						pnlDC->BevelOuter 		= Controls::bvNone;//200429
					}
				}
			}
		}

//		shpThumb->Top		= nShpTop;
//		shpThumb->Visible	= true;
//		shpThumb->BringToFront();

	}
}
