//201130//각 페이지당 전체체크여부//
void __fastcall TfrmMain::chkAllThumbMouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	if(palWait->Visible)
		return;

	for(int i = m_nThumbSttIdx; i < m_nThumbSttIdx + m_nThumbDownCnt && m_nThumbDownloadedCnt > 0; i++)
	{
		TCheckBox *chkDocDC    = (TCheckBox *)chkThumbList->Items[i - m_nThumbSttIdx];
		if(chkDocDC != NULL)
		{
			chkDocDC->Checked	= chkAllThumb->Checked;
			m_vThumbPathList[i].CHECKED	= chkAllThumb->Checked;
		}
	}
}
