//201126//
void __fastcall TfrmMain::chkThumbDC_onMouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	if(palWait->Visible)
		return;

	int nTag 		= dynamic_cast<TCheckBox*>(Sender)->Tag;
	int	nCheckedCnt	= 0;

	if(nTag < 0)
	{
		//200123//여기는 들어오면 안됨//
		frmMsg->funcMessageDlg("파일확인:", "미리보기파일(Tag)에 문제가 있습니다. 개발사에 문의해주세요.", 2);
		return;
	}

	m_vThumbPathList[nTag].CHECKED	= !m_vThumbPathList[nTag].CHECKED;

	for(int i = m_nThumbSttIdx; i < m_nThumbSttIdx + m_nThumbDownCnt && m_nThumbDownloadedCnt > 0; i++)
	{
		TCheckBox *chkDocDC    = (TCheckBox *)chkThumbList->Items[i - m_nThumbSttIdx];
		if(chkDocDC != NULL)
		{
			if(chkDocDC->Checked)
				nCheckedCnt++;
		}
	}

	if(nCheckedCnt == m_nThumbDownCnt)
		chkAllThumb->Checked	= true;
	else
		chkAllThumb->Checked	= false;
}
