void __fastcall TfrmMain::btnPrevClick(TObject *Sender)
{
	if(m_nCurrTab > 1)
	{
		m_nCurrTab--;
		m_nCurrPage	= m_nCurrTab * 3 - 2;
		m_nThumbSttIdx	= (m_nCurrPage - 1) * m_nPerThumbCnt;
		if(m_nCurrPage < m_nPageCount)
		{
			m_nThumbDownCnt	= m_nPerThumbCnt;
		}
		else
		{
			m_nThumbDownCnt	= m_nThumbCount % m_nPerThumbCnt;//201228//
			if(m_nThumbDownCnt == 0)	   m_nThumbDownCnt	= m_nPerThumbCnt;
		}

		funcSetLabelPage();
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::btnNextClick(TObject *Sender)
{
	if(m_nCurrTab < m_nTotalTab)
	{
		m_nCurrTab++;
		m_nCurrPage	= m_nCurrTab * 3 - 2;
		m_nThumbSttIdx	= (m_nCurrPage - 1) * m_nPerThumbCnt;
		if(m_nCurrPage < m_nPageCount)
		{
			m_nThumbDownCnt	= m_nPerThumbCnt;
		}
		else
		{
			m_nThumbDownCnt	= m_nThumbCount % m_nPerThumbCnt;//201228//
			if(m_nThumbDownCnt == 0)	   m_nThumbDownCnt	= m_nPerThumbCnt;
		}

		funcSetLabelPage();
	}
}
