void __fastcall TfrmMain::lblPreviewPageClick(TObject *Sender)
{
	int nToChangePage	= 0;

	if(Sender == lblPage1)
	{
		nToChangePage	= lblPage1->Caption.ToInt();
	}
	else if(Sender == lblPage2)
	{
		nToChangePage	= lblPage2->Caption.ToInt();

	}
	else if(Sender == lblPage3)
	{
		nToChangePage	= lblPage3->Caption.ToInt();
	}

	if(nToChangePage != m_nCurrPage)
	{
		m_nCurrPage		= nToChangePage;
		m_nThumbSttIdx	= (m_nCurrPage - 1) * m_nPerThumbCnt;
		if(m_nCurrPage < m_nPageCount)
		{
			m_nThumbDownCnt	= m_nPerThumbCnt;
		}
		else
		{
			m_nThumbDownCnt	= m_nThumbCount % m_nPerThumbCnt;//201228//
			if(m_nThumbDownCnt == 0)	   m_nThumbDownCnt	= m_nPerThumbCnt;
		}

		funcSetLabelPage();
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcSetLabelPage()
{
	int nLabelNo	= m_nCurrPage % 3;
	if(nLabelNo == 1)
	{
		if(m_nCurrPage <= m_nPageCount)
		{
			lblPage1->Visible		= true;
			lblPage1->Caption		= m_nCurrPage;
			lblPage1->Font->Color	= clBlue;
			lblPage1->Font->Style   = TFontStyles() << fsBold << fsUnderline;
		}

		if(m_nCurrPage + 1 <= m_nPageCount)
		{
			lblPage2->Visible		= true;
			lblPage2->Caption		= m_nCurrPage+1;
			lblPage2->Font->Color	= clBlack;
			lblPage2->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
		}
		else
		{
			lblPage2->Visible	= false;
		}

		if(m_nCurrPage + 2 <= m_nPageCount)
		{
			lblPage3->Visible		= true;
			lblPage3->Caption		= m_nCurrPage+2;
			lblPage3->Font->Color	= clBlack;
			lblPage3->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
		}
		else
		{
			lblPage3->Visible	= false;
		}
	}
	else if(nLabelNo == 2)
	{
		lblPage1->Visible		= true;
		lblPage2->Visible		= true;
		lblPage1->Caption		= m_nCurrPage-1;
		lblPage1->Font->Color	= clBlack;
		lblPage1->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
		lblPage2->Caption		= m_nCurrPage;
		lblPage2->Font->Color	= clBlue;
		lblPage2->Font->Style   = TFontStyles() << fsBold << fsUnderline;

		if(m_nCurrPage + 1 <= m_nPageCount)
		{
			lblPage3->Visible		= true;
			lblPage3->Caption		= m_nCurrPage+1;
			lblPage3->Font->Color	= clBlack;
			lblPage3->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
		}
		else
		{
			lblPage3->Visible	= false;
		}
	}
	else if(nLabelNo == 0)
	{
		if(m_nCurrPage <= m_nPageCount)
		{
			lblPage1->Visible		= true;
			lblPage2->Visible		= true;
			lblPage3->Visible		= true;
			lblPage1->Caption		= m_nCurrPage-2;
			lblPage1->Font->Color	= clBlack;
			lblPage1->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
			lblPage2->Caption		= m_nCurrPage-1;
			lblPage2->Font->Color	= clBlack;
			lblPage2->Font->Style   = TFontStyles() >> fsBold << fsUnderline;
			lblPage3->Caption		= m_nCurrPage;
			lblPage3->Font->Color	= clBlue;
			lblPage3->Font->Style   = TFontStyles() << fsBold << fsUnderline;
		}
	}

	if(m_nCurrTab == 1)
		btnPrev->Enabled	= false;
	else
		btnPrev->Enabled	= true;

	if(m_nCurrTab < m_nTotalTab)
		btnNext->Enabled	= true;
	else
		btnNext->Enabled	= false;

//	if(m_nCurrTab == 1)
//		btnPrev->Enabled	= false;
//	else if(m_nCurrTab < m_nPageCount)
//		btnPrev->Enabled	= true;
//
//	if(m_nCurrTab == m_nTotalTab)
//		btnNext->Enabled	= false;
//	else if(m_nCurrTab < m_nTotalTab)
//		btnNext->Enabled	= true;

	funcGotoPageThumb();
}
