void __fastcall TfrmMain::btnGotoClick(TObject *Sender)
{
	AnsiString asStr	="";
	int 	nGotoPage	= 0;

	asStr	= edtGoto->Text;
	if(asStr.IsEmpty() || asStr == "0")
	{
		frmMsg->funcMessageDlg("입력 요청:", "이동할 페이지번호를 입력해주세요.", 3);
		return;
	}
	nGotoPage	= asStr.ToInt();
	if(nGotoPage != m_nCurrPage)
	{
		m_nCurrPage		= nGotoPage;
		m_nThumbSttIdx	= (m_nCurrPage - 1) * m_nPerThumbCnt;
		if(m_nCurrPage < m_nPageCount)
		{
			m_nThumbDownCnt	= m_nPerThumbCnt;
		}
		else
		{
			m_nThumbDownCnt	= m_nThumbCount % m_nPerThumbCnt;//201228//
			if(m_nThumbDownCnt == 0)	   m_nThumbDownCnt	= m_nPerThumbCnt;
		}

		m_nTotalTab     = (m_nPageCount / 3) + 1;
		m_nCurrTab		= ((m_nCurrPage - 2) / 3) + 1;

		funcSetLabelPage();
	}
}
