void __fastcall TfrmMain::funcProcessThumb()
{
	if (!DirectoryExists(frmMain->THUMBPATH))
		CreateDir(frmMain->THUMBPATH);

//200808
//	//delete file of local temp directoy to download
//	eFunc->DeleteFileinDir(frmMain->THUMBPATH);

    //---
	m_nThumbCount 	= m_vThumbPathList.size();
	m_nPageCount	= ((m_nThumbCount - 1) / m_nPerThumbCnt) + 1;//200928//
//260611//[REQ]페이지 관계없이 항상 미리보기//
/*
	if(m_nPageCount > 1)//250429//[Add]전체 미리보기(REQ)
		pnlAllPreview->Visible		= true;
	else
		pnlAllPreview->Visible		= false;
*/

//	//
//	if(cboPreviewDocKind->Items->Count > 2)//250429//[Add]전체 미리보기(REQ)
//		pnlPreviewDocKind->Visible	= true;
//	else
//		pnlPreviewDocKind->Visible	= false;

//	if(m_nThumbCount % m_nPerThumbCnt == 0)
//        m_nPageCount++;
	previewStatusBar->Caption = "전체페이지수 : " + IntToStr(m_nPageCount);

	m_nCurrPage		= (m_nThumbPathIndex / m_nPerThumbCnt) + 1;
	m_nThumbSttIdx	= (m_nCurrPage - 1) * m_nPerThumbCnt;
	if(m_nCurrPage < m_nPageCount)
	{
		m_nThumbDownCnt	= m_nPerThumbCnt;
	}
	else
	{
		m_nThumbDownCnt	= m_nThumbCount % m_nPerThumbCnt;//201228//
		if(m_nThumbDownCnt == 0)	   m_nThumbDownCnt	= m_nPerThumbCnt;
	}

	//250513//페이지 1개 뿐이라면 표시할 필요 없음//
	if(m_nPageCount <= 1)
	{
		pnlPreviewGoto->Height	= 0;
		pnlPreviewPage->Height	= 0;
	}
	else
	{
		pnlPreviewGoto->Height	= 40;
		pnlPreviewPage->Height	= 40;
	}

	m_nTotalTab     = (m_nPageCount + 2) / 3;
	m_nCurrTab		= (m_nCurrPage + 2) / 3;

	edtGoto->Text = m_nCurrPage;
	funcSetLabelPage();
}
