//201227//_bSub:열람 이미지 내의 다른 지번 검색 시 사용//
void __fastcall TfrmMain::funcCalcWorldToMap(bool _bSub)
{
	TPoint tPoint;
	GPoint gPoint;
	//200401//
	AnsiString 	asScale 	= "";
	double 		dBaseX      = 0.0;
	double 		dBaseY      = 0.0;
	double 		dDGBaseX    = 0.0;
	double 		dDGBaseY    = 0.0;
	double 		dDGPosX     = 0.0;
	double 		dDGPosY     = 0.0;
	double 		dRatioX     = 0.0;
	double 		dRatioY     = 0.0;
	int 		nScale 		= 0;

	currMapPoint.POS_X	= 0;
	currMapPoint.POS_Y	= 0;

	if(_bSub)//_bSub:열람 이미지 내의 다른 지번 검색 시 사용//
	{
		if (!m_ResultDocument07_SUB.size()) return;

		if(m_ResultDocument07_SUB[0].REMARK == 2)//from TB_DOCUMENT07_PNU
		{
			currMapPoint.POS_X = m_ResultDocument07_SUB[0].BASE_X;
			currMapPoint.POS_Y = m_ResultDocument07_SUB[0].BASE_Y;
		}
		else if(m_ResultDocument07_SUB[0].REMARK == 1)//from TB_DOCUMENT07_PNU
		{
			if((int)m_vLANDINFO.size() == 0)//211007//land_info에 존재하지 않는 지번처리//
				return;

			asScale 	= m_ResultDocument07_SUB[0].SCALE;
			dBaseX      = m_ResultDocument07_SUB[0].BASE_X;
			dBaseY      = m_ResultDocument07_SUB[0].BASE_Y;
			dDGBaseX    = m_ResultDocument07_SUB[0].X1;
			dDGBaseY    = m_ResultDocument07_SUB[0].Y1;
			dDGPosX     = m_vLANDINFO_SUB[0].X;//[TODO]
			dDGPosY     = m_vLANDINFO_SUB[0].Y;//[TODO]
			dRatioX     = m_ResultDocument07_SUB[0].RATIOX;
			dRatioY     = m_ResultDocument07_SUB[0].RATIOY;

			if(asScale.Length() > 0)
				nScale = StrToInt(asScale) * 100;

			gPoint.x = (dDGPosX - dDGBaseX) / dRatioX;
			gPoint.y = (dDGPosY - dDGBaseY) / dRatioY;
			tPoint = eFunc->funcCmToBitMapImage(gPoint, &mGetImageInfo.mBitMapHeadInfo, nScale);

			currMapPoint.POS_X = dBaseX + tPoint.x;
			currMapPoint.POS_Y = dBaseY - tPoint.y;
		}
	}
	else
	{
		if (!frmSql->m_ResultDoc07DBInfo.size()) return;

		if(frmSql->m_ResultDoc07DBInfo[0].REMARK == 2)//from TB_DOCUMENT07_PNU
		{
			currMapPoint.POS_X = frmSql->m_ResultDoc07DBInfo[0].BASE_X;
			currMapPoint.POS_Y = frmSql->m_ResultDoc07DBInfo[0].BASE_Y;
		}
		else if(frmSql->m_ResultDoc07DBInfo[0].REMARK == 1)//from TB_DOCUMENT07_PNU
		{
			if((int)m_vLANDINFO.size() == 0)//211007//land_info에 존재하지 않는 지번처리//
				return;

			asScale 	= frmSql->m_ResultDoc07DBInfo[0].SCALE;
			dBaseX      = frmSql->m_ResultDoc07DBInfo[0].BASE_X;
			dBaseY      = frmSql->m_ResultDoc07DBInfo[0].BASE_Y;
			dDGBaseX    = frmSql->m_ResultDoc07DBInfo[0].X1;
			dDGBaseY    = frmSql->m_ResultDoc07DBInfo[0].Y1;
			dDGPosX     = m_vLANDINFO[0].X;//[TODO]
			dDGPosY     = m_vLANDINFO[0].Y;//[TODO]
			dRatioX     = frmSql->m_ResultDoc07DBInfo[0].RATIOX;
			dRatioY     = frmSql->m_ResultDoc07DBInfo[0].RATIOY;

			if(asScale.Length() > 0)
				nScale = StrToInt(asScale) * 100;

			gPoint.x = (dDGPosX - dDGBaseX) / dRatioX;
			gPoint.y = (dDGPosY - dDGBaseY) / dRatioY;
			tPoint = eFunc->funcCmToBitMapImage(gPoint, &mGetImageInfo.mBitMapHeadInfo, nScale);

			currMapPoint.POS_X = dBaseX + tPoint.x;
			currMapPoint.POS_Y = dBaseY - tPoint.y;
		}
	}
}
