void __fastcall TfrmMain::imgCalClick(TObject *Sender)
{
	AnsiString asSenderName = dynamic_cast<TComponent*>(Sender)->Name;
	AnsiString asNowDt 		= Now().FormatString("YYYY-MM-DD");
	AnsiString asDate 		= "";
	AnsiString asStr 		= "";
	AnsiString asHint 		= dynamic_cast<TImage*>(Sender)->Hint;
	int nHint 				= asHint.ToInt();
	int nTag 				= dynamic_cast<TImage*>(Sender)->Tag;
	int	nLeft				= dynamic_cast<TImage*>(Sender)->Left;
	int	nTop				= dynamic_cast<TImage*>(Sender)->Top;
	int	nWidth				= dynamic_cast<TImage*>(Sender)->Width;

	TImage *tcmpImg;
	tcmpImg = (TImage*)this->FindComponent(asSenderName.c_str());

	if(nTag % 2 == 1)//if(nTag == 1)
	{
		//200526//#4>>>
		if(nHint == 1)
			asDate = dtStartDayDoc1->Text;
		else if(nHint == 2)
			asDate = dtStartDayDoc2->Text;
		else if(nHint == 3)
			asDate = dtStartDayDoc3->Text;
		else if(nHint == 5)
			asDate = dtStartDayDoc5->Text;
		else if(nHint == 14)
			asDate = dtStartDayDoc14->Text;
		else if(nHint == 18)
			asDate = dtStartDayDoc18->Text;
		//
		asStr = StringReplace(asDate, "-", "", TReplaceFlags() << rfReplaceAll);
		asStr = StringReplace(asStr, " ", "", TReplaceFlags() << rfReplaceAll);
		if(asStr.Length() == 8)
			CalendarDoc1->Date	= (TDateTime)asDate;
		else
			CalendarDoc1->Date 	= (TDateTime)asNowDt;
		//200526//#4<<<

		if ( !CalendarDoc1->Showing )
		{
			CalendarDoc1->Left 	= 0;//pnlSearchBar->Left + nLeft - CalendarDoc1->Width / 2;
			CalendarDoc1->Top  	= pnlSearchBar->Top + pnlSearchBar->Height + nTop + tcmpImg->Height + 2;
			CalendarDoc1->Visible = true;
			CalendarDoc1->BringToFront();
		}
		if ( CalendarDoc2->Showing )
		{
			CalendarDoc2->Visible = false;
		}
	}
	else if(nTag % 2 == 0)//else if(nTag == 2)
	{
		//200526//#4>>>
		if(nHint == 1)
			asDate = dtEndDayDoc1->Text;
		else if(nHint == 2)
			asDate = dtEndDayDoc2->Text;
		else if(nHint == 3)
			asDate = dtEndDayDoc3->Text;
		else if(nHint == 5)
			asDate = dtEndDayDoc5->Text;
		else if(nHint == 14)
			asDate = dtEndDayDoc14->Text;
		else if(nHint == 18)
			asDate = dtEndDayDoc18->Text;
		//
		asStr = StringReplace(asDate, "-", "", TReplaceFlags() << rfReplaceAll);
		asStr = StringReplace(asStr, " ", "", TReplaceFlags() << rfReplaceAll);
		if(asDate.Length() == 8)
			CalendarDoc2->Date	= (TDateTime)asDate;
		else
			CalendarDoc2->Date 	= (TDateTime)asNowDt;
		//200526//#4<<<


		if ( !CalendarDoc2->Showing )
		{
			CalendarDoc2->Left 	= pnlSearchBar->Left + nLeft + nWidth - CalendarDoc2->Width;
			CalendarDoc2->Top  	= pnlSearchBar->Top + pnlSearchBar->Height + nTop + tcmpImg->Height + 2;
			CalendarDoc2->Visible = true;
			CalendarDoc2->BringToFront();
		}
		if ( CalendarDoc1->Showing )
		{
			CalendarDoc1->Visible = false;
		}
	}
}
