void __fastcall TfrmMain::CalendarDocDblClick(TObject *Sender)
{
	int nTag 			= dynamic_cast<TMonthCalendar*>(Sender)->Tag;
//	AnsiString asHint   = dynamic_cast<TMonthCalendar*>(Sender)->Hint;
//	int nHint 			= asHint.ToInt();
	wchar_t 		wBufCalendar[64];
	TMonthCalendar 	*tcmpCalendar;
	wchar_t 		wBufMEdit1[64];
	TMaskEdit	 	*tcmpMEdit1;
	wchar_t 		wBufMEdit2[64];
	TMaskEdit	 	*tcmpMEdit2;

	memset(wBufCalendar, 0, sizeof(wBufCalendar));
	swprintf(wBufCalendar, L"CalendarDoc%d", nTag);
	tcmpCalendar = (TMonthCalendar*)this->FindComponent(wBufCalendar);

	//
	memset(wBufMEdit1, 0, sizeof(wBufMEdit1));
	swprintf(wBufMEdit1, L"dtStartDayDoc%d", m_nActiveDoc);
	tcmpMEdit1 = (TMaskEdit*)this->FindComponent(wBufMEdit1);
	//
	memset(wBufMEdit2, 0, sizeof(wBufMEdit2));
	swprintf(wBufMEdit2, L"dtEndDayDoc%d", m_nActiveDoc);
	tcmpMEdit2 = (TMaskEdit*)this->FindComponent(wBufMEdit2);

	if(nTag == 1)
	{
		tcmpMEdit1->Text = tcmpCalendar->Date.FormatString("YYYY-MM-DD");
		if(tcmpMEdit2->Text != "    -  -  " && (AnsiString)tcmpMEdit1->Text > (AnsiString)tcmpMEdit2->Text)
		{
			AnsiString strMsg = "시작일자를 종료일자보다 빠른 날짜로 설정해주세요.";
			frmMsg->funcMessageDlg("날짜 범위 확인:", strMsg, 3);
			if(nTag == 1)
				tcmpMEdit1->SetFocus();
			else if(nTag == 2)
				tcmpMEdit2->SetFocus();
		}
	}
	else if(nTag == 2)
	{
		tcmpMEdit2->Text = tcmpCalendar->Date.FormatString("YYYY-MM-DD");
		if(tcmpMEdit1->Text != "    -  -  " && (AnsiString)tcmpMEdit1->Text > (AnsiString)tcmpMEdit2->Text)
		{
			AnsiString strMsg = "종료일자를 시작일자보다 늦은 날짜로 설정해주세요.";
			frmMsg->funcMessageDlg("날짜 범위 확인:", strMsg, 3);
			if(nTag == 1)
				tcmpMEdit1->SetFocus();
			else if(nTag == 2)
				tcmpMEdit2->SetFocus();
		}
	}

}
