void __fastcall TfrmMain::IMGSPACEClick(TObject *Sender)
{
	if(m_nZoomFactor < 10)
	{
		frmMsg->funcMessageDlg("알림:", "영역검색은 최대로 확대된 상태에서 해주세요.", 3);
		return;
	}

	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 영역검색을 해주세요.", 3);
		return;
	}

	if(_CURRENT_COMWORKMODE == "거리재기" || _CURRENT_COMWORKMODE == "면적재기")//200429
	{
		funcFreeEachButtonImage(IMGSPATIALCONTROLAREA);
		funcFreeEachButtonImage(IMGSPATIALCONTROLDIST);
	}

	funcClosePanel();//200226

	if(_CURRENT_COMWORKMODE == "메모등록")
	{
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGMEMOPOINT, false, false);
		//=============================================

		_CURRENT_COMWORKMODE	= "";
		m_eManipulationMode    	= Panning;
		ICONMEMOPOINT->Visible = false;
		MEMOPOINTHELP->Visible = false;
		m_vMEMORECT.clear();
		if(PBCONTROL1->Visible) PBCONTROL1->Visible = false;
	}
	if(_CURRENT_COMWORKMODE == "영역등록")
	{
		//=============================================
		//241205//[레이어] 이미지 표시 설정//
		//=============================================
		funcSetImageLayer(IMGMEMOPOLY, false, false);
		//=============================================

		_CURRENT_COMWORKMODE	= "";
		m_eManipulationMode    	= Panning;
		ICONMEMOPOLY->Visible = false;
		MEMOPOLYHELP->Visible = false;
		if(m_vMEMORECT.size() > 0)
			PBCONTROL1->Invalidate();
	}


	//200316//funcSpaceSearch호출전에 clear하고, <영역검색> 눌렀다가 영역선택 안하고 <영역검색>해제하면 다시 보여야 하므로//
	//m_vSelectedID.clear();//#JIBUNSEL//191212
	funcSetPalPoi();//POI 있는 곳으로 이동하자//


	//=============================================
	//241205//[레이어] 이미지 표시 설정//
	//=============================================
	funcSetImageLayer(IMGSPACE, !PBSPACE->Visible, true);
	//=============================================

	if(_CURRENT_COMWORKMODE == "공간검색")
	{
		_CURRENT_COMWORKMODE	= "";
		m_vSPACE.clear();
		m_eManipulationMode    	= Panning;

		func_DrawImagePaint();
	}
	else
	{
		_CURRENT_COMWORKMODE = "공간검색";

		if(_CURRENT_WORKMODE == "SPATIAL"){
			PBSPACE->Left    = IMGSCREEN1->Left;
			PBSPACE->Top     = IMGSCREEN1->Top;
			PBSPACE->Width   = IMGSCREEN1->Width;
			PBSPACE->Height  = IMGSCREEN1->Height;
			PBSPACE->BringToFront();
			//200109//IMGSPREAD->BringToFront();
			IMGMODECHANGEDOC->BringToFront();
			IMGMODECHANGEJIJUK->BringToFront();

			m_eManipulationMode = SpaceRect;
			mSpaceRectFlags 	= true;
			m_vSPACE.clear();
		}
	}
}
