void __fastcall TfrmMain::funcSetPrevNextBar()
{
	if(m_nFTPPathIndex == 0)
	{
		funcFreeEachButtonImage(IMGPREV);
		if(m_vFTPPathList.size() > 1)
		{
			funcFreeEachButtonImage(IMGNEXT);
			IMGNEXT->Picture->LoadFromFile(IMAGEMAINPATH + "select_next.png");
		}
	}
	else
	{
		funcFreeEachButtonImage(IMGNEXT);
		if(m_nFTPPathIndex < (int)m_vFTPPathList.size() - 1)
		{
			IMGNEXT->Picture->LoadFromFile(IMAGEMAINPATH + "select_next.png");
		}
		if(m_vFTPPathList.size() > 1)
		{
			funcFreeEachButtonImage(IMGPREV);
			IMGPREV->Picture->LoadFromFile(IMAGEMAINPATH + "select_prev.png");
		}
	}

	IMGPREV->BringToFront();
	IMGNEXT->BringToFront();
}
