// 공통 함수들//
//
//---------------------------------------------------------------------------
int __fastcall TfrmMain::funcGetJibunPos(AnsiString str)
{
	bool	bChecked	= false;
	int idx = 0;
	char *s=str.c_str();
	if(*s=='-' ||*s=='+')s++;
	while(*s)
	{
		if(*s>='0' && *s<='9')
		{
			//=======================================
			//241202//'1가', '1리' 등 처리//(ex. 중앙동1가, 창선1리 등)
			//=======================================
			if( (str.c_str()[idx+1] & 0x80) == 0x80 )// - nIndex~nIndex+1까지 2바이트가 한글// - 한글 일 때 처리
			{
				bChecked	= true;
				s += 3;
				idx += 3;
				continue;
			}
			//=======================================

			return idx;
		}
		s++;
		idx++;
	}
	return 0;
}
//---------------------------------------------------------------------------

bool __fastcall TfrmMain::funcCheckAddressData(AnsiString str)
{
	char *s=str.c_str();
//	if(*s=='-' ||*s=='+')s++;
	while(*s)
    {
		if((*s<'0' || *s > '9') && ((*s & 0x80) != 0x80) && *s != '-' && *s != ' ')	return false;
		if((*s & 0x80) == 0x80)	s++;//한글이면 2byte 건너띄움//
		s++;
	}
	return true;
}
