//201222//TrackBar로 변경//불편하다는 민원//44270//Req//
void __fastcall TfrmMain::funcProcessAdjustBar(int _nTag)
{
	wchar_t wBufLabel[64];
	TLabel *tcmpLabel;
	wchar_t wBufBar[64];
	TTrackBar *tcmpBar;
	int nOldValue 	= 0;
	int nValue    	= 0;
	int nDiff     	= 0;
	int nCalcValue 	= 0;
	bool	bAdjust	= false;

	//---
	memset(wBufLabel, 0, sizeof(wBufLabel));
	swprintf(wBufLabel, L"lblAdjust%d", _nTag);
	tcmpLabel = (TLabel*)this->FindComponent(wBufLabel);

	if(m_bAdjustIng1 == true && _nTag != 1 && m_nAdjustValue1 != m_nAdjustMiddle)
	{
		m_bAdjustReject	= true;//201223//
		frmMsg->funcMessageDlg("음영조정 적용 확인:", "밝기조절을 적용하시겠습니까?", 1);
		if(frmMsg->m_bClick)
		{
			bAdjust	= true;
		}
		m_bAdjustIng1	= false;
		m_nAdjustValue1	= m_nAdjustMiddle;
		lblAdjust1->Caption		= m_nAdjustValue1;
		bsAdjust1->Value		= m_nAdjustValue1;
	}
	else if(m_bAdjustIng2 == true && _nTag != 2 && m_nAdjustValue2 != m_nAdjustMiddle)
	{
		m_bAdjustReject	= true;//201223//
		frmMsg->funcMessageDlg("음영조정 적용 확인:", "명암조절을 적용하시겠습니까?", 1);
		if(frmMsg->m_bClick)
		{
			bAdjust	= true;
		}
		m_bAdjustIng2	= false;
		m_nAdjustValue2	= m_nAdjustMiddle;
		lblAdjust2->Caption		= m_nAdjustValue2;
		bsAdjust2->Value		= m_nAdjustValue2;
	}
	else if(m_bAdjustIng3 == true && _nTag != 3 && m_nAdjustValue3 != m_nAdjustMiddle)
	{
		m_bAdjustReject	= true;//201223//
		frmMsg->funcMessageDlg("음영조정 적용 확인:", "감마조절을 적용하시겠습니까?", 1);
		if(frmMsg->m_bClick)
		{
			bAdjust	= true;
		}
		m_bAdjustIng3	= false;
		m_bAdjustReject	= true;//201223//
		m_nAdjustValue3	= m_nAdjustMiddle;
		lblAdjust3->Caption		= m_nAdjustValue3;
		bsAdjust3->Value		= m_nAdjustValue3;
	}

	m_bAdjustReject	= false;//201223//

	if(bAdjust)
	{
		//==========================================================
		//201007//#CLONE
		if(m_DIBClone != NULL)
		{
			FreeImage_Unload(m_DIBClone);
			m_DIBClone	= NULL;
		}
		m_DIBClone	= FreeImage_Clone(mGetImageInfo.m_DIB);
		//==========================================================
	}

	nOldValue = StrToInt(tcmpLabel->Caption);//Get Old Value
	switch(_nTag)//Set New Value
	{
		case 1:
		{
			m_bAdjustIng1			= true;
			m_nAdjustValue1			= bsAdjust1->Value;
			lblAdjust1->Caption 	= IntToStr(m_nAdjustValue1);//260911//[44760]AlphaView && MainView.Adjust 시 깨짐 오류//
			break;
		}
		case 2:
		{
			m_bAdjustIng2 			= true;
			m_nAdjustValue2			= bsAdjust2->Value;
			lblAdjust2->Caption 	= IntToStr(m_nAdjustValue2);//260911//[44760]AlphaView && MainView.Adjust 시 깨짐 오류//
			break;
		}
		case 3:
		{
			m_bAdjustIng3			= true;
			m_nAdjustValue3			= bsAdjust3->Value;
			lblAdjust3->Caption 	= IntToStr(m_nAdjustValue3);//260911//[44760]AlphaView && MainView.Adjust 시 깨짐 오류//
			break;
		}
	}
	nValue = StrToInt(tcmpLabel->Caption);


	//---
	nDiff = nValue - nOldValue;
	if(nDiff == 0)		return;


	if(_nTag == 1)
		bsAdjust1->Enabled	= false;
	else if(_nTag == 2)
		bsAdjust2->Enabled	= false;
	else if(_nTag == 3)
		bsAdjust3->Enabled	= false;

	funcSetWaitWindows(true);

	//==========================================================
	//201007//#CLONE
	if(mGetImageInfo.m_DIB != NULL)
	{
		FreeImage_Unload(mGetImageInfo.m_DIB);
		mGetImageInfo.m_DIB	= NULL;
	}
	mGetImageInfo.m_DIB	= FreeImage_Clone(m_DIBClone);
	//==========================================================

	switch(_nTag)
	{
		case 1://Brightness
			nCalcValue = (nValue - m_nAdjustMiddle) * (10);//210113//44270//Req//최동현//
			this->funcBrightnessImage(nCalcValue);
			//func_DrawImage();
			break;
		case 2://Contrast
			nCalcValue = (nValue - m_nAdjustMiddle)* (10);//210113//44270//Req//최동현//
			this->funcContrastImage(nCalcValue);
			//func_DrawImage();
			break;
		case 3://Gamma
			nDiff	= nValue - m_nAdjustMiddle;
			double dTemp = (double)1 + (double)nDiff * (double)0.1;//210112//44270//Req//최동현//
			this->funcGammaImage(dTemp);
			//func_DrawImage();
			break;
	}

	if(_nTag == 1)
	{
		bsAdjust1->Enabled	= true;
		//m_bAdjustIng1		= false;
	}
	else if(_nTag == 2)
	{
		bsAdjust2->Enabled	= true;
		//m_bAdjustIng2		= false;
	}
	else if(_nTag == 3)
	{
		bsAdjust3->Enabled	= true;
		//m_bAdjustIng3		= false;
	}

	funcSetWaitWindows(false);
}
