void __fastcall TfrmMain::btnZoomTrackBarMouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	btnZoomTrackBar->Value 	= btnZoomTrackBar->MaxValue - ((Y - 4)  / ((btnZoomTrackBar->Height - 8) / (btnZoomTrackBar->MaxValue - btnZoomTrackBar->MinValue)));//201223//

	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 확대/축소를 해주세요.", 3);
		return;
	}
}
