void __fastcall TfrmMain::funcSetMaxScreen()
{
	TRect rc;
	SystemParametersInfo(SPI_GETWORKAREA, 0, &rc, 0);
	this->Left         = rc.Left;
	this->Top          = rc.Top;
	this->ClientWidth  = rc.Width();
	this->ClientHeight = rc.Height();
}
