//200302
bool __fastcall TfrmMain::funcCheckFindKeyword(TObject *Sender)
{
	if(palWait->Visible)
		return false;

	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 검색을 해주세요.", 3);
		return false;
	}

	m_vSelectedID.clear();//#JIBUNSEL//191212
	//NotUsed//m_vSelectedGagamID.clear();//231114//GAGAMLAYER in LandArchive
	funcSetPalPoi();//POI 있는 곳으로 이동하자//
	m_nReadJibunIndex			= -1;//속도개선//
	frmSql->m_nKindOfDocIndex 	= -1;//속도개선//
	m_asSearchPnu  	= "";//200225
	m_asSearchText 	= "";
	m_nViewDocNo	= 0;

	//==========================================================================
	// KEYWORD 검사//
	//==========================================================================
	AnsiString _findtext = "";
	AnsiString emdnm = "";

	if(Sender == edtMiniSearchText || palMiniSearchBar->Visible)
	{
		if(edtMiniSearchText->Text != "")
			_findtext = edtMiniSearchText->Text;
	}
	else if(Sender == edtMainSearchText || palMainSearchBar->Visible)
	{
		if(edtMainSearchText->Text != "")
			_findtext = edtMainSearchText->Text;
	}

	_findtext = StringReplace(_findtext, "  ", " ", TReplaceFlags() << rfReplaceAll);

	//
	if( eFunc->IsNumberString(_findtext) )
	{
		frmMsg->funcMessageDlg("검색어 확인:", "지역명을 입력해주세요.", 3);
		return false;
	}
	//
	if( !funcCheckAddressData(_findtext) )
	{
		frmMsg->funcMessageDlg("입력 확인:", "주소를 다시 입력해주세요.", 3);
		return false;
	}


	//
	int iPos;
	iPos = _findtext.Pos(" ");
	if(iPos < 1)//M
	{
		iPos	= funcGetJibunPos(_findtext);
		if(iPos > 1)//지역명과 지번이 공백없이//
		{
			_findtext = _findtext.SubString(1,iPos) + " " + _findtext.SubString(iPos+1,_findtext.Length()-iPos);
		}
		else//검색어에 지번정보 없이//
		{
			_findtext = " " + _findtext;
			emdnm = _findtext.Trim();

			if(emdnm != ""){//<읍면동, 리> 이름만 넣었을 때 해당 동으로 이동//
				return false;
			}
		}
	}
	else emdnm = _findtext.SubString(1,iPos-1);

	if( _findtext.IsEmpty() )
	{
		frmMsg->funcMessageDlg("검색어 확인:", "지역명을 입력해주세요.", 3);
		return false;
	}

	//==========================================================================
	AnsiString asStr = "";
	iPos = _findtext.Pos(" ");
	if(iPos > 1)//읍면동 존재//
	{
		asStr 	= _findtext.SubString(1, iPos-1);
		if(asStr.Length() < 3)
		{
			frmMsg->funcMessageDlg("검색어 확인:", "지역명을 2글자 이상 입력해주세요.", 3);
			return false;
		}
	}
	else
	{
		iPos	= frmMain->funcGetJibunPos(_findtext);
		if(iPos > 1)//읍면동 존재//
		{
			asStr 	= _findtext.SubString(1, iPos-1);
			if(asStr.Length() < 3)
			{
				frmMsg->funcMessageDlg("검색어 확인:", "지역명을 2글자 이상 입력해주세요.", 3);
				return false;
			}
		}
	}

	//==========================================================================
	AnsiString 	asSearchTextBck	= _findtext;

	if(m_asSearchPnu.Length() != 19)//210201//지번적용으로 이미 pnu 19자리를 구성했을 때//
	{
		m_asSearchText 	= _findtext;
		m_asSearchPnu 	= frmSql->func_ConvertAddressToLandcd(m_asSearchText, false);
	}

	if(m_asSearchPnu.Length() != 19 || m_asSearchPnu.SubString(12, 8) == "00000000")//200910
	{
		frmMsg->funcMessageDlg("입력 확인:", "<" + asSearchTextBck + ">을 찾을 수 없습니다.", 3);
		m_asSearchText 			= "";
		edtMainSearchText->Text = "";
		edtMiniSearchText->Text = "";
		return false;
	}

	//TEST
	//210111//#SEJONG_PNU//통합검색어의 읍면동+리 명이 계속 짤린다//#DEBUG
	if(m_asSearchPnu.Length() != 19)
		_findtext       = func_ConvertLandcdToAddress(m_asSearchPnu);//확인필요//

	if(m_asSearchText != _findtext)//리명만 넣어서 가장 먼저 찾은 리의 읍면동명까지 검색어에 표시해주자//
	{
		m_asSearchText 			= _findtext;
		edtMainSearchText->Text = _findtext;
		edtMiniSearchText->Text = _findtext;
	}

	//==========================================================================

	return true;
}
