//통합검색-메모//지번 여부 확인 전에 먼저 찾는다//
bool __fastcall TfrmMain::funcCheckFindMemo(TObject *Sender)
{
	if(palWait->Visible)
		return false;

	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 검색을 해주세요.", 3);
		return false;
	}


	//200305//
//	funcClosePanel();//200110
//	funcInitPBControl2();//init pbRect
//	IMGSCREEN2->Canvas->Brush->Style = bsClear;
//	IMGSCREEN2->Picture->Bitmap	= NULL;
//	IMGSCREEN2->Picture			= NULL;
//	IMGLOGO->Left       		= (pnlImgDocView->Width - 22 - IMGLOGO->Width)/2;
//	IMGLOGO->Top        		= (pnlImgDocView->Height - IMGLOGO->Height)/2;
//	if(pnlImgDocView->Visible)
//	{
//		IMGLOGO->Visible			= true;
//	}

	m_vSelectedID.clear();//#JIBUNSEL//191212
	funcSetPalPoi();//POI 있는 곳으로 이동하자//
	m_nReadJibunIndex			= -1;//속도개선//
	frmSql->m_nKindOfDocIndex 	= -1;//속도개선//
	m_asSearchPnu  	= "";//200225
	m_asSearchText 	= "";
	m_nViewDocNo	= 0;

	//==========================================================================
	// KEYWORD 검사//
	//==========================================================================
	AnsiString _findtext = "";
	AnsiString emdnm = "";

	if(Sender == edtMiniSearchText || palMiniSearchBar->Visible)
	{
		if(edtMiniSearchText->Text != "")
			_findtext = edtMiniSearchText->Text;
	}
	else if(Sender == edtMainSearchText || palMainSearchBar->Visible)
	{
		if(edtMainSearchText->Text != "")
			_findtext = edtMainSearchText->Text;
	}

	_findtext = StringReplace(_findtext, "  ", " ", TReplaceFlags() << rfReplaceAll);


	//====================================================
	bool bReturn = false;

	if(INIINFO.B_MEMO)
	{
		funcSetWaitWindows(true);
		funcInitSearchList();
		frmSearch->funcInitSearchSuccess();

//230207//funcSetUserHistState()Param변경//
//		AnsiString asKindCode = eFunc->funcGetKindNameToKindCode(503, "검색");//210305//#44710//1
//		if( !asKindCode.IsEmpty() )
//			frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, asKindCode.ToInt(), frmMain->m_nActiveDoc);
		frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, "검색", frmMain->m_nActiveDoc);

		//====================================================
		AnsiString asSql 		= "";
		AnsiString asWhere 		= "";
		AnsiString asOrderBy 	= "POI_KEY DESC";

		if( !_findtext.IsEmpty() )
		{
			asWhere		= "TITLE LIKE '%" + _findtext + "%' ";
		}
		asSql.sprintf("SELECT * FROM %s WHERE %s ORDER BY %s", frmMain->TABLE_MEMOINFO, asWhere, asOrderBy);
		frmSql->funcReadMemo(asSql.c_str());
		//====================================================

		totalCount[0] = m_ResultMemo.size();

		if(totalCount[0] > 0)
		{
			bReturn = true;
			eTree->funcSettingTreeView(0);
		}

		frmSearch->funcSaveLog(1, 0, asSql);//save data
		frmSearch->funcSaveLog(2, 0, "");//save to file
	}

	funcSetWaitWindows(false);
	frmSearch->funcSetSearchFinish();
	m_bSearching	= false;
	return bReturn;
}
