void __fastcall TfrmMain::IMGFINDClick(TObject *Sender)
{
	if(palWait->Visible || m_bSearching)//200302
		return;

	//==================================================
	//221208//#DOC8_OVERLAP//
	chkOwnNames->Checked	= INIUSERSETINFO.B_OWNLABEL;
	chkDoc8Overlap->Checked	= false;
	//==================================================

	//==========================================================================
	if(Sender != NULL)//231121//if(Sender == IMGFIND)//210129
	{
		//=========================================================================
		//231121//Moved//검색어 입력 후 검색버튼을 클릭하면, 아래 변수들이 초기화되지 않아서 이전 지번을 검색하므로 초기화 부분 위치 이동//
		m_asSearchPnu		= "";
		m_asSearchText      = "";
		m_asSejongOldPnu	= "";
		//=========================================================================
		Sender = edtMainSearchText;
	}

	m_bSearching = true;
	m_bAlreadyShowMsg = false;//210107//#SEJONGPNU
	frmSearch->funcSaveLog(0, 0, "");//first
	frmSearch->funcSaveLog(9, 0, "KEYWORD");

	//200326////===================================================
	if(Sender != NULL)//if Sender == NULL, PNU is made from PoiInfo already.
	{
		if( !INIUSERSETINFO.B_AUTOJIBUN )//입력한 그대로 찾기//
		{
			if(Sender == edtMiniSearchText || palMiniSearchBar->Visible)
			{
				if(edtMiniSearchText->Text != "")
				{
					m_asSearchText 			= edtMiniSearchText->Text;
					edtMainSearchText->Text = m_asSearchText;
				}
			}
			else if(Sender == edtMainSearchText || palMainSearchBar->Visible)
			{
				if(edtMainSearchText->Text != "")
				{
					m_asSearchText 			= edtMainSearchText->Text;
					edtMiniSearchText->Text = m_asSearchText;
				}
			}

			if( frmMain->m_asSearchText.IsEmpty() )
			{
				m_bSearching	= false;//201221//
				return;
			}

			m_asSearchPnu 	= frmSql->func_ConvertAddressToLandcd(m_asSearchText, false);
			if(m_asSearchPnu.Length() != 19)
			{
				m_vSearchPnuList.clear();
				m_vSelectedID.clear();
				_SELECTREALLANDCD 			= "";

				frmSearch->funcTotalSearchKeyword();
				return;
			}
		}
		else
		{
			//210201//if( !funcCheckFindKeyword(Sender) )//200302
			if( m_asSearchPnu.Length() != 19 && !funcCheckFindKeyword(Sender) )//210201//
			{
				m_bSearching = false;
				return;
			}
		}
	}


	//==========================
	//210308//#LOADING_TEST
	m_cStart	= clock();
	//==========================


	//210412//#MEMO_KEYWORD
	AnsiString  asSearchText	= func_ConvertLandcdToAddress(m_asSearchPnu);//통합검색//
	bsSkinStatusPanel->Caption = "지번 <" + asSearchText + ">을 검색합니다.";
	StatusBar2->Panels->Items[0]->Text = "지번 <" + asSearchText + ">을 검색합니다.";
//	m_asSearchText	= func_ConvertLandcdToAddress(m_asSearchPnu);//통합검색//
//	bsSkinStatusPanel->Caption = "지번 <" + m_asSearchText + ">을 검색합니다.";
//	StatusBar2->Panels->Items[0]->Text = "지번 <" + m_asSearchText + ">을 검색합니다.";

	//==========================================================================
	IMGTABClick(IMGTAB00);//함수 안에서 한다//m_nActiveDoc = 0;//무조건//

	//210107//#SEJONGPNU
	if ( _SIDOCODE == "36110" && m_asSearchPnu.SubString(1, 5) != _SIDOCODE)
		eFunc->funcPnuToSejongPnu(0);

	if(m_asSearchPnu.Length() == 19)
	{
		m_asSearchPnuDoc0	= m_asSearchPnu;//210104//

		frmSearch->funcSaveLog(9, 0, "JIBUN");
		//210308//#LOADING_TEST//func_JibunUnifiedSearch(m_asSearchText, INIINFO.SIDOCODE);
		//210308//#LOADING_TEST//from func_JibunUnifiedSearch()
		//---
		//구축문서에 있는 지번(과거지번 포함)에서 정보 가져온다//191127
		frmSql->func_readKindofDocData(m_asSearchPnu);
		if(frmSql->m_vKINDOFDOCDATA.size() == 0)
			frmSql->m_nKindOfDocIndex = -1;
		else
			frmSql->m_nKindOfDocIndex = 0;
        //---

		frmSearch->funcTotalSearchJibun();
	}

	m_asSearchText	= asSearchText;//210412//#MEMO_KEYWORD


	//==========================
	//210308//#LOADING_TEST
	m_cFinish	= clock();
	double  duration = (double)(m_cFinish - m_cStart) / CLOCKS_PER_SEC;
	if(m_bDEBUG)
		funcSetStatusBarMsg(1, "Search:" + FloatToStr(duration));
	//==========================

}
