void __fastcall TfrmMain::WndProc(TMessage &Message)
{
	switch(Message.Msg) {
		case WM_ACTIVATE :
			if(m_nMaxLogoutTimeCount > 0){//타임체크를 진행함
				m_sCurrentActiveMode = "ACTIVATE";
				GetCursorPos(&m_pStartPoint);
				m_pCheckPoint  = m_pStartPoint;
				m_pDiffPoint.x = abs(m_pCheckPoint.x - m_pStartPoint.x);
				m_pDiffPoint.y = abs(m_pCheckPoint.y - m_pStartPoint.y);
				m_nLogoutTimeCount = 0;
				//191129//bsSkinStatusPanel5->Caption = m_sCurrentActiveMode;
				if(LogoutTimerCount->Enabled == false) LogoutTimerCount->Enabled = true;
			}
			else{
				//191129//bsSkinStatusPanel5->Caption = "NO CHECK";
			}
			break;

		case WM_CAPTURECHANGED://210305//#44710//
			if(!B_CAPTURE && m_asCurrentId != func_Encoder("admin") && !m_bDEBUG && IsSNAPSHOTpressed())//240415//[REQ][44130]김영훈J//220111//ITKOREA테스트계정&디버그모드//210305//#44710//
//240415//Test//			if(m_asCurrentId != func_Encoder("admin") && !m_bDEBUG && IsSNAPSHOTpressed())//240415//[REQ][44130]김영훈J//220111//ITKOREA테스트계정&디버그모드//210305//#44710//
			{
				frmMsg->funcMessageDlg("알림:", "화면캡처 기능을 사용할 수 없습니다.", 3);
	            return;
            }
			break;

		default:
			break;
	}

	TForm::WndProc( Message );
}
