//---------------------------------------------------------------------------

void __fastcall TfrmMain::LogoutTimerCountTimer(TObject *Sender)
{
	if(m_nMaxLogoutTimeCount > 0){//타임체크를 진행함
		if(frmProgramCloseQ->Showing == false){
			if(m_nMaxLogoutTimeCount > 0){//타임체크를 진행함
				if(m_sCurrentActiveMode == "DEACTIVATE"){//현재 DEACTIVATE 라면..
					bool success = false;
					HWND hCurrentWnd  = GetForegroundWindow();
					if(hCurrentWnd != NULL){
						HWND hOwnerWnd = GetWindow(hCurrentWnd, GW_OWNER);
						if(hOwnerWnd != NULL){
							char* lpString = new char[255];
							int nMaxCount = 254;
							memset(lpString, 0, 255);

							GetWindowText(hOwnerWnd, lpString, 255);

							AnsiString strString = (char*)lpString;
							if(strString == "지적문서통합관리시스템"){//종료하지마....
								success = true;
							}

							delete lpString;
						}
					}

					if(success == false){
						m_nLogoutTimeCount++;

						if(m_nMaxLogoutTimeCount < m_nLogoutTimeCount){//설정시간이 지났으면...
							LogoutTimerCount->Enabled = false;

							frmProgramCloseQ->CountLabel->Visible        = true;
							frmProgramCloseQ->CountMessageLabel->Visible = true;
							frmProgramCloseQ->m_bCount = m_LastLogoutCount;
							frmProgramCloseQ->CountLabel->Caption = "[" + IntToStr(frmProgramCloseQ->m_bCount) + "]";
							frmProgramCloseQ->Timer1->Enabled = true;
							frmProgramCloseQ->ShowModal();

							if(frmProgramCloseQ->Tag == 1){
								funcExecLogin();
								m_bCloseProcess = false;
								Close();
							}
							else SetFocus();
						}
					}
					else{//메인폼과 연결된 폼이 활성화 되었다면...
						//ACTIVATE 된것으로 판단함...
						GetCursorPos(&m_pCheckPoint);
						m_pDiffPoint.x = abs(m_pCheckPoint.x - m_pStartPoint.x);
						m_pDiffPoint.y = abs(m_pCheckPoint.y - m_pStartPoint.y);

						if(m_pDiffPoint.x == 0 && m_pDiffPoint.y == 0){
							m_nLogoutTimeCount++;

							if(m_nMaxLogoutTimeCount < m_nLogoutTimeCount){//설정시간이 지났으면...
								LogoutTimerCount->Enabled = false;

								frmProgramCloseQ->CountLabel->Visible        = true;
								frmProgramCloseQ->CountMessageLabel->Visible = true;
								frmProgramCloseQ->m_bCount = m_LastLogoutCount;//191118
								frmProgramCloseQ->CountLabel->Caption = "[" + IntToStr(frmProgramCloseQ->m_bCount) + "]";
								frmProgramCloseQ->Timer1->Enabled = true;
								frmProgramCloseQ->ShowModal();

								if(frmProgramCloseQ->Tag == 1){
									funcExecLogin();
									m_bCloseProcess = false;
									Close();
								}
								else SetFocus();
							}
						}
						else{//움직이고 있다면...
							m_pStartPoint =	m_pCheckPoint;

							if(m_nLogoutTimeCount != 0) m_nLogoutTimeCount = 0;
						}
					}
				}
				else{//현재 ACTIVATE라면
					GetCursorPos(&m_pCheckPoint);
					m_pDiffPoint.x = abs(m_pCheckPoint.x - m_pStartPoint.x);
					m_pDiffPoint.y = abs(m_pCheckPoint.y - m_pStartPoint.y);

					if(m_pDiffPoint.x == 0 && m_pDiffPoint.y == 0){
						m_nLogoutTimeCount++;

						if(m_nMaxLogoutTimeCount < m_nLogoutTimeCount){//설정시간이 지났으면...
							LogoutTimerCount->Enabled = false;

							frmProgramCloseQ->CountLabel->Visible        = true;
							frmProgramCloseQ->CountMessageLabel->Visible = true;
							frmProgramCloseQ->m_bCount = m_LastLogoutCount;//191118
							frmProgramCloseQ->CountLabel->Caption = "[" + IntToStr(frmProgramCloseQ->m_bCount) + "]";
							frmProgramCloseQ->Timer1->Enabled = true;
							frmProgramCloseQ->ShowModal();

							if(frmProgramCloseQ->Tag == 1){
								funcExecLogin();
								m_bCloseProcess = false;
								Close();
							}
							else SetFocus();
						}
					}
					else{//움직이고 있다면...
						m_pStartPoint =	m_pCheckPoint;

						if(m_nLogoutTimeCount != 0) m_nLogoutTimeCount = 0;
					}
				}
			}
			else LogoutTimerCount->Enabled = false;
		}
		//191129//bsSkinStatusPanel5->Caption = m_sCurrentActiveMode + " : " + IntToStr(m_nLogoutTimeCount) + "/" + IntToStr(m_nMaxLogoutTimeCount);
	}
	else{
		//191129//bsSkinStatusPanel5->Caption = "NO CHECK TIME";
	}
}
