void __fastcall TfrmMain::funcExecLogin()
{
//
	AnsiString exefile = frmMain->ROOTPATH + "..\\지적문서통합관리시스템.exe";//231010//

	if(FileExists(exefile)){
		SHELLEXECUTEINFO ExVal;
		ExVal.cbSize       = sizeof(SHELLEXECUTEINFO);
		ExVal.fMask        = NULL;
		ExVal.hwnd         = NULL;
		ExVal.lpVerb       = NULL;
		ExVal.lpFile       = exefile.c_str();
		ExVal.lpParameters = "SYSTEM_OK";
		ExVal.lpDirectory  = "";
		ExVal.nShow        = SW_SHOW;
		ExVal.hInstApp     = NULL;
		ShellExecuteEx(&ExVal);
	}
}
