//===========================================================================
// 문서별 상세검색 예외처리// 상세검색 읍면동코드 혹은 지번 입력의 공통 기능//
//===========================================================================
void __fastcall TfrmMain::funcDetailCommonKeyPress()
{
	if(edtUmdRiNm->Text.IsEmpty() || edtUmdRiCd->Text.IsEmpty())
		IMGCODEFINDClick(btnCodeSearch);
	else if(cboGbn->Enabled)//210104//
	{
		if(m_asSearchPnuDoc0.Length() >= 11)
		{
			cboGbn->ItemIndex 	= m_asSearchPnuDoc0.SubString(11, 1).ToInt() - 1;
			if(_SIDOCODE == "36110" && cboGbn->ItemIndex < 0)//220727//세종_옛날지번으로 검색시 TB_SEJONG_PNU.FD_PNU_NEW 정보를 가져와서 LAND_GBN 정보가 없는 경우가 많다.
			{
				cboGbn->ItemIndex 	= m_asSejongOldPnu.SubString(11, 1).ToInt() - 1;
			}
			edtBobn->SetFocus();
		}
		else
		{
			cboGbn->SetFocus();
		}
	}
	else if(edtBobn->Text.IsEmpty())
		edtBobn->SetFocus();
	else if(edtBubn->Text.IsEmpty())
		edtBubn->SetFocus();
	else
		btnQSearchClick(btnQSearch);
}
