void __fastcall TfrmMain::doc18KeyPress(TObject *Sender, wchar_t &Key)
{
// 숫자만 입력//
	if(Key == VK_RETURN)
	{
		if(Sender == edtJigu18)
		{
			edtDogn18->SetFocus();
		}
		else if(Sender == edtDogn18)
		{
			if(edtJigu18->Text.Trim() == "" && edtDogn18->Text.Trim() != "" && eFunc->IsNumberString( AnsiString(edtDogn18->Text.Trim()) ) )
			{
				frmMsg->funcMessageDlg("데이터 입력 확인:", "도근명칭이 아닌 숫자만 입력하는 경우에는 지구명도 입력해주세요.", 3);
				edtDogn18->SetFocus();
				return;
            }
			edtX18->SetFocus();
		}
		if(Sender == edtX18)
		{
			if(edtX18->Text.Trim() != "" && edtX18->Text.Trim().Length() < 6)
			{
				frmMsg->funcMessageDlg("데이터 입력 확인:", "좌표 값을 6자리로 입력해주세요.", 3);
				edtX18->SetFocus();
				return;
			}
			edtY18->SetFocus();
		}
		if(Sender == edtY18)
		{
			if(edtY18->Text.Trim() != "" && edtY18->Text.Trim().Length() < 6)
			{
				frmMsg->funcMessageDlg("데이터 입력 확인:", "좌표 값을 6자리로 입력해주세요.", 3);
				edtY18->SetFocus();
				return;
			}
			dtStartDayDoc18->SetFocus();
		}
		if(Sender == dtStartDayDoc18)
		{
			dtEndDayDoc18->SetFocus();
		}
		else if(Sender == dtEndDayDoc18)
		{
			if((AnsiString)dtStartDayDoc18->Text > (AnsiString)dtEndDayDoc18->Text)
			{
				AnsiString strMsg = "시작일자를 종료일자보다 빠르게 설정해주세요.";
				frmMsg->funcMessageDlg("날짜 범위 확인:", strMsg, 3);
				dtStartDayDoc18->SetFocus();
				return;
			}
			cboKindDoc18->SetFocus();
		}
		else if(Sender == cboKindDoc18)
		{
			btnQSearchClick(btnQSearch);
        }
	}
	else
	{
		if(Sender == dtStartDayDoc18 || Sender == dtEndDayDoc18)
		{
			if ((Key > 47 && Key < 58) || Key == 8)// 0~9, backspace(8) 예외
				;
			else
            	Key = NULL;
		}
		else if(Sender == edtX18 || Sender == edtY18)
		{
			AnsiString asStr = "";

			if ((Key > 47 && Key < 58) || Key == 8 || Key == 46)// 0~9, dot(46), backspace(8) 예외
			{
				if (Sender == edtX18)
					asStr = edtX18->Text.Trim();
				else if (Sender == edtY18)
					asStr = edtY18->Text.Trim();

				int pos = asStr.Pos(".");
				if (pos > 0)
					bDotFlag = true;
				else
					bDotFlag = false;

				if(Key == 46 && bDotFlag)
					Key = NULL;
			}
			else
				Key = NULL;
		}
	}
}
