void __fastcall TfrmMain::funcSQLInsertDoc07(int _nScaleType, int _nIndex)
{
	AnsiString asSIDOSGG;
	AnsiString asUMD;
	AnsiString asRI;
	AnsiString asGBN;
	AnsiString asSCALE;
	AnsiString asDOHO_BON;
	AnsiString asStr;
	int        nValue;
	AnsiString 	asSqlQry	= "";
	AnsiString 	asSqlTbl 	= "TB_DOCUMENT07";
	AnsiString 	asSqlCol 	= "";
	AnsiString 	asSqlVal 	= "";
	AnsiString 	asSqlWhere 	= "";
	char 		cCol[14][20] = {	"SIDOSGG", "UMD", "RI", "SCALE", "DOHO_BON", "X1", "Y1", "X2", "Y2", "SIZE_X", "SIZE_Y", "RATIOX", "RATIOY", "REMARK"};
	int			nColCount 	= 14;
	polyObject  tempSHPINDEX;

	memset(&tempSHPINDEX, 0x00, sizeof(polyObject));

	switch(_nScaleType)
	{
		case 500:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX0500[_nIndex], sizeof(polyObject));
			break;
		case 600:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX0600[_nIndex], sizeof(polyObject));
			break;
		case 1000:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX1000[_nIndex], sizeof(polyObject));
			break;
		case 1200:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX1200[_nIndex], sizeof(polyObject));
			break;
		case 3000:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX3000[_nIndex], sizeof(polyObject));
			break;
		case 6000:
			memcpy(&tempSHPINDEX, &m_vSHPPOLYIDX6000[_nIndex], sizeof(polyObject));
			break;
	}

	if(tempSHPINDEX.label.Length() == 12)
	{
		asSIDOSGG 	= INIINFO.SIDOCODE;
		asUMD 		= tempSHPINDEX.label.SubString(1, 3);
		asRI 		= tempSHPINDEX.label.SubString(4, 2);
		asSCALE 	= tempSHPINDEX.label.SubString(7, 2);
		asDOHO_BON 	= tempSHPINDEX.label.SubString(10, 3);
	}

	//Insert Column
	for(int i = 0; i < nColCount; i++)
	{
		AnsiString asCol = cCol[i];
		asSqlCol = asSqlCol + asCol;
		if(i != nColCount-1)
			asSqlCol = asSqlCol + ", ";
	}

	//Insert Values
	asSqlVal 	= asSqlVal + "'" + asSIDOSGG.Trim() + "', ";
	asSqlVal 	= asSqlVal + "'" + asUMD.Trim() + "', ";
	asSqlVal 	= asSqlVal + "'" + asRI.Trim() + "', ";
	asSqlVal 	= asSqlVal + "'" + asSCALE.Trim() + "', ";
	asSqlVal 	= asSqlVal + "'" + asDOHO_BON.Trim() + "', ";
	nValue    	= tempSHPINDEX.m_MBR.xmin;
	asSqlVal 	= asSqlVal + nValue + ", ";
	nValue    	= tempSHPINDEX.m_MBR.ymin;
	asSqlVal 	= asSqlVal + nValue + ", ";
	nValue    	= tempSHPINDEX.m_MBR.xmax;
	asSqlVal 	= asSqlVal + nValue + ", ";
	nValue    	= tempSHPINDEX.m_MBR.ymax;
	asSqlVal 	= asSqlVal + nValue + ", ";
	nValue      = tempSHPINDEX.m_MBR.xmax - tempSHPINDEX.m_MBR.xmin;
	asSqlVal 	= asSqlVal + nValue + ", ";
	nValue      = tempSHPINDEX.m_MBR.ymax - tempSHPINDEX.m_MBR.ymin;
	asSqlVal 	= asSqlVal + nValue + ", ";
	asSqlVal 	= asSqlVal + "1, 1, 0";

	asSqlQry.sprintf("INSERT INTO %s (%s) values (%s)",	asSqlTbl, asSqlCol, asSqlVal);

	frmSql->func_QryProcess(asSqlQry);
}
