int __fastcall TfrmMain::funcGetDoc07Index(AnsiString _label)
{
	AnsiString asLabel = "";
	int nIndex = -1;

	//191122//인덱스별 문서 개수 표시//
	for(int i = 0; i < (int)m_ResultDocument07Index.size(); i++)
	{
		asLabel = (char*)m_ResultDocument07Index[i].SUR;
		asLabel = asLabel + (char*)m_ResultDocument07Index[i].SCALE;
		asLabel = asLabel + (char*)m_ResultDocument07Index[i].DOHO_BON;
		if(_label == asLabel)
		{
			nIndex = i;
			break;
		}
	}

	return nIndex;
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::funcSQLUpdateXYDoc07Index(AnsiString _label, double _X, double _Y)
{
	AnsiString asSqlQry;
	AnsiString asWhere;
	AnsiString asSUR;
	AnsiString asGBN;
	AnsiString asSCALE;
	AnsiString asDOHO_BON;

	if(_label.Length() == 12)
	{
		asSUR 		= INIINFO.SIDOCODE + _label.SubString(1, 5);
		asSCALE 	= _label.SubString(7, 2);
		asDOHO_BON 	= _label.SubString(10, 3);

	}

	asWhere = "SUR = '" + asSUR.Trim() + "' AND SCALE = '" + asSCALE.Trim() + "' AND DOHO_BON = '" + asDOHO_BON.Trim() + "'";
	asSqlQry = "UPDATE TB_DOCUMENT07_INDEX SET X=" + FloatToStr(_X).Trim() + ", Y=" + FloatToStr(_Y).Trim() + " WHERE " + asWhere;
	frmSql->func_QryProcess(asSqlQry);

	asSqlQry = "COMMIT;";
	frmSql->func_QryProcess(asSqlQry);
}
