void __fastcall TfrmMain::IMGSCREEN2DblClick(TObject *Sender)
{
	if(IMGSCREEN2->Picture->Bitmap->Width == 0)
		return;

	if(m_nViewDocNo == 7 && IsCTRLpressed())
	{
		mMouseState.bLeftDownFlag = false;
		if(	mMouseState.tpStartPoint.x == mMouseState.tpMovePoint.x && mMouseState.tpStartPoint.y == mMouseState.tpMovePoint.y)//PnuXY
		{
			int nOrgX = (int)((double)(mMouseState.tpMovePoint.x) / ((double)m_dDocFactor * (double)m_dDocFactor));
			int nOrgY = (int)((double)(mMouseState.tpMovePoint.y) / ((double)m_dDocFactor * (double)m_dDocFactor));

			//200401//
			if(frmSql->m_ResultDoc07DBInfo.size() == 0)
			{
				m_ResultDocument07[frmMain->m_nNodeIndexInDoc].BASE_X = nOrgX;
				m_ResultDocument07[frmMain->m_nNodeIndexInDoc].BASE_Y = nOrgY;
				m_asCurrentFilePath = (char*)m_ResultDocument07[frmMain->m_nNodeIndexInDoc].PATH_NAME;
			}
			else
			{
				frmSql->m_ResultDoc07DBInfo[0].BASE_X = nOrgX;
				frmSql->m_ResultDoc07DBInfo[0].BASE_Y = nOrgY;
				m_asCurrentFilePath = (char*)frmSql->m_ResultDoc07DBInfo[0].PATH_NAME;
			}

			frmSql->funcQryInsert_DOCUMENT07_BASEXY(1, nOrgX, nOrgY);

			if(m_asSearchPnu.Length() == 19)//191120
			{
				//200401
				frmMain->m_vLANDINFO.clear();
				frmMain->m_vLANDINFO_SUB.clear();//201227//

				frmSql->funcQrySelect_LAND_INFO_MAPPOINT(false, m_asSearchPnu);

				funcCalcWorldToMap(false);//DB value : 지번표시
				if(currMapPoint.POS_X > 0 && currMapPoint.POS_Y > 0)
				{
					if(m_bOtherJibun)
					{
						lblMapPoint->Caption = "인근지번";
						lblMapPoint->Width = 52;//200227
					}
					else
					{
						lblMapPoint->Caption = eFunc->funcPnuToBonbuName(m_asSearchPnu.c_str(), 0);
						lblMapPoint->Width = lblMapPoint->Caption.Length() * lblMapPoint->Font->Size;//200227//frmIniControl->mUserSetIniInfo.ulDoc0_V5_1);
					}

					shpMapPoint->Width = lblMapPoint->Width + imgMapPointClose->Width + 4;//200227
					if(m_vLANDINFO.size() == 0 && frmSql->m_ResultDoc07DBInfo[0].REMARK == 2)
					{
						lblMapPoint->Font->Color 	= clRed;
						shpMapPoint->Pen->Color 	= clRed;
					}
					else
					{
						lblMapPoint->Font->Color 	= clBlue;
						shpMapPoint->Pen->Color 	= clBlue;
					}
					lblMapPoint->Font->Color 	= clBlue;
					shpMapPoint->Pen->Color 	= clBlue;
					funcSetLabelMapPoint(true);
					funcRedrawMapPoint();
				}
				else
				{
					funcSetLabelMapPoint(false);
				}
			}

			if(chkDogakLine->Checked)
			{
				funcDeleteRectangle();
				funcDeleteAreaGauge();
				funcDeleteStreetGauge();

				funcMakeDogakLine();

				palMainView->SetFocus();
			}
		}
	}
}
