void __fastcall TfrmMain::funcSetModeLayer(bool _bLayer)
{
	palMode->Left			= palClient->Width - (EDGEGAP + palMode->Width);
	palMode->Top			= EDGEGAP;
	palLayer->Left			= palMode->Left - (EDGEGAP + IMGLAYER->Width);
	palLayer->Top			= EDGEGAP;
	palLayerSet->Left		= palLayer->Left - palLayerSet->Width / 2;
	palLayerSet->Top		= palLayer->Top + palLayer->Height - 1;
	palRegist->Left	  		= palMode->Left - (EDGEGAP + palRegist->Width);//프로그램 로딩 시, 일단 보여줘야 하니까 위치 설정//
	palRoadView->Top		= palMode->Top + palMode->Height + EDGEGAP;//210427//#ROADVIEW
	//TEMPDOC//
	if(palRegist->Visible)	palTempList->Left	  	= palRegist->Left - (EDGEGAP + palTempList->Width);
	else                  	palTempList->Left	  	= palMode->Left - (EDGEGAP + palTempList->Width);
	palTempList->Top		= EDGEGAP;

	if(PROGRAM_START)
	{
		palLayer->Visible		= _bLayer;
		palLayerSet->Visible	= false;

		//#ICONPOI#상단//
		palPoi->Visible			= _bLayer;

		//210427//#ROADVIEW
//241108//CommonFunctions//
//		if(INI_B_ROADVIEW)
			palRoadView->Visible	= _bLayer;

		//#REGIST#
		if(_bLayer)
			palRegist->Left	  	= palLayer->Left - (EDGEGAP + palRegist->Width);
		else
			palRegist->Left	  	= palMode->Left - (EDGEGAP + palRegist->Width);

		palRegist->Top			= EDGEGAP;
		palRegistSet->Left		= palRegist->Left - palRegistSet->Width / 2;
		palRegistSet->Top		= palRegist->Top + palRegistSet->Height - 1;
		palRegistSet->Visible	= false;
	}
}
