void __fastcall TfrmMain::funcDrawPbDogeun()
{
	PBDOGN->Canvas->Lock();

	HPEN pen;
	HFONT m_font;
	HFONT hOldFont;
	TPoint start, end;
	GPoint inputPoint;
	HDC hdc = PBDOGN->Canvas->Handle;
	int size = m_ResultDocument18All.size();

	if(size > 0){
		pen   = ::CreatePen(PS_SOLID, 3, 0x000000ff);
		::SelectObject(hdc, pen);
		int oldro2 = ::SetROP2( hdc, R2_COPYPEN);

		m_font    = ::CreateFont(12, 0, 0, 0, FW_HEAVY, FALSE, FALSE, 0, HANGUL_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
		hOldFont  = (HFONT)::SelectObject(hdc, m_font);
		::SetBkMode(hdc, TRANSPARENT);
		::SetTextColor(hdc, RGB(255, 0, 0));

		TRect  mbrRect, rectBuffer;
		TRect _rect;
		_rect.Left   = 0;
		_rect.Top    = 0;
		_rect.Right  = IMGSCREEN1->Width;
		_rect.Bottom = IMGSCREEN1->Height;

		for(int i=0; i<size; i++){
			// 화면 밖이면 그리지 않는다..
			MBR tmbr;
			tmbr.xmin = m_ResultDocument18All[i].X - 3;
			tmbr.ymin = m_ResultDocument18All[i].Y - 3;
			tmbr.xmax = m_ResultDocument18All[i].X + 3;
			tmbr.ymax = m_ResultDocument18All[i].Y + 3;
			mbrRect = func_WorldToDevice(tmbr);
			if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
				continue;
			}

			inputPoint.x = m_ResultDocument18All[i].X;
			inputPoint.y = m_ResultDocument18All[i].Y;
			start = func_WorldToDevice(inputPoint);
			::Rectangle(hdc, start.x-3, start.y-3,start.x+3, start.y+3);
			AnsiString asLabel = m_ResultDocument18All[i].DOGNPOINT;
			PBDOGN->Canvas->TextOutA(start.x - 20/* - (asLabel.Length()*10)/2*/, start.y-20, asLabel);
		}

		::SelectObject(hdc, hOldFont);
		::DeleteObject(m_font);

		::SetROP2( hdc, oldro2);
		::DeleteObject( pen );
	}

	PBDOGN->Canvas->Unlock();
}
