int __fastcall TfrmMain::funcGetMemoIndex(AnsiString _label)
{
	AnsiString asLabel = "";
	int nIndex = -1;

	for(int i = 0; i < (int)frmSql->m_vALLMEMOINFO.size(); i++)
	{
		asLabel = (char*)frmSql->m_vALLMEMOINFO[i].POI_KEY;
		if(_label == asLabel)
		{
			nIndex = i;
			break;
		}
	}

	return nIndex;
}
