void __fastcall TfrmMain::funcSetTabButtons()
{
	wchar_t wBufImg[64];
	TImage *tcmpImg;
	int nTag   = -1;
	int nCount = 0;//<검색>버튼 항상 포함이지만 width가 다르다//

	for(int i = 1; i < DF_DOC_CNT; i++)//191223//원복//#TAB00DEL#<검색>은 제외하기로//사장님Req//
	{
		//210201//#IMGTAB2ROW//
//		if(nCount >= 5)
//			break;

		memset(wBufImg, 0, sizeof(wBufImg));
		swprintf(wBufImg, L"IMGTAB%02d", i);
		tcmpImg = (TImage*)this->FindComponent(wBufImg);
		if(tcmpImg != NULL)
		{
			tcmpImg->Picture->Bitmap	= NULL;
			tcmpImg->Picture			= NULL;

			if( !INIINFO.B_DOCFAVOR[i] )
			{
				tcmpImg->Visible	= false;
				continue;
			}

			if( !INIINFO.B_DOCKIND[i] )
				continue;

			if( i == IMGTABDETAIL->Tag )
				tcmpImg->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[i][1]);
			else
				tcmpImg->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[i][0]);
			tcmpImg->Visible	= true;
			//210201//#IMGTAB2ROW//tcmpImg->Left		= 42 + nCount * (BITMAP_BTN_TABDOC[i][0]->Width + 4);
			if(nCount <= 6)//231114//상세검색 탭 기능추가//
			{
				tcmpImg->Left		= 2 + nCount * (BITMAP_BTN_TABDOC[i][0]->Width + 1);//231101//2->1//210201//#IMGTAB2ROW//
				tcmpImg->Top		= 144;//231114//상세검색 탭 기능추가//100 -> 136
			}
			else
			{
				tcmpImg->Left		= 2 + (nCount - 7)* (BITMAP_BTN_TABDOC[i][0]->Width + 1);//231101//2->1//210201//#IMGTAB2ROW//
				tcmpImg->Top		= 178;//231114//상세검색 탭 기능추가//134 -> 170
			}
			nCount++;
		}
//ORG
//		//210201//#IMGTAB2ROW//
//		if(m_nTABCOUNT <= 6)//231114//상세검색 탭 기능추가//
//			pnlSearchBar->Height	= 170;//231114//상세검색 탭 기능추가//144 -> 170
//		else
//			pnlSearchBar->Height	= 206;//231114//상세검색 탭 기능추가//180 -> 206
	}

//231118//상세검색 탭 표시.미표시 역할//
	m_nTABCOUNT = nCount;
	if(m_nActiveDoc != 0)//상세검색//
	{
		if(m_nTABCOUNT <= 7)//231114//상세검색 탭 기능추가//
			pnlSearchBar->Height	= 178;//231114//상세검색 탭 기능추가//144 -> 170
		else
			pnlSearchBar->Height	= 214;//231114//상세검색 탭 기능추가//180 -> 206
	}
	else//통합검색//
	{
		pnlSearchBar->Height	= 130;
	}
}
