	m_bChkIndexAll = true;

	if(m_vSHPPOLYIDX0500.size() > 0)
		chkIndex500->Checked 	= chkIndexAll->Checked;
	if(m_vSHPPOLYIDX0600.size() > 0)
		chkIndex600->Checked 	= chkIndexAll->Checked;
	if(m_vSHPPOLYIDX1000.size() > 0)
		chkIndex1000->Checked 	= chkIndexAll->Checked;
	if(m_vSHPPOLYIDX1200.size() > 0)
		chkIndex1200->Checked 	= chkIndexAll->Checked;
	if(m_vSHPPOLYIDX3000.size() > 0)
		chkIndex3000->Checked 	= chkIndexAll->Checked;
	if(m_vSHPPOLYIDX6000.size() > 0)
		chkIndex6000->Checked 	= chkIndexAll->Checked;

	int configindex = func_ConfigIndexAlloc(1,"인덱스0500", "");
	if(configindex < 0) return;
	m_vCONFIGLP[configindex].showuse	= chkIndex500->Checked;

	configindex = func_ConfigIndexAlloc(1,"인덱스0600", "");
	if(configindex < 0) return;
	m_vCONFIGLP[configindex].showuse	= chkIndex600->Checked;

	configindex = func_ConfigIndexAlloc(1,"인덱스1000", "");
	if(configindex < 0) return;
