void __fastcall TfrmMain::treSystemClick(TObject *Sender)
{
	if (this->palWait->Visible)
		return;

	if (treSystem->Selected == NULL) {
		mSearchNode.tSelectNode = NULL;
		return;
	}

	funcSetPnlPnuList( false );

	if(frmMemo->m_bMemoRegist)//등록중일 때, 더블클릭으로 두번 실행되는 것 방지//등록상태에서 다른 것을 선택했을 때//
	{
		frmMsg->funcMessageDlg("메모등록 확인:", "메모등록중입니다.", 3);
		return;
	}

	if(m_eManipulationMode == MemoPoint || m_eManipulationMode == MemoRect)
	{
		frmMsg->funcMessageDlg("메모등록:", "메모등록 후에 선택을 해주세요.", 3);
		return;
	}

	//200305//funcClosePanel();//200110

//241116//NotUsed//	if (mSearchNode.tbeforeSelectNode) {}

	//201201//TEST
	mSearchNode.tSelectNode 		= treSystem->Selected;
//241116//NotUsed//	mSearchNode.tbeforeSelectNode 	= mSearchNode.tSelectNode;

	if (mSearchNode.tSelectNode->Parent->Index == -1) {
		return;
	}
}
