void __fastcall TfrmMain::treSystemMouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	//==========================================================
	//마우스 모양 변경
	TControl *SenderControl = dynamic_cast<TTreeView *>(Sender);
	int SysCommWparam = -1;

	if(SenderControl != NULL)//201228//
	{
		if(Y < 8)
			SenderControl->Cursor = SC_DRAG_RESIZEU;
		else
			SenderControl->Cursor = crDefault;
	}

	if(SysCommWparam != -1){
		ReleaseCapture();
		SendMessage(Handle, WM_SYSCOMMAND, SysCommWparam, 0);

		currentWidth  = this->ClientWidth;
		currentHeight = this->ClientHeight;
	}
	//==========================================================

	if (Button != mbRight)
	{
		return;
	}
	else if (Button == mbRight)
	{
		if(mSearchNode.tSelectNode == NULL)//201211//아직 선택한 노드 없을때 바로 우클릭하면 에러발생//
			return;

		if(m_nViewDocNo == 8 || m_nViewDocNo == 9)//201215//구대장/보존문서 썸네일 없어서 Pass//
			return;

		if( !pnlPreview->Visible || m_vThumbPathList.size() == 0)//201215//썸네일 없으면 Pass//
			return;

		//201126//return;

		if(m_bThumbChecked)//210104//
			return;

		//201201//
		bool	bPopupShow	= false;

		if(mSearchNode.tSelectNode->Level == 1)
		{
			if(m_nViewDocNo == 3 || m_nViewDocNo == 4)//always, Node Level = 1/
				bPopupShow	= true;
			else if(/*m_nViewDocNo == 9 && */frmSearch->m_bKindDoc)//상세검색//문서구분 선택//
				bPopupShow	= true;
			else
				bPopupShow	= true;
		}
		else if(mSearchNode.tSelectNode->Level > 1)
		{
			if(m_nViewDocNo == 9)//KIND_CODE 폴더링이라 하위 내용이 서로 다른 건이다//
				bPopupShow	= true;
			else
				bPopupShow	= true;
		}

		//201130//
		if(bPopupShow)
		{
			//201215//개별인쇄 삭제//금란K//Req//
//			if(frmMain->mSelectNodeFile == frmMain->mSelectNodeFolder || mSearchNode.tSelectNode == treSystem->Selected || mSearchNode.tSelectNode == treSystem->Selected->Parent )
//			{
//				this->mnuLeftOnePrint->Enabled   = true;
//				this->mnuLeftGroupPrint->Enabled = true;
//				this->mnuLeftGroupSave->Enabled  = true;
//			}
//			else if(mSearchNode.tSelectNode->ImageIndex == 5)
//			{
//				this->mnuLeftOnePrint->Enabled   = true;
//				this->mnuLeftGroupPrint->Enabled = false;
//				this->mnuLeftGroupSave->Enabled  = false;
//			}

			//210112//
			//======================================================================
			HWND hWnd = NULL;
			hWnd = FindWindow(NULL, "Preview");
			if(hWnd)
			{
//				frmMsg->funcMessageDlg("인쇄프로그램 확인:", "기존 실행중이던 인쇄프로그램을 종료합니다.", 3);
//				SendMessage(hWnd,WM_CLOSE,0,0);
				frmMsg->funcMessageDlg("인쇄프로그램 확인:", "이미 인쇄프로그램이 실행중입니다.", 3);
				return;
			}
			//======================================================================


			TPoint    _poppoint;
			GetCursorPos(&_poppoint);
			PopupMenu3->Popup(_poppoint.x, _poppoint.y);
		}
		else
		{
			return;
		}
	}

	//211206//속성표시 안함//#OWNINFO#
//	if(frmMain->INI_B_OWNNAMES && m_nViewDocNo == 8)//201126//200814// && frmResultList->OutputPage->ActivePage == frmResultList->TabHistory)
//	{
//		if( !frmResultList->Showing )
//			frmResultList->Show();
//	}

	TTreeNode *Node = treSystem->GetNodeAt(X,Y);
	if(Node)
	{
		Node->Selected=true;//treSystem->Selected=true;//또는 이렇게...
		Node->Expand(true);
		int nCnt = Node->Count;
		treSystemClick(treSystem);
	}
}
