void __fastcall TfrmMain::func_Trans()
{
	//HRGN : 윈도우의 GDI Handle
	//CombineRgn : HRGN 핸들을 조합하는 것. 원하는 모양을 잘라냈을 때의 핸들.(실제로 적용은 하지 않습니다.)
	//SetWindowRgn : 잘라냈을때의 핸들을 윈도우에 적용시키는 것.
	HRGN hRegion,hRegion1;

	hRegion1 = CreateRectRgn(palMainView->Left, palMainView->Top, palMainView->Width, palMainView->Height);
	hRegion  = CreateRectRgn(pnlImgDocView->Left, pnlImgDocView->Top, pnlImgDocView->Width, pnlImgDocView->Height);
	CombineRgn(hRegion, hRegion1, hRegion, RGN_DIFF);

	SetWindowRgn(Handle, hRegion, True);
}
