void __fastcall TfrmMain::chkOwnNamesClick(TObject *Sender)
{
	if(chkOwnNames->Checked)
	{
		if( !frmDoc8View->Showing )
		{
			if(FileExists(frmAlphaDoc8->m_asSavedFileName))
			{
				frmDoc8View->Left	= 0;
				frmDoc8View->Top	= 0;

				frmDoc8View->Show();
				//220121//#TB_COPY_DOC08//구대장<한글표시> 체크 : DB 저장//
				frmSql->funcSQLWriteTbCopyDoc08(DF_NEW_RECORD, 1);
			}

			if(frmAlphaDoc8->Showing)
				frmAlphaDoc8->Close();//221208//#PRINT_IMPROVE//
		}
//===================================================
	}
	else
	{
		//
		if( frmAlphaDoc8->Showing )
			frmAlphaDoc8->Close();
		//230328//한글변환Form을 직접 닫을 때 chkOwnNames을 해제하는데 그 때 frmDoc8View->Close()를 또 호출하며 반복하기에 Flag 처리//
		//한글변환Form을 직접 닫을 때, true 처리-> chkOwnNamesClick 처리 후 해제//
		if( !frmDoc8View->m_bDoc8ViewClose )//230328//e08DataAlpha->m_bDoc8ViewClose 조건추가//
		{
			if( frmDoc8View->Showing )
				frmDoc8View->Close();
		}
		else
		{
			frmDoc8View->m_bDoc8ViewClose	= false;
		}

		palMainView->SetFocus();
		mToolButtonState = DF_PANNING;//190906

		//minji@230308//#DOC08_INFO_ICON//
		funcFreeEachButtonImage(IMGDOC08OWNNAMES);
	}
}
