void __fastcall TfrmMain::funcRedrawMapPoint()
{
	if(lblMapPoint->Visible || shpMapPoint->Visible)
	{
//		shpMapPoint->Left 	= IMGSCREEN2->Left + realLeft + (currMapPoint.POS_X * m_dDocFactor) - pnlMapPoint->Width / 2;
//		shpMapPoint->Top 	= IMGSCREEN2->Top -realTop + (currMapPoint.POS_Y * m_dDocFactor) - pnlMapPoint->Height;
		shpMapPoint->Left 	= IMGSCREEN2->Left + (realLeft + currMapPoint.POS_X) * m_dDocFactor - pnlMapPoint->Width / 2;
		shpMapPoint->Top 	= IMGSCREEN2->Top + (currMapPoint.POS_Y - realTop) * m_dDocFactor - pnlMapPoint->Height;
		lblMapPoint->Left = shpMapPoint->Left + 4;
		if(m_bOtherJibun)
			lblMapPoint->Top = shpMapPoint->Top + 2;
		else
			lblMapPoint->Top = shpMapPoint->Top + 3;
		imgMapPointClose->Left = shpMapPoint->Left + shpMapPoint->Width - imgMapPointClose->Width - 2;
		imgMapPointClose->Top = shpMapPoint->Top + 5;
		shpMapPoint->BringToFront();
		lblMapPoint->BringToFront();
		imgMapPointClose->BringToFront();
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcRotateMapPoint()
{
	if(lblMapPoint->Visible || shpMapPoint->Visible)
	{
		int nImageW = this->mGetImageInfo.nImageWidth;
		int nImageH = this->mGetImageInfo.nImageHeight;
		double dScaleW = 0.0;//(double)nImageW / (double)this->img32DocView->Width;
		double dScaleH = 0.0;//(double)nImageH / (double)this->img32DocView->Height;
		int shpMapPointL = shpMapPoint->Width / 2;
		int shpMapPointT = shpMapPoint->Height;

		switch(m_nAngleCount)
		{
			case 0:
				dScaleW = (double)nImageW / (double)this->pnlImgDocView->Width;
				dScaleH = (double)nImageH / (double)this->pnlImgDocView->Height;
				shpMapPoint->Left = (currMapPoint.POS_X / dScaleW) - shpMapPointL;
				shpMapPoint->Top  = (currMapPoint.POS_Y / dScaleH) - shpMapPointT;
				break;
			case 1:
				dScaleW = (double)nImageW / (double)this->pnlImgDocView->Width;
				dScaleH = (double)nImageH / (double)this->pnlImgDocView->Height;
				shpMapPoint->Left = (nImageW - currMapPoint.POS_Y) / dScaleW - shpMapPointL;
				shpMapPoint->Top  = (currMapPoint.POS_X / dScaleH) - shpMapPointT;
				break;
			case 2:
				dScaleW = (double)nImageW / (double)this->pnlImgDocView->Width;
				dScaleH = (double)nImageH / (double)this->pnlImgDocView->Height;
				shpMapPoint->Left = (nImageW - currMapPoint.POS_X) / dScaleW - shpMapPointL;
				shpMapPoint->Top  = (nImageH - currMapPoint.POS_Y) / dScaleH - shpMapPointT;
				break;
			case 3:
				dScaleW = (double)nImageW / (double)this->pnlImgDocView->Width;
				dScaleH = (double)nImageH / (double)this->pnlImgDocView->Height;
				shpMapPoint->Left = (currMapPoint.POS_Y / dScaleW) - shpMapPointL;
				shpMapPoint->Top  = (nImageH - currMapPoint.POS_X) / dScaleH - shpMapPointT;
				break;
		}
		lblMapPoint->Left = shpMapPoint->Left + 3;
		if(m_bOtherJibun)
			lblMapPoint->Top = shpMapPoint->Top + 2;
		else
			lblMapPoint->Top = shpMapPoint->Top + 3;
		imgMapPointClose->Left = shpMapPoint->Left + shpMapPoint->Width - imgMapPointClose->Width - 2;
		imgMapPointClose->Top = shpMapPoint->Top + 5;
	}
}
