void __fastcall TfrmMain::funcDogakLinePaint()
{
	HPEN pen1, pen2;
	HFONT m_font, m_fontA;
	HFONT hOldFont, hOldFontA;
	TPoint start, end;
	double scaleW, scaleH;
	HDC hdc = pbRect3->Canvas->Handle;

	pen1   = ::CreatePen(PS_SOLID, 1, 0x000000ff);
	::SelectObject(hdc, pen1);
	int oldro1 = ::SetROP2(hdc, R2_COPYPEN);

	if(m_vDOGAKLINE.size() > 0)
	{
		for (int i=0; i<(int)m_vDOGAKLINE.size(); i++)
		{
			start 	= m_vDOGAKLINE[i].tpMapStt;
			end		= m_vDOGAKLINE[i].tpMapEnd;
			::MoveToEx(hdc, start.x, start.y, NULL);
			::LineTo(hdc, end.x, end.y);
			::SetROP2 (hdc, oldro1);
		}

		::SetROP2 (hdc, oldro1);
		::DeleteObject( pen1 );
	}


	if(m_vDOGAKLINE.size() > 0)
	{
		AnsiString asValueW = "500";
		AnsiString asValueH = "400";//"4\r\n0\r\n0";
		AnsiString asValueHelp = "<본 도곽선은 1200 도곽선으로 참고용입니다.>";
		int nText1X = 0;
		int nText1Y = 0;
		int nText2X = 0;
		int nText2Y = 0;
		TPoint tpText1, tpText2;
		int nTextWLen = asValueW.Length();
		int nTextHLen = asValueH.Length();

		//---
		tpText1 = m_vDOGAKLINE[0].tpMapStt;
		tpText2 = m_vDOGAKLINE[(m_vDOGAKLINE.size()/2)].tpMapStt;

		//---
		int fontwidth = 14;//[TODO]//frmIniControl->mUserSetIniInfo.nDoc0_V5;
		m_font    = ::CreateFont(fontwidth, 0, 0, 0, FW_HEAVY, FALSE, FALSE, 0, HANGUL_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
		hOldFont  = (HFONT)::SelectObject(hdc, m_font);
		::SetBkMode(hdc, TRANSPARENT);
		::SetTextColor(hdc, 0x000000ff);//200313//color변경
		tcmpPaintBox[3]->Canvas->TextOutA(tpText1.x + 8, tpText1.y + 1, asValueW);
		tcmpPaintBox[3]->Canvas->TextOutA(tpText1.x + 2, tpText1.y - 12, asValueHelp);
		::SelectObject(hdc, hOldFont);
		::DeleteObject(m_font);

		//---
		m_fontA   = ::CreateFont(fontwidth, 0, 2700, 2700, FW_HEAVY, FALSE, FALSE, 0, HANGUL_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
		hOldFontA = (HFONT)::SelectObject(tcmpPaintBox[3]->Canvas->Handle, m_fontA);
		::SetBkMode(hdc, TRANSPARENT);
		::SetTextColor(hdc, 0x000000ff);//200313//Color적용//frmIniControl->mUserSetIniInfo.ulDoc0_V5_1*/);
		tcmpPaintBox[3]->Canvas->TextOutA(tpText2.x + 12, tpText2.y + 8, asValueH);
		::SelectObject(hdc, hOldFontA);
		::DeleteObject(m_fontA);

		//---
		AnsiString asValueMove = "(원하는 위치로 도곽선을 드래그하여 사용하세요.)";
		pen2   = ::CreatePen(PS_SOLID, 1, 0x00ff0000);//200313//color변경//0x0000f2ff->0x00ff0000
		::SelectObject(tcmpPaintBox[3]->Canvas->Handle, pen2);
		int oldro2 = ::SetROP2(tcmpPaintBox[3]->Canvas->Handle, R2_COPYPEN);
		::SetBkMode(hdc, TRANSPARENT);
		::SetTextColor(hdc, 0x00ff0000);//200313//color변경//0x0000f2ff->0x00ff0000
		tcmpPaintBox[3]->Canvas->TextOutA(tpText1.x + 2, tpText1.y - 24, asValueMove);
		::SetROP2 (hdc, oldro2);
		::DeleteObject( pen2 );
	}
}
