void __fastcall TfrmMain::pbRect3MouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	palMainView->SetFocus();

	if (Button != mbLeft)
		return;

	if( m_vDOGAKLINE.size() > 0 )
	{
		TPoint start, end;
		double scaleW, scaleH;

		int i = 0;
		for(i = 0; i < (int)m_vDOGAKLINE.size(); i++)
		{
			start 	= m_vDOGAKLINE[i].tpMapStt;
			end 	= m_vDOGAKLINE[i].tpMapEnd;

			if( (X >= start.x - 1 && X <= start.x + 1) || (X >= end.x - 1 && X <= end.x + 1)
			 || (Y >= start.y - 1 && Y <= start.y + 1) || (Y >= end.y - 1 && Y <= end.y + 1) )
			{
				break;
			}
		}

		if (i == (int)m_vDOGAKLINE.size())
		{
			mToolButtonStateBck = mToolButtonState;
			mToolButtonState 	= DF_PANNING;
		}
		else
		{
			mToolButtonState = DF_DOGAKLINE;
        }
	}

	if(mToolButtonState == DF_DOGAKLINE)
	{
		TPoint tpClickPoint;
		tpClickPoint.x = X;
		tpClickPoint.y = Y;

		mMouseState.tpStartPoint = tpClickPoint;
		mRactState.tpRactStartPoint = tpClickPoint;
		mRactState.tpRactEndPoint = tpClickPoint;
		mDogakLineFlags = true;

		if(IsCTRLpressed() && INI_B_SETMAPPOINT)
		{
			frmMsg->funcMessageDlg("요청:", "Base 좌표 설정은 도각선 해제 후 설정해주세요.", 3);
		}
	}
	else if(mToolButtonState == DF_PANNING)
	{
		this->IMGSCREEN2MouseDown(Sender, Button, Shift, X, Y);
	}
}
//---------------------------------------------------------------------------


void __fastcall TfrmMain::pbRect3MouseMove(TObject *Sender, TShiftState Shift, int X,
          int Y)
{
	if(mToolButtonState == DF_DOGAKLINE && mDogakLineFlags)
	{
		m_nMovedW = 0;
		m_nMovedH = 0;

		mMouseState.tpMovePoint.x = X;
		mMouseState.tpMovePoint.y = Y;
		mRactState.tpRactEndPoint = mMouseState.tpMovePoint;

		if(mDogakLineFlags)
		{
			m_nMovedW = (mRactState.tpRactEndPoint.x - mRactState.tpRactStartPoint.x) * m_dDocFactor;
			m_nMovedH = (mRactState.tpRactEndPoint.y - mRactState.tpRactStartPoint.y) * m_dDocFactor;

			for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
			{
				m_vDOGAKLINE[i].tpMapStt.x += m_nMovedW;
				m_vDOGAKLINE[i].tpMapStt.y += m_nMovedH;
				m_vDOGAKLINE[i].tpMapEnd.x += m_nMovedW;
				m_vDOGAKLINE[i].tpMapEnd.y += m_nMovedH;
			}
			tcmpPaintBox[3]->Invalidate();
			mRactState.tpRactStartPoint = mMouseState.tpMovePoint;
		}
	}
	else if(mToolButtonState == DF_PANNING){
		this->IMGSCREEN2MouseMove(Sender, Shift, X, Y);
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::pbRect3MouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	if(mToolButtonState == DF_DOGAKLINE && mDogakLineFlags)
	{
		m_nMovedW = 0;
		m_nMovedH = 0;

		mRactState.tpRactEndPoint.x = X;
		mRactState.tpRactEndPoint.y = Y;

		m_nMovedW = (mRactState.tpRactEndPoint.x - mRactState.tpRactStartPoint.x) * m_dDocFactor;
		m_nMovedH = (mRactState.tpRactEndPoint.y - mRactState.tpRactStartPoint.y) * m_dDocFactor;

		for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
		{
			m_vDOGAKLINE[i].tpMapStt.x += m_nMovedW;
			m_vDOGAKLINE[i].tpMapStt.y += m_nMovedH;
			m_vDOGAKLINE[i].tpMapEnd.x += m_nMovedW;
			m_vDOGAKLINE[i].tpMapEnd.y += m_nMovedH;
		}
		tcmpPaintBox[3]->Invalidate();
		mDogakLineFlags = false;
	}
	else if(mToolButtonState == DF_PANNING){
		this->IMGSCREEN2MouseUp(Sender, Button, Shift, X, Y);
	}
}
