void __fastcall TfrmMain::pbRect3Paint(TObject *Sender)
{
	if(!tcmpPaintBox[3]->Visible)
		return;

	tcmpPaintBox[3]->Canvas->Lock();

	funcDogakLinePaint();

	tcmpPaintBox[3]->Canvas->Unlock();
}
