void __fastcall TfrmMain::funcMakeDogakLine()
{
	funcInitPBControl2();//init pbRect

	this->m_vDOGAKLINE.clear();
	func_DogakLine();

	int nDogakW = 500;
	int nDogakH = 400;
	int nMarginL = 0;
	int nMarginT = 0;
	int nRateW = (int)(mGetImageInfo.nImageWidth / nDogakW);
	int nRateH = (int)(mGetImageInfo.nImageHeight / nDogakH);
	int nGapW = 0;
	int nGapH = 0;
	int nDpiX = 0;
	int nDpiY = 0;
	int nLineW = 0;
	int nLineH = 0;
	double dPixeltoMM = 153.846;

	if(m_vDOC07TEMP.SIZE_X == 2500)
		m_nDogakCount = 5;
	else if(m_vDOC07TEMP.SIZE_X == 3000)
		m_nDogakCount = 6;
	else//231220//TEST//
        m_nDogakCount = 5;

//241108//CommonFunctions//	if(INI_B_DOGWAK)//PixelPerMeter
	{
		nDpiX = (int)(RoundTo((double)mGetImageInfo.mBitMapHeadInfo.biXPelsPerMeter * (double)2.54, 0) / 100);
		nDpiY = (int)(RoundTo((double)mGetImageInfo.mBitMapHeadInfo.biYPelsPerMeter * (double)2.54, 0) / 100);

		nGapW = (int)(((double)nDogakW / (double)dPixeltoMM) * (double)nDpiX);
		nGapH = (int)(((double)nDogakH / (double)dPixeltoMM) * (double)nDpiY);
	}
//	else//0, 500x400
//	{
//		if(nRateW > nRateH)//작은 값 기준
//		{
//			nGapW = (nRateH * nDogakW) / m_nDogakCount;
//			nGapH = (nRateH * nDogakH) / m_nDogakCount;
//		}
//		else
//		{
//			nGapW = (nRateW * nDogakW) / m_nDogakCount;
//			nGapH = (nRateW * nDogakH) / m_nDogakCount;
//		}
//	}

	nLineW = nGapW * m_nDogakCount;
	nLineH = nGapH * m_nDogakCount;

	nMarginL = (m_vDOC07TEMP.BASE_X > 0) ? (m_vDOC07TEMP.BASE_X) : (nDogakW);
	nMarginT = (m_vDOC07TEMP.BASE_Y > 0) ? (m_vDOC07TEMP.BASE_Y - nLineH) : (nDogakH);

	funcActDeactPaintBox(3, true);

	for(int i = 0; i < (m_nDogakCount + 1)* 2; i++)
	{
		DOGAKLINE_STRUCT mTempDogak;
		memset(&mTempDogak, 0, sizeof(DOGAKLINE_STRUCT));

		if(i < m_nDogakCount + 1)
		{
			mTempDogak.gpMapStt.x 	= nMarginL;
			mTempDogak.gpMapStt.y 	= nMarginT + i * nGapH;
			mTempDogak.tpMapStt		= eFunc->funcSurveyMapToDevice(mTempDogak.gpMapStt);
			mTempDogak.gpMapEnd.x 	= nMarginL + nLineW;
			mTempDogak.gpMapEnd.y 	= nMarginT + i * nGapH;
			mTempDogak.tpMapEnd		= eFunc->funcSurveyMapToDevice(mTempDogak.gpMapEnd);
		}
		else
		{
			mTempDogak.gpMapStt.x 	= nMarginL + (i - (m_nDogakCount + 1)) * nGapW;
			mTempDogak.gpMapStt.y 	= nMarginT;
			mTempDogak.tpMapStt		= eFunc->funcSurveyMapToDevice(mTempDogak.gpMapStt);
			mTempDogak.gpMapEnd.x 	= nMarginL + (i - (m_nDogakCount + 1)) * nGapW;
			mTempDogak.gpMapEnd.y 	= nMarginT + nLineH;
			mTempDogak.tpMapEnd		= eFunc->funcSurveyMapToDevice(mTempDogak.gpMapEnd);
		}

		m_vDOGAKLINE.push_back(mTempDogak);
		tcmpPaintBox[3]->Invalidate();
	}
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcRotateDogakLine()
{
	if(lblMapPoint->Visible || shpMapPoint->Visible)
	{
		int nImageW = this->mGetImageInfo.nImageWidth;
		int nImageH = this->mGetImageInfo.nImageHeight;
		double dScaleW = (double)nImageW / (double)this->pnlImgDocView->Width;
		double dScaleH = (double)nImageH / (double)this->pnlImgDocView->Height;

		switch(m_nAngleCount)
		{
			case 0:
				for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
				{
					m_vDOGAKLINE[i].tpMapStt.x = m_vDOGAKLINE[i].tpMapStt.x / dScaleW;
					m_vDOGAKLINE[i].tpMapStt.y = m_vDOGAKLINE[i].tpMapStt.y / dScaleH;
					m_vDOGAKLINE[i].tpMapEnd.x = m_vDOGAKLINE[i].tpMapEnd.x / dScaleW;
					m_vDOGAKLINE[i].tpMapEnd.y = m_vDOGAKLINE[i].tpMapEnd.y / dScaleH;
				}
				break;
			case 1:
				for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
				{
					m_vDOGAKLINE[i].tpMapStt.x = (nImageW - m_vDOGAKLINE[i].tpMapStt.y) / dScaleW;
					m_vDOGAKLINE[i].tpMapStt.y = m_vDOGAKLINE[i].tpMapStt.x / dScaleH;
					m_vDOGAKLINE[i].tpMapEnd.x = (nImageW - m_vDOGAKLINE[i].tpMapEnd.y) / dScaleW;
					m_vDOGAKLINE[i].tpMapEnd.y = m_vDOGAKLINE[i].tpMapEnd.x / dScaleH;
				}
				break;
			case 2:
				for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
				{
					m_vDOGAKLINE[i].tpMapStt.x = (nImageW - m_vDOGAKLINE[i].tpMapStt.x) / dScaleW;
					m_vDOGAKLINE[i].tpMapStt.y = (nImageH - m_vDOGAKLINE[i].tpMapStt.y) / dScaleH;
					m_vDOGAKLINE[i].tpMapEnd.x = (nImageW - m_vDOGAKLINE[i].tpMapEnd.x) / dScaleW;
					m_vDOGAKLINE[i].tpMapEnd.y = (nImageH - m_vDOGAKLINE[i].tpMapEnd.y) / dScaleH;
				}
				break;
			case 3:
				for(int i = 0; i < (int)m_vDOGAKLINE.size(); i++)
				{
					m_vDOGAKLINE[i].tpMapStt.x = m_vDOGAKLINE[i].tpMapStt.y / dScaleW;
					m_vDOGAKLINE[i].tpMapStt.y = (nImageH - m_vDOGAKLINE[i].tpMapStt.x) / dScaleH;
					m_vDOGAKLINE[i].tpMapEnd.x = m_vDOGAKLINE[i].tpMapEnd.y / dScaleW;
					m_vDOGAKLINE[i].tpMapEnd.y = (nImageH - m_vDOGAKLINE[i].tpMapEnd.x) / dScaleH;
				}
				break;
		}

//		if((int)m_vDOGAKLINE.size() > 0)
//		{
//			StatusBar1->Panels->Items[5]->Text = "S(" + IntToStr((int)m_vDOGAKLINE[0].tpMapStt.x) + ", " + IntToStr((int)m_vDOGAKLINE[0].tpMapStt.y) + "),E(" + IntToStr((int)m_vDOGAKLINE[1].tpMapEnd.x) + ", " + IntToStr((int)m_vDOGAKLINE[1].tpMapEnd.y) + ")";
//			StatusBar1->Panels->Items[6]->Text = "S(" + IntToStr((int)m_vDOGAKLINE[2].tpMapStt.x) + ", " + IntToStr((int)m_vDOGAKLINE[2].tpMapStt.y) + "),E(" + IntToStr((int)m_vDOGAKLINE[3].tpMapEnd.x) + ", " + IntToStr((int)m_vDOGAKLINE[3].tpMapEnd.y) + ")";
//		}
	}
}
