//---------------------------------------------------------------------------
//210215//TEdit 포커스 상태에서 <임시저장>을 누르면 포커스된 Edit의 Exit함수를 호출한다//
//Exit 함수 내에서 예외가 발생하는 경우(동일지번, 날짜오류 등) 처리 못하고 그냥 저장되어 함수로 만들어서 사용한다//
bool __fastcall TfrmMain::funcExitDate(TObject *Sender)
{
	wchar_t wBufMaskEdit[64];
	TMaskEdit *tcmpMaskEdit;
	wchar_t wBufMaskEdit2[64];
	TMaskEdit *tcmpMaskEdit2;
	int nYear = 2018;
	int nMonth = 1;
	int nDay = 1;
	AnsiString asYear;
	AnsiString asMonth;
	AnsiString asDay;
	AnsiString asData;
	int nTag = dynamic_cast<TMaskEdit*>(Sender)->Tag;

	try {
		if(nTag == 1 || nTag == 2 || nTag == 3 || nTag == 5 || nTag == 14 || nTag == 18)
		{
			AnsiString asCmptName = dynamic_cast<TComponent*>(Sender)->Name;
			if(asCmptName.SubString(1, 13) == "dtStartDayDoc")
			{
				memset(wBufMaskEdit, 0, sizeof(wBufMaskEdit));
				swprintf(wBufMaskEdit, L"dtStartDayDoc%d", nTag);
				tcmpMaskEdit = (TMaskEdit*)this->FindComponent(wBufMaskEdit);

				if(tcmpMaskEdit->Text != "    -  -  ")
				{
					if(tcmpMaskEdit->Text.Trim().Length() != 10)
					{
						tcmpMaskEdit->SetFocus();
						tcmpMaskEdit->SelectAll();//210205//
						m_bExceptingMainViewFocus	= true;//210215//
						frmMsg->funcMessageDlg("요청:", "시작일자를 확인해주세요.", 3);
						return false;
					}
					else
					{
						if (!eFunc->funcCheckDate(tcmpMaskEdit->Text.Trim()))
						{
							tcmpMaskEdit->SetFocus();
							tcmpMaskEdit->SelectAll();//210205//SelStart = 0;
							m_bExceptingMainViewFocus	= true;//210215//
							frmMsg->funcMessageDlg("요청:", "시작일자를 확인해주세요.", 3);
							return false;
						}
					}
				}

				memset(wBufMaskEdit2, 0, sizeof(wBufMaskEdit2));
				swprintf(wBufMaskEdit2, L"dtEndDayDoc%d", nTag);
				tcmpMaskEdit2 = (TMaskEdit*)this->FindComponent(wBufMaskEdit2);
				if(tcmpMaskEdit2 != NULL)
				{
					if(tcmpMaskEdit->Text != "    -  -  ")
					{
						asYear = tcmpMaskEdit->Text.SubString(1,4);
						asMonth = tcmpMaskEdit->Text.SubString(6,2);
						asDay = tcmpMaskEdit->Text.SubString(9,2);
						asData = IntToStr(StrToInt(asYear) + 1) + "-" + asMonth + "-" + asDay;
						tcmpMaskEdit2->Text = asData;
					}

					if(tcmpMaskEdit->Text == "    -  -  ")//200206//시작일자를 초기화하면 종료일자도 초기화시킨다//
					{
						tcmpMaskEdit2->Text = "    -  -  ";
						return false;
					}

					if((AnsiString)tcmpMaskEdit->Text > (AnsiString)tcmpMaskEdit2->Text)
					{
						tcmpMaskEdit->SetFocus();
						tcmpMaskEdit->SelectAll();//210205//
						m_bExceptingMainViewFocus	= true;//210215//
						frmMsg->funcMessageDlg("요청:", "시작일자를 종료일자보다 빠르게 설정해주세요.", 3);
						return false;
					}
				}
			}
			else if(asCmptName.SubString(1, 11) == "dtEndDayDoc")
			{
				memset(wBufMaskEdit2, 0, sizeof(wBufMaskEdit2));
				swprintf(wBufMaskEdit2, L"dtEndDayDoc%d", nTag);
				tcmpMaskEdit2 = (TMaskEdit*)this->FindComponent(wBufMaskEdit2);

	//			if(tcmpMaskEdit2->Text.Length() != 10)
	//			{
	//				frmMsg->funcMessageDlg("요청:", "종료일자를 확인해주세요.", 3);
	//				tcmpMaskEdit2->SetFocus();
	//				return;
	//			}

				memset(wBufMaskEdit, 0, sizeof(wBufMaskEdit));
				swprintf(wBufMaskEdit, L"dtStartDayDoc%d", nTag);
				tcmpMaskEdit = (TMaskEdit*)this->FindComponent(wBufMaskEdit);
				if(tcmpMaskEdit->Text.Trim().Length() == 10)
				{
					if (!eFunc->funcCheckDate(tcmpMaskEdit2->Text.Trim()))
					{
//=============================================================================
//231014//종료일자를 지우면 팝업처리하지 말고, 시작일자 있으면 1년 뒤로 자동설정할 것!!!//
						asYear = tcmpMaskEdit->Text.SubString(1,4);
						asMonth = tcmpMaskEdit->Text.SubString(6,2);
						asDay = tcmpMaskEdit->Text.SubString(9,2);
						asData = IntToStr(StrToInt(asYear) + 1) + "-" + asMonth + "-" + asDay;
						tcmpMaskEdit2->Text = asData;
//						tcmpMaskEdit2->SetFocus();
//						tcmpMaskEdit2->SelectAll();//210205//SelStart = 0;
//						m_bExceptingMainViewFocus	= true;//210215//
//						frmMsg->funcMessageDlg("요청:", "종료일자를 확인해주세요.", 3);
//						return false;
//=============================================================================
					}
				}

				if((AnsiString)tcmpMaskEdit->Text > (AnsiString)tcmpMaskEdit2->Text)
				{
					tcmpMaskEdit2->SetFocus();
					tcmpMaskEdit2->SelectAll();//210205//
					m_bExceptingMainViewFocus	= true;//210215//
					frmMsg->funcMessageDlg("요청:", "종료일자를 시작일자보다 빠르게 설정해주세요.", 3);
					return false;
				}
			}
		}
	}
	catch(EConvertError & E) {
		frmMsg->funcMessageDlg("알림:", "날짜가 잘못입력되었습니다.", 3);
	}

	m_bExceptingMainViewFocus	= false;//210215//

	return true;


	//조회 기간 1년 자동설정하기 위함인데... 강제가 아니므로 주석처리
	/*if(tcmpMaskEdit != NULL && tcmpMaskEdit->Text.Trim().Length() == 10)
	{
		asYear = tcmpMaskEdit->Text.SubString(1,4);
		asMonth = tcmpMaskEdit->Text.SubString(6,2);
		asDay = tcmpMaskEdit->Text.SubString(9,2);
		asData = IntToStr(StrToInt(asYear) + 1) + "-" + asMonth + "-" + asDay;

		memset(wBufMaskEdit2, 0, sizeof(wBufMaskEdit2));
		swprintf(wBufMaskEdit2, L"dtEndDayDoc%d", nTag);
		tcmpMaskEdit2 = (TMaskEdit*)this->FindComponent(wBufMaskEdit2);
		tcmpMaskEdit2->Text = asData;
	}*/
}
