//===========================================================================
//palDocControlBar
//palTempDoc
//palPrevNextBar
void __fastcall TfrmMain::funcSetDocControlBar()
{
	if(palMiniSearchBar->Visible)//미니검색창//
	{
		palDocControlBar->Left = palMiniSearchBar->Left + palMiniSearchBar->Width + EDGEGAP;
		if(palConvBar->Visible)		palConvBar->Left = palDocControlBar->Left + IMGDOCCONV->Left;
		if(palAdjustBar->Visible)	palAdjustBar->Left = palDocControlBar->Left + IMGDOCADJUST->Left;
	}
	else//메인검색창//
	{
		if(pnlPreview->Visible == true)	palDocControlBar->Left = EDGEGAP + pnlPreview->Width ;
		else                           	palDocControlBar->Left = EDGEGAP;
		//
		if(palConvBar->Visible)		palConvBar->Left = palDocControlBar->Left + IMGDOCCONV->Left;
		if(palAdjustBar->Visible)	palAdjustBar->Left = palDocControlBar->Left + IMGDOCADJUST->Left;
	}

	//TEMPDOC//always//
	if(palTempDoc->Visible)
	{
		palTempDoc->Left = palDocControlBar->Left + palDocControlBar->Width + EDGEGAP;
		palTempDoc->Top = palDocControlBar->Top;
		if(frmTempDoc->funcGetIndexList(m_asCurrentFilePath) > -1)
		{
			IMGTEMPDOC->Tag = 1;
			IMGTEMPDOC->Picture->Bitmap->Assign(BITMAP_BTN_BUTTONS[0][TempDocUn]);//기 보관함 존재//
		}
		else
		{
			IMGTEMPDOC->Tag = 0;
			IMGTEMPDOC->Picture->Bitmap->Assign(BITMAP_BTN_BUTTONS[0][TempDoc]);//보관함 없는 경우//
		}
	}

	//
	palDoc08Bar->Visible	= m_bVisibleDoc08Bar;
	palDoc08Bar->Enabled	= m_bVisibleDoc08Bar;
	if(m_asParamStr2 == "SYSTEM_OK_ADMIN")//241011//#한글화편집#//
		palDoc08Bar1->Visible	= palDoc08Bar->Visible;
	if(palDoc08Bar->Visible)
	{
		palDoc08Bar->Left = palTempDoc->Left + palTempDoc->Width + EDGEGAP;
		palDoc08Bar->Top  = palTempDoc->Top;
	}
	if(palDoc08Bar1->Visible)
	{
		palDoc08Bar1->Left = palDoc08Bar->Left + palDoc08Bar->Width + EDGEGAP;
		palDoc08Bar1->Top  = palDoc08Bar->Top;
	}

	//
	palPrevNextBar->Visible	= m_bVisiblePrevNextBar;
	if(palPrevNextBar->Visible)
	{
		funcSetPrevNextBar();//funcSetDocControlBar
		//241205//구대장.이전다음문서 툴바 누락(위치조정 때문인 듯)으로 추가//
		if(palDoc08Bar1->Visible)		palPrevNextBar->Left 	= palDoc08Bar1->Left + palDoc08Bar1->Width + EDGEGAP;
		else if(palDoc08Bar->Visible)	palPrevNextBar->Left 	= palDoc08Bar->Left + palDoc08Bar->Width + EDGEGAP;
		else if(palTempDoc->Visible)	palPrevNextBar->Left 	= palTempDoc->Left + palTempDoc->Width + EDGEGAP;
		else                         	palPrevNextBar->Left 	= palDocControlBar->Left + palDocControlBar->Width + EDGEGAP;
		palPrevNextBar->Top  = palDoc08Bar->Top;
	}

	//LMFS//Doc 1 or 8//
	if(palLMFS->Visible)
	{
		if(palPrevNextBar->Visible)		palLMFS->Left 	= palPrevNextBar->Left + palPrevNextBar->Width + EDGEGAP;
		else if(palDoc08Bar1->Visible)	palLMFS->Left 	= palDoc08Bar1->Left + palDoc08Bar1->Width + EDGEGAP;
		else if(palDoc08Bar->Visible)	palLMFS->Left 	= palDoc08Bar->Left + palDoc08Bar->Width + EDGEGAP;
		else if(palTempDoc->Visible)	palLMFS->Left 	= palTempDoc->Left + palTempDoc->Width + EDGEGAP;
		else							palLMFS->Left 	= palDocControlBar->Left + palDocControlBar->Width + EDGEGAP;
		palLMFS->Top = palDocControlBar->Top;
	}
}
