void __fastcall TfrmMain::funcDispPnuList()
{
	AnsiString asLandKey	= "";
	AnsiString asStr		= "";

	for(int i = 0; i < (int)m_vSearchPnuList.size(); i++)
	{
		//sgPnuList->RowColor[i+1] = (TColor)RGB(240,240,240);
		asLandKey = (char*)m_vSearchPnuList[i].LAND_CD;//210308//#ADDRESS_DUP//(char*)m_vSearchPnuList[i].LAND_KEY;
		asStr = (char*)m_vSearchPnuList[i].ADDRESS;//210308//#ADDRESS_DUP//func_ConvertLandcdToAddress(asLandKey);
		sgPnuList->Cells[0][i+1] = asStr;
		sgPnuList->Cells[1][i+1] = asLandKey;
	}
	sgPnuList->Refresh();
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::funcDispPnuHist()
{
	AnsiString asLandKey	= "";
	AnsiString asStr		= "";

	for(int i = 0; i < (int)m_vSearchPnuHist.size(); i++)
	{
		//sgPnuHist->RowColor[i+1] = (TColor)RGB(240,240,240);
		sgPnuHist->AddBitmap(0, i+1, BITMAP_BTN_ICON[Poi18], false, haCenter, vaCenter);
		asLandKey = (char*)m_vSearchPnuHist[i].LAND_CD;//210308//#ADDRESS_DUP//(char*)m_vSearchPnuHist[i].LAND_KEY;
		asStr = (char*)m_vSearchPnuHist[i].ADDRESS;//210308//#ADDRESS_DUP//func_ConvertLandcdToAddress(asLandKey);
		sgPnuHist->Cells[1][i+1] = asStr;
		sgPnuHist->AddBitmap(2, i+1, BITMAP_BTN_SYSTEM[Close20], false, haCenter, vaCenter);
	}
	sgPnuHist->Refresh();
}
