void __fastcall TfrmMain::sgPnuHistClickCell(TObject *Sender, int ARow, int ACol)

{
	if (ACol == 0) {//위치이동//
		int _cbndindex = -1;
		//210308//#ADDRESS_DUP//
//		_SELECTREALLANDCD = (char*)m_vSearchPnuHist[ARow-1].LAND_KEY;
//		_cbndindex = func_readJibunIndex(_SELECTREALLANDCD) - 1;
		_SELECTREALLANDCD = (char*)m_vSearchPnuHist[ARow-1].LAND_CD;
		_cbndindex = m_vSearchPnuHist[ARow-1].JIBUNINDEX;
		if(_cbndindex > -1)
		{
			//210308//#ADDRESS_DUP//
			m_vSelectedID.clear();
			m_vSelectedID.push_back(_cbndindex);//지번인덱스
			funcSetPalPoi();//POI 있는 곳으로 이동하자//

			m_geoCenterPoint.x = m_vSHPPOLYCBND[_cbndindex].x;
			m_geoCenterPoint.y = m_vSHPPOLYCBND[_cbndindex].y;

			//지적도, 항공뷰, 지적도+항공뷰이면 그대로 표시//
			//200923//사장님Req//문서보기 상태였다면 통합검색에서는 그대로 있을 것, 상세검색에서는 문서열기//
			if(_CURRENT_WORKMODE != "DOCUMENT")
			{
				m_nZoomFactor	= 8;//220105//
				btnZoomTrackBar->Value = m_nZoomFactor;

				if(IMGSCREEN1->Visible == false) IMGSCREEN1->Visible = true;


					func_DrawImagePaint();
			}
//			m_nZoomFactor	= 10;
//			btnZoomTrackBar->Value = m_nZoomFactor;
//
//			if(_CURRENT_WORKMODE == "DOCUMENT")
//			{
//				IMGMODECHANGEClick(IMGMODECHANGEJIJUK);
//			}
//			else
//			{
//				if(IMGSCREEN1->Visible == false) IMGSCREEN1->Visible = true;
//				func_DrawImagePaint();//
//			}
		}

		funcSetPnlPnuList( false );
	}
	else if (ACol == 1) {//통합검색//
		//210308//#ADDRESS_DUP//
//		AnsiString _SELECTREALLANDCD = (char*)m_vSearchPnuHist[ARow-1].LAND_KEY;
//		m_asSearchText = func_ConvertLandcdToAddress(_SELECTREALLANDCD);
		//210308//#ADDRESS_DUP//
		m_asSearchPnu 	= (char*)m_vSearchPnuHist[ARow-1].LAND_CD;
		m_asSearchText 	= (char*)m_vSearchPnuHist[ARow-1].ADDRESS;

		if( !m_asSearchText.IsEmpty() )
		{
			edtMainSearchText->Font->Color = clBlack;//200227
			edtMiniSearchText->Font->Color = clBlack;//200227
			edtMainSearchText->Text = m_asSearchText;
			edtMiniSearchText->Text = m_asSearchText;
		}

		if(palMiniSearchBar->Visible)
		{
			edtMiniSearchText->SetFocus();
		}
		else if(palMainSearchBar->Visible)
		{
			edtMainSearchText->SetFocus();
		}

		funcSetPnlPnuList( false );

		IMGFINDClick(NULL);//231121//200429
	}
	else if (ACol == 2) {//삭제//
		//[TODO]VECTOR도 삭제//
		m_vSearchPnuHist.erase(m_vSearchPnuHist.begin() + ARow - 1);
		sgPnuHist->RemoveRows(ARow, 1);
		funcSetPnlPnuList(true);
	}
}
