/*

edtMainSearchText->OnEnter
funcSetPnlPnuList(true);

edtMainSearchText->OnExit, OnKeyPress(VK_RETURN)
funcSetPnlPnuList(false);

edtMainSearchText->OnKeyPress


*/
void __fastcall TfrmMain::funcSetPnlPnuList(bool _bVisible)
{
	if( !PROGRAM_START )//200318//
		return;

	if( !palMainSearchBar->Visible && !palMiniSearchBar->Visible )
		return;

	if( !_bVisible && _bVisible == pnlPnuList->Visible)//200925//
		return;

	int nHistHeight = 0;

	if(_bVisible)
	{
		if(palMiniSearchBar->Visible)
		{
			pnlPnuList->Left 	= palMiniSearchBar->Left + 123;
			//200925//pnlPnuList->Top		= palMiniSearchBar->Top + palMiniSearchBar->Height;//200313//panWindowsMove삭제//사장님Req//panWindowsMove->Height + 31;
			pnlPnuList->Top		= palMiniSearchBar->Top + edtMiniSearchText->Top + edtMiniSearchText->Height;//200925//
		}
		else
		{
			pnlPnuList->Left 	= palMainSearchBar->Left + pnlSearchBar->Left + 34;//231208//16;
			pnlPnuList->Top		= 92;//200313//panWindowsMove삭제//사장님Req//panWindowsMove->Height + 91;
		}


		//List
		if((int)m_vSearchPnuList.size() == 0)
		{
			pnlPnuList->Height		= 0;
			sgPnuList->Visible 		= false;
			pnlHistTitle->BevelKind = Controls::bvNone;
		}
		else
		{
			//200326//moved//
			funcDispPnuList();

			pnlHistTitle->BevelKind		= bkFlat;
			pnlHistTitle->BevelEdges   	>> beLeft;
			pnlHistTitle->BevelEdges   	<< beTop;
			pnlHistTitle->BevelEdges   	>> beRight;
			pnlHistTitle->BevelEdges   	>> beBottom;

			sgPnuList->RowCount 	= (int)m_vSearchPnuList.size() + 1;
			sgPnuList->Height 		= sgPnuList->RowCount * sgPnuList->DefaultRowHeight;
			sgPnuList->Top			= 0 - sgPnuList->DefaultRowHeight + 1;
			sgPnuList->Visible 		= true;
			pnlPnuList->Height		= sgPnuList->Height - sgPnuHist->DefaultRowHeight + 1;
		}

		//Hist
		if(m_bPnuHistON)
		{
			lblHistOff->Caption = "히스토리 끄기";
			pnlHistTitle->Top		= pnlPnuList->Height;
			pnlHistTitle->Visible 	= true;

			if((int)m_vSearchPnuHist.size() == 0)
			{
				pnlHistTitle->Caption 	= "";
				lblHistZero->Visible 	= true;

				sgPnuHist->Height		= 0;
				sgPnuHist->Visible 		= false;
				nHistHeight				= sgPnuHist->Height;

				lblHistDel->Visible 	= false;

				pnlPnuList->Height		= pnlPnuList->Height + pnlHistTitle->Height + pnlHistOff->Height + 1;
			}
			else
			{
				funcDispPnuHist();

				pnlHistTitle->Caption 	= "   히스토리";
				lblHistZero->Visible 	= false;
				pnlHistTitle->Top		= pnlPnuList->Height;

				sgPnuHist->RowCount 	= (int)m_vSearchPnuHist.size() + 1;
				sgPnuHist->Height 		= sgPnuHist->RowCount * sgPnuHist->DefaultRowHeight;
				sgPnuHist->Top			= pnlPnuList->Height + pnlHistTitle->Height - sgPnuHist->DefaultRowHeight;
				sgPnuHist->Visible 		= true;
				nHistHeight				= sgPnuHist->Height - sgPnuHist->DefaultRowHeight;

				lblHistDel->Visible 	= true;
				pnlPnuList->Height		= pnlPnuList->Height + pnlHistTitle->Height + nHistHeight + pnlHistOff->Height + 1;
			}
			pnlHistOff->Top		= pnlPnuList->Height - pnlHistOff->Height - 1;
			pnlHistOff->Visible	= true;
		}
		else
		{
			lblHistOff->Caption = "히스토리 켜기";
			lblHistDel->Visible 	= false;
			pnlHistTitle->Visible 	= false;
			sgPnuHist->Visible 		= false;
			pnlHistOff->Top			= pnlPnuList->Height - 1;
			pnlPnuList->Height		= pnlPnuList->Height + pnlHistOff->Height + 1;
		}
		shpPnuList->Height		= pnlPnuList->Height;//200402
		shpPnuList->BringToFront();
	}
	//201224//moved to edtMainSearchTextExit()
//	else
//	{
//		if(edtMainSearchText->Text == "" || edtMiniSearchText->Text == "")
//		{
//			edtMainSearchText->Text = "지번, 문서명을 입력해주세요.";
//			edtMainSearchText->Font->Color = clSilver;
//			edtMiniSearchText->Text = "지번, 문서명을 입력해주세요.";
//			edtMiniSearchText->Font->Color = clSilver;
//			m_vSearchPnuList.clear();//200402
//			//201222//검색어입력창에 포커스 상태에서 마우스 움직이면 포커스가 해제되는 일//pnlSearchList->SetFocus();
//		}
//	}

	pnlPnuList->Visible = _bVisible;
}
