void __fastcall TfrmMain::funcSetMainViewBar()//IMGMODECHANGEClick
{
//200305//여기서 말고 필요한 곳에서 각자 호출한다// 문서<->지적도로 움직이는 경우도 있어 무조건 초기화하면 안됨//
//	funcClosePanel();
//	funcInitPBControl2();//init pbRect
//	funcInitThumb();//200228
//	funcSetLabelMapPoint(false);//200228
//	funcInitToOpenFile();//200228//

	bool _bDocVisible = (_CURRENT_WORKMODE == "DOCUMENT") ? (true):(false);

	//=============================================
	//241205//우측 상단 [문서]-[지적도] 이미지 표시 설정//
	//=============================================
	funcSetImageModeChange(_bDocVisible);
	pnlImgDocView->Visible	= _bDocVisible;

	if(_CURRENT_WORKMODE != "DOCUMENT")//지적도
	{
		//===========================================
		funcInitDoc08Bar(false);//funcSetMainViewBar
		funcSetDocumentView(false, /*false, */false, false);//funcSetMainViewBar//모드변경(지적도<->문서뷰)//
		//===========================================
		funcSetPreview(false);
		funcSetLMFSButton(false);//LMFS_메뉴버튼 비활성화//

		//_SELECTREALLANDCD
		if(IMGSCREEN1->Visible == false) IMGSCREEN1->Visible = true;
		func_DrawImagePaint();

		if(currentModeShow8 == true){
			if(StatusBar1->Panels->Items[5]->Text == "")	funcSetStatusBarMsg(5, "본지도는 열람조회용으로 제공하는 것으로 실제 이용현황과 다를 수 있습니다. 참고바랍니다.");
		}
		else{
			if(StatusBar1->Panels->Items[5]->Text != "")	funcSetStatusBarMsg(5, "");
		}
	}
	else//문서뷰//_CURRENT_WORKMODE == "DOCUMENT"//
    {
		if(_CURRENT_COMWORKMODE == "메모등록")
		{
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGMEMOPOINT, false, false);
			//=============================================

			_CURRENT_COMWORKMODE	= "";
			m_eManipulationMode    	= Panning;
			ICONMEMOPOINT->Visible = false;
			MEMOPOINTHELP->Visible = false;
			m_vMEMORECT.clear();
		}

		if(_CURRENT_COMWORKMODE == "영역등록")
		{
			//=============================================
			//241205//[레이어] 이미지 표시 설정//
			//=============================================
			funcSetImageLayer(IMGMEMOPOLY, false, false);
			//=============================================

			_CURRENT_COMWORKMODE	= "";
			m_eManipulationMode    	= Panning;
			ICONMEMOPOLY->Visible = false;
			MEMOPOLYHELP->Visible = false;
		}

		funcSetStatusBarMsg(3, "");

		if(IMGSCREEN2->Picture->Bitmap == NULL || IMGSCREEN2->Picture->Bitmap->Width == 0)//띄워진 문서 없음//
		{
			funcSetDocumentView(false, /*false, */false, true);//funcSetMainViewBar//띄워진 문서없음//
		}
		else//띄워진 문서 있음//
		{
			m_bVisiblePrevNextBar = (m_nFTPPathIndex > -1) ? (true):(false);
			funcSetDocumentView(true, /*m_bVisibleDoc08Bar, */m_bVisiblePrevNextBar, false);//funcSetMainViewBar//띄워진 문서없음//
			//=============================================
			if(m_nViewDocNo == 8)//문서열람 > 지적도 > 다시 문서 클릭하면 구대장한글화 관련 버튼이 보이지 않아 처리//
			{
				funcProcessDoc8OwnNames((char*)m_ResultDocument08[0].PATH_NAME);//#OWNINFO#
			}
			//=============================================
		}

		if(m_nThumbCount > 0)
		{
			funcSetPreview(true);
		}
		//===========================================
		funcSetDocControlBar();//funcSetMainViewBar

		if(m_nViewDocNo == 2 || m_nViewDocNo == 7)//문서=측량결과도, 지적도 아니면 면적/거리 제한//
		{
			palSpatialControlBar->Left		= palZoomControlBar->Left;
			palSpatialControlBar->Visible 	= true;
		}
	}

	IMGDOCTIP32->Visible	= false;
	IMGCOMTIP32->Visible 	= false;
	palMode->BringToFront();
}
