void __fastcall TfrmMain::funcInitSpatialControlBar()
{
	if(palSpatialControlBar->Visible)
	{
		if(_CURRENT_WORKMODE == "SPATIAL"){
			//면적재기, 거리재기 취소 호출
			m_vAREA.clear();
			m_vREALAREA.clear();

			m_vDIST.clear();
			m_vREALDIST.clear();

			if(PBCONTROL1->Visible) PBCONTROL1->Visible = false;//200227
			m_eManipulationMode = Panning;
			m_bControlFlags     = false;
			func_DrawImagePaint();

	//			if(mToolButtonState == DF_SPACERECT)//M
	//			{
	//				funcActDeactPaintBox(0, false);
	//				mToolButtonState = DF_PANNING;
	//			}
		}
		//M
		else if(_CURRENT_WORKMODE == "DOCUMENT"){
			if(_CURRENT_COMWORKMODE == "면적재기")
				funcControlArea();
			else if(_CURRENT_COMWORKMODE == "거리재기")
				funcControlDist();

			_CURRENT_COMWORKMODE = "";

			funcInitPBControl2();//init pbRect
		}

		_CURRENT_COMWORKMODE	= "";//191212

		Application->ProcessMessages();

		funcFreeEachButtonImage(IMGSPATIALCONTROLCANCEL);
	}
}
