void __fastcall TfrmMain::funcSelectSGPnuList(int _nIndex)
{
	if(palWait->Visible || m_bSearching)//200302
		return;

	m_bStopSearch = true;//200326

	//210308//#ADDRESS_DUP//
//	AnsiString _SELECTREALLANDCD = sgPnuList->Cells[1][_nIndex];//(char*)m_vSearchPnuList[_nIndex].LAND_KEY;
//	m_asSearchText = func_ConvertLandcdToAddress(_SELECTREALLANDCD);
	//210308//#ADDRESS_DUP//
	m_asSearchPnu 	= sgPnuList->Cells[1][_nIndex];
	m_asSearchText 	= sgPnuList->Cells[0][_nIndex];

	if( !m_asSearchText.IsEmpty() )
	{
		edtMainSearchText->Font->Color = clBlack;//200227
		edtMiniSearchText->Font->Color = clBlack;//200227
		edtMainSearchText->Text = m_asSearchText;
		edtMiniSearchText->Text = m_asSearchText;

		if(palMiniSearchBar->Visible)
		{
			edtMiniSearchText->SetFocus();
			edtMiniSearchText->SelStart	= edtMiniSearchText->Text.Length();
		}
		else if(palMainSearchBar->Visible)
		{
			edtMainSearchText->SetFocus();
			edtMainSearchText->SelStart	= edtMainSearchText->Text.Length();
		}

		funcSetPnlPnuList( false );
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::sgPnuListKeyPress(TObject *Sender, wchar_t &Key)
{
	if(Key == VK_RETURN)
	{
		funcSelectSGPnuList(sgPnuList->Row);
	}
	else if(Key == VK_DOWN && sgPnuList->Row == sgPnuList->RowCount - 1)
	{
		if(sgPnuHist->Visible && sgPnuList->RowCount > 1)
			sgPnuHist->Row = 1;
    }
}
