void __fastcall TfrmMain::IMGPOIMouseEnter(TObject *Sender)
{
	int left, top;
	IMGCOMTIP32->Bitmap         = NULL;
	IMGCOMTIP32->Bitmap->Assign(BITMAP_BTN_HELP[TipPoi]);

	IMGCOMTIP32->Width	= IMGCOMTIP32->Bitmap->Width;
	IMGCOMTIP32->Height	= IMGCOMTIP32->Bitmap->Height;
	left   = palPoi->Left - IMGCOMTIP32->Width;
	top    = palPoi->Top  + IMGPOI->Top + (IMGPOI->Height - IMGCOMTIP32->Height) / 2;
	IMGCOMTIP32->Left 		= left - 4;
	IMGCOMTIP32->Top  		= top;
	IMGCOMTIP32->Visible 	= true;
	IMGCOMTIP32->BringToFront();
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::IMGTIPMouseLeave(TObject *Sender)
{
	IMGCOMTIP32->Bitmap  = NULL;
	IMGCOMTIP32->Visible = false;
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::pnlSearchListClick(TObject *Sender)
{
	funcSetPnlPnuList( false );
}
