//===========================================================================
// 토지대장_주민번호삭제 영역정보 갖고 있는지 확인//#JUMINHIDE#
//===========================================================================
void __fastcall TfrmMain::funcDrawRectangleLayer1_8()
{
	PBCONTROL2->Canvas->Lock();

	HPEN pen1   = ::CreatePen(PS_SOLID, 2, 0x000000ff);
	::SelectObject(PBCONTROL2->Canvas->Handle, pen1);

	PBCONTROL2->Canvas->Brush->Style = bsClear;

	if(mRactStateLayer1_8[0].bRactCalcFlag)
	{
		if (m_vRECT.size() > 0)
		{
			TPoint	_tPoint;
			GPoint	_gPoint;
			int 	nLeft = 0;
			int 	nTop = 0;
			int 	nRight = 0;
	        int 	nBottom = 0;

			for (int i=0; i<(int)m_vRECT.size(); i++)
			{
				_gPoint.x	= m_vRECT[i].rImage.left;
				_gPoint.y	= m_vRECT[i].rImage.top;
				_tPoint	= eFunc->funcSurveyMapToDevice(_gPoint);
				nLeft	= _tPoint.x;
				nTop	= _tPoint.y;

				_gPoint.x	= m_vRECT[i].rImage.right;
				_gPoint.y	= m_vRECT[i].rImage.bottom;
				_tPoint	= eFunc->funcSurveyMapToDevice(_gPoint);
				nRight	= _tPoint.x;
				nBottom	= _tPoint.y;

				PBCONTROL2->Canvas->Rectangle(nLeft, nTop, nRight, nBottom);
			}
		}
	}

	::DeleteObject(pen1);
	PBCONTROL2->Canvas->Unlock();
}
//---------------------------------------------------------------------------

//DB에 JUMIN_XY 값이 없는 경우 사용자 선택으로 그릴 때//
void __fastcall TfrmMain::funcSet_mRactStateLayer1_8Redraw()
{
	GPoint _gPoint;

	mDoc8Rect.nLeft 		= IMGSCREEN2->Width  * m_dStartRateX;
	mDoc8Rect.nTop	 		= IMGSCREEN2->Height * m_dStartRateY;
	mDoc8Rect.nWidth 		= StrToInt(edtDoc8W->Text);
	mDoc8Rect.nHeight 		= StrToInt(edtDoc8H->Text);
	mDoc8Rect.nGapHeight 	= StrToInt(edtDoc8G->Text);
	mDoc8Rect.nCount 		= StrToInt(edtDoc8C->Text);

	for(int i = 1; i < mDoc8Rect.nCount + 1; i++)
	{
		mRactStateLayer1_8[i].tpRactStartPoint.x = mDoc8Rect.nLeft;
		mRactStateLayer1_8[i].tpRactStartPoint.y = mDoc8Rect.nTop + mDoc8Rect.nGapHeight * (i - 1);
		mRactStateLayer1_8[i].tpRactEndPoint.x   = mRactStateLayer1_8[i].tpRactStartPoint.x + mDoc8Rect.nWidth  / m_dDocFactor;
		mRactStateLayer1_8[i].tpRactEndPoint.y   = mRactStateLayer1_8[i].tpRactStartPoint.y + mDoc8Rect.nHeight / m_dDocFactor;
		mRactState.tpRactStartPoint = mRactStateLayer1_8[i].tpRactStartPoint;
		mRactState.tpRactEndPoint   = mRactStateLayer1_8[i].tpRactEndPoint;

		mToolButtonState = DF_RECTANGLE;

		_gPoint	= eFunc->funcDeviceToSurveyMap(mRactState.tpRactStartPoint);
		tempRECT.rImage.left    = _gPoint.x;
		tempRECT.rImage.top     = _gPoint.y;
		_gPoint	= eFunc->funcDeviceToSurveyMap(mRactState.tpRactEndPoint);
		tempRECT.rImage.right   = _gPoint.x;
		tempRECT.rImage.bottom  = _gPoint.y;
		tempRECT.option  = true;  //기존 정보인지 추가 정보인지를 구분하는 옵션값..true이면 추가정보, 저장시 적용됨.

		m_vRECT.push_back(tempRECT);
	}

	nMoveStatus = 1;
	PBCONTROL2->Invalidate();

	//200319//mRactStateLayer1_8[0].bRactCalcFlag 	 = true;
	m_bJuminRactCalcFlag = true;

	//===============================================
	if(m_vRECT.size() > 0)
	{
		funcFreeEachButtonImage(IMGDOCRECTCLEAR);
		IMGDOCRECTCLEAR->Picture->Bitmap->Assign(BITMAP_BTN_DOC[RectClear]);
		_CURRENT_DOCWORKMODE = "영역선택";
	}
}
