//DB에 JUMIN_XY 값이 있는 경우//
void __fastcall TfrmMain::funcSet_mRactStateLayer1_8DB(AnsiString _asJuminXY)
{
	int nXYSetLen 	= 16;//length of (left + top + right + bottom)
	int nDataLen 	= 4;//length of left, top, right, bottom
	int nLength 	= _asJuminXY.Length();
	int nCount  	= nLength / nXYSetLen;
	int nIndex 		= 0;

	for(int i = 0; i < nCount; i++)
	{
		mRactStateLayer1_8Data[nIndex].left 	= StrToInt(_asJuminXY.SubString( (i * nXYSetLen + 1), nDataLen));
		mRactStateLayer1_8Data[nIndex].top 		= StrToInt(_asJuminXY.SubString( (i * nXYSetLen + 1 + nDataLen * 1), nDataLen));
		mRactStateLayer1_8Data[nIndex].right 	= StrToInt(_asJuminXY.SubString( (i * nXYSetLen + 1 + nDataLen * 2), nDataLen));
		mRactStateLayer1_8Data[nIndex].bottom 	= StrToInt(_asJuminXY.SubString( (i * nXYSetLen + 1 + nDataLen * 3), nDataLen));
		nIndex++;
	}

	GPoint _gPoint;

	for(int j = 1; j < nCount + 1; j++)
	{
		mRactStateLayer1_8[j].tpRactStartPoint.x = (int)((double)mRactStateLayer1_8Data[j-1].left   * (double)m_dDocFactor);
		mRactStateLayer1_8[j].tpRactStartPoint.y = (int)((double)mRactStateLayer1_8Data[j-1].top 	  * (double)m_dDocFactor);
		mRactStateLayer1_8[j].tpRactEndPoint.x   = (int)((double)mRactStateLayer1_8Data[j-1].right  * (double)m_dDocFactor);
		mRactStateLayer1_8[j].tpRactEndPoint.y   = (int)((double)mRactStateLayer1_8Data[j-1].bottom * (double)m_dDocFactor);
		mRactState.tpRactStartPoint = mRactStateLayer1_8[j].tpRactStartPoint;
		mRactState.tpRactEndPoint   = mRactStateLayer1_8[j].tpRactEndPoint;

		mToolButtonState = DF_RECTANGLE;

		PBCONTROL2->Invalidate();

		_gPoint	= eFunc->funcDeviceToSurveyMap(mRactState.tpRactStartPoint);
		tempRECT.rImage.left    = _gPoint.x;
		tempRECT.rImage.top     = _gPoint.y;
		_gPoint	= eFunc->funcDeviceToSurveyMap(mRactState.tpRactEndPoint);
		tempRECT.rImage.right   = _gPoint.x;
		tempRECT.rImage.bottom  = _gPoint.y;
		tempRECT.option  = true;  //기존 정보인지 추가 정보인지를 구분하는 옵션값..true이면 추가정보, 저장시 적용됨.

		m_vRECT.push_back(tempRECT);
	}

	//200319//mRactStateLayer1_8[0].bRactCalcFlag 	 = true;
	m_bJuminRactCalcFlag = true;

	//===============================================
	if(m_vRECT.size() > 0)//200318//
	{
		funcFreeEachButtonImage(IMGDOCRECTCLEAR);
		IMGDOCRECTCLEAR->Picture->Bitmap->Assign(BITMAP_BTN_DOC[RectClear]);
		_CURRENT_DOCWORKMODE = "영역선택";
	}
}
