AnsiString __fastcall TfrmMain::funcSetDoc8JuminXY()
{
	int nLeft 	= 0;
	int nTop 	= 0;
	int nRight 	= 0;
	int nBottom = 0;
	AnsiString asDBStr = "";

	for(int i=0; i<(int)m_vRECT.size(); i++){
		AnsiString asStr = "";
		nLeft   = (int)m_vRECT[i].rImage.left;
		nTop    = (int)m_vRECT[i].rImage.top;
		nRight  = (int)m_vRECT[i].rImage.right;
		nBottom = (int)m_vRECT[i].rImage.bottom;
		asStr.sprintf("%04d%04d%04d%04d", nLeft, nTop, nRight, nBottom);
		asDBStr += asStr;
	}

	return asDBStr;
}
