void __fastcall TfrmMain::edtDoc8_OnExit(TObject *Sender)
{
	if( Sender == edtDoc8C)
	{
		int nLen = edtDoc8C->Text.Trim().Length();
		if(nLen == 0)	goto msg;
	}
	else if( Sender == edtDoc8W)
	{
		int nLen = edtDoc8W->Text.Trim().Length();
		if(nLen == 0)	goto msg;
	}
	else if( Sender == edtDoc8H)
	{
		int nLen = edtDoc8H->Text.Trim().Length();
		if(nLen == 0)	goto msg;
	}
	else if( Sender == edtDoc8G)
	{
		int nLen = edtDoc8G->Text.Trim().Length();
		if(nLen == 0)	goto msg;
	}

	return;

msg:
	frmMsg->funcMessageDlg("입력확인:", "값을 입력해주세요.", 3);
	return;
}
