void __fastcall TfrmMain::funcReadInfoFileJGW(int _nScale, AnsiString _asFileName)
{
	FILE *fp_stdin;
	FILE *fp_out;
	char buf_in[255];
	int nIndex = 0;
	biXPelsPerMeterJGW = 0.0;
	biYPelsPerMeterJGW = 0.0;

	if(FileExists(_asFileName))
	{
		fp_stdin = fopen(_asFileName.c_str(),"rb");
		while(fgets(buf_in, sizeof(buf_in), fp_stdin) != NULL)
		{
			AnsiString asStr = buf_in;
			asStr = asStr.Trim();
			int pos = asStr.Pos("\n");
			if (pos > 0) {
				asStr = asStr.SubString(1, pos-1);
			}

			if(asStr.Length() > 0)
			{
				if( StrToFloat(asStr) != 0.0 )
				{
					if(nIndex == 0)
						biXPelsPerMeterJGW = (LONG)((double)_nScale / (double)StrToFloat(asStr));
					else if(nIndex == 3)
						biYPelsPerMeterJGW = (LONG)(fabs((double)_nScale / (double)StrToFloat(asStr)));
				}
			}
			nIndex++;
		}
	}

	fclose(fp_stdin);
}
