void __fastcall TfrmMain::btnQueryDoc07JibunClick(TObject *Sender)
{
	AnsiString asPnu 	= "";
	AnsiString asGbn 	= "";
	AnsiString asBobn 	= "";
	AnsiString asBubn 	= "";

	if(m_asSearchPnu.Length() == 19)
	{
		asGbn 	= (cboDoc07Gbn->ItemIndex == 0) ? (1) : (2);
		asBobn 	= edtDoc07Bobn->Text;
		if(asBobn.IsEmpty())	asBobn = "0";
		asBubn 	= edtDoc07Bubn->Text;
		if(asBubn.IsEmpty())	asBubn = "0";

		asPnu.sprintf("%s%s%04d%04d", m_asSearchPnu.SubString(1, 10), asGbn, asBobn.ToInt(), asBubn.ToInt());

		frmMain->m_vLANDINFO_SUB.clear();
		frmMain->m_ResultDocument07_SUB.clear();

		frmSql->funcQrySelect_LAND_INFO_MAPPOINT(true, asPnu);

		frmSearch->m_bDoc07Check     = false;
		frmSearch->m_sDoc07DohoCheck = "";

		//201227//
		//===================================================================
		if((int)frmMain->m_vLANDINFO_SUB.size() > 0)
		{
			frmSql->funcQrySelect_DOCUMENT07_MAPPOINT(true, 0, "");//데이터 있으면 tree 구성 함수 안에서 처리한다//v1.0.0.5//DOC07_JIBUN_DISPLAY_FOR_SEJONG(Old LAND_CD)//
		}

		//201217//태안//
		//DOC07도곽좌표 없고, DOC07_PNU이미지 좌표만 있다면//
		//shape에 없는 좌표는 검색되지만, shape에 없는 좌표는 검색되지 않는다//
		if(frmMain->m_ResultDocument07_SUB.size() == 0)
		{
			frmSql->funcQrySelect_DOCUMENT07_PNU(true, asPnu);
		}

		funcCalcWorldToMap(true);//DB value : 지번표시
		if(currMapPoint.POS_X > 0 && currMapPoint.POS_Y > 0)
		{
			if(m_bOtherJibun)
			{
				lblMapPoint->Caption = "인근지번";
				lblMapPoint->Width = 52;
			}
			else
			{
				lblMapPoint->Caption = eFunc->funcPnuToBonbuName(asPnu.c_str(), 0);
				//lblMapPoint->Width = lblMapPoint->Caption.Length() * lblMapPoint->Font->Size;//200227//frmIniControl->mUserSetIniInfo.ulDoc0_V5_1);
				//lblMapPoint->Width = lblMapPoint->Width * lblMapPoint->Font->Size;//200227//frmIniControl->mUserSetIniInfo.ulDoc0_V5_1);
			}

			shpMapPoint->Width = lblMapPoint->Width + imgMapPointClose->Width + 4;//200227

			if(m_vLANDINFO_SUB.size() == 0 && m_ResultDocument07_SUB[0].REMARK == 2)
			{
				lblMapPoint->Font->Color 	= clRed;
				shpMapPoint->Pen->Color 	= clRed;
			}
			else
			{
				lblMapPoint->Font->Color 	= clBlue;
				shpMapPoint->Pen->Color 	= clBlue;
			}

			funcSetLabelMapPoint(true);
			funcRedrawMapPoint();
		}
		else
		{
			funcSetLabelMapPoint(false);
		}
	}
}
