void __fastcall TfrmMain::pnlDoc07JibunKeyPress(TObject *Sender, wchar_t &Key)
{
	if(Key == VK_RETURN)
	{
		if(Sender == cboDoc07Gbn)
			edtDoc07Bobn->SetFocus();
		else if(Sender == edtDoc07Bobn)
		{
			if(edtDoc07Bobn->Text.Trim().Length() == 0)
			{
				frmMsg->funcMessageDlg("입력확인:","본번을 입력해주세요.",3);
				edtDoc07Bobn->SetFocus();
				return;
			}
			edtDoc07Bubn->SetFocus();
		}
		else if(Sender == edtDoc07Bubn)
		{
			if(edtDoc07Bubn->Text.Trim().Length() == 0)
				edtDoc07Bubn->Text = "0";

			btnQueryDoc07JibunClick(NULL);
		}
	}
}
