void __fastcall TfrmMain::PBCONTROL2DbLClick(TObject *Sender)
{
	if(mToolButtonState == DF_AREAGAUGE && m_bControlFlags)
	{
		int size = m_vAREA2.size();
		if(size >= 3){
			for(int i=0; i<size; i++)
			{
				memset(&tempREALAREA, 0x00, sizeof(REALAREA_STRUCT));

				if(i==0) tempREALAREA.gbn = 1;
				else if(i == size-1)
				{
					tempREALAREA.gbn = 3;
					tempREALAREA.labelx = m_vAREA2[i].x;
					tempREALAREA.labely = m_vAREA2[i].y;
					tempREALAREA.area = func_DrawAreaValue2();
				}
				else tempREALAREA.gbn = 2;
				tempREALAREA.x    = m_vAREA2[i].x;
				tempREALAREA.y    = m_vAREA2[i].y;
				m_vREALAREA2.push_back(tempREALAREA);

				if(tempREALAREA.gbn == 3)
				{
					TPoint _tPoint;
					GPoint _gPoint;

					_gPoint.x 	= tempREALAREA.x;
					_gPoint.y 	= tempREALAREA.y;
					_tPoint	= eFunc->funcSurveyMapToDevice(_gPoint);
				}
			}
		}
		m_vAREA2.clear();

		PBCONTROL2->Cursor	= crDefault;//200227
		m_bControlFlags   	= false;
		pbControl2DblClick 	= true;
		PBCONTROL2->Invalidate();

		//191212//mToolButtonState = Panning;//M//191031
	}
	else if(mToolButtonState == DF_STREETGAUGE )
	{
		int size = m_vDIST2.size();
		if(size >= 2)
		{
			for(int i=0; i<size; i++)
			{
				memset(&tempREALDIST, 0x00, sizeof(REALDIST_STRUCT));

				if(i==0)             tempREALDIST.gbn = 1; //시작점
				else if(i == size-1) tempREALDIST.gbn = 3; //끝점
				else                 tempREALDIST.gbn = 2; //중간점

				tempREALDIST.x      = m_vDIST2[i].x;
				tempREALDIST.y      = m_vDIST2[i].y;
				tempREALDIST.labelx = m_vDIST2[i].x;
				tempREALDIST.labely = m_vDIST2[i].y;
				tempREALDIST.dist   = m_vDIST2[i].dist;
				m_vREALDIST2.push_back(tempREALDIST);

				if(tempREALDIST.gbn == 3)
				{
					TPoint _tPoint;
					GPoint _gPoint;

					_gPoint.x 	= tempREALDIST.x;
					_gPoint.y 	= tempREALDIST.y;
					_tPoint	= eFunc->funcSurveyMapToDevice(_gPoint);
				}
			}
		}
		m_vDIST2.clear();

		PBCONTROL2->Cursor	= crDefault;//200227
		m_bControlFlags    	= false;
		pbControl2DblClick 	= true;
		PBCONTROL2->Invalidate();

		//191212//mToolButtonState = Panning;
	}
}
