				m_font   = ::CreateFont(fontwidth, 0, 0, 0, 0, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔고딕" );
				hOldFont = (HFONT)::SelectObject(PBCONTROL2->Canvas->Handle,m_font);
//201119//측정(면적거리) Label Size, Color//
				::SetBkMode(PBCONTROL2->Canvas->Handle,TRANSPARENT);
//				::SetTextAlign(PBCONTROL2->Canvas->Handle,0|0);
