int __fastcall TfrmMain::func_FindFirst2MinDistanceIndex(vector<GPoint>& _vPoint, GPoint _GPoint)
{
	int index = -1;
	int i;
	int size = _vPoint.size();

	double x1, y1, x2, y2;
	double x, y;

	double dist  = -1;
	double dist1 = 0;

	x = _GPoint.x;
	y = _GPoint.y;
	for (int i = 0; i < size-1; i++) {
		x1    = _vPoint[i].x;
		y1    = _vPoint[i].y;

		if(i == size-1){
			x2    = _vPoint[i+1].x;
			y2    = _vPoint[i+1].y;
		}
		else{
			x2    = _vPoint[0].x;
			y2    = _vPoint[0].y;
		}
		x1 = x1 + (x1-x2)/2;
		y1 = y1 + (y1-y2)/2;

		dist1 = sqrt(pow(x-x1, 2) + pow(y-y1, 2));

		if(dist == -1 || dist1 < dist){
			dist  = dist1;
			index = i;
		}
	}

	return index;
}
//---------------------------------------------------------------------------

int __fastcall TfrmMain::func_FindSecond2MinDistanceIndex(vector<GPoint>& _vPoint, GPoint _GPoint, int _findex)
{
	int index = -1;
	int i;
	int size = _vPoint.size();

	double x1, y1, x2, y2;
	double x, y;
	double dist  = -1;
	double dist1 = 0;

	x = _GPoint.x;
	y = _GPoint.y;

	for (int i = 0; i < size-1; i++) {
		if(i != _findex){
			x1    = _vPoint[i].x;
			y1    = _vPoint[i].y;

			if(i == size-1){
				x2    = _vPoint[i+1].x;
				y2    = _vPoint[i+1].y;
			}
			else{
				x2    = _vPoint[0].x;
				y2    = _vPoint[0].y;
			}
			x1 = x1 + (x1-x2)/2;
			y1 = y1 + (y1-y2)/2;

			dist1 = sqrt(pow(x-x1, 2) + pow(y-y1, 2));

			if(dist == -1 || dist1 < dist){
				dist  = dist1;
				index = i;
			}
		}
	}

	return index;
}
