void __fastcall TfrmMain::funcFastReportOpen(char *_cParameters, int _nType)
{
	AnsiString asExecFile;
	asExecFile = frmMain->ROOTPATH + "GroupPrint.exe";

	int nDoc = frmMain->m_nViewDocNo;

//230207//funcSetUserHistState()Param변경//
//	AnsiString asKindCode = eFunc->funcGetKindNameToKindCode(503, "인쇄");//210305//#44710//4
//	if( !asKindCode.IsEmpty() )
//		frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, asKindCode.ToInt(), nDoc);
	frmUserManagement->funcSetUserHistState(&frmUserManagement->mCurrentUser, "인쇄", nDoc);

	SHELLEXECUTEINFO ExVal;
	ExVal.cbSize       = sizeof(SHELLEXECUTEINFO);
	ExVal.fMask        = NULL;
	ExVal.hwnd         = NULL;
	ExVal.lpVerb       = NULL;
	ExVal.lpFile       = asExecFile.c_str();

	ExVal.lpParameters = _cParameters;
	ExVal.lpDirectory  = "";
	ExVal.nShow        = SW_SHOW;
	ExVal.hInstApp     = NULL;
	ShellExecuteEx(&ExVal);
}
