void __fastcall TfrmMain::btnPreviewActClick(TObject *Sender)
{
	if(btnPreviewAct->Caption == "그룹 인쇄")
	{
		if(!pnlPrinterList->Visible)
		{
			funcGetPrinterList();//프린터 목록 가져오기
			if(m_sPrinterList->Count == 0)
			{
				frmMsg->funcMessageDlg("프린터기 확인", "연결된 프린터기가 없습니다. 확인해주세요.", 3);
				return;
			}

			pnlPrinterList->Visible	= true;
		}
	}
	else if(btnPreviewAct->Caption == "그룹 저장")
	{
		mnuLeftGroupSaveClick(NULL);
	}

	//210104//
	m_nDownloadCnt	= 0;
	mnuLeftGroupPrint->Enabled	= true;
	mnuLeftGroupSave->Enabled	= true;
}
