void __fastcall TfrmMain::cboGbnKeyPress(TObject *Sender, wchar_t &Key)
{
	if(Key == VK_RETURN)
	{
		if(edtBobn->Enabled)
			edtBobn->SetFocus();
	}
	else
	{
		if(Key == 49)//Number 1
			cboGbn->ItemIndex = 0;
		else if(Key == 50)//Number 2
			cboGbn->ItemIndex = 1;
	}
}
