void __fastcall TfrmMain::bsAdjustLastChange(TObject *Sender)
{
	if( !bsAdjust1->Enabled || !bsAdjust2->Enabled || !bsAdjust3->Enabled )
		return;

	if( m_bAdjustReject )
		return;

	int nTag = dynamic_cast<TbsSkinTrackBar *>(Sender)->Tag;

	if(nTag == 1 && bsAdjust1->Value == m_nAdjustValue1)
		return;
	else if(nTag == 2 && bsAdjust2->Value == m_nAdjustValue2)
		return;
	else if(nTag == 3 && bsAdjust3->Value == m_nAdjustValue3)
		return;

	funcProcessAdjustBar(nTag);
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::bsAdjustMouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
//
}
