void __fastcall TfrmMain::bsAdjust1MouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift, int X, int Y)
{
	if( !bsAdjust1->Enabled || !bsAdjust2->Enabled || !bsAdjust3->Enabled )
		return;

	if( m_bAdjustReject )
		return;

	int nTag = dynamic_cast<TbsSkinTrackBar *>(Sender)->Tag;

	if(nTag == 1)
		bsAdjust1->Value 	= /*bsAdjust1->MaxValue - */((X + 4) / ((bsAdjust1->Width - 8) / (bsAdjust1->MaxValue)));
	else if(nTag == 2)
		bsAdjust2->Value 	= /*bsAdjust2->MaxValue - */((X + 4) / ((bsAdjust2->Width - 8) / (bsAdjust2->MaxValue)));
	else if(nTag == 3)
		bsAdjust3->Value 	= /*bsAdjust3->MaxValue - */((X + 4) / ((bsAdjust3->Width - 8) / (bsAdjust3->MaxValue)));

	funcProcessAdjustBar(nTag);
}
