//210208//#IMGMODE//비암호화 문서를 암호화/복호화/업로드 기능//
//***************************************************************************
//
// 비암호화 문서 암호화/복호화/업로드 기능//
//
//***************************************************************************
int __fastcall TfrmMain::funcGetFileBuffer(bool _bEncrypt)
{
	int nRet	= 0;
	int chunksize, datasize, pos;
	char* temp;

	//Init
	if(m_pImage != NULL)
	{
		memset(m_pImage, 0x00, m_lFileSize);
		delete m_pImage;
		m_pImage	= NULL;
	}

	if(FileExists(m_asEncLocalPathName))
	{
		FILE *fd;
		size_t nResult = 0;

		fd = fopen(m_asEncLocalPathName.c_str(),"rb");
		if (fd==NULL)
		{
			ShowMessage("fopen error");
			return -1;
		}

		//===============================
		// obtain file size:
		fseek (fd , 0 , SEEK_END);
		m_lFileSize = ftell (fd);
		rewind (fd);

		m_pImage = (char*)malloc(sizeof(char)*m_lFileSize);
		if(m_pImage == NULL)
		{
			ShowMessage("메모리 할당 에러");
			return -1;
		}
		memset(m_pImage, 0x00, m_lFileSize);

		nResult = fread(m_pImage, sizeof(char), m_lFileSize, fd);
		if((LONG)nResult != m_lFileSize)
		{
			ShowMessage("파일 읽기 오류");
			return -1;
		}

		fclose(fd);
		Application->ProcessMessages() ;
	}

	AnsiString  asFileExt	= ExtractFileExt(m_asEncLocalPathName);

	if(_bEncrypt)//비암호화 문서를 암호화 후 FTP Upload//
	{
		if(asFileExt.UpperCase() == ".JPG")
			nRet	= funcEncryptJpgDimensions();
		else if(asFileExt.UpperCase() == ".TIF")
			nRet	= funcEncryptTifDimensions();
		else if(asFileExt.UpperCase() == ".BMP")
			nRet	= funcEncryptBmpDimensions();
	}
	else//비암호화 문서였지만, 내부 모듈을 통해서 복호화//
	//외부 암호화모듈을 통해 암호화된 이미지 일수도 있음. 그러면 return -1;이 반환될 것임//
	{
		if(asFileExt.UpperCase() == ".JPG")
			nRet	= funcDecryptJpgDimensions();
		else if(asFileExt.UpperCase() == ".TIF")
			nRet	= funcDecryptTifDimensions();
		else if(asFileExt.UpperCase() == ".BMP")
			nRet	= funcDecryptBmpDimensions();
	}

	//Init
	if(m_pImage != NULL)
	{
		memset(m_pImage, 0x00, m_lFileSize);
		delete m_pImage;
		m_pImage	= NULL;
	}

	return nRet;
}
