//===========================================================================
//
//	JPEG
//
//===========================================================================
int __fastcall TfrmMain::funcEncryptJpgDimensions()
{
    int             nIndex;
	int             nStartOfFrame;
	int             nError = 0;
    bool            markerFound = false;
	unsigned char   ucWord0;
    unsigned char   ucWord1;
	LONG 			u32Xdensity;
	LONG		 	u32Ydensity;
	LONG		 	u32XdensityChg;
	LONG		 	u32YdensityChg;
	LONG		 	u32Width;
	LONG		 	u32Height;
	LONG		 	u32WidthChg;
	LONG		 	u32HeightChg;
	AnsiString      asMsg	= "";

	//===============================
	//First
	AnsiString  asEncHdrFirst	= func_Encoder("~!enc");//fiFlbmMA
	AnsiString  asEncData		= func_Encoder("en");//ZW4A
	char cEncHdrFirst[8+1];
	char cEncData[4+1];

	memset(cEncHdrFirst, 0x00, sizeof(cEncHdrFirst));
	memset(cEncData, 0x00, sizeof(cEncData));
	strcpy(cEncHdrFirst, asEncHdrFirst.c_str());
	strcpy(cEncData, asEncData.c_str());
	//===============================


	// verify START OF IMAGE marker = FF D8
	nIndex = 0;
	ucWord0 = m_pImage[nIndex];
	ucWord1 = m_pImage[nIndex+1];

//	ucWord0 = m_pImage[134];//28
//	ucWord1 = m_pImage[135];//29
//	ucWord0 = m_pImage[136];//29
//	ucWord1 = m_pImage[137];//FF


	// marker FF D8  starts a valid JPEG
    if ((ucWord0 == 0xFF)  && (ucWord1 == 0xD8))
    {
        // search for START OF FRAME 0  marker  FF C0
        for (nIndex = 2;
			(nIndex < (int)m_lFileSize-4);
             nIndex += 2)
        {
			ucWord0 = m_pImage[nIndex];
            ucWord1 = m_pImage[nIndex+1];

			//
			m_pImage[nIndex]	= ucWord1;
			m_pImage[nIndex+1]	= ucWord0;

			if (ucWord0 == 0xFF)
            {
				if (ucWord1 == 0xC0)
                {
                    markerFound = true;
                    nStartOfFrame = nIndex;
                }
            }
            if (ucWord1 == 0xFF)
			{
                ucWord0 = m_pImage[nIndex+2];
                if (ucWord0 == 0xC0)
				{
                    markerFound = true;
                    nStartOfFrame = nIndex+1;
                }
			}
		} // while

        if (markerFound)
        {
            nError  = NO_ERROR;

			//===============================
			//10자리를 변환하기 위함 (JFIF까지 10자리임)
			//HdrFirst FF D8 FF E0 00 10 4A 46 => fiFlbmMA
			for(int i = 0; i < (int)sizeof(cEncHdrFirst)-1; i++)
			{
				m_pImage[i]	= cEncHdrFirst[i];
			}
			m_pImage[8]	= 0xFF;
			m_pImage[9]	= 0xFF;

			//Data//FF C0
			for(int i = 0; i < (int)sizeof(cEncData)-1; i++)
			{
				m_pImage[nStartOfFrame + i]	= cEncData[i];
			}

			//Last//FF D9
			m_pImage[m_lFileSize-2]	= 0xFF;
			m_pImage[m_lFileSize-1]	= 0xFF;

			funcEncryptFile();
			//===============================

			asMsg	= "A valid JPEG image!!!";
        }
        else
        {
			// start of frame 0 not found
            nError = -2;
			asMsg	= "Not a valid JPEG image. START OF FRAME 0 marker FFC0 not found";
        }
	}
    else   // START OF IMAGE marker not found
    {
        nError = -1;
		asMsg	= "Not a valid JPEG image. START OF IMAGE marker FFD8 not found";
	}

	//ShowMessage(asMsg);
	return nError;
}
//---------------------------------------------------------------------------

//encrypt, en, 앞뒤 byte change
int __fastcall TfrmMain::funcDecryptJpgDimensions()
{

	int             nIndex;
    int             nStartOfFrame;
	int             nError = 0;
	bool            markerFound = false;
	unsigned char   ucWord0;
	unsigned char   ucWord1;
	unsigned char   ucWord2;
	AnsiString      asMsg	= "";

	//===============================
	//First
	AnsiString  asDecHdrFirst	= func_Decoder("fiFlbmMA");//~!enc
	AnsiString  asEncHdrFirst	= "";
	char cDecHdrFirst[8+1];

	memset(cDecHdrFirst, 0x00, sizeof(cDecHdrFirst));
	memcpy(cDecHdrFirst, m_pImage, sizeof(cDecHdrFirst)-1);
	asEncHdrFirst	= (char*)cDecHdrFirst;
	//===============================


	//===============================
	//10자리를 변환하기 위함 (JFIF까지 10자리임)
	//HdrFirst fiFlbmMA 0xFF FF => FF D8 FF E0 00 10 4A 46 49 46
	//fiFlbmMA 0xFF FF (10자리 만들기 위함)
	if(asDecHdrFirst == func_Decoder(asEncHdrFirst) && (unsigned char)m_pImage[sizeof(cDecHdrFirst)-1] == 0xFF && (unsigned char)m_pImage[sizeof(cDecHdrFirst)] == 0xFF)
	{
		//First
		m_pImage[0]	= 0xFF;
		m_pImage[1]	= 0xD8;
		m_pImage[2]	= 0xFF;
		m_pImage[3]	= 0xE0;
		m_pImage[4]	= 0x00;
		m_pImage[5]	= 0x10;
		m_pImage[6]	= 0x4A;
		m_pImage[7]	= 0x46;
		m_pImage[8]	= 0x49;
		m_pImage[9]	= 0x46;
		m_pImage[m_lFileSize-2]	= 0xFF;
		m_pImage[m_lFileSize-1]	= 0xD9;

		// search for START OF FRAME 0  marker  FF C0
		//앞뒤 byte change
		for (nIndex = 10; (nIndex < (int)m_lFileSize-4); nIndex += 2)
		{
			ucWord0 = m_pImage[nIndex];
			ucWord1 = m_pImage[nIndex+1];
			m_pImage[nIndex]	= ucWord1;
			m_pImage[nIndex+1]	= ucWord0;

			//search for START of 'ZW4A'
			if ((ucWord0 == 0x5A)  && (ucWord1 == 0x57))
			{
				ucWord0 = m_pImage[nIndex+2];
				ucWord1 = m_pImage[nIndex+3];
				if((ucWord0 == 0x34)  && (ucWord1 == 0x41))
				{
					markerFound = true;
					nStartOfFrame = nIndex;
					nIndex += 2;
				}
			}
			else if ((ucWord1 == 0x5A))
			{
				ucWord0 = m_pImage[nIndex+2];
				ucWord1 = m_pImage[nIndex+3];
				ucWord2 = m_pImage[nIndex+4];
				if((ucWord0 == 0x57) && (ucWord1 == 0x34) && (ucWord2 == 0x41))
				{
					markerFound = true;
					nStartOfFrame = nIndex+1;
					nIndex += 3;
				}
			}
		}

		if (markerFound)
		{
			m_pImage[nStartOfFrame]		= 0xFF;
			m_pImage[nStartOfFrame+1]	= 0xC0;
			m_pImage[nStartOfFrame+2]	= 0x00;
			m_pImage[nStartOfFrame+3]	= 0x11;
		}

		//Last//FF D9
		m_pImage[m_lFileSize-2]	= 0xFF;
		m_pImage[m_lFileSize-1]	= 0xD9;

		funcDecryptFile();
	}
	else
	{
		//ShowMessage("Not a valid Encrypt JPG image.");
		nError	= -1;
	}

	return nError;
}
//---------------------------------------------------------------------------



//===========================================================================
//
//	TIFF
//
//===========================================================================
int __fastcall TfrmMain::funcEncryptTifDimensions()
{
    int             nIndex;
	int             nStartOfFrame;
	int             nError = 0;
    bool            markerFound = false;
	unsigned char   ucWord0;
	unsigned char   ucWord1;
	unsigned char   ucWord2;
	unsigned char   ucWord3;
	AnsiString      asMsg	= "";

	//===============================
	//First
	AnsiString  asEncHdrFirst	= func_Encoder("en");//ZW4A
	char cEncHdrFirst[4+1];
	char cDataFst[128+1];
	char cDataSnd[128+1];

	memset(cEncHdrFirst, 0x00, sizeof(cEncHdrFirst));
	memset(cDataFst, 0x00, sizeof(cDataFst));
	memset(cDataSnd, 0x00, sizeof(cDataSnd));
	strcpy(cEncHdrFirst, asEncHdrFirst.c_str());
	//===============================


	// verify START OF IMAGE marker = FF D8
	nIndex = 0;
	ucWord0 = m_pImage[nIndex];
	ucWord1 = m_pImage[nIndex+1];
	ucWord2 = m_pImage[nIndex+2];
	ucWord3 = m_pImage[nIndex+3];

	// marker FF D8  starts a valid JPEG
	if ((ucWord0 == 0x49)  && (ucWord1 == 0x49) && (ucWord2 == 0x2A)  && (ucWord3 == 0x00))
	{
		//Start//49 49 2A 00 ==> ZW4A
		for(int i = 0; i < (int)sizeof(cEncHdrFirst)-1; i++)
		{
			m_pImage[i]	= cEncHdrFirst[i];
		}

		//128 bytes little endian
		for (nIndex = 0; nIndex < 256; nIndex++)
		{
			if( nIndex < 128 )
			{
				if( nIndex % 2 == 0)
					cDataSnd[nIndex+1]	= m_pImage[nIndex];
				else
					cDataSnd[nIndex-1]	= m_pImage[nIndex];
			}
			else
			{
				if( nIndex % 2 == 0)
					cDataFst[nIndex-128+1]	= m_pImage[nIndex];
				else
					cDataFst[nIndex-128-1]	= m_pImage[nIndex];
			}
		} // while

		memcpy(m_pImage, cDataFst, sizeof(cDataFst)-1);
		memcpy(&(m_pImage[sizeof(cDataFst)-1]), cDataSnd, sizeof(cDataSnd)-1);

		funcEncryptFile();
		//===============================

		asMsg	= "A valid TIFF image!!!";
	}
	else// START OF IMAGE marker not found
    {
        nError = -1;
		asMsg	= "Not a valid TIFF image. START OF IMAGE marker FFD8 not found";
	}

	//ShowMessage(asMsg);
	return nError;
}
//---------------------------------------------------------------------------
int __fastcall TfrmMain::funcDecryptTifDimensions()
{
    int             nIndex;
    int             nStartOfFrame;
	int             nError = 0;
    bool            markerFound = false;
	unsigned char   ucWord0;
	unsigned char   ucWord1;
	unsigned char   ucWord2;
	unsigned char   ucWord3;
	AnsiString      asMsg	= "";

	//===============================
	//First
	AnsiString  asEncHdrFirst	= func_Encoder("en");//ZW4A
	char cEncHdrFirst[4+1];
	char cDataFst[128+1];
	char cDataSnd[128+1];

	memset(cEncHdrFirst, 0x00, sizeof(cEncHdrFirst));
	memset(cDataFst, 0x00, sizeof(cDataFst));
	memset(cDataSnd, 0x00, sizeof(cDataSnd));
	strcpy(cEncHdrFirst, asEncHdrFirst.c_str());
	//===============================


	// verify START OF IMAGE marker = FF D8
	nIndex = 128;
	ucWord0 = m_pImage[nIndex];
	ucWord1 = m_pImage[nIndex+1];
	ucWord2 = m_pImage[nIndex+2];
	ucWord3 = m_pImage[nIndex+3];

	// marker FF D8  starts a valid JPEG
	if ((ucWord0 == 0x57)  && (ucWord1 == 0x5A) && (ucWord2 == 0x41)  && (ucWord3 == 0x34))
	{
		// search for START OF FRAME 0  marker  FF C0
		for (nIndex = 0; nIndex < 256; nIndex++)
		{
			if( nIndex < 128 )
			{
				if( nIndex % 2 == 0)
					cDataSnd[nIndex+1]	= m_pImage[nIndex];
				else
					cDataSnd[nIndex-1]	= m_pImage[nIndex];
			}
			else
			{
				if( nIndex % 2 == 0)
					cDataFst[nIndex-128+1]	= m_pImage[nIndex];
				else
					cDataFst[nIndex-128-1]	= m_pImage[nIndex];
			}
		} // while

		memcpy(m_pImage, cDataFst, sizeof(cDataFst)-1);
		memcpy(&(m_pImage[sizeof(cDataFst)-1]), cDataSnd, sizeof(cDataSnd)-1);

		m_pImage[0]	= 0x49;
		m_pImage[1]	= 0x49;
		m_pImage[2]	= 0x2A;
		m_pImage[3]	= 0x00;

		funcDecryptFile();
	}
	else
	{
		//ShowMessage("Not a valid Encrypt TIF image.");
		nError	= -1;
	}

	return nError;
}
