int __fastcall TfrmMain::funcDecryptBmpDimensions()
{
    int             nIndex;
    int             nStartOfFrame;
	int             nError = 0;
    bool            markerFound = false;
	unsigned char   ucWord0;
	unsigned char   ucWord1;
	unsigned char   ucWord2;
	unsigned char   ucWord3;
	AnsiString      asMsg	= "";

	//===============================
	//First
	AnsiString  asEncHdrFirst	= "BM";//func_Encoder("en");//ZW4A
	char cEncHdrFirst[2+1];
	char cDataFst[128+1];
	char cDataSnd[128+1];

	memset(cEncHdrFirst, 0x00, sizeof(cEncHdrFirst));
	memset(cDataFst, 0x00, sizeof(cDataFst));
	memset(cDataSnd, 0x00, sizeof(cDataSnd));
	strcpy(cEncHdrFirst, asEncHdrFirst.c_str());
	//===============================


	// verify START OF IMAGE marker = FF D8
	nIndex = 128;
	ucWord0 = m_pImage[nIndex];
	ucWord1 = m_pImage[nIndex+1];

	// marker FF D8  starts a valid JPEG
	if ((ucWord0 == 0x57)  && (ucWord1 == 0x5A))
	{
		// search for START OF FRAME 0  marker  FF C0
		for (nIndex = 0; nIndex < 256; nIndex++)
		{
			if( nIndex < 128 )
			{
				if( nIndex % 2 == 0)
					cDataSnd[nIndex+1]	= m_pImage[nIndex];
				else
					cDataSnd[nIndex-1]	= m_pImage[nIndex];
			}
			else
			{
				if( nIndex % 2 == 0)
					cDataFst[nIndex-128+1]	= m_pImage[nIndex];
				else
					cDataFst[nIndex-128-1]	= m_pImage[nIndex];
			}
		} // while

		memcpy(m_pImage, cDataFst, sizeof(cDataFst)-1);
		memcpy(&(m_pImage[sizeof(cDataFst)-1]), cDataSnd, sizeof(cDataSnd)-1);

		m_pImage[0]	= 0x42;
		m_pImage[1]	= 0x4D;

		funcDecryptFile();
	}
	else
	{
		//ShowMessage("Not a valid Encrypt BMP image.");
		nError	= -1;
	}

	return nError;
}
