void __fastcall TfrmMain::funcUploadFile(AnsiString _asFilePathEnc)
{
	FTP_FILE_STRUCT	mUploadFile;
	AnsiString asTarget 	= ExtractFilePath(m_asCurrentFilePath);

	asTarget	= StringReplace(asTarget, "\\", "/", TReplaceFlags() << rfReplaceAll);

	memset(&mUploadFile, 0x00, sizeof(mUploadFile));
	wsprintf(mUploadFile.cTarget, "%s", asTarget.c_str());
	wsprintf(mUploadFile.cLocalFilePath, "%s", _asFilePathEnc.c_str());//Local File Path
	_asFilePathEnc	= StringReplace(_asFilePathEnc, "_enc", "", TReplaceFlags() << rfReplaceAll);
	_asFilePathEnc	= ExtractFileName(_asFilePathEnc);
	wsprintf(mUploadFile.cFileName, "%s", _asFilePathEnc.c_str());//Local File Path
	wsprintf(mUploadFile.cFileType, "%s", _asFilePathEnc.SubString(_asFilePathEnc.Length() - 2, 3));

	if (!frmFtpControl->FuncFtpFileUpload(19, &mUploadFile, 0)) {
		return;
	}

	//FTP 사용 안함 이면 Local에 저장하므로 파일 삭제하면 안됨
	//if(FileExists(m_asSignPath))
	//	DeleteFile(m_asSignPath);
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::btnDownloadReasonSaveClick(TObject *Sender)
{
	if(edtDownloadReason->Text.Trim().IsEmpty())
	{
		frmMsg->funcMessageDlg("입력 확인:", "다운로드 사유를 입력해주세요.", 3);
		return;
	}

	funcSaveFile();
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::funcSetPnlDownloadReason(bool _bVisible)
{
	edtDownloadReason->Text	= "";

	pnlDownloadReason->Visible	= _bVisible;
	if(_bVisible)
	{
		pnlDownloadReason->Left		= (pnlImgDocView->Width - pnlDownloadReason->Width) / 2;
		pnlDownloadReason->Top		= (pnlImgDocView->Height - pnlDownloadReason->Height) / 2;
//		pnlDownloadReason->Left = EDGEGAP;
//		pnlDownloadReason->Top 	= palDocControlBar->Top + palDocControlBar->Height;
		edtDownloadReason->SetFocus();
	}
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::edtDownloadReasonExit(TObject *Sender)
{
	if(edtDownloadReason->Text.Trim().IsEmpty())
	{
		frmMsg->funcMessageDlg("입력 확인:", "다운로드 사유를 입력해주세요.", 3);
		return;
	}

	btnDownloadReasonSave->SetFocus();
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::edtDownloadReasonKeyPress(TObject *Sender, wchar_t &Key)
{
	if(Key == VK_RETURN)
	{
		if(Sender == edtDownloadReason)
		{
        	btnDownloadReasonSaveClick(btnDownloadReasonSave);
		}
		else if(Sender == btnDownloadReasonSave)
		{
			edtDownloadReasonExit(edtDownloadReason);
		}
	}
}
//---------------------------------------------------------------------------





