void __fastcall TfrmMain::func_DrawMentInfor()
{
	pbMentInfor->Canvas->Lock();

//	// ::AlphaBlend(pbMentInfor->Canvas->Handle, 8, 3 ,IMGMENTINFOR->Width, IMGMENTINFOR->Height ,IMGMENTINFOR->Canvas->Handle,0,0,IMGMENTINFOR->Width, IMGMENTINFOR->Height,bgltbf);
//	::AlphaBlend(pbMentInfor->Canvas->Handle, 0, 0, IMGMENTINFOR->Width, IMGMENTINFOR->Height, IMGMENTINFOR->Canvas->Handle, 0, 0, IMGMENTINFOR->Width, IMGMENTINFOR->Height, bgltbf);
	::AlphaBlend(pbMentInfor->Canvas->Handle, 0, 0, BITMAP_BTN_TGA[TgaStamp]->Width, BITMAP_BTN_TGA[TgaStamp]->Height, BITMAP_BTN_TGA[TgaStamp]->Canvas->Handle, 0, 0, BITMAP_BTN_TGA[TgaStamp]->Width, BITMAP_BTN_TGA[TgaStamp]->Height, frmMain->flagbf);

	HFONT m_font;
	// 12.01
	m_font = ::CreateFontA((20 * 1.0/*g_d720bby*/), 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔바른고딕");
	HFONT hOldFont = (HFONT)::SelectObject(pbMentInfor->Canvas->Handle, m_font);

	::SetBkMode(pbMentInfor->Canvas->Handle, TRANSPARENT);
	::SetTextColor(pbMentInfor->Canvas->Handle, (TColor)RGB(79, 191, 229));
	::SetTextAlign(pbMentInfor->Canvas->Handle, 0 | 0);

	// 검색지번
	// ::TextOut(pbMentInfor->Canvas->Handle,144 ,14,mentSearchJibun.c_str(),mentSearchJibun.Length());
	::TextOut(pbMentInfor->Canvas->Handle, (257 * 1.0/*g_d720bby*/), (14 * 1.0/*g_d720bby*/), m_asSearchText/*mentSearchJibun*/.c_str(), m_asSearchText/*mentSearchJibun*/.Length());
	// 새주소
	// ::TextOut(pbMentInfor->Canvas->Handle,144 ,37,mentSearchRoad.c_str(),mentSearchRoad.Length());
	::TextOut(pbMentInfor->Canvas->Handle, (257 * 1.0/*g_d720bby*/), (37 * 1.0/*g_d720bby*/), m_asSearchText/*mentSearchRoad*/.c_str(), m_asSearchText/*mentSearchRoad*/.Length());

	::SelectObject(pbMentInfor->Canvas->Handle, hOldFont);
	::DeleteObject(m_font);

	pbMentInfor->Canvas->Unlock();
}
// ---------------------------------------------------------------------------

void __fastcall TfrmMain::func_DrawWarningInfor()
{
	pbWarningInfor->Canvas->Lock();

	AnsiString ment = "본 도면은 열람조회용으로 제공하는 것으로 실제현황과 다를 수 있으므로 참고바립니다.";
	HFONT m_font;
	// 12.01
	m_font = ::CreateFontA((20 *  1.0/*g_d720bby*/), 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, "나눔바른고딕");
	HFONT hOldFont = (HFONT)::SelectObject(pbWarningInfor->Canvas->Handle, m_font);

	::SetBkMode(pbWarningInfor->Canvas->Handle, TRANSPARENT);
	//::SetTextColor(pbWarningInfor->Canvas->Handle, (TColor)RGB(79, 191, 229));
	::SetTextColor(pbWarningInfor->Canvas->Handle, (TColor)RGB(255, 255, 255));
	::SetTextAlign(pbWarningInfor->Canvas->Handle, 0 | 0);

	::TextOut(pbWarningInfor->Canvas->Handle, 0, 0,	ment.c_str(), ment.Length());

	::SelectObject(pbWarningInfor->Canvas->Handle, hOldFont);
	::DeleteObject(m_font);

	pbWarningInfor->Canvas->Unlock();
}
