//#OWNINFO#
void __fastcall TfrmMain::funcGetDoc8Ini()
{
	if (!FileExists(CONFIGDOC8INI->FileName))
	{
		String sMessage = L"구대장 한글화 표시 설정파일이 존재하지 않습니다.";
		if (Application->MessageBox(sMessage.c_str(), L"오류", MB_OK) == IDOK)
		{
//			Close();
//			return;
		}
	}

	//===========================================================================================
	//CONFIGDOC8INI에서 가져오면 글자가 깨진다//m_asFontName		= CONFIGDOC8INI->ReadString("FUNCTIONS", "FONT_NAME", "바탕체");
	m_asFontName	= CONFIGDOC8INI->ReadString("FUNCTIONS", "FONT_NAME", "굴림체");
	m_nBonbuType    = CONFIGDOC8INI->ReadInteger("FUNCTIONS", "BONBU_TYPE", 1);
	m_nAreaPoint    = CONFIGDOC8INI->ReadInteger("FUNCTIONS", "AREA_POINT", 0);//230213//지적숫자값 정수만 표시(0:Default), 1(소수1자리표시)//
	m_nSharpWidthPrint   	= CONFIGDOC8INI->ReadInteger("FUNCTIONS", "SHARP_WIDTH_PRINT", 4);//230213//[인쇄_확대축소화면]부분삭제(취소선) 두께//
	m_nSharpWidthOverlap	= CONFIGDOC8INI->ReadInteger("FUNCTIONS", "SHARP_WIDTH_OVERLAP", 2);//230213//[오버랩]부분삭제(취소선) 두께//

	m_nEmptyBgColor     = CONFIGDOC8INI->ReadInteger("FUNCTIONS", "EMPTY_BGCOLOR", 128);
	if(m_nEmptyBgColor > 220)
		m_nEmptyBgColor	= 220;
	else if(m_nEmptyBgColor < 30)
		m_nEmptyBgColor	= 30;

	//
	if(m_nAreaPoint > 1)
		m_nAreaPoint	= 1;
	//[인쇄_확대축소화면]부분삭제(취소선) 두께//
	if(m_nSharpWidthPrint > 8)
		m_nSharpWidthPrint	= 8;
	else if(m_nSharpWidthPrint < 1)
		m_nSharpWidthPrint	= 1;
	//[오버랩]부분삭제(취소선) 두께//
	if(m_nSharpWidthOverlap > 3)
		m_nSharpWidthOverlap	= 3;
	else if(m_nSharpWidthOverlap < 1)
		m_nSharpWidthOverlap	= 1;

	//A3 이미지 설정정보//
	frmAlphaDoc8->m_nFontSize		= 42;//A3 이미지에서 사용할 폰트크기(42)//토지대장A.jpg참고//
//231118//#SHAREOWN#//부책, 공유지연명부A,B 에 따라 다르므로 funcGetPrintViewBoundary, funcGetPrintViewBoundaryShare()에서 설정//	e08DataAlpha->m_nMiddleWidth	= 153;//A3 이미지에서 사용할 중간-간격(153)//토지대장A.jpg참고//

	//===========================================================================================
	int nColor;
	//
	nColor	= CONFIGDOC8INI->ReadInteger(L"FUNCTIONS", L"HEADER", 8421504);
	frmResultList->COLOR_HEADER_BG	= (TColor)RGB(GetRValue(nColor), GetGValue(nColor), GetBValue(nColor));
	frmResultList2->COLOR_HEADER_BG	= (TColor)RGB(GetRValue(nColor), GetGValue(nColor), GetBValue(nColor));
	//
	nColor	= CONFIGDOC8INI->ReadInteger(L"FUNCTIONS", L"INPUT", 16509155);//입력화면 교대로 표시되는 배경화면//
	frmResultList->COLOR_INPUT_BG	= (TColor)RGB(GetRValue(nColor), GetGValue(nColor), GetBValue(nColor));
	frmResultList2->COLOR_INPUT_BG	= (TColor)RGB(GetRValue(nColor), GetGValue(nColor), GetBValue(nColor));

	// '빈칸' 텍스트 및 배경색 표시 여부(1:표시, 0:미표시<Default>//
	frmResultList->m_INI_EMPTY	= CONFIGDOC8INI->ReadInteger(L"FUNCTIONS", L"EMPTY", 0);
	frmResultList2->m_INI_EMPTY	= CONFIGDOC8INI->ReadInteger(L"FUNCTIONS", L"EMPTY", 0);
	//===========================================================================================

}
