//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//220214//COPY_LMREQ_TO_SMARTONESTOP
BOOL __fastcall TfrmMain::func_DBMSConnectC()
{
	if(frmSql->m_hStmtC) SQLCloseCursor(frmSql->m_hStmtC);
	if(frmSql->m_hStmtC) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmtC);
	if(frmSql->m_hDbcC)  SQLDisconnect(frmSql->m_hDbcC);
	if(frmSql->m_hDbcC)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbcC);
	if(frmSql->m_hEnvC)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnvC);
	frmSql->m_hStmtC = NULL;
	frmSql->m_hDbcC  = NULL;
	frmSql->m_hEnvC  = NULL;

	//========================================================================
	SQLRETURN Ret;
	//환경 핸들을 할당하고 버전 속성을 설정한다.
	if(SQLAllocHandle(SQL_HANDLE_ENV, SQL_NULL_HANDLE, &frmSql->m_hEnvC) != SQL_SUCCESS)
		return FALSE;
	if(SQLSetEnvAttr(frmSql->m_hEnvC, SQL_ATTR_ODBC_VERSION, (SQLPOINTER)SQL_OV_ODBC3, SQL_IS_INTEGER) != SQL_SUCCESS)
		return FALSE;

	//연결 핸들을 할당하고 연결한다
	if(SQLAllocHandle(SQL_HANDLE_DBC, frmSql->m_hEnvC, &frmSql->m_hDbcC) != SQL_SUCCESS)
		return FALSE;

	_ONESTOP_DBIP_ 		= func_Decoder(AnsiString(SIDOINI->ReadString("ONESTOP_DB","IP","")));
	_ONESTOP_DATABASE_  = func_Decoder(AnsiString(SIDOINI->ReadString("ONESTOP_DB","SID","")));//"LANDARCHIVE";
	_ONESTOP_DBPORT_ 	= func_Decoder(AnsiString(SIDOINI->ReadString("ONESTOP_DB","PORT","")));
	_ONESTOP_DBID_ 		= func_Decoder(AnsiString(SIDOINI->ReadString("ONESTOP_DB","ID","")));
	_ONESTOP_DBPW_ 		= func_Decoder(AnsiString(SIDOINI->ReadString("ONESTOP_DB","PW","")));

	AnsiString connectString;
	connectString = "Driver=MySQL ODBC 5.1 Driver; server=" + _ONESTOP_DBIP_ + ";database=" + _ONESTOP_DATABASE_ + ";Port=" + _ONESTOP_DBPORT_ + ";uid=" + _ONESTOP_DBID_ + ";pwd=" + _ONESTOP_DBPW_ + ";OPTION=3; charset=euckr";//외부

//	TStringList *qry = new TStringList();
//	if(qry != NULL)
//	{
//		qry->Clear();
//		qry->Text = "";
//		qry->Add(connectString);//
//		AnsiString asDestFile = frmMain->ROOTPATH + "instr.txt";
//		qry->SaveToFile(asDestFile.c_str());
//		qry->Text = "";
//		qry->Clear();
//		delete qry;
//		qry = NULL;
//	}

	if(_ONESTOP_DATABASE_ == "") return FALSE;

	wsprintf((char *)frmSql->m_InConC, connectString.c_str());

	Ret = SQLDriverConnect(frmSql->m_hDbcC, NULL, frmSql->m_InConC, sizeof(frmSql->m_InConC), frmSql->m_OutConC, sizeof(frmSql->m_OutConC), &frmSql->m_cbOutConC, SQL_DRIVER_NOPROMPT);
	if((Ret != SQL_SUCCESS) && (Ret != SQL_SUCCESS_WITH_INFO))
		return FALSE;

	//명령 핸들을 할당한다.
	if(SQLAllocHandle(SQL_HANDLE_STMT, frmSql->m_hDbcC, &frmSql->m_hStmtC) != SQL_SUCCESS)
		return FALSE;

	return TRUE;
}
//---------------------------------------------------------------------------
void __fastcall TfrmMain::func_DBMSDisconnectC()
{
	if(frmSql->m_hStmtC) SQLCloseCursor(frmSql->m_hStmtC);
	if(frmSql->m_hStmtC) SQLFreeHandle(SQL_HANDLE_STMT,frmSql->m_hStmtC);
	if(frmSql->m_hDbcC)  SQLDisconnect(frmSql->m_hDbcC);
	if(frmSql->m_hDbcC)  SQLFreeHandle(SQL_HANDLE_DBC,frmSql->m_hDbcC);
	if(frmSql->m_hEnvC)  SQLFreeHandle(SQL_HANDLE_ENV,frmSql->m_hEnvC);
	frmSql->m_hStmtC = NULL;
	frmSql->m_hDbcC  = NULL;
	frmSql->m_hEnvC  = NULL;
}
