//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//220428//#LOG_EXCEPT//
void __fastcall TfrmMain::AppException( System:: TObject*  Sender,  Sysutils:: Exception*  E)
{
	AnsiString sObj = "" ;
	if ( Sender){
		if ( Sender->InheritsFrom( __classid( TControl) ) ){
			TControl  * ctrl= ( TControl * ) Sender;
			while ( ctrl){
				sObj = ctrl->Name+ " -> " + sObj;
				ctrl = ctrl->Parent;
			}
		 }
		 else  if ( Sender->InheritsFrom( __classid( TComponent) ) ){
			 TComponent  * Comp= ( TComponent * ) Sender;
			 sObj = Comp->Name;
			 if ( Comp->Owner){
				 sObj = Comp->Owner->Name +  " -> " +  sObj;
			 }
		 }
	}

	AnsiString sExpMsg = sObj +  " Msg:"  + E->Message;
	qryErr->Add(sExpMsg.c_str());
	AnsiString  asLogFile 	= LOGPATH + "err_" + Now().FormatString("yyyymmddhhmmsszzz") + ".txt";
	qryErr->SaveToFile(asLogFile.c_str());

	frmMsg->funcMessageDlg("[AppException]", sExpMsg, 2);
	Close();//
}
