//221209//#DOC8_OVERLAP//
void __fastcall TfrmMain::funcGetDoc8BasicFont()
{
	m_nFontSize		= CONFIGDOC8INI->ReadInteger("FUNCTIONS", "FONT_SIZE", 12);
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::funcGetDoc8FontSize()
{
	funcGetDoc8BasicFont();

	int nSize 	= m_nFontSize;

	if(m_dDocFactor <= m_dDocFitFactor)//10%
		nSize	= nSize;
//	else if(m_dDocFactor < 0.2)//20%
//		nSize	= nSize;
//	else if(m_dDocFactor < 0.3)//30%
//		nSize	= nSize+1;
	else if(m_dDocFactor < 0.5)//50%
		nSize	= nSize+1;
	else if(m_dDocFactor < 0.7)//70%
		nSize	= nSize+2;
	else if(m_dDocFactor < 1.0)//100%
		nSize	= nSize+3;
	else if(m_dDocFactor < 1.5)//150%
		nSize	= nSize+4;
	else if(m_dDocFactor < 2.0)//200%
		nSize	= nSize+5;
	else if(m_dDocFactor < 3.0)//300%
		nSize	= nSize+6;
	else if(m_dDocFactor < 5.0)//500%
		nSize	= nSize+7;
	else if(m_dDocFactor < 7.0)//700%
		nSize	= nSize+8;
	else if(m_dDocFactor < 10.0)//1000%
		nSize	= nSize+9;
	else if(m_dDocFactor >= 10.0)//1000% 이상//
		nSize	= (nSize+(int)m_dDocFactor);

	m_nFontSize = nSize;
}
