//230920//지적도 로딩 시, 화면에 맞는 Zoom Level을 찾기//
void __fastcall TfrmMain::funcGetFitZoomFactor(double _dRatio)
{
	bool success = false;
	for(int i=0; i<10; i++){
		if(daumscalemapping[i] <= _dRatio && daumscalemapping[i+1] >= _dRatio){
			m_nZoomFactor = i+1;
			success = true;
			break;
		}
	}

	if(success == false) m_nZoomFactor = 10;
	if(m_nZoomFactor > 10) m_nZoomFactor = 10;
	else if(m_nZoomFactor <= 0) m_nZoomFactor = 1;
}
