void __fastcall TfrmMain::func_DrawPaintImageSelectGagam(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

 	//--------
	UnicodeString 	usPoiFileName1 = frmMain->ROOTPATH + L"RES\\POI\\iconDoc20_1.png";//지역좌표계//
	UnicodeString 	usPoiFileName2 = frmMain->ROOTPATH + L"RES\\POI\\iconDoc20_3.png";//세계측지계//
	UnicodeString 	usPoiFileName;

	int configindex = func_ConfigIndexAlloc(1,"가감대장", "");
	if(configindex < 0) return;

	int showuse           = m_vCONFIGLP[configindex].showuse;
	int showlevel         = m_vCONFIGLP[configindex].showlevel;
	int labeluse          = m_vCONFIGLP[configindex].labeluse;
	int labelscale        = m_vCONFIGLP[configindex].labelscale;
	int labelcolor        = m_vCONFIGLP[configindex].labelcolor;
	AnsiString labelfont  = m_vCONFIGLP[configindex].labelfont;
	int brushuse          = m_vCONFIGLP[configindex].brushuse;
	int brushcolor        = m_vCONFIGLP[configindex].brushcolor;
	int lineuse           = m_vCONFIGLP[configindex].lineuse;
	int linecolor         = m_vCONFIGLP[configindex].linecolor;
	int linewidth         = m_vCONFIGLP[configindex].linewidth;

	//231031//가감대장.HMF 표시 레벨(from DB Value)//
	m_nGagamShowLevel = showlevel;

	if(showuse != 1) return;
	if(showlevel > m_nZoomFactor) return;
	if(brushuse != 1 && lineuse != 1) return;

	int labelR 	= GetRValue(labelcolor);
	int labelG 	= GetGValue(labelcolor);
	int labelB 	= GetBValue(labelcolor);
	int pathR 	= GetRValue(brushcolor);
	int pathG 	= GetGValue(brushcolor);
	int pathB 	= GetBValue(brushcolor);
	int lineR 	= GetRValue(linecolor);
	int lineG 	= GetGValue(linecolor);
	int lineB 	= GetBValue(linecolor);
	int lineR1, lineG1, lineB1;//Selected
	int pathR1, pathG1, pathB1;//Selected

	if(currentModeShow8)
	{
		lineR1 	= 255;
		lineG1 	= 128;
		lineB1 	= 0;
		pathR1 	= 255;
		pathG1 	= 128;
		pathB1 	= 0;
	}
	else
	{
		lineR1 	= 0;
		lineG1 	= 0;
		lineB1 	= 255;
		pathR1 	= 0;
		pathG1 	= 0;
		pathB1 	= 255;
	}

	//--------
	TRect  mbrRect, rectBuffer;
	//---
	TRect rect;
	rect.Left   = 0;
	rect.Top    = 0;
	rect.Right  = IMGSCREEN1->Width;
	rect.Bottom = IMGSCREEN1->Height;

	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = m_STANDARDGAGAM.m_nRecords;

//	for(int i = 0; i < m_nRecords; ++i)
	if(m_nSelectGagamIndex < m_nRecords)
	{
		MBR tmbr = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].m_MBR;
		mbrRect = func_WorldToDevice(tmbr);
		if(IntersectRect(&rectBuffer,&mbrRect, &_rect)){

			//=====================================================================
			//POLYGON 표시//
			//=====================================================================
			TPoint vPoint, tPoint;
			GPoint gPoint;
			int x, y;

			lineR 	= GetRValue(linecolor);
			lineG 	= GetGValue(linecolor);
			lineB 	= GetBValue(linecolor);

			int nSize = (int)m_vSHPPOLYGAGAM[m_nSelectGagamIndex].m_nNumPoints;
			if(nSize > 0)
			{
				//=====================================================================
				//폴리곤 정보 가져오기//
				//=====================================================================
				gdp::Point *points = new gdp::Point[nSize];
				for(int j = 0; j < nSize; j++){
					gPoint.x = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].m_vPoints[j].x;
					gPoint.y = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].m_vPoints[j].y;
					tPoint  = func_WorldToDevice(gPoint);
					points[j].X = tPoint.x;
					points[j].Y = tPoint.y;
				}

				//=====================================================================
				//폴리곤 표시//
				//=====================================================================
				graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

				//=================================================================
				//m_nSelectGagamIndex > -1 데이터가 존재하면 첫 번째 것만 선택 표시한다.
				//funcGetSelectedGagamIndex 함수도 1개 찾으면 멈추고 반환하므로 굳이 loop 수행할 필요 없다.//
				//=================================================================
				//폴리곤//
				gdp::Pen pen(gdp::Color(lineR1, lineG1, lineB1), linewidth);
				pen.SetDashStyle(gdp::DashStyleDash);
				gdp::SolidBrush solidbrushNew(gdp::Color(m_MAININI.SELECT_REMARK_ALPHA, pathR1, pathG1, pathB1));
				gdp::GraphicsPath Path;
				Path.AddPolygon(points, nSize);
				if(brushuse)
					graphics.FillPath(&solidbrushNew, &Path);
				if(lineuse)
					graphics.DrawPath(&pen,&Path);

				delete []points;

				//=====================================================================
				//심볼 && LABEL 표시//
				//=====================================================================
				vPoint.x = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].x;
				vPoint.y = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].y;
				gPoint   = vPoint;
				tPoint = func_WorldToDevice(gPoint);

				AnsiString  label = m_v_READGAGAM[m_nSelectGagamIndex].REMARK;
				String sLabel	= label;
				HDC memDC1 = ::CreateCompatibleDC(IMGSCREEN1->Canvas->Handle);
				int x1, y1;
				int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
				HFONT m_font = ::CreateFont(fsize, 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, label.c_str());
				HFONT hOldFont = (HFONT)::SelectObject(memDC1,m_font);
				gdp::Font font(memDC1, m_font);
				gdp::SolidBrush solidbrush(gdp::Color(255, pathR1, pathG1, pathB1));
				gdp::StringFormat format;
				format.SetAlignment(gdp::StringAlignmentNear);
				format.SetLineAlignment(gdp::StringAlignmentNear);

				//----------------------------------------------
				//[REQ_260715]_#1.DB 구조 변경 - 가감대장(document20) 지역/세계 구분 추가항목
				//----------------------------------------------
				if(label.AnsiPos("세계.") > 0)
					usPoiFileName = usPoiFileName2;
				else
					usPoiFileName = usPoiFileName1;
				//----------------------------------------------

				//=================================================================
				//m_nSelectGagamIndex > -1 벡터에 데이터가 존재하면 첫 번째 것만 선택 표시한다.
				//funcGetSelectedGagamIndex 함수도 1개 찾으면 멈추고 반환하므로 굳이 loop 수행할 필요 없다.//
				//=================================================================
				//심볼//
				if(FileExists(usPoiFileName)){
					gdp::Image image(usPoiFileName.w_str());
					int nImgW	= image.GetWidth();
					int nImgH	= image.GetHeight();
					x    = tPoint.x - nImgW/2;
					y    = tPoint.y - nImgH/2;
					graphics.DrawImage(&image, x, y, nImgW, nImgH);//이미지그대로출력
					//Label//
					x    = x + nImgW/2 + 4;
					y    = tPoint.y - fsize/2;
					gdp::PointF ptText(x, y);
					graphics.DrawString(sLabel.w_str(), -1, &font, ptText , &format, &solidbrush);
					::SelectObject(memDC1, hOldFont);
					::DeleteObject(m_font);
				}
				//=================================================================
			}//nSize > 0
		}
	}
}
