void __fastcall TfrmMain::funcGetGagamIndex(AnsiString _asMNUM)
{
	AnsiString asLabel = "";
	int nIndex = -1;

	m_vSelectedRIID.clear();
	//NotUsed//m_vSelectedGagamID.clear();

	for(int i = 0; i < (int)m_v_READGAGAM.size(); i++)
	{
		asLabel = (char*)m_v_READGAGAM[i].MNUM;
		if(_asMNUM == asLabel.SubString(1, 19))
		{
			m_nSelectGagamIndex = i;
			if(m_vSHPPOLYGAGAM[m_nSelectGagamIndex].x > 0 && m_vSHPPOLYGAGAM[m_nSelectGagamIndex].y >0)
			{
				m_geoCenterPoint.x = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].x;
				m_geoCenterPoint.y = m_vSHPPOLYGAGAM[m_nSelectGagamIndex].y;
			}
			//NotUsed//m_vSelectedGagamID.push_back(i);//가감대장 레이어.index

			//===================================================
			//241210//선택된 가감대장에 속하는 필지목록만 가져온다. 그러면 채색하는 부분에서 전체필지 비교하여 채색할 필요 없음.//
			//===================================================
			//GAGAMLAYER in LandArchive//가감대장 지번목록 자료 가져오기//
			//=============================================================================
			AnsiString  asMNUM 		= m_v_READGAGAM[m_nSelectGagamIndex].MNUM;
			AnsiString  asKwonNo	= asMNUM.SubString(11, 4);
			AnsiString  asGagamNo 	= asMNUM.SubString(15, 5);
			frmSql->funcReadGagamLandList(asKwonNo, asGagamNo);
			//=============================================================================
			break;//241127//
		}
	}

	//240403//현재 선택한 가감레이어 index 가져오기//
	//NotUsed//if( (int)m_vSelectedGagamID.size() > 0)
	if( m_nSelectGagamIndex == -1)//없으면 '리' 정보로 표시//
	{
		int nRiIndex = func_readRIIndex(_asMNUM.SubString(1, 10));
		if(nRiIndex > -1)
			m_vSelectedRIID.push_back(nRiIndex);//리 인덱스
	}
}
