void __fastcall TfrmMain::func_DrawPaintImageBasePoint(HDC _pDC, HDC _pDCEtc, TRect _rect)
{
	gdp::Graphics graphics(_pDC);
	graphics.SetSmoothingMode(gdp::SmoothingModeHighQuality);

//=============================================================================
//231113//가감대장.지번목록은 별도표시하지 않음.func_DrawPaintImageCbndPolygon
//231214/* TODO : 231214 : 추후 논산, 홍성 가감대장 SHP 구축 시 변경할 것 */
//논산, 홍성 가감대장(2021 구축)의 경우, 공간정보사업부로부터 SHP을 받기 전까지는 LANDLIST 정보로 표시할 것
	if(_SIDOCODE == "44230" || _SIDOCODE == "44800")
	{
		int configindex = func_ConfigIndexAlloc(1,"가감대장", "");
		if(configindex < 0) return;

		m_nGagamShowLevel = m_vCONFIGLP[configindex].showlevel;//240403//
	}
//=============================================================================


	if( !INIUSERSETINFO.B_GAGAMLAYER || m_nZoomFactor < m_nGagamShowLevel + 1)//231117//기준점 심볼은 가감대장 표시Level을 +1단계로 적용//
    	return;

	UnicodeString	usPoiFileName	= IMAGEPOIPATH + L"iconDoc20_0.png";

	HDC memDC1 = ::CreateCompatibleDC(IMGSCREEN1->Canvas->Handle);
	int configindex = func_ConfigIndexAlloc(1,"가감대장", "");
	int fsize = m_vCONFIGLP[configindex].fontsize[m_nZoomFactor-1];
	AnsiString labelfont = m_vCONFIGLP[configindex].labelfont;
	HFONT m_font = ::CreateFont(fsize, 0, 0, 0, FW_BOLD, FALSE, FALSE, 0, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, labelfont.c_str());
	HFONT hOldFont = (HFONT)::SelectObject(memDC1,m_font);
	gdp::Font font(memDC1, m_font);
	gdp::StringFormat format;
	format.SetAlignment(gdp::StringAlignmentCenter);
	format.SetLineAlignment(gdp::StringAlignmentCenter);


	TRect  mbrRect, rectBuffer;
	//*******************************************************************************
	//아이콘//
	int _index = 0;
	int m_nRecords  = m_vGAGAMBASEPOINT.size();

	for(int i = 0; i < m_nRecords; ++i){
		MBR tmbr;

		if(m_vGAGAMBASEPOINT[i].X <= -1) continue;

		//=====================================================================
		//241219//선택 필지가 존재하면 기준점이 화면MBR 벗어나도 그려준다.(가감필지와의 연결선 표시)//
		//=====================================================================
//resource error//		if(m_vSelectedID.size() == 0)
		{
			tmbr.xmin = m_vGAGAMBASEPOINT[i].X - (double)9 / m_lfZoomFactor / m_lfRatio;
			tmbr.ymin = m_vGAGAMBASEPOINT[i].Y - (double)9 / m_lfZoomFactor / m_lfRatio;
			tmbr.xmax = m_vGAGAMBASEPOINT[i].X + (double)9 / m_lfZoomFactor / m_lfRatio;
			tmbr.ymax = m_vGAGAMBASEPOINT[i].Y + (double)9 / m_lfZoomFactor / m_lfRatio;
			mbrRect = func_WorldToDevice(tmbr);
			if(!IntersectRect(&rectBuffer,&mbrRect, &_rect)){
				continue;
			}
		}
		//=====================================================================

		TPoint vPoint, tmpPoint;
		GPoint gPoint;

		vPoint.x = m_vGAGAMBASEPOINT[i].X;
		vPoint.y = m_vGAGAMBASEPOINT[i].Y;
		gPoint   = vPoint;
		tmpPoint = func_WorldToDevice(gPoint);


		int x, y;
		int gapx, gapy;

		//가감대장 기준점 심볼 표시//
		if(FileExists(usPoiFileName)){
			gdp::Image image(usPoiFileName.w_str());
			x    = tmpPoint.x - image.GetWidth()/2;
			y    = tmpPoint.y - image.GetHeight()/2;
			graphics.DrawImage(&image, x, y, image.GetWidth(), image.GetHeight());//이미지그대로출력
		}

		//Label//
		if(m_nZoomFactor >= m_nGagamShowLevel + 2)//231117//Label은 표시Level을 +1단계로 적용//
		{
			AnsiString label = (char*)m_vGAGAMBASEPOINT[i].POINT_NAME;
			String sLabel	= label;

			//===========================================================================
			// 가감대장 - 기준점 + 사업명 + 토지소재지 + 문서 //GAGAM2021//
			//===========================================================================
			//선택한 사업에 포함되는 기준점일때 컬러 다르게 표시//
			int nGagamBaseListIndex = -1;
			nGagamBaseListIndex	= funcGetIndexGagamBaseList(label);

			int x1, y1;
			x1 = x + 8;// - (label.Length() * fsize) / 2;
			y1 = y - 6;
			gdp::PointF ptText(x1, y1);
			gdp::SolidBrush solidbrush(gdp::Color(255, 0, 0, 255));//Blue - 가감대장 레이어와 비슷해서 헷갈려서 Blue변경함//
			gdp::SolidBrush solidbrush1(gdp::Color(255, 0, 128, 128));//Orange - 선택 가감대장의 기준점 다른 컬러로 표시//
			if(nGagamBaseListIndex > -1)
			{
				AnsiString  asStr	= "";
				asStr.sprintf("(X=%0.2f,Y=%0.2f)", m_vGAGAMBASELIST[nGagamBaseListIndex].DIFF_X, m_vGAGAMBASELIST[nGagamBaseListIndex].DIFF_Y);
				sLabel = sLabel + " " + asStr;
				graphics.DrawString(sLabel.w_str(), -1, &font, ptText, &format, &solidbrush1);

				//=============================================================
				//241218//선택가감대장과 기준과의 가감값 표시//#GAGAM_DISTANCE#//
				//=============================================================
				if(m_tPOINT.sPoint.x > 0 && m_tPOINT.sPoint.y > 0)//241127//선택 가감레이어를 가장 마지막에 그리자//
				{
					m_tPOINT.ePoint = tmpPoint;
					gdp::Pen depthpen(gdp::Color(255, 0, 0), 3);
					depthpen.SetDashStyle(gdp::DashStyleDot);
					depthpen.SetLineJoin(gdp::LineJoinRound);     //꺽이는부분처리
					depthpen.SetEndCap(gdp::LineCapArrowAnchor);
					graphics.DrawLine(&depthpen, (int)m_tPOINT.sPoint.x , (int)m_tPOINT.sPoint.y, (int)m_tPOINT.ePoint.x, (int)m_tPOINT.ePoint.y );
				}
				//=============================================================
			}
			else
			{
				graphics.DrawString(sLabel.w_str(), -1, &font, ptText , &format, &solidbrush);
			}
		}
	}
//250516//
	::SelectObject(memDC1, hOldFont);
	::DeleteObject(m_font);
}
