//241210//금산,논산,홍성 가감대장 동일 처리를 위해 변경//
//241210//선택된 가감대장에 속하는 기준점목록만 가져온다.//
//TB_DOCUMENT20_BASELIST의 모든 데이터(m_vGAGAMBASELIST)에서 원하는 지번 INDEX 찾기//
int __fastcall TfrmMain::funcGetIndexGagamList(AnsiString _landcd)
{
	int size = m_vGAGAMLIST.size();
	int result = -1;

	if(size == 0)
		return result;


	//=============================================================================
	AnsiString readlandcd;
	int head, mid, tail, prev;
	head = 0;
	tail = size;
	mid  = (tail + head)/2;

	readlandcd   = (char*)m_vGAGAMLIST[mid].LAND_CD;
	if(size > 0){
		while(1){
			if(readlandcd == ""){
				result = -1;
				break;
			}
			if(_landcd < readlandcd) tail = mid;
			else if(_landcd > readlandcd) head = mid;
			else{
				if(_landcd == readlandcd)
				{
					result = mid;
					break;
				}
				else
				{
					result = -1;
					break;
				}
//=============================================================================
			}
			prev = mid;
			mid = (head + tail)/2;
			readlandcd = (char*)m_vGAGAMLIST[mid].LAND_CD;
			if(prev == mid){
				break;
			}
		}
	}
	return result;
}
