//=============================================================================
//241210//금산,논산,홍성 가감대장 동일 처리를 위해 변경//
//241210//선택된 가감대장에 속하는 기준점목록만 가져온다.//
//TB_DOCUMENT20_BASELIST의 모든 데이터(m_vGAGAMBASELIST)에서 원하는 지번 INDEX 찾기//
int __fastcall TfrmMain::funcGetIndexGagamBaseList(AnsiString _pointName)
{
	int size = m_vGAGAMBASELIST.size();
	int result = -1;

	if(size == 0)
		return result;

	//=============================================================================
	AnsiString readPoint;
	int head, mid, tail, prev;
	head = 0;
	tail = size;
	mid  = (tail + head)/2;

	readPoint   = (char*)m_vGAGAMBASELIST[mid].BASEPOINT;
	while(1){
		//250516//구축 문서 상 기준점명에 'W'가 붙으면 '세계측지계' 사용으로 좌표값은 다르지만, 'W'를 제외하면 같은 기준점이라고 판단//
		readPoint   = StringReplace(readPoint, "W", "", TReplaceFlags() << rfReplaceAll);

		if(readPoint == ""){
			result = -1;
			break;
		}
		if(_pointName < readPoint) tail = mid;
		else if(_pointName > readPoint) head = mid;
		else{
			if(_pointName == readPoint)
			{
				result = mid;
				break;
			}
			else
			{
				result = -1;
				break;
			}
		}
		prev = mid;
		mid = (head + tail)/2;
		readPoint = (char*)m_vGAGAMBASELIST[mid].BASEPOINT;
		if(prev == mid){
			break;
		}
	}
	return result;
}
