void __fastcall TfrmMain::IMGTABDETAILClick(TObject *Sender)
{
	if(m_nActiveDoc != 0)//[상세검색] '활성화' > [상세검색] 다시 클릭하면 '비활성화'
	{
		IMGTABClick(IMGTAB00);
	}
	else
	{
		wchar_t wBufTab[64];
		TImage *tcmpTab;
		memset(wBufTab, 0, sizeof(wBufTab));
		swprintf(wBufTab, L"IMGTAB%02d", IMGTABDETAIL->Tag);
		tcmpTab = (TImage*)frmMain->FindComponent(wBufTab);
		if(tcmpTab != NULL)
			IMGTABClick(tcmpTab);
		else
			IMGTABClick(IMGTAB00);
	}
}
