//231118//통합검색 버튼 <-> 상세검색 버튼//
void __fastcall TfrmMain::funcSetTotalDetailQueryButtons(int _nTag)
{
	if(_nTag != 0)//통합검색 -> 상세검색//
	{
//240108//상세검색일 때 통합검색 제한//		edtMainSearchText->Enabled			= false;//231121//
		edtMainSearchText->ReadOnly			= true;//240108//상세검색일 때 통합검색 제한//

		funcFreeEachButtonImage(IMGTAB00);
		funcFreeEachButtonImage(IMGTABDETAIL);
		IMGTAB00->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[0][0]);//비활성화//
		IMGTABDETAIL->Picture->Bitmap->Assign(BITMAP_BTN_TAB[1][TabDetail]);//231114//상세검색 탭 기능추가//활성화//

		//231120//		m_nActiveDoc = -1;
		if(m_nTABCOUNT <= 7)
			pnlSearchBar->Height	= 174;
		else
			pnlSearchBar->Height	= 210;
	}
	else//상세검색 -> 통합검색//
	{
//240108//상세검색일 때 통합검색 제한//		edtMainSearchText->Enabled			= true;//231121//
		edtMainSearchText->ReadOnly			= false;//240108//상세검색일 때 통합검색 제한//

		funcFreeEachButtonImage(IMGTAB00);
		funcFreeEachButtonImage(IMGTABDETAIL);
		IMGTAB00->Picture->Bitmap->Assign(BITMAP_BTN_TABDOC[0][1]);//활성화//
		IMGTABDETAIL->Picture->Bitmap->Assign(BITMAP_BTN_TAB[0][TabDetail]);//상세검색 탭 기능추가//비활성화//

		//231120//		m_nActiveDoc = 0;
		pnlSearchBar->Height	= 130;
	}
}
