void __fastcall TfrmMain::funcDrawMaskingRect(bool _bFront)
{
	m_vMASKINGRECT.clear();

	if(_bFront)//앞면//W:79%, H:35%
	{
		tempRECT.rImage.Left	= mGetImageInfo.nImageWidth * m_dPIFrontLeftRate;
		tempRECT.rImage.Top		= mGetImageInfo.nImageHeight * m_dPIFrontTopRate;
		tempRECT.rImage.Right	= mGetImageInfo.nImageWidth * m_dPIFrontRightRate;
		tempRECT.rImage.Bottom	= mGetImageInfo.nImageHeight * m_dPIFrontBottomRate;
	}
	else//뒷면//W:79%, H:6%
	{
		tempRECT.rImage.Left	= mGetImageInfo.nImageWidth * m_dPIBackLeftRate;
		tempRECT.rImage.Top		= mGetImageInfo.nImageHeight * m_dPIBackTopRate;
		tempRECT.rImage.Right	= mGetImageInfo.nImageWidth * m_dPIBackRightRate;
		tempRECT.rImage.Bottom	= mGetImageInfo.nImageHeight * m_dPIBackBottomRate;
	}

	m_vMASKINGRECT.push_back(tempRECT);
}
