//240322//[Add]카드대장.개인정보.MASKING.최소사용자 권한//
//=============================================================================
//카드대장 확인해서 B_MASKING 설정하는 함수//
void __fastcall TfrmMain::funcCheckCardMasking(AnsiString _asPathName)
{
	AnsiString  asSqlQry 	= "";
	AnsiString  asColData 	= "";

	_asPathName = StringReplace(_asPathName, "\\", "/", TReplaceFlags() << rfReplaceAll);

	asSqlQry	= "SELECT SINGU_NAME FROM TB_DOCUMENT08 WHERE PATH_NAME='" + _asPathName + "';";
	asColData	= frmSql->funcSQLColumnData(asSqlQry);
	if(asColData == "카드")
	{
		B_MASKING	= true;
		if(funcCheckCardFront(_asPathName))
			funcDrawMaskingRect(true);
		else
			funcDrawMaskingRect(false);
	}
	else
	{
		B_MASKING	= false;
	}
}
//---------------------------------------------------------------------------

//카드대장.앞면 확인하는 함수//
bool __fastcall TfrmMain::funcCheckCardFront(AnsiString _asPathName)
{
	AnsiString  asSqlQry 	= "";
	AnsiString  asColData 	= "";
	bool		bReturn		= false;

	_asPathName = StringReplace(_asPathName, "\\", "/", TReplaceFlags() << rfReplaceAll);

	asSqlQry	= "SELECT ONOFF_CODE FROM TB_DOCUMENT08 WHERE PATH_NAME='" + _asPathName + "';";
	asColData	= frmSql->funcSQLColumnData(asSqlQry);
	if(asColData != "1")
		bReturn	= true;

	return bReturn;
}
