void __fastcall TfrmMain::tmrDoc08AITimer(TObject *Sender)
{
	int barLeft	= 40;
	int barTop	= 183;
	int barWidth = 40;
	int bgWidth = 520;

	imgDoc08AIBg->Left 			= (pnlImgDocView->Width - imgDoc08AIBg->Width) / 2;
	imgDoc08AIBg->Top  			= (pnlImgDocView->Height - imgDoc08AIBg->Height) / 2;
	imgDoc08AIBar->Left 		= imgDoc08AIBg->Left + barLeft;
	imgDoc08AIBar->Top  		= imgDoc08AIBg->Top + barTop;
	imgDoc08AIBar->Visible		= true;
	imgDoc08AIBg->Visible		= true;

//260713//TEST
/*	int nTurnCount	= (500 / imgDoc08AIBar->Width) - 1;
	if( (m_nAIOCRTimerValue / nTurnCount) % 2 == 0)//Forward
		imgDoc08AIBar->Left	= imgDoc08AIBg->Left + 43 + imgDoc08AIBar->Width * (m_nAIOCRTimerValue % nTurnCount);
	else//Backward
		imgDoc08AIBar->Left	= imgDoc08AIBg->Left + 43 + imgDoc08AIBar->Width * (nTurnCount - m_nAIOCRTimerValue % nTurnCount);
*/

	int nTurnCount	= ((bgWidth-barLeft-imgDoc08AIBar->Width) / barWidth) + 1;
	if( (m_nAIOCRTimerValue / nTurnCount) % 2 == 0)//Forward
		imgDoc08AIBar->Left	= imgDoc08AIBg->Left + barLeft + barWidth * (m_nAIOCRTimerValue % nTurnCount);
	else//Backward
		imgDoc08AIBar->Left	= imgDoc08AIBg->Left + barLeft + barWidth * (nTurnCount - m_nAIOCRTimerValue % nTurnCount);

	m_nAIOCRTimerValue++;
}
