//#UPDATE tb_user4 SET FT_DOC=CAST(SUBSTRING(FT_PATHNAME, 9, 2) AS UNSIGNED INTEGER) WHERE FT_DOC=0 AND FT_PATHNAME LIKE 'DOCUMENT%'

void __fastcall TfrmMain::pbRect4MouseDown(TObject *Sender, TMouseButton Button, TShiftState Shift,
          int X, int Y)
{
	if (this->palWait->Visible)//221214//
		return;

	bOwnNamesMove = false;

	TRect	tRect;
	vector<DATA_STRUCT>			m_vDATA;

	if( m_bSUBBOOK )//부책//
	{
		for(int i = 0; i < DOC08_SUBBOOK_CNT; i++)
		{
			//Current Position
			e08DataAIOCR->m_nDoc8MouseGap[i].x	= e08DataAIOCR->m_bpDoc8OwnInfo[i].tLT.x - X;
			e08DataAIOCR->m_nDoc8MouseGap[i].y  = e08DataAIOCR->m_bpDoc8OwnInfo[i].tLT.y - Y;
		}

		//pbRect2 region
		for(int i = 0; i < DOC08_SUBBOOK_CNT; i++)//241203//#등급#추가//
		{
			m_vDATA.clear();

			if(i == 0)
				m_vDATA	= e08DataAIOCR->m_vLAND;
			else if(i == 1)
				m_vDATA	= e08DataAIOCR->m_vJIBUN;
			else if(i == 2)
				m_vDATA	= e08DataAIOCR->m_vMEMO;
			else if(i == 3)
				m_vDATA	= e08DataAIOCR->m_vJIMOK;
			else if(i == 4)
				m_vDATA	= e08DataAIOCR->m_vAREA;
			else if(i == 5)
				m_vDATA	= e08DataAIOCR->m_vVALUE1;
			else if(i == 6)
				m_vDATA	= e08DataAIOCR->m_vVALUE2;
			else if(i == 7)
				m_vDATA	= e08DataAIOCR->m_vHISTORY;
			else if(i == 8)
				m_vDATA	= e08DataAIOCR->m_vOWNINFODATE;
			else if(i == 9)
				m_vDATA	= e08DataAIOCR->m_vOWNINFOREASON;
			else if(i == 10)
				m_vDATA	= e08DataAIOCR->m_vOWNINFOADDRESS;
			else if(i == 11)
				m_vDATA	= e08DataAIOCR->m_vOWNINFONAME;
			else if(i == 12)
				m_vDATA	= e08DataAIOCR->m_vCAUTION;
			else if(i == 13)
				m_vDATA	= e08DataAIOCR->m_vLEVEL;

			for( int j = 0; j < (int)m_vDATA.size(); j++)
			{
				tRect   = m_vDATA[j].tRect;

				if(tRect.Left <= X && X <= tRect.Right && tRect.Top <= Y && Y <= tRect.Bottom)
				{
					bOwnNamesMove = true;
					j = (int)m_vDATA.size()-1;//break를 하면 for(i)도 종료해서 다른 tLT 이동을 안하기에 변경//break;
				}

				if(i == 0 && j == 0)
				{
					if(tRect.Right+32 <= X && X <= tRect.Right+32+imgDoc08Mover4->Width && tRect.Top <= Y && Y <= tRect.Top+imgDoc08Mover4->Height)//minji@230310//사장님REQ//
					{
						bOwnNamesMove = true;
						j = (int)m_vDATA.size()-1;//break를 하면 for(i)도 종료해서 다른 tLT 이동을 안하기에 변경//break;
					}
				}
			}
		}
	}
	else//공유지연명부//
	{
		for(int i = 0; i < DOC08_SHAREOWN_CNT; i++)//m_vDeletePos는 미포함//아래에서 처리//241203//#등급#추가//
		{
			//Current Position
			e08DataAIOCR->m_nDoc8MouseGapShare[i].x	= e08DataAIOCR->m_bpDoc8ShareOwn[i].tLT.x - X;
			e08DataAIOCR->m_nDoc8MouseGapShare[i].y = e08DataAIOCR->m_bpDoc8ShareOwn[i].tLT.y - Y;
		}

		//pbRect2 region
		for(int i = 0; i < DOC08_SHAREOWN_CNT; i++)//241203//#등급#추가//
		{
			m_vDATA.clear();

			if(i == 0)
				m_vDATA	= e08DataAIOCR->m_vLAND;
			else if(i == 1)
				m_vDATA	= e08DataAIOCR->m_vJIBUN;
			else if(i == 2)
				m_vDATA	= e08DataAIOCR->m_vMEMO;
			else if(i == 3)
				m_vDATA	= e08DataAIOCR->m_vSHAREOWNDATE;
			else if(i == 4)
				m_vDATA	= e08DataAIOCR->m_vSHAREOWNREASON;
			else if(i == 5)
				m_vDATA	= e08DataAIOCR->m_vSHAREOWNRATIO;
			else if(i == 6)
				m_vDATA	= e08DataAIOCR->m_vSHAREOWNADDRESS;
			else if(i == 7)
				m_vDATA	= e08DataAIOCR->m_vSHAREOWNNAME;
			else if(i == 8)
				m_vDATA	= e08DataAIOCR->m_vCAUTION;
			else if(i == 9)
				m_vDATA	= e08DataAIOCR->m_vSHARECOMMENT;
			else if(i == 10)
				m_vDATA	= e08DataAIOCR->m_vLEVEL;

			for( int j = 0; j < (int)m_vDATA.size(); j++)
			{
				tRect   = m_vDATA[j].tRect;

				if(tRect.Left <= X && X <= tRect.Right && tRect.Top <= Y && Y <= tRect.Bottom)
				{
					bOwnNamesMove = true;
					j = (int)m_vDATA.size()-1;//break를 하면 for(i)도 종료해서 다른 tLT 이동을 안하기에 변경//break;
				}

				if(i == 0 && j == 0)
				{
					if(tRect.Right+32 <= X && X <= tRect.Right+32+imgDoc08Mover4->Width && tRect.Top <= Y && Y <= tRect.Top+imgDoc08Mover4->Height)//minji@230310//사장님REQ//
					{
						bOwnNamesMove = true;
						j = (int)m_vDATA.size()-1;//break를 하면 for(i)도 종료해서 다른 tLT 이동을 안하기에 변경//break;
					}
				}
			}
		}
	}
//=============================================================================

	if( !bOwnNamesMove )
		this->IMGSCREEN2MouseDown(IMGSCREEN2, Button, Shift, X, Y);
}
