void __fastcall TfrmMain::pbRect4MouseMove(TObject *Sender, TShiftState Shift, int X,
          int Y)
{
	if(bOwnNamesMove)
	{
		if( m_bSUBBOOK )//부책//
		{
			for(int i = 0; i < DOC08_SUBBOOK_CNT; i++)//241203//#등급#추가//
			{
				e08DataAIOCR->m_bpDoc8OwnInfo[i].tLT.x	= X + e08DataAIOCR->m_nDoc8MouseGap[i].x;
				e08DataAIOCR->m_bpDoc8OwnInfo[i].tLT.y  = Y + e08DataAIOCR->m_nDoc8MouseGap[i].y;
				e08DataAIOCR->m_bpDoc8OwnInfo[i].gLT  	= eFunc->funcDeviceToSurveyMap(e08DataAIOCR->m_bpDoc8OwnInfo[i].tLT);
			}
		}
		else//공유지연명부//
		{
			for(int i = 0; i < DOC08_SHAREOWN_CNT; i++)//m_vDeletePos는 별도로//241203//#등급#추가//
			{
				e08DataAIOCR->m_bpDoc8ShareOwn[i].tLT.x	= X + e08DataAIOCR->m_nDoc8MouseGapShare[i].x;
				e08DataAIOCR->m_bpDoc8ShareOwn[i].tLT.y	= Y + e08DataAIOCR->m_nDoc8MouseGapShare[i].y;
				e08DataAIOCR->m_bpDoc8ShareOwn[i].gLT	= eFunc->funcDeviceToSurveyMap(e08DataAIOCR->m_bpDoc8ShareOwn[i].tLT);
			}
		}
//=============================================================================

		pbRect4->Invalidate();
	}
	else
		IMGSCREEN2MouseMove(IMGSCREEN2, Shift, X, Y);
}
//---------------------------------------------------------------------------

void __fastcall TfrmMain::pbRect4MouseUp(TObject *Sender, TMouseButton Button, TShiftState Shift,
		  int X, int Y)
{
	if(bOwnNamesMove)
	{
		bOwnNamesMove = false;
	}
	else
		IMGSCREEN2MouseUp(IMGSCREEN2, Button, Shift, X, Y);
}
