void __fastcall TfrmMain::IMGTEMPDOCClick(TObject *Sender)
{
	if(frmTempDoc->funcGetIndexList(m_asCurrentFilePath) > -1)
	{
		ShowMessage("이미 '임시저장'된 파일입니다.");
		return;
	}

	//현재 썸네일 복사//
	AnsiString asOrgFile 	= "";
	AnsiString asTgtFile 	= "";
	AnsiString asFileName 	= "";
	AnsiString asFileExt 	= "";
	//Vector에 데이터 추가
	DOCUMENT_PATHLIST_STRUCT 		tempList;

	memset(&tempList, 0x00, sizeof(DOCUMENT_PATHLIST_STRUCT));

	if(INI_AS_THUMBEXT	== "JPG")	asFileExt 	= ".jpg";
	else                         	asFileExt 	= ".bmp";

	if((int)m_vThumbPathList.size())
	{
		asFileName 	= ExtractFileName((char *)m_vThumbPathList[m_nThumbCurrIndex].PATH_NAME);
		asOrgFile	= asFileName.SubString(1, asOrgFile.Pos(".")-1) + asFileExt;
		asOrgFile 	= THUMBPATH + asFileName;
		asTgtFile 	= TMPTHUMBPATH + asFileName;
		if(FileExists(asOrgFile))
		{
			CopyFile(asOrgFile.c_str(), asTgtFile.c_str(), false);
			strcpy(tempList.THUMB_NAME, m_asCurrentFilePath.c_str());
		}
	}

	//현재 열람문서 복사//
	asFileName 	= ExtractFileName(m_asCurrentFilePath);
	asOrgFile 	= TMPPATH + asFileName;
	asTgtFile 	= TMPDOCPATH + asFileName;
	if(FileExists(asOrgFile))
		CopyFile(asOrgFile.c_str(), asTgtFile.c_str(), false);

	//tempList.KWON_NO
	//tempList.KIND_CODE
	//tempList.PAGE_NO
	//tempList.DOHO
	tempList.DOC_NO = m_nViewDocNo;
	strcpy(tempList.PATH_NAME, m_asCurrentFilePath.c_str());
	//tempList.CHECKED
	frmTempDoc->m_vTmpDocList.push_back(tempList);

	//보관함 있는 경우//
	funcFreeEachButtonImage(IMGTEMPDOC);
	IMGTEMPDOC->Tag = 1;//이미 보관됨//
	IMGTEMPDOC->Picture->Bitmap->Assign(BITMAP_BTN_BUTTONS[0][TempDocUn]);

	if(frmTempDoc->m_vTmpDocList.size())
		palTempList->Visible = true;

	if(frmTempDoc->Showing)
		frmTempDoc->funcRefreshShow();
}
