void __fastcall TfrmMain::IMGLMFSClick(TObject *Sender)
{
	if( !IMGLMFS->Enabled)
		return;

	if(IMGLMFS->Tag == 0)//ArchiveLMFS 프로그램 실행 전//
	{
		IMGLMFS->Enabled= false;
		funcSetLMFSButton(true);
		if(funcExeArchiveLMFS())
		{
			IMGLMFS->Tag = 1;
		}
		else
		{
			funcSetLMFSButton(false);
		}
		IMGLMFS->Enabled = true;
	}
	else//ArchiveLMFS 프로그램 실행 중//
	{
		IMGLMFS->Tag = 0;
		HWND hWnd = FindWindow(NULL, "토지이동흐름도");
		if(hWnd)
			SendMessage(hWnd,WM_CLOSE,0,0);

		funcSetLMFSButton(false);
	}
}
