void __fastcall TfrmMain::funcSetLMFSButton(bool _bUsing)
{
	if(_bUsing)//ArchiveLMFS 프로그램 실행 전//
	{
		funcFreeEachButtonImage(IMGLMFS);
		IMGLMFS->Picture->Bitmap->Assign(BITMAP_BTN_BUTTONS[1][BtnLMFS]);
	}
	else//초기화//
	{
        IMGLMFS->Tag = 0;
		funcFreeEachButtonImage(IMGLMFS);
		IMGLMFS->Picture->Bitmap->Assign(BITMAP_BTN_BUTTONS[0][BtnLMFS]);
	}
}
