void __fastcall TfrmMain::TimerLMFSTimer(TObject *Sender)
{
    if (hProcessB == NULL) return;

    DWORD exitCode;
    if (GetExitCodeProcess(hProcessB, &exitCode)) {
        if (exitCode != STILL_ACTIVE) {
            Timer1->Enabled = false;
            CloseHandle(hProcessB);
            hProcessB = NULL;

			funcSetLMFSButton(false);
			//ShowMessage("pnu 파라미터를 넘겨 실행했던 B 프로그램이 종료되었습니다.");
        }
    }
}
